(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("isocrates-orations-3-e", [{"sp": "HDR", "t": "Λόγοι, τόμος Γʹ"}, {"sp": "HDR", "t": "Εὐαγόρας", "st": "9"}, {"sp": "N", "t": "ὁρῶν, ὦ Νικόκλεις, τιμῶντά σε τὸν τάφον τοῦ πατρὸς οὐ μόνον τῷ πλήθει καὶ τῷ κάλλει τῶν ἐπιφερομένων, ἀλλὰ καὶ χοροῖς καὶ μουσικῇ καὶ γυμνικοῖς ἀγῶσιν, ἔτι δὲ πρὸς τούτοις ἵππων τε καὶ τριήρων ἁμίλλαις, καὶ λείποντ’ οὐδεμίαν τῶν τοιούτων ὑπερβολήν,", "st": "9.1"}, {"sp": "N", "t": "ἡγησάμην Εὐαγόραν, εἴ τίς ἐστιν αἴσθησις τοῖς τετελευτηκόσι περὶ τῶν ἐνθάδε γιγνομένων, εὐμενῶς μὲν ἀποδέχεσθαι καὶ ταῦτα, καὶ χαίρειν ὁρῶντα τήν τε περὶ αὑτὸν ἐπιμέλειαν καὶ τὴν σὴν μεγαλοπρέπειαν, πολὺ δ’ ἂν ἔτι πλείω χάριν ἔχειν ἢ τοῖς ἄλλοις ἅπασιν, εἴ τις δυνηθείη περὶ τῶν ἐπιτηδευμάτων αὐτοῦ καὶ τῶν κινδύνων ἀξίως διελθεῖν τῶν ἐκείνῳ πεπραγμένων·", "st": "9.2"}, {"sp": "N", "t": "εὑρήσομεν γὰρ τοὺς φιλοτίμους καὶ μεγαλοψύχους τῶν ἀνδρῶν οὐ μόνον ἀντὶ τῶν τοιούτων ἐπαινεῖσθαι βουλομένους, ἀλλ’ ἀντὶ τοῦ ζῆν ἀποθνῄσκειν εὐκλεῶς αἱρουμένους, καὶ μᾶλλον περὶ τῆς δόξης ἢ τοῦ βίου σπουδάζοντας, καὶ πάντα ποιοῦντας, ὅπως ἀθάνατον τὴν περὶ αὑτῶν μνήμην καταλείψουσιν.", "st": "9.3"}, {"sp": "N", "t": "αἱ μὲν οὖν δαπάναι τῶν μὲν τοιούτων οὐδὲν ἐξεργάζονται, τοῦ δὲ πλούτου σημεῖόν εἰσιν· οἱ δὲ περὶ τὴν μουσικὴν καὶ τὰς ἄλλας ἀγωνίας ὄντες, οἱ μὲν τὰς δυνάμεις τὰς αὑτῶν, οἱ δὲ τὰς τέχνας ἐπιδειξάμενοι, σφᾶς αὐτοὺς ἐντιμοτέρους κατέστησαν· ὁ δὲ λόγος εἰ καλῶς διέλθοι τὰς ἐκείνου πράξεις, ἀείμνηστον ἂν τὴν ἀρετὴν τὴν Εὐαγόρου παρὰ πᾶσιν ἀνθρώποις ποιήσειεν.", "st": "9.4"}, {"sp": "N", "t": "ἐχρῆν μὲν οὖν καὶ τοὺς ἄλλους ἐπαινεῖν τοὺς ἐφ’ αὑτῶν ἄνδρας ἀγαθοὺς γεγενημένους, ἵν’ οἵ τε δυνάμενοι τὰ τῶν ἄλλων ἔργα κοσμεῖν ἐν εἰδόσι ποιούμενοι τοὺς λόγους ταῖς ἀληθείαις ἐχρῶντο περὶ αὐτῶν, οἵ τε νεώτεροι φιλοτιμοτέρως διέκειντο πρὸς τὴν ἀρετήν, εἰδότες ὅτι τούτων εὐλογήσονται μᾶλλον ὧν ἂν ἀμείνους σφᾶς αὐτοὺς παράσχωσιν. νῦν δὲ τίς οὐκ ἂν ἀθυμήσειεν,", "st": "9.5"}, {"sp": "N", "t": "ὅταν ὁρᾷ τοὺς μὲν περὶ τὰ Τρωϊκὰ καὶ τοὺς ἐπέκεινα γενομένους ὑμνουμένους καὶ τραγῳδουμένους, αὑτὸν δὲ προειδῇ, μηδ’ ἂν ὑπερβάλλῃ τὰς ἐκείνων ἀρετάς, μηδέποτε τοιούτων ἐπαίνων ἀξιωθησόμενον; τούτων δ’ αἴτιος ὁ φθόνος, ᾧ τοῦτο μόνον ἀγαθὸν πρόσεστιν, ὅτι μέγιστον κακὸν τοῖς ἔχουσίν ἐστιν. οὕτω γάρ τινες δυσκόλως πεφύκασιν, ὥσθ’ ἥδιον ἂν εὐλογουμένων ἀκούοιεν οὓς οὐκ ἴσασιν εἰ γεγόνασιν, ἢ τούτων, ὑφ’ ὧν εὖ πεπονθότες αὐτοὶ τυγχάνουσιν.", "st": "9.6"}, {"sp": "N", "t": "οὐ μὴν δουλευτέον τοὺς νοῦν ἔχοντας τοῖς οὕτω κακῶς φρονοῦσιν, ἀλλὰ τῶν μὲν τοιούτων ἀμελητέον, τοὺς δ’ ἄλλους ἐθιστέον ἀκούειν περὶ ὧν καὶ λέγειν δίκαιόν ἐστιν, ἄλλως τ’ ἐπειδὴ καὶ τὰς ἐπιδόσεις ἴσμεν γιγνομένας καὶ τῶν τεχνῶν καὶ τῶν ἄλλων ἁπάντων οὐ διὰ τοὺς ἐμμένοντας τοῖς καθεστῶσιν, ἀλλὰ διὰ τοὺς ἐπανορθοῦντας καὶ τολμῶντας ἀεί τι κινεῖν τῶν μὴ καλῶς ἐχόντων.", "st": "9.7"}, {"sp": "N", "t": "οἶδα μὲν οὖν ὅτι χαλεπόν ἐστιν ὃ μέλλω ποιεῖν, ἀνδρὸς ἀρετὴν διὰ λόγων ἐγκωμιάζειν. σημεῖον δὲ μέγιστον· περὶ μὲν γὰρ ἄλλων πολλῶν καὶ παντοδαπῶν λέγειν τολμῶσιν οἱ περὶ τὴν φιλοσοφίαν ὄντες, περὶ δὲ τῶν τοιούτων οὐδεὶς πώποτ’ αὐτῶν συγγράφειν ἐπεχείρησεν. καὶ πολλὴν αὐτοῖς ἔχω συγγνώμην. τοῖς μὲν γὰρ ποιηταῖς πολλοὶ δέδονται κόσμοι·", "st": "9.8"}, {"sp": "N", "t": "καὶ γὰρ πλησιάζοντας τοὺς θεοὺς τοῖς ἀνθρώποις οἷόν τ’ αὐτοῖς ποιῆσαι καὶ διαλεγομένους καὶ συναγωνιζομένους οἷς ἂν βουληθῶσι, καὶ περὶ τούτων δηλῶσαι μὴ μόνον τοῖς τεταγμένοις ὀνόμασιν, ἀλλὰ τὰ μὲν ξένοις, τὰ δὲ καινοῖς, τὰ δὲ μεταφοραῖς, καὶ μηδὲν παραλιπεῖν, ἀλλὰ πᾶσι τοῖς εἴδεσι διαποικῖλαι τὴν ποίησιν·", "st": "9.9"}, {"sp": "N", "t": "τοῖς δὲ περὶ τοὺς λόγους οὐδὲν ἔξεστι τῶν τοιούτων, ἀλλ’ ἀποτόμως καὶ τῶν ὀνομάτων τοῖς πολιτικοῖς μόνον καὶ τῶν ἐνθυμημάτων τοῖς περὶ αὐτὰς τὰς πράξεις ἀναγκαῖόν ἐστι χρῆσθαι. πρὸς δὲ τούτοις οἱ μὲν μετὰ μέτρων καὶ ῥυθμῶν ἅπαντα ποιοῦσιν, οἱ δ’ οὐδενὸς τούτων κοινωνοῦσιν· ἃ τοσαύτην ἔχει χάριν, ὥστ’ ἂν καὶ τῇ λέξει καὶ τοῖς ἐνθυμήμασιν ἔχῃ κακῶς, ὅμως αὐταῖς ταῖς εὐρυθμίαις καὶ ταῖς συμμετρίαις ψυχαγωγοῦσι τοὺς ἀκούοντας.", "st": "9.10"}, {"sp": "N", "t": "γνοίη δ’ ἄν τις ἐκεῖθεν τὴν δύναμιν αὐτῶν· ἢν γάρ τις τῶν ποιημάτων τῶν εὐδοκιμούντων τὰ μὲν ὀνόματα καὶ τὰς διανοίας καταλίπῃ, τὸ δὲ μέτρον διαλύσῃ, φανήσεται πολὺ καταδεέστερα τῆς δόξης ἧς νῦν ἔχομεν περὶ αὐτῶν. ὅμως δὲ καίπερ τοσοῦτον πλεονεκτούσης τῆς ποιήσεως, οὐκ ὀκνητέον, ἀλλ’ ἀποπειρατέον τῶν λόγων ἐστίν, εἰ καὶ τοῦτο δυνήσονται, τοὺς ἀγαθοὺς ἄνδρας εὐλογεῖν μηδὲν χεῖρον τῶν ἐν ταῖς ᾠδαῖς καὶ τοῖς μέτροις ἐγκωμιαζόντων.", "st": "9.11"}, {"sp": "N", "t": "πρῶτον μὲν οὖν περὶ τῆς φύσεως τῆς Εὐαγόρου, καὶ τίνων ἦν ἀπόγονος, εἰ καὶ πολλοὶ προεπίστανται, δοκεῖ μοι πρέπειν κἀμὲ τῶν ἄλλων ἕνεκα διελθεῖν περὶ αὐτῶν, ἵνα πάντες εἰδῶσιν ὅτι καλλίστων αὐτῷ καὶ μεγίστων παραδειγμάτων καταλειφθέντων οὐδὲν καταδεέστερον αὑτὸν ἐκείνων παρέσχεν.", "st": "9.12"}, {"sp": "N", "t": "ὁμολογεῖται μὲν γὰρ τοὺς ἀπὸ Διὸς εὐγενεστάτους τῶν ἡμιθέων εἶναι, τούτων δ’ αὐτῶν οὐκ ἔστιν ὅστις οὐκ ἂν Αἰακίδας προκρίνειεν· ἐν μὲν γὰρ τοῖς ἄλλοις γένεσιν εὑρήσομεν τοὺς μὲν ὑπερβάλλοντας, τοὺς δὲ καταδεεστέρους ὄντας, οὗτοι δ’ ἅπαντες ὀνομαστότατοι τῶν καθ’ αὑτοὺς γεγόνασιν.", "st": "9.13"}, {"sp": "N", "t": "τοῦτο μὲν γὰρ Αἰακὸς ὁ Διὸς μὲν ἔκγονος, τοῦ δὲ γένους τοῦ Τευκριδῶν πρόγονος, τοσοῦτον διήνεγκεν ὥστε γενομένων αὐχμῶν ἐν τοῖς Ἕλλησι καὶ πολλῶν ἀνθρώπων διαφθαρέντων, ἐπειδὴ τὸ μέγεθος τῆς συμφορᾶς ὑπερέβαλλεν, ἦλθον οἱ προεστῶτες τῶν πόλεων ἱκετεύοντες αὐτόν, νομίζοντες διὰ τῆς συγγενείας καὶ τῆς εὐσεβείας τῆς ἐκείνου τάχιστ’ ἂν εὑρέσθαι παρὰ τῶν θεῶν τῶν παρόντων κακῶν ἀπαλλαγήν.", "st": "9.14"}, {"sp": "N", "t": "σωθέντες δὲ καὶ τυχόντες ὧν ἐδεήθησαν, ἱερὸν ἐν Αἰγίνῃ κατεστήσαντο κοινὸν τῶν Ἑλλήνων, οὗπερ ἐκεῖνος ἐποιήσατο τὴν εὐχήν. καὶ κατ’ ἐκεῖνόν τε τὸν χρόνον ἕως ἦν μετ’ ἀνθρώπων, μετὰ καλλίστης ὢν δόξης διετέλεσεν· ἐπειδή τε μετήλλαξε τὸν βίον, λέγεται παρὰ Πλούτωνι καὶ Κόρῃ μεγίστας τιμὰς ἔχων παρεδρεύειν ἐκείνοις.", "st": "9.15"}, {"sp": "N", "t": "τούτου δὲ παῖδες ἦσαν Τελαμὼν καὶ Πηλεύς, ὧν ὁ μὲν ἕτερος μεθ’ Ἡρακλέους ἐπὶ Λαομέδοντα στρατευσάμενος ἀριστείων ἠξιώθη, Πηλεὺς δ’ ἔν τε τῇ μάχῃ τῇ πρὸς Κενταύρους ἀριστεύσας καὶ κατὰ πολλοὺς ἄλλους κινδύνους εὐδοκιμήσας Θέτιδι τῇ Νηρέως, θνητὸς ὢν ἀθανάτῃ, συνῴκησε, καὶ μόνου τούτου φασὶ τῶν προγεγενημένων ὑπὸ θεῶν ἐν τοῖς γάμοις ὑμέναιον ᾀσθῆναι.", "st": "9.16"}, {"sp": "N", "t": "τούτοιν δ’ ἑκατέρου, Τελαμῶνος μὲν Αἴας καὶ Τεῦκρος ἐγενέσθην, Πηλέως δ’ Ἀχιλλεύς, οἳ μέγιστον καὶ σαφέστατον ἔλεγχον ἔδοσαν τῆς αὑτῶν ἀρετῆς· οὐ γὰρ ἐν ταῖς αὑτῶν πόλεσι μόνον ἐπρώτευσαν, οὐδ’ ἐν τοῖς τόποις ἐν οἷς κατῴκουν, ἀλλὰ στρατείας τοῖς Ἕλλησιν ἐπὶ τοὺς βαρβάρους γενομένης, καὶ πολλῶν μὲν ἑκατέρων ἀθροισθέντων,", "st": "9.17"}, {"sp": "N", "t": "οὐδενὸς δὲ τῶν ὀνομαστῶν ἀπολειφθέντος, ἐν τούτοις τοῖς κινδύνοις Ἀχιλλεὺς μὲν ἁπάντων διήνεγκεν. Αἴας δὲ μετ’ ἐκεῖνον ἠρίστευσε, Τεῦκρος δὲ τῆς τε τούτων συγγενείας ἄξιος καὶ τῶν ἄλλων οὐδενὸς χείρων γενόμενος, ἐπειδὴ Τροίαν συνεξεῖλεν, ἀφικόμενος εἰς Κύπρον Σαλαμῖνά τε κατῴκισεν, ὁμώνυμον ποιήσας τῆς πρότερον αὑτῷ πατρίδος οὔσης, καὶ τὸ γένος τὸ νῦν βασιλεῦον κατέλιπεν.", "st": "9.18"}, {"sp": "N", "t": "τὰ μὲν οὖν ἐξ ἀρχῆς Εὐαγόρᾳ παρὰ τῶν προγόνων ὑπάρξαντα τηλικαῦτα τὸ μέγεθός ἐστιν. τοῦτον δὲ τὸν τρόπον τῆς πόλεως κατοικισθείσης κατὰ μὲν ἀρχὰς οἱ γεγονότες ἀπὸ Τεύκρου τὴν βασιλείαν εἶχον, χρόνῳ δ’ ὕστερον ἀφικόμενος ἐκ Φοινίκης ἀνὴρ φυγὰς καὶ πιστευθεὶς ὑπὸ τοῦ τότε βασιλεύοντος καὶ μεγάλας δυναστείας λαβὼν οὐ χάριν ἔσχε τούτων,", "st": "9.19"}, {"sp": "N", "t": "ἀλλὰ κακὸς μὲν γενόμενος περὶ τὸν ὑποδεξάμενον, δεινὸς δὲ πρὸς τὸ πλεονεκτῆσαι, τὸν μὲν εὐεργέτην ἐξέβαλεν, αὐτὸς δὲ τὴν βασιλείαν κατέσχεν. ἀπιστῶν δὲ τοῖς πεπραγμένοις καὶ βουλόμενος ἀσφαλῶς κατασκευάσασθαι τὰ περὶ αὑτὸν τήν τε πόλιν ἐξεβαρβάρωσε καὶ τὴν νῆσον ὅλην βασιλεῖ τῷ μεγάλῳ κατεδούλωσεν.", "st": "9.20"}, {"sp": "N", "t": "οὕτω δὲ τῶν πραγμάτων καθεστώτων καὶ τῶν ἐκγόνων τῶν ἐκείνου τὴν ἀρχὴν ἐχόντων Εὐαγόρας γίγνεται· περὶ οὗ τὰς μὲν φήμας καὶ τὰς μαντείας καὶ τὰς ὄψεις τὰς ἐν τοῖς ὕπνοις γενομένας, ἐξ ὧν μειζόνως ἂν φανείη γεγονὼς ἢ κατ’ ἄνθρωπον, αἱροῦμαι παραλιπεῖν, οὐκ ἀπιστῶν τοῖς λεγομένοις, ἀλλ’ ἵνα πᾶσι ποιήσω φανερὸν ὅτι τοσούτου δέω πλασάμενος εἰπεῖν τι περὶ τῶν ἐκείνῳ πεπραγμένων, ὥστε καὶ τῶν ὑπαρχόντων ἀφίημι τὰ τοιαῦτα περὶ ὧν ὀλίγοι τινὲς ἐπίστανται καὶ μὴ πάντες οἱ πολῖται συνίσασιν. ἄρξομαι δ’ ἐκ τῶν ὁμολογουμένων λέγειν περὶ αὐτοῦ.", "st": "9.21"}, {"sp": "N", "t": "παῖς μὲν γὰρ ὢν ἔσχε κάλλος καὶ ῥώμην καὶ σωφροσύνην, ἅπερ τῶν ἀγαθῶν πρεπωδέστατα τοῖς τηλικούτοις ἐστίν. καὶ τούτων μάρτυρας ἄν τις ποιήσαιτο, τῆς μὲν σωφροσύνης τοὺς συμπαιδευθέντας τῶν πολιτῶν, τοῦ δὲ κάλλους ἅπαντας τοὺς ἰδόντας, τῆς δὲ ῥώμης ἅπαντας τοὺς ἀγῶνας ἐν οἷς ἐκεῖνος τῶν ἡλικιωτῶν ἐκρατίστευσεν.", "st": "9.22"}, {"sp": "N", "t": "ἀνδρὶ δὲ γενομένῳ ταῦτά τε πάντα συνηυξήθη καὶ πρὸς τούτοις ἀνδρία προσεγένετο καὶ σοφία καὶ δικαιοσύνη, καὶ ταῦτ’ οὐ μέσως οὐδ’ ὥσπερ ἑτέροις τισίν, ἀλλ’ ἕκαστον αὐτῶν εἰς ὑπερβολήν· τοσοῦτον γὰρ καὶ ταῖς τοῦ σώματος καὶ ταῖς τῆς ψυχῆς ἀρεταῖς διήνεγκεν,", "st": "9.23"}, {"sp": "N", "t": "ὥσθ’ ὁπότε μὲν αὐτὸν ὁρῷεν οἱ τότε βασιλεύοντες, ἐκπλήττεσθαι καὶ φοβεῖσθαι περὶ τῆς ἀρχῆς, ἡγουμένους οὐχ οἷόν τ’ εἶναι τὸν τοιοῦτον τὴν φύσιν ἐν ἰδιώτου μέρει διαγαγεῖν, ὁπότε δ’ εἰς τοὺς τρόπους ἀποβλέψειαν, οὕτω σφόδρα πιστεύειν, ὥστ’ εἰ καί τις ἄλλος τολμῴη περὶ αὐτοὺς ἐξαμαρτάνειν, νομίζειν Εὐαγόραν αὑτοῖς ἔσεσθαι βοηθόν.", "st": "9.24"}, {"sp": "N", "t": "καὶ τοσοῦτον τῆς δόξης παραλλαττούσης οὐδετέρου τούτων ἐψεύσθησαν· οὔτε γὰρ ἰδιώτης ὢν διετέλεσεν οὔτε περὶ ἐκείνους ἐξήμαρτεν, ἀλλὰ τοσαύτην ὁ δαίμων ἔσχεν αὐτοῦ πρόνοιαν, ὅπως καλῶς λήψεται τὴν βασιλείαν, ὥσθ’ ὅσα μὲν ἀναγκαῖον ἦν παρασκευασθῆναι δι’ ἀσεβείας,", "st": "9.25"}, {"sp": "N", "t": "ταῦτα μὲν ἕτερος ἔπραξεν, ἐξ ὧν δ’ οἷόν τ’ ἦν ὁσίως καὶ δικαίως λαβεῖν τὴν ἀρχήν, Εὐαγόρᾳ διεφύλαξεν. εἷς γὰρ τῶν δυναστευόντων ἐπιβουλεύσας τόν τε τύραννον ἀπέκτεινε καὶ συλλαβεῖν Εὐαγόραν ἐπεχείρησεν, ἡγούμενος οὐ δυνήσεσθαι κατασχεῖν τὴν ἀρχήν, εἰ μὴ κἀκεῖνον ἐκποδὼν ποιήσαιτο.", "st": "9.26"}, {"sp": "N", "t": "διαφυγὼν δὲ τὸν κίνδυνον καὶ σωθεὶς εἰς Σόλους τῆς Κιλικίας οὐ τὴν αὐτὴν γνώμην ἔσχε τοῖς ταῖς τοιαύταις συμφοραῖς περιπίπτουσιν. οἱ μὲν γὰρ ἄλλοι, κἂν ἐκ τυραννίδος ἐκπέσωσι, διὰ τὰς παρούσας τύχας ταπεινοτέρας τὰς ψυχὰς ἔχουσιν· ἐκεῖνος δ’ εἰς τοσοῦτον μεγαλοφροσύνης ἦλθεν, ὥστε τὸν ἄλλον χρόνον ἰδιώτης ὤν, ἐπειδὴ φεύγειν ἠναγκάσθη,", "st": "9.27"}, {"sp": "N", "t": "τυραννεῖν ᾠήθη δεῖν. καὶ τοὺς μὲν πλάνους τοὺς φυγαδικοὺς καὶ τὸ δι’ ἑτέρων ζητεῖν τὴν κάθοδον καὶ θεραπεύειν αὑτοῦ χείρους ὑπερεῖδεν, λαβὼν δὲ ταύτην ἀφορμήν, ἥνπερ χρὴ τοὺς εὐσεβεῖν βουλομένους, ἀμύνεσθαι καὶ μὴ προτέρους ὑπάρχειν, καὶ προελόμενος ἢ κατορθώσας τυραννεῖν ἢ διαμαρτὼν ἀποθανεῖν, παρακαλέσας ἀνθρώπους, ὡς οἱ τοὺς πλείστους λέγοντες, περὶ πεντήκοντα, μετὰ τούτων παρεσκευάζετο ποιεῖσθαι τὴν κάθοδον.", "st": "9.28"}, {"sp": "N", "t": "ὅθεν καὶ μάλιστ’ ἄν τις καὶ τὴν φύσιν τὴν ἐκείνου καὶ τὴν δόξαν ἣν εἶχε παρὰ τοῖς ἄλλοις θεωρήσειεν· μέλλοντος γὰρ πλεῖν μετὰ τοσούτων ἐπὶ τηλικαύτην πρᾶξιν τὸ μέγεθος καὶ πάντων τῶν δεινῶν πλησίον ὄντων οὔτ’ ἐκεῖνος ἠθύμησεν οὔτε τῶν παρακληθέντων οὐδεὶς ἀποστῆναι τῶν κινδύνων ἠξίωσεν, ἀλλ’ οἱ μὲν ὥσπερ θεῷ συνακολουθοῦντες ἅπαντες ἐνέμειναν τοῖς ὡμολογημένοις, ὁ δ’ ὥσπερ ἢ στρατόπεδον ἔχων κρεῖττον τῶν ἀντιπάλων ἢ προειδὼς τὸ συμβησόμενον οὕτω διέκειτο τὴν γνώμην.", "st": "9.29"}, {"sp": "N", "t": "δῆλον δ’ ἐκ τῶν ἔργων· ἀποβὰς γὰρ εἰς τὴν νῆσον οὐχ ἡγήσατο δεῖν χωρίον ἐχυρὸν καταλαβὼν καὶ τὸ σῶμ’ ἐν ἀσφαλείᾳ καταστήσας περιιδεῖν εἴ τινες αὑτῷ τῶν πολιτῶν βοηθήσουσιν· ἀλλ’ εὐθύς, ὥσπερ εἶχε, ταύτης τῆς νυκτὸς διελὼν τοῦ τείχους πυλίδα καὶ ταύτῃ τοὺς μεθ’ αὑτοῦ διαγαγὼν προσέβαλλε πρὸς τὸ βασίλειον.", "st": "9.30"}, {"sp": "N", "t": "καὶ τοὺς μὲν θορύβους τοὺς ἐν τοῖς τοιούτοις καιροῖς γιγνομένους καὶ τοὺς φόβους τοὺς τῶν ἄλλων καὶ τὰς παρακελεύσεις τὰς ἐκείνου τί δεῖ λέγοντα διατρίβειν; γενομένων δ’ αὐτῷ τῶν μὲν περὶ τὸν τύραννον ἀνταγωνιστῶν, τῶν δ’ ἄλλων πολιτῶν θεατῶν, δεδιότες γὰρ τοῦ μὲν τὴν ἀρχήν, τοῦ δὲ τὴν ἀρετήν,", "st": "9.31"}, {"sp": "N", "t": "ἡσυχίαν εἶχον, οὐ πρότερον ἐπαύσατο μαχόμενος καὶ μόνος πρὸς πολλοὺς καὶ μετ’ ὀλίγων πρὸς ἅπαντας τοὺς ἐχθροὺς, πρὶν ἑλεῖν τὸ βασίλειον, καὶ τούς τ’ ἐχθροὺς ἐτιμωρήσατο καὶ τοῖς φίλοις ἐβοήθησεν, ἔτι δὲ τῷ γένει τὰς τιμὰς τὰς πατρίους ἐκομίσατο, καὶ τύραννον αὑτὸν τῆς πόλεως κατέστησεν.", "st": "9.32"}, {"sp": "N", "t": "ἡγοῦμαι μὲν οὖν, εἰ καὶ μηδενὸς ἄλλου μνησθείην, ἀλλ’ ἐνταῦθα καταλίποιμι τὸν λόγον, ῥᾴδιον ἐκ τούτων εἶναι γνῶναι τήν τ’ ἀρετὴν τὴν Εὐαγόρου καὶ τὸ μέγεθος τῶν πεπραγμένων· οὐ μὴν ἀλλ’ ἔτι γε σαφέστερον περὶ ἀμφοτέρων τούτων ἐκ τῶν ἐχομένων οἶμαι δηλώσειν.", "st": "9.33"}, {"sp": "N", "t": "τοσούτων γὰρ τυράννων ἐν ἅπαντι τῷ χρόνῳ γεγενημένων οὐδεὶς φανήσεται τὴν τιμὴν ταύτην κάλλιον ἐκείνου κτησάμενος. εἰ μὲν οὖν πρὸς ἕκαστον αὐτῶν τὰς πράξεις τὰς Εὐαγόρου παραβάλλοιμεν, οὔτ’ ἂν ὁ λόγος ἴσως τοῖς καιροῖς ἁρμόσειεν οὔτ’ ἂν ὁ χρόνος τοῖς λεγομένοις ἀρκέσειεν· ἢν δὲ προελόμενοι τοὺς εὐδοκιμωτάτους ἐπὶ τούτων σκοπῶμεν, οὐδὲν μὲν χεῖρον ἐξετῶμεν, πολὺ δὲ συντομώτερον διαλεχθησόμεθα περὶ αὐτῶν.", "st": "9.34"}, {"sp": "N", "t": "τῶν μὲν οὖ τὰς πατρικὰς βασιλείας παραλαβόντων τίς οὐκ ἂν τοὺς Εὐαγόρου κινδύνους προκρίνειεν; οὐδεὶς γάρ ἐστιν οὕτω ῥᾴθυμος, ὅστις ἂν δέξαιτο παρὰ τῶν προγόνων τὴν ἀρχὴν ταύτην παραλαβεῖν μᾶλλον ἢ κτησάμενος ὥσπερ ἐκεῖνος τοῖς παισὶ τοῖς αὑτοῦ καταλιπεῖν.", "st": "9.35"}, {"sp": "N", "t": "καὶ μὴν τῶν γε παλαιῶν καθόδων αὗται μάλιστ’ εὐδοκιμοῦσιν ἃς παρὰ τῶν ποιητῶν ἀκούομεν· οὗτοι γὰρ οὐ μόνον τῶν γεγενημένων τὰς καλλίστας ἡμῖν ἀπαγγέλλουσιν, ἀλλὰ καὶ παρ’ αὑτῶν καινὰς συντιθέασιν. ἀλλ’ ὅμως οὐδεὶς αὐτῶν μεμυθολόγηκεν, ὅστις οὕτω δεινοὺς καὶ φοβεροὺς ποιησάμενος τοὺς κινδύνους εἰς τὴν αὑτοῦ κατῆλθεν· ἀλλ’ οἱ μὲν πλεῖστοι πεποίηνται διὰ τύχην λαβόντες τὰς βασιλείας, οἱ δὲ μετὰ δόλου καὶ τέχνης περιγενόμενοι τῶν ἐχθρῶν.", "st": "9.36"}, {"sp": "N", "t": "ἀλλὰ μὴν τῶν γ’ ἐπὶ τάδε γεγενημένων, ἴσως δὲ καὶ τῶν ἁπάντων, Κῦρον τὸν Μήδων μὲν ἀφελόμενον τὴν ἀρχήν, Πέρσαις δὲ κτησάμενον, καὶ πλεῖστοι καὶ μάλιστα θαυμάζουσιν. ἀλλ’ ὁ μὲν τῷ Περσῶν στρατοπέδῳ τὸ Μήδων ἐνίκησεν, ὃ πολλοὶ καὶ τῶν Ἑλλήνων καὶ τῶν βαρβάρων ῥᾳδίως ἂν ποιήσειαν· ὁ δὲ διὰ τῆς ψυχῆς τῆς αὑτοῦ καὶ τοῦ σώματος τὰ πλεῖστα φαίνεται τῶν προειρημένων διαπραξάμενος.", "st": "9.37"}, {"sp": "N", "t": "ἔπειτ’ ἐκ μὲν τῆς Κύρου στρατηγίας οὔπω δῆλον ὅτι καὶ τοὺς Εὐαγόρου κινδύνους ἂν ὑπέμεινεν, ἐκ δὲ τῶν τούτῳ πεπραγμένων ἅπασι φανερόν, ὅτι ῥᾳδίως ἂν κἀκείνοις τοῖς ἔργοις ἐπεχείρησεν. πρὸς δὲ τούτοις τῷ μὲν ὁσίως καὶ δικαίως ἅπαντα πέπρακται, τῷ δ’ οὐκ εὐσεβῶς ἔνια συμβέβηκεν· ὁ μὲν γὰρ τοὺς ἐχθροὺς ἀπώλεσε, Κῦρος δὲ τὸν πατέρα τὸν τῆς μητρὸς ἀπέκτεινεν. ὥστ’ εἴ τινες βούλοιντο μὴ τὸ μέγεθος τῶν συμβάντων ἀλλὰ τὴν ἀρετὴν τὴν ἑκατέρου κρίνειν, δικαίως ἂν Εὐαγόραν καὶ τούτου μᾶλλον ἐπαινέσειαν.", "st": "9.38"}, {"sp": "N", "t": "εἰ δὲ δεῖ συντόμως καὶ μηδὲν ὑποστειλάμενον μηδὲ δείσαντα τὸν φθόνον, ἀλλὰ παρρησίᾳ χρησάμενον εἰπεῖν, οὐδεὶς οὔτε θνητὸς οὔθ’ ἡμίθεος οὔτ’ ἀθάνατος εὑρεθήσεται κάλλιον οὐδὲ λαμπρότερον οὐδ’ εὐσεβέστερον λαβὼν ἐκείνου τὴν βασιλείαν. καὶ τούτοις ἐκείνως ἄν τις μάλιστα πιστεύσειεν, εἰ σφόδρα τοῖς λεγομένοις ἀπιστήσας ἐξετάζειν ἐπιχειρήσειεν, ὅπως ἕκαστος ἐτυράννευσεν. φανήσομαι γὰρ οὐκ ἐκ παντὸς τρόπου μεγάλα λέγειν προθυμούμενος, ἀλλὰ διὰ τὴν τοῦ πράγματος ἀλήθειαν οὕτω περὶ αὐτοῦ θρασέως εἰρηκώς.", "st": "9.39"}, {"sp": "N", "t": "εἰ μὲν οὖν ἐπὶ μικροῖς διήνεγκε, τοιούτων ἂν καὶ τῶν λόγων αὐτῷ προσῆκεν ἀξιοῦσθαι· νῦν δ’ ἅπαντες ἂν ὁμολογήσειαν τυραννίδα καὶ τῶν θείων ἀγαθῶν καὶ τῶν ἀνθρωπίνων μέγιστον καὶ σεμνότατον καὶ περιμαχητότατον εἶναι. τὸν δὴ τὸ κάλλιστον τῶν ὄντων κάλλιστα κτησάμενον τίς ἂν ἢ ποιητὴς ἢ λόγων εὑρετὴς ἀξίως τῶν πεπραγμένων ἐπαινέσειεν;", "st": "9.40"}, {"sp": "N", "t": "οὐ τοίνυν ἐν τούτοις ὑπερβαλόμενος ἐν τοῖς ἄλλοις εὑρεθήσεται καταδεέστερος γενόμενος, ἀλλὰ πρῶτον μὲν εὐφυέστατος ὢν τὴν γνώμην καὶ πλεῖστα κατορθοῦν δυνάμενος ὅμως οὐκ ᾠήθη δεῖν ὀλιγωρεῖν οὐδ’ αὐτοσχεδιάζειν περὶ τῶν πραγμάτων, ἀλλ’ ἐν τῷ ζητεῖν καὶ φροντίζειν καὶ βουλεύεσθαι τὸν πλεῖστον τοῦ χρόνου διέτριβεν, ἡγούμενος μέν, εἰ καλῶς τὴν αὑτοῦ φρόνησιν παρασκευάσειεν, καλῶς αὑτῷ καὶ τὴν βασιλείαν ἕξειν, θαυμάζων δ’ ὅσοι τῶν μὲν ἄλλων ἕνεκα τῆς ψυχῆς ποιοῦνται τὴν ἐπιμέλειαν, αὐτῆς δὲ ταύτης μηδὲν τυγχάνουσι φροντίζοντες.", "st": "9.41"}, {"sp": "N", "t": "ἔπειτα καὶ περὶ τῶν πραγμάτων τὴν αὐτὴν διάνοιαν εἶχεν· ὁρῶν γὰρ τοὺς ἄριστα τῶν ὄντων ἐπιμελουμένους ἐλάχιστα λυπουμένους, καὶ τὰς ἀληθινὰς τῶν ῥᾳθυμιῶν οὐκ ἐν ταῖς ἀργίαις ἀλλ’ ἐν ταῖς εὐπραγίαις καὶ καρτερίαις ἐνούσας, οὐδὲν ἀνεξέταστον παρέλειπεν, ἀλλ’ οὕτως ἀκριβῶς καὶ τὰς πράξεις ᾔδει καὶ τῶν πολιτῶν ἕκαστον ἐγίγνωσκεν ὥστε μήτε τοὺς ἐπιβουλεύοντας αὐτῷ φθάνειν μήτε τοὺς ἐπιεικεῖς ὄντας λανθάνειν, ἀλλὰ πάντας τυγχάνειν τῶν προσηκόντων· οὐ γὰρ ἐξ ὧν ἑτέρων ἤκουεν οὔτ’ ἐκόλαζεν οὔτ’ ἐτίμα τοὺς πολίτας, ἀλλ’ ἐξ ὧν αὐτὸς συνῄδει τὰς κρίσεις ἐποιεῖτο περὶ αὐτῶν.", "st": "9.42"}, {"sp": "N", "t": "ἐν τοιαύταις δ’ ἐπιμελείαις αὑτὸν καταστήσας οὐδὲ περὶ τῶν κατὰ τὴν ἡμέραν ἑκάστην προσπιπτόντων οὐδὲ περὶ ἓν πεπλανημένως εἶχεν, ἀλλ’ οὕτω θεοφιλῶς καὶ φιλανθρώπως διῴκει τὴν πόλιν ὥστε τοὺς εἰσαφικνουμένους μὴ μᾶλλον Εὐαγόραν τῆς ἀρχῆς ζηλοῦν ἢ τοὺς ἄλλους τῆς ὑπ’ ἐκείνου βασιλείας· ἅπαντα γὰρ τὸν χρόνον διετέλεσεν οὐδένα μὲν ἀδικῶν, τοὺς δὲ χρηστοὺς τιμῶν, καὶ σφόδρα μὲν ἁπάντων ἄρχων, νομίμως δὲ τοὺς ἐξαμαρτόντας κολάζων·", "st": "9.43"}, {"sp": "N", "t": "οὐδὲν μὲν συμβούλων δεόμενος, ὅμως δὲ τοῖς φίλοις συμβουλευόμενος· πολλὰ μὲν τῶν χρωμένων ἡττώμενος, ἅπαντα δὲ τῶν ἐχθρῶν περιγιγνόμενος· σεμνὸς ὢν οὐ ταῖς τοῦ προσώπου συναγωγαῖς ἀλλὰ ταῖς τοῦ βίου κατασκευαῖς· οὐδὲ πρὸς ἓν ἀτάκτως οὐδ’ ἀνωμάλως διακείμενος, ἀλλ’ ὁμοίως τὰς ἐν τοῖς ἔργοις ὁμολογίας ὥσπερ τὰς ἐν τοῖς λόγοις διαφυλάττων·", "st": "9.44"}, {"sp": "N", "t": "μέγα φρονῶν οὐκ ἐπὶ τοῖς διὰ τύχην ἀλλ’ ἐπὶ τοῖς δι’ αὑτὸν γιγνομένοις· τοὺς μὲν φίλους ταῖς εὐεργεσίαις ὑφ’ αὑτῷ ποιούμενος, τοὺς δ’ ἄλλους τῇ μεγαλοψυχίᾳ καταδουλούμενος· φοβερὸς ὢν οὐ τῷ πολλοῖς χαλεπαίνειν, ἀλλὰ τῷ πολὺ τὴν τῶν ἄλλων φύσιν ὑπερβάλλειν· ἡγούμενος τῶν ἡδονῶν, ἀλλ’ οὐκ ἀγόμενος ὑπ’ αὐτῶν· ὀλίγοις πόνοις πολλὰς ῥᾳστώνας κτώμενος, ἀλλ’ οὐ διὰ μικρὰς ῥᾳθυμίας μεγάλους πόνους ὑπολειπόμενος·", "st": "9.45"}, {"sp": "N", "t": "ὅλως οὐδὲν παραλείπων ὧν προσεῖναι δεῖ τοῖς βασιλεῦσιν, ἀλλ’ ἐξ ἑκάστης τῆς πολιτείας ἐξειλεγμένος τὸ βέλτιστον, καὶ δημοτικὸς μὲν ὢν τῇ τοῦ πλήθους θεραπείᾳ, πολιτικὸς δὲ τῇ τῆς πόλεως ὅλης διοικήσει, στρατηγικὸς δὲ τῇ πρὸς τοὺς κινδύνους εὐβουλίᾳ, τυραννικὸς δὲ τῷ πᾶσι τούτοις διαφέρειν. καὶ ταῦθ’ ὅτι προσῆν Εὐαγόρᾳ, καὶ πλείω τούτων, ἐξ αὐτῶν τῶν ἔργων ῥᾴδιον καταμαθεῖν.", "st": "9.46"}, {"sp": "N", "t": "παραλαβὼν γὰρ τὴν πόλιν ἐκβεβαρβαρωμένην καὶ διὰ τὴν Φοινίκων ἀρχὴν οὔτε τοὺς Ἕλληνας προσδεχομένην οὔτε τέχνας ἐπισταμένην οὔτ’ ἐμπορίῳ χρωμένην οὔτε λιμένα κεκτημένην ταῦτά τε πάντα διώρθωσε καὶ πρὸς τούτοις καὶ χώραν πολλὴν προσεκτήσατο καὶ τείχη προσπεριεβάλετο καὶ τριήρεις ἐναυπηγήσατο καὶ ταῖς ἄλλαις κατασκευαῖς οὕτως ηὔξησε τὴν πόλιν ὥστε μηδεμιᾶς τῶν Ἑλληνίδων ἀπολελεῖφθαι, καὶ δύναμιν τοσαύτην ἐνεποίησεν ὥστε πολλοὺς φοβεῖσθαι τῶν πρότερον καταφρονούντων αὐτῆς.", "st": "9.47"}, {"sp": "N", "t": "καίτοι τηλικαύτας ἐπιδόσεις τὰς πόλεις λαμβάνειν οὐχ οἷόν τ’ ἐστίν, ἢν μὴ τις αὐτὰς διοικῇ τοιούτοις ἤθεσιν οἵοις Εὐαγόρας μὲν εἶχεν ἐγὼ δ’ ὀλίγῳ πρότερον ἐπειράθην διελθεῖν. ὥστ’ οὐ δέδοικα μὴ φανῶ μείζω λέγων τῶν ἐκείνῳ προσόντων, ἀλλὰ μὴ πολὺ λίαν ἀπολειφθῶ τῶν πεπραγμένων αὐτῷ.", "st": "9.48"}, {"sp": "N", "t": "τίς γὰρ ἂν ἐφίκοιτο τοιαύτης φύσεως, ὃς οὐ μόνον τὴν αὑτοῦ πόλιν πλείονος ἀξίαν ἐποίησεν ἀλλὰ καὶ τὸν τόπον ὅλον τὸν περιέχοντα τὴν νῆσον ἐπὶ πραότητα καὶ μετριότητα προήγαγεν; πρὶν μέν γε λαβεῖν Εὐαγόραν τὴν ἀρχὴν οὕτως ἀπροσοίστως καὶ χαλεπῶς εἶχον, ὥστε καὶ τῶν ἀρχόντων τούτους ἐνόμιζον εἶναι βελτίστους οἵτινες ὠμότατα πρὸς τοὺς Ἕλληνας διακείμενοι τυγχάνοιεν·", "st": "9.49"}, {"sp": "N", "t": "νῦν δὲ τοσοῦτον μεταπεπτώκασιν ὥσθ’ ἁμιλλᾶσθαι μὲν οἵτινες αὐτῶν δόξουσι φιλέλληνες εἶναι μάλιστα, παιδοποιεῖσθαι δὲ τοὺς πλείστους αὐτῶν γυναῖκας λαμβάνοντας παρ’ ἡμῶν, χαίρειν δὲ καὶ τοῖς κτήμασι καὶ τοῖς ἐπιτηδεύμασι τοῖς Ἑλληνικοῖς μᾶλλον ἢ τοῖς παρὰ σφίσιν αὐτοῖς, πλείους δὲ καὶ τῶν περὶ τὴν μουσικὴν καὶ τῶν περὶ τὴν ἄλλην παίδευσιν ἐν τούτοις τοῖς τόποις διατρίβειν ἢ παρ’ οἷς πρότερον εἰωθότες ἦσαν. καὶ τούτων ἁπάντων οὐδεὶς ὅστις οὐκ ἂν Εὐαγόραν αἴτιον εἶναι προσομολογήσειεν.", "st": "9.50"}, {"sp": "N", "t": "μέγιστον δὲ τεκμήριον καὶ τοῦ τρόπου καὶ τῆς ὁσιότητος τῆς ἐκείνου· τῶν γὰρ Ἑλλήνων πολλοὶ καὶ καλοὶ κἀγαθοὶ τὰς αὑτῶν πατρίδας ἀπολιπόντες ἦλθον εἰς Κύπρον οἰκήσοντες, ἡγούμενοι κουφοτέραν καὶ νομιμωτέραν εἶναι τὴν Εὐαγόρου βασιλείαν τῶν οἴκοι πολιτειῶν· ὧν τοὺς μὲν ἄλλους ὀνομαστὶ διελθεῖν πολὺ ἂν ἔργον εἴη·", "st": "9.51"}, {"sp": "N", "t": "Κόνωνα δὲ τὸν διὰ πλείστας ἀρετὰς πρωτεύσαντα τῶν Ἑλλήνων τίς οὐκ οἶδεν ὅτι δυστυχησάσης τῆς πόλεως ἐξ ἁπάντων ἐκλεξάμενος ὡς Εὐαγόραν ἦλθε, νομίσας καὶ τῷ σώματι βεβαιοτάτην εἶναι τὴν παρ’ ἐκείνῳ καταφυγὴν καὶ τῇ πόλει τάχιστ’ ἂν αὐτὸν γενέσθαι βοηθόν. καὶ πολλὰ πρότερον ἤδη κατωρθωκὼς οὐδὲ περὶ ἑνὸς πώποτε πράγματος ἔδοξεν ἄμεινον ἢ περὶ τούτου βουλεύσασθαι·", "st": "9.52"}, {"sp": "N", "t": "συνέβη γὰρ αὐτῷ διὰ τὴν ἄφιξιν τὴν εἰς Κύπρον καὶ ποιῆσαι καὶ παθεῖν πλεῖστ’ ἀγαθά. πρῶτον μὲν γὰρ οὐκ ἔφθασαν ἀλλήλοις πλησιάσαντες καὶ περὶ πλείονος ἐποιήσαντο σφᾶς αὐτοὺς ἢ τοὺς πρότερον οἰκείους ὄντας. ἔπειτα περί τε τῶν ἄλλων ὁμονοοῦντες ἅπαντα τὸν χρόνον διετέλεσαν καὶ περὶ τῆς ἡμετέρας πόλεως τὴν αὐτὴν γνώμην εἶχον.", "st": "9.53"}, {"sp": "N", "t": "ὁρῶντες γὰρ αὐτὴν ὑπὸ Λακεδαιμονίοις οὖσαν καὶ μεγάλῃ μεταβολῇ κεχρημένην λυπηρῶς καὶ βαρέως ἔφερον, ἀμφότεροι προσήκοντα ποιοῦντες· τῷ μὲν γὰρ ἦν φύσει πατρίς, τὸν δὲ διὰ πολλὰς καὶ μεγάλας εὐεργεσίας νόμῳ πολίτην ἐπεποίηντο. σκοπουμένοις δ’ αὐτοῖς ὅπως τῶν συμφορῶν αὐτὴν ἀπαλλάξουσι, ταχὺν τὸν καιρὸν Λακεδαιμόνιο παρεσκεύασαν· ἄρχοντες γὰρ τῶν Ἑλλήνων καὶ κατὰ γῆν καὶ κατὰ θάλατταν εἰς τοῦτ’ ἀπληστίας ἦλθον, ὥστε καὶ τὴν Ἀσίαν κακῶς ποιεῖν ἐπεχείρησαν.", "st": "9.54"}, {"sp": "N", "t": "λαβόντες δ’ ἐκεῖνοι τοῦτον τὸν καιρὸν καὶ τῶν στρατηγῶν τῶν βασιλέως ἀπορούντων ὅ τι χρήσωνται τοῖς πράγμασιν, ἐδίδασκον αὐτοὺς μὴ κατὰ γῆν ἀλλὰ κατὰ θάλατταν ποιεῖσθαι τὸν πόλεμον τὸν πρὸς Λακεδαιμονίους, νομίζοντες, εἰ μὲν πεζὸν στρατόπεδον καταστήσαιντο καὶ τούτῳ περιγένοιντο, τὰ περὶ τὴν ἤπειρον μόνον καλῶς ἕξειν, εἰ δὲ κατὰ θάλατταν κρατήσειαν, ἅπασαν τὴν Ἑλλάδα τῆς νίκης ταύτης μεθέξειν.", "st": "9.55"}, {"sp": "N", "t": "ὅπερ συνέβη· πεισθέντων γὰρ ταῦτα τῶν στρατηγῶν καὶ ναυτικοῦ συλλεγέντος Λακεδαιμόνιοι μὲν κατεναυμαχήθησαν καὶ τῆς ἀρχῆς ἀπεστερήθησαν, οἱ δ’ Ἕλληνες ἠλευθερώθησαν, ἡ δὲ πόλις ἡμῶν τῆς τε παλαιᾶς δόξης μέρος τι πάλιν ἀνέλαβε καὶ τῶ συμμάχων ἡγεμὼν κατέστη. καὶ ταῦτ’ ἐπράχθη Κόνωνος μὲν στρατηγοῦντος, Εὐαγόρου δὲ τοῦτό τε παρασχόντος καὶ τῆς δυνάμεως τὴν πλείστην παρασκευάσαντος.", "st": "9.56"}, {"sp": "N", "t": "ὑπὲρ ὧν ἡμεῖς μὲν αὐτοὺς ἐτιμήσαμεν ταῖς μεγίσταις τιμαῖς καὶ τὰς εἰκόνας αὐτῶν ἐστήσαμεν οὗπερ τὸ τοῦ Διὸς ἄγαλμα τοῦ σωτῆρος, πλησίον ἐκείνου τε καὶ σφῶν αὐτῶν, ἀμφοτέρων ὑπόμνημα καὶ τοῦ μεγέθους τῆς εὐεργεσίας καὶ τῆς φιλίας τῆς πρὸς ἀλλήλους. βασιλεὺς δ’ οὐ τὴν αὐτὴν γνώμην ἔσχε περὶ αὐτῶν, ἀλλ’ ὅσῳ μείζω καὶ πλείονος ἄξια κατειργάσαντο, τοσούτῳ μᾶλλον ἔδεισεν αὐτούς. περὶ μὲν οὖν Κόνωνος ἄλλος ἡμῖν ἔσται λόγος· ὅτι δὲ πρὸς Εὐαγόραν οὕτως ἔσχεν, οὐδ’ αὐτὸς λαθεῖν ἐζήτησεν.", "st": "9.57"}, {"sp": "N", "t": "φαίνεται γὰρ μᾶλλον μὲν σπουδάσας περὶ τὸν ἐν Κύπρῳ πόλεμον ἢ περὶ τοὺς ἄλλους ἅπαντας, μείζω δὲ καὶ χαλεπώτερον ἐκεῖνον ἀνταγωνιστὴν νομίσας ἢ Κῦρον τὸν περὶ τῆς βασιλείας ἀμφισβητήσαντα. μέγιστον δὲ τεκμήριον· τοῦ μὲν γὰρ ἀκούων τὰς παρασκευὰς τοσοῦτον κατεφρόνησεν ὥστε διὰ τὸ μὴ φροντίζειν μικροῦ δεῖν ἔλαθεν αὐτὸν ἐπὶ τὸ βασίλειον ἐπιστάς· πρὸς δὲ τοῦτον οὕτως ἐκ πολλοῦ περιδεῶς ἔσχεν, ὥστε μεταξὺ πάσχων εὖ πολεμεῖν πρὸς αὐτὸν ἐπεχείρησε, δίκαια μὲν οὐ ποιῶν, οὐ μὴν παντάπασιν ἀλόγως βουλευσάμενος.", "st": "9.58"}, {"sp": "N", "t": "ἠπίστατο μὲν γὰρ πολλοὺς καὶ τῶν Ἑλλήνων καὶ τῶν βαρβάρων ἐκ ταπεινῶν καὶ φαύλων πραγμάτων μεγάλας δυναστείας κατεργασαμένους, ᾐσθάνετο δὲ τὴν Εὐαγόρου μεγαλοψυχίαν καὶ τὰς ἐπιδόσεις αὐτῷ καὶ τῆς δόξης καὶ τῶν πραγμάτων οὐ κατὰ μικρὸν γιγνομένας, ἀλλὰ καὶ τὴν φύσιν ἀνυπέρβλητον ἔχοντα καὶ τὴν τύχην αὐτῷ συναγωνιζομένην·", "st": "9.59"}, {"sp": "N", "t": "ὥστ’ οὐχ ὑπὲρ τῶν γεγενημένων ὀργιζόμενος ἀλλὰ περὶ τῶν μελλόντων φοβούμενος, οὐδὲ περὶ Κύπρου μόνον δεδιώς, ἀλλὰ πολὺ περὶ μειζόνων ἐποιήσατο τὸν πόλεμον πρὸς αὐτόν. οὕτω δ’ οὖν ὥρμησεν ὥστ’ εἰς τὴν στρατείαν ταύτην πλέον ἢ τάλαντα πεντακισχίλια καὶ μύρια κατηνάλωσεν.", "st": "9.60"}, {"sp": "N", "t": "ἀλλ’ ὅμως Εὐαγόρας πάσαις ἀπολελειμμένος ταῖς δυνάμεσιν, ἀντιτάξας τὴν αὑτοῦ γνώμην πρὸς τὰς οὕτως ὑπερμεγέθεις παρασκευάς, ἐπέδειξεν αὑτὸν ἐν τούτοις πολὺ θαυμαστότερον ἢ τοῖς ἄλλοις τοῖς προειρημένοις. ὅτε μὲν γὰρ αὐτὸν εἴων εἰρήνην ἄγειν,", "st": "9.61"}, {"sp": "N", "t": "τὴν αὑτοῦ πόλιν μόνην εἶχεν· ἐπειδὴ δ’ ἠναγκάσθη πολεμεῖν, τοιοῦτος ἦν καὶ τοιοῦτον εἶχε Πνυταγόραν τὸν υἱὸν τὸν αὑτοῦ συναγωνιστὴν ὥστε μικροῦ μὲν ἐδέησε Κύπρον ἅπασαν κατασχεῖν, Φοινίκην δ’ ἐπόρθησε, Τύρον δὲ κατὰ κράτος εἷλε, Κιλικίαν δὲ βασιλέως ἀπέστησε, τοσούτους δὲ τῶν πολεμίων ἀπώλεσεν ὥστε πολλοὺς Περσῶν πενθοῦντας τὰς αὑτῶν συμφορὰς μεμνῆσθαι τῆς ἀρετῆς τῆς ἐκείνου·", "st": "9.62"}, {"sp": "N", "t": "τελευτῶν δ’ οὕτως ἐνέπλησεν αὐτοὺς τοῦ πολεμεῖν, ὥστ’ εἰθισμένων τὸν ἄλλον χρόνον τῶν βασιλέων μὴ διαλλάττεσθαι τοῖς ἀποστᾶσι πρὶν κύριοι γένοιντο τῶν σωμάτων, ἄσμενοι τὴν εἰρήνην ἐποιήσαντο, λύσαντες μὲν τὸν νόμον τοῦτον, οὐδὲν δὲ κινήσαντες τῆς Εὐαγόρου τυραννίδος.", "st": "9.63"}, {"sp": "N", "t": "καὶ Λακεδαιμονίων μὲν τῶν καὶ δόξαν καὶ δύναμιν μεγίστην ἐχόντων κατ’ ἐκεῖνον τὸν χρόνον ἐντὸς τριῶν ἐτῶν ἀφείλετο τὴν ἀρχήν, Εὐαγόρα δὲ πολεμήσας ἔτη δέκα τῶν αὐτῶν κύριον αὐτὸν κατέλιπεν, ὧνπερ ἦν καὶ πρὶν εἰς τὸν πόλεμον εἰσελθεῖν. ὃ δὲ πάντων δεινότατον· τὴν γὰρ πόλιν, ἣν Εὐαγόρας ἑτέρου τυραννοῦντος μετὰ πεντήκοντ’ ἀνδρῶν εἷλε, ταύτην βασιλεὺς ὁ μέγας τοσαύτην δύναμιν ἔχων οὐχ οἷός τ’ ἐγένετο χειρώσασθαι.", "st": "9.64"}, {"sp": "N", "t": "καίτοι πῶς ἄν τις τὴν ἀνδρίαν ἢ τὴν φρόνησιν ἢ σύμπασαν τὴν ἀρετὴν τὴν Εὐαγόρου φανερώτερον ἐπιδείξειεν ἢ διὰ τοιούτων ἔργων καὶ κινδύνων; οὐ γὰρ μόνον φανεῖται τοὺς ἄλλους πολέμους, ἀλλὰ καὶ τὸν τῶν ἡρώων ὑπερβαλόμενος, τὸν ὑπὸ πάντων ἀνθρώπων ὑμνούμενον. οἱ μὲν γὰρ μεθ’ ἁπάσης τῆς Ἑλλάδος Τροίαν μόνην εἷλον, ὁ δὲ μίαν πόλιν ἔχων πρὸς ἅπασαν τὴν Ἀσίαν ἐπολέμησεν· ὥστ’ εἰ τοσοῦτοι τὸ πλῆθος ἐγκωμιάζειν αὐτὸν ἠβουλήθησαν ὅσοι περ ἐκείνους, πολὺ ἂν μείζω καὶ τὴν δόξαν αὐτῶν ἔλαβεν.", "st": "9.65"}, {"sp": "N", "t": "τίνα γὰρ εὑρήσομεν τῶν τότε γενομένων, εἰ τοὺς μύθους ἀφέντες τὴν ἀλήθειαν σκοποῖμεν, τοιαῦτα διαπεπραγμένον, ἢ τίνα τοσούτων μεταβολῶν ἐν τοῖς πράγμασιν αἴτιον γεγενημένον; ὃς αὑτὸν μὲν ἐξ ἰδιώτου τύραννον κατέστησε, τὸ δὲ γένος ἅπαν ἀπεληλαμένον τῆς πολιτείας εἰς τὰς προσηκούσας τιμὰς πάλιν ἐπανήγαγε, τοὺς δὲ πολίτας ἐκ βαρβάρων μὲν Ἕλληνας ἐποίησεν,", "st": "9.66"}, {"sp": "N", "t": "ἐξ ἀνάνδρων δὲ πολεμικούς, ἐξ ἀδόξων δ’ ὀνομαστούς, τὸν δὲ τόπον ἄμικτον ὅλον παραλαβὼν καὶ παντάπασιν ἐξηγριωμένον ἡμερώτερον καὶ πραότερον κατέστησεν, ἔτι δὲ πρὸς τούτοις εἰς ἔχθραν μὲν βασιλεῖ καταστὰς οὕτως αὐτὸν ἠμύνατο καλῶς ὥστ’ ἀείμνηστον γεγενῆσθαι τὸν πόλεμον τὸν περὶ Κύπρον, ὅτε δ’ ἦν αὐτῷ σύμμαχος, τοσούτῳ χρησιμώτερον αὑτὸν παρέσχε τῶν ἄλλων", "st": "9.67"}, {"sp": "N", "t": "ὥσθ’ ὁμολογουμένως μεγίστην αὐτῷ συμβαλέσθαι δύναμιν εἰς τὴν ναυμαχίαν τὴν περὶ Κνίδον, ἧς γενομένης βασιλεὺς μὲν ἁπάσης τῆς Ἀσίας κύριος κατέστη, Λακεδαιμόνιοι δ’ ἀντὶ τοῦ τὴν ἤπειρον πορθεῖν περὶ τῆς αὑτῶν κινδυνεύειν ἠναγκάσθησαν, οἱ δ’ Ἕλληνες ἀντὶ δουλείας αὐτονομίας ἔτυχον, Ἀθηναῖοι δὲ τοσοῦτον ἐπέδοσαν ὥστε τοὺς πρότερον αὐτῶν ἄρχοντας ἐλθεῖν αὐτοῖς τὴν ἀρχὴν δώσοντας.", "st": "9.68"}, {"sp": "N", "t": "ὥστ’ εἴ τις ἔροιτό με, τί νομίζω μέγιστον εἶναι τῶν Εὐαγόρᾳ πεπραγμένων, πότερον τὰς ἐπιμελείας καὶ τὰς παρασκευὰς τὰς πρὸς Λακεδαιμονίους ἐξ ὧν τὰ προειρημένα γέγονεν, ἢ τὸν τελευταῖον πόλεμον, ἢ τὴν κατάληψιν τῆς βασιλείας, ἢ τὴν ὅλην τῶν πραγμάτων διοίκησιν, εἰς πολλὴν ἀπορίαν ἂν κατασταίην· ἀεὶ γάρ μοι δοκεῖ μέγιστον εἶναι καὶ θαυμαστότατον καθ’ ὅ τι ἂν αὐτῶν ἐπιστήσω τὴν διάνοιαν.", "st": "9.69"}, {"sp": "N", "t": "ὥστ’ εἴ τινες τῶν προγεγενημένων δι’ ἀρετὴν ἀθάνατοι γεγόνασιν, οἶμαι κἀκεῖνον ἠξιῶσθαι ταύτης τῆς δωρεᾶς, σημείοις χρώμενος ὅτι καὶ τὸν ἐνθάδε χρόνον εὐτυχέστερον καὶ θεοφιλέστερον ἐκείνων διαβεβίωκεν. τῶν μὲν γὰρ ἡμιθέων τοὺς πλείστους καὶ τοὺς ὀνομαστοτάτους εὑρήσομεν ταῖς μεγίσταις συμφοραῖς περιπεσόντας, Εὐαγόρας δ’ οὐ μόνον θαυμαστότατος ἀλλὰ καὶ μακαριστότατος ἐξ ἀρχῆς ὢν διετέλεσεν.", "st": "9.70"}, {"sp": "N", "t": "τί γὰρ ἀπέλιπεν εὐδαιμονίας, ὃς τοιούτων μὲν προγόνων ἔτυχεν οἵων οὐδεὶς ἄλλος, πλὴν εἴ τις ἀπὸ τῶν αὐτῶν ἐκείνῳ γέγονεν, τοσοῦτον δὲ καὶ τῷ σώματι καὶ τῇ γνώμῃ τῶν ἄλλων διήνεγκεν ὥστε μὴ μόνον Σαλαμῖνος ἀλλὰ καὶ τῆς Ἀσίας ἁπάσης ἄξιος εἶναι τυραννεῖν, κάλλιστα δὲ κτησάμενος τὴν βασιλείαν ἐν ταύτῃ τὸν βίον διετέλεσε, θνητὸς δὲ γενόμενος ἀθάνατον τὴν περὶ αὑτοῦ μνήμην κατέλιπε, τοσοῦτον δ’ ἐβίω χρόνον ὥστε μήτε τοῦ γήρως ἄμοιρος γενέσθαι μήτε τῶν νόσων μετασχεῖν τῶν διὰ ταύτην τὴν ἡλικίαν γιγνομένων.", "st": "9.71"}, {"sp": "N", "t": "πρὸς δὲ τούτοις, ὃ δοκεῖ σπανιώτατον εἶναι καὶ χαλεπώτατον, εὐπαιδίας τυχεῖν ἅμα καὶ πολυπαιδίας, οὐδὲ τούτου διήμαρτεν, ἀλλὰ καὶ τοῦτ’ αὐτῷ συνέπεσεν. καὶ τὸ μέγιστον, ὅτι τῶν ἐξ αὑτοῦ γεγονότων οὐδένα κατέλιπεν ἰδιωτικοῖς ὀνόμασι προσαγορευόμενον, ἀλλὰ τὸν μὲν βασιλέα καλούμενον, τοὺς δ’ ἄνακτας, τὰς δ’ ἀνάσσας. ὥστ’ εἴ τινες τῶν ποιητῶν περί τινος τῶν προγεγενημένων ὑπερβολαῖς κέχρηνται, λέγοντες ὡς ἦν θεὸς ἐν ἀνθρώποις ἢ δαίμων θνητός, ἅπαντα τὰ τοιαῦτα περὶ τὴν ἐκείνου φύσιν ῥηθῆναι μάλιστ’ ἂν ἁρμόσειεν.", "st": "9.72"}, {"sp": "N", "t": "τῶν μὲν οὖν εἰς Εὐαγόραν πολλὰ μὲν οἶμαι παραλιπεῖν· ὑστερίζω γὰρ τῆς ἀκμῆς τῆς ἐμαυτοῦ, μεθ’ ἧς ἀκριβέστερον καὶ φιλοπονώτερον ἐξειργασάμην ἂν τὸν ἔπαινον τοῦτον· οὐ μὴν ἀλλὰ καὶ νῦν, ὅσον κατὰ τὴν ἐμὴν δύναμιν, οὐκ ἀνεγκωμίαστός ἐστιν. ἐγὼ δ’, ὦ Νικόκλεις, ἡγοῦμαι καλὰ μὲν εἶναι μνημεῖα καὶ τὰς τῶν σωμάτων εἰκόνας, πολὺ μέντοι πλείονος ἀξίας τὰς τῶν πράξεων καὶ τῆς διανοίας, ἃς ἐν τοῖς λόγοις ἄν τις μόνον τοῖς τεχνικῶς ἔχουσι θεωρήσειεν.", "st": "9.73"}, {"sp": "N", "t": "προκρίνω δὲ ταύτας πρῶτον μὲν εἰδὼς τοὺς καλοὺς κἀγαθοὺς τῶν ἀνδρῶν οὐχ οὕτως ἐπὶ τῷ κάλλει τοῦ σώματος σεμνυνομένους ὡς ἐπὶ τοῖς ἔργοις καὶ τῇ γνώμῃ φιλοτιμουμένους· ἔπειθ’ ὅτι τοὺς μὲν τύπους ἀναγκαῖον παρὰ τούτοις εἶναι μόνοις, παρ’ οἷς ἂν σταθῶσι, τοὺς δὲ λόγους ἐξενεχθῆναί θ’ οἷόν τ’ ἐστὶν εἰς τὴν Ἑλλάδα καί, διαδοθέντας ἐν ταῖς τῶν εὖ φρονούντων διατριβαῖς, ἀγαπᾶσθαι παρ’ οἷς κρεῖττόν ἐστιν ἢ παρὰ τοῖς ἄλλοις ἅπασιν εὐδοκιμεῖν·", "st": "9.74"}, {"sp": "N", "t": "πρὸς δὲ τούτοις ὅτι τοῖς μὲν πεπλασμένοις καὶ τοῖς γεγραμμένοις οὐδεὶς ἂν τὴν τοῦ σώματος φύσιν ὁμοιώσειε, τοὺς δὲ τρόπους τοὺς ἀλλήλων καὶ τὰς διανοίας τὰς ἐν τοῖς λεγομένοις ἐνούσας ῥᾴδιόν ἐστι μιμεῖσθαι τοῖς μὴ ῥᾳθυμεῖν αἱρουμένοις, ἀλλὰ χρηστοῖς εἶναι βουλομένοις.", "st": "9.75"}, {"sp": "N", "t": "ὧν ἕνεκα καὶ μᾶλλον ἐπεχείρησα γράφειν τὸν λόγον τοῦτον, ἡγούμενος καὶ σοὶ καὶ τοῖς σοῖς παισὶ καὶ τοῖς ἄλλοις τοῖς ἀπ’ Εὐαγόρου γεγονόσι πολὺ καλλίστην ἂν γενέσθαι ταύτην παράκλησιν, εἴ τις ἀθροίσας τὰς ἀρετὰς τὰς ἐκείνου καὶ τῷ λόγῳ κοσμήσας παραδοίη θεωρεῖν ὑμῖν καὶ συνδιατρίβειν αὐταῖς.", "st": "9.76"}, {"sp": "N", "t": "τοὺς μὲν γὰρ ἄλλους προτρέπομεν ἐπὶ τὴν φιλοσοφίαν ἑτέρους ἐπαινοῦντες, ἵνα ζηλοῦντες τοὺς εὐλογουμένους τῶν αὐτῶν ἐκείνοις ἐπιτηδευμάτων ἐπιθυμῶσιν, ἐγὼ δὲ σὲ καὶ τοὺς σοὺς οὐκ ἀλλοτρίοις παραδείγμασι χρώμενος ἀλλ’ οἰκείοις παρακαλῶ, καὶ συμβουλεύω προσέχειν τὸν νοῦν, ὅπως καὶ λέγειν καὶ πράττειν μηδενὸς ἧττον δυνήσει τῶν Ἑλλήνων.", "st": "9.77"}, {"sp": "N", "t": "καὶ μὴ νόμιζέ με καταγιγνώσκειν, ὡς νῦν ἀμελεῖς, ὅτι πολλάκις σοι διακελεύομαι περὶ τῶν αὐτῶν. οὐ γὰρ οὔτ’ ἐμὲ λέληθας οὔτε τοὺς ἄλλους ὅτι καὶ πρῶτος καὶ μόνος τῶν ἐν τυραννίδι καὶ πλούτῳ καὶ τρυφαῖς ὄντων φιλοσοφεῖν καὶ πονεῖν ἐπικεχείρηκας, οὐδ’ ὅτι πολλοὺς τῶν βασιλέων ποιήσεις ζηλώσαντας τὴν σὴν παίδευσιν τούτων τῶν διατριβῶν ἐπιθυμεῖν, ἀφεμένους ἐφ’ οἷς νῦν λίαν χαίρουσιν.", "st": "9.78"}, {"sp": "N", "t": "ἀλλ’ ὅμως ἐγὼ ταῦτ’ εἰδὼς οὐδὲν ἧττον καὶ ποιῶ καὶ ποιήσω ταὐτὸν ὅπερ ἐν τοῖς γυμνικοῖς ἀγῶσιν οἱ θεαταί· καὶ γὰρ ἐκεῖνοι παρακελεύονται τῶν δρομέων οὐ τοῖς ἀπολελειμμένοις ἀλλὰ τοῖς περὶ τῆς νίκης ἁμιλλωμένοις.", "st": "9.79"}, {"sp": "N", "t": "ἐμὸν μὲν οὖν ἔργον καὶ τῶν ἄλλων φίλων τοιαῦτα καὶ λέγειν καὶ γράφειν ἐξ ὧν μέλλομέν σε παροξύνειν ὀρέγεσθαι τούτων, ὧνπερ καὶ νῦν τυγχάνεις ἐπιθυμῶν· σοὶ δὲ προσήκει μηδὲν ἐλλείπειν ἀλλ’ ὥσπερ ἐν τῷ παρόντι καὶ τὸν λοιπὸν χρόνον ἐπιμελεῖσθαι καὶ τὴν ψυχὴν ἀσκεῖν, ὅπως ἄξιος ἔσει καὶ τοῦ πατρὸς καὶ τῶν ἄλλων προγόνων. ὡς ἅπασι μὲν προσήκει περὶ πολλοῦ ποιεῖσθαι τὴν φρόνησιν, μάλιστα δ’ ὑμῖν τοῖς πλείστων καὶ μεγίστων κυρίοις οὖσιν.", "st": "9.80"}, {"sp": "N", "t": "χρὴ δ’ οὐκ ἀγαπᾶν, εἰ τῶν παρόντων τυγχάνεις ὢν ἤδη κρείττων, ἀλλ’ ἀγανακτεῖν, εἰ τοιοῦτος μὲν ὢν αὐτὸς τὴν φύσιν, γεγονὼς δὲ τὸ μὲν παλαιὸν ἀπὸ Διός, τὸ δ’ ὑπογυιότατον ἐξ ἀνδρὸς τοιούτου τὴν ἀρετήν, μὴ πολὺ διοίσεις καὶ τῶν ἄλλων καὶ τῶν ἐν ταῖς αὐταῖς σοι τιμαῖς ὄντων. ἔστι δ’ ἐπὶ σοὶ μὴ διαμαρτεῖν τούτων· ἂν γὰρ ἐμμένῃς τῇ φιλοσοφίᾳ καὶ τοσοῦτον ἐπιδιδῷς ὅσον περ νῦν, ταχέως γενήσει τοιοῦτος οἷόν σε προσήκει.", "st": "9.81"}, {"sp": "HDR", "t": "Ἑλένης ἐγκώμιον", "st": "10"}, {"sp": "N", "t": "εἰσί τινες οἳ μέγα φρονοῦσιν, ἢν ὑπόθεσιν ἄτοπον καὶ παράδοξον ποιησάμενοι περὶ ταύτης ἀνεκτῶς εἰπεῖν δυνηθῶσι· καὶ καταγεγηράκασιν οἱ μὲν οὐ φάσκοντες οἷόν τ’ εἶναι ψευδῆ λέγειν οὐδ’ ἀντιλέγειν οὐδὲ δύω λόγω περὶ τῶν αὐτῶν πραγμάτων ἀντειπεῖν, οἱ δὲ διεξιόντες ὡς ἀνδρία καὶ σοφία καὶ δικαιοσύνη ταὐτόν ἐστι, καὶ φύσει μὲν οὐδὲν αὐτῶν ἔχομεν, μία δ’ ἐπιστήμη καθ’ ἁπάντων ἐστίν· ἄλλοι δὲ περὶ τὰς ἔριδας διατρίβουσι τὰς οὐδὲν μὲν ὠφελούσας, πράγματα δὲ παρέχειν τοῖς πλησιάζουσι δυναμένας.", "st": "10.1"}, {"sp": "N", "t": "ἐγὼ δ’ εἰ μὲν ἑώρων νεωστὶ τὴν περιεργίαν ταύτην ἐν τοῖς λόγοις ἐγγεγενημένην καὶ τούτους ἐπὶ τῇ καινότητι τῶν εὑρημένων φιλοτιμουμένους, οὐκ ἂν ὁμοίως ἐθαύμαζον αὐτῶν· νῦν δὲ τίς ἐστιν οὕτως ὀψιμαθής, ὅστις οὐκ οἶδε Πρωταγόραν καὶ τοὺς κατ’ ἐκεῖνον τὸν χρόνον γενομένους σοφιστάς, ὅτι καὶ τοιαῦτα καὶ πολὺ τούτων πραγματωδέστερα συγγράμματα κατέλιπον ἡμῖν;", "st": "10.2"}, {"sp": "N", "t": "πῶς γὰρ ἄν τις ὑπερβάλοιτο Γοργίαν τὸν τολμήσαντα λέγειν ὡς οὐδὲν τῶν ὄντων ἔστιν, ἢ Ζήνωνα τὸν ταὐτὰ δυνατὰ καὶ πάλιν ἀδύνατα πειρώμενον ἀποφαίνειν, ἢ Μέλισσον ὃς ἀπείρων τὸ πλῆθος πεφυκότων τῶν πραγμάτων ὡς ἑνὸς ὄντος τοῦ παντὸς ἐπεχείρησεν ἀποδείξεις εὑρίσκειν;", "st": "10.3"}, {"sp": "N", "t": "ἄλλ’ ὅμως οὕτω φανερῶς ἐκείνων ἐπιδειξάντων ὅτι ῥᾴδιόν ἐστι, περὶ ὧν ἄν τις πρόθηται, ψευδῆ μηχανήσασθαι λόγον, ἔτι περὶ τὸν τόπον τοῦτον διατρίβουσιν· οὓς ἐχρῆν ἀφεμένους ταύτης τῆς τερθρείας, τῆς ἐν μὲν τοῖς λόγοις ἐξελέγχειν προσποιουμένης, ἐν δὲ τοῖς ἔργοις πολὺν ἤδη χρόνον ἐξεληλεγμένης, τὴν ἀλήθειαν διώκειν, καὶ περὶ τὰς πράξεις ἐν αἷς πολιτευόμεθα,", "st": "10.4"}, {"sp": "N", "t": "τοὺς συνόντας παιδεύειν, καὶ περὶ τὴν ἐμπειρίαν τὴν τούτων γυμνάζειν, ἐνθυμουμένους ὅτι πολὺ κρεῖττόν ἐστι περὶ τῶν χρησίμων ἐπιεικῶς δοξάζειν ἢ περὶ τῶν ἀχρήστων ἀκριβῶς ἐπίστασθαι, καὶ μικρὸν προέχειν ἐν τοῖς μεγάλοις μᾶλλον ἢ πολὺ διαφέρειν ἐν τοῖς μικροῖς καὶ τοῖς μηδὲν πρὸς τὸν βίον ὠφελοῦσιν.", "st": "10.5"}, {"sp": "N", "t": "ἀλλὰ γὰρ οὐδενὸς αὐτοῖς ἄλλου μέλει πλὴν τοῦ χρηματίζεσθαι παρὰ τῶν νεωτέρων. ἔστι δ’ ἡ περὶ τὰς ἔριδας φιλοσοφία δυναμένη τοῦτο ποιεῖν· οἱ γὰρ μήτε τῶν ἰδίων πω μήτε τῶν κοινῶν φροντίζοντες τούτοις μάλιστα χαίρουσι τῶν λόγων οἳ μηδὲ πρὸς ἓν χρήσιμοι τυγχάνουσιν ὄντες.", "st": "10.6"}, {"sp": "N", "t": "τοῖς μὲν οὖν τηλικούτοις πολλὴ συγγνώμη ταύτην ἔχειν τὴν διάνοιαν· ἐπὶ γὰρ ἁπάντων τῶν πραγμάτων πρὸς τὰς περιττότητας καὶ τὰς θαυματοποιίας οὕτω διακείμενοι διατελοῦσι· τοῖς δὲ παιδεύειν προσποιουμένοις ἄξιον ἐπιτιμᾶν, ὅτι κατηγοροῦσι μὲν τῶν ἐπὶ τοῖς ἰδίοις συμβολαίοις ἐξαπατώντων καὶ μὴ δικαίως τοῖς λόγοις χρωμένων, αὐτοὶ δ’ ἐκείνων δεινότερα ποιοῦσιν· οἱ μὲν γὰρ ἄλλους τινὰς ἐζημίωσαν, οὗτοι δὲ τοὺς συνόντας μάλιστα βλάπτουσιν.", "st": "10.7"}, {"sp": "N", "t": "τοσοῦτον δ’ ἐπιδεδωκέναι πεποιήκασι τὸ ψευδολογεῖν ὥστ’ ἤδη τινές, ὁρῶντες τούτους ἐκ τῶν τοιούτων ὠφελουμένους, τολμῶσι γράφειν ὡς ἔστιν ὁ τῶν πτωχευόντων καὶ φευγόντων βίος ζηλωτότερος ἢ τῶν ἄλλων ἀνθρώπων, καὶ ποιοῦνται τεκμήριον, ὡς εἰ περὶ πονηρῶν πραγμάτων ἔχουσί τι λέγειν, περί γε τῶν καλῶν κἀγαθῶν ῥᾳδίως εὐπορήσουσιν.", "st": "10.8"}, {"sp": "N", "t": "ἐμοὶ δὲ δοκεῖ πάντων εἶναι καταγελαστότατον τὸ διὰ τούτων τῶν λόγων ζητεῖν πείθειν ὡς περὶ τῶν πολιτικῶν ἐπιστήμην ἔχουσιν, ἐξὸν ἐν αὐτοῖς οἷς ἐπαγγέλλονται τὴν ἐπίδειξιν ποιεῖσθαι· τοὺς γὰρ ἀμφισβητοῦντας τοῦ φρονεῖν καὶ φάσκοντας εἶναι σοφιστὰς οὐκ ἐν τοῖς ἠμελημένοις ὑπὸ τῶν ἄλλων, ἀλλ’ ἐν οἷς ἅπαντές εἰσιν ἀνταγωνισταί, προσήκει διαφέρειν καὶ κρείττους εἶναι τῶν ἰδιωτῶν.", "st": "10.9"}, {"sp": "N", "t": "νῦν δὲ παραπλήσιον ποιοῦσιν. ὥσπερ ἂν εἴ τις προσποιοῖτο κράτιστος εἶναι τῶν ἀθλητῶν ἐνταῦθα καταβαίνων, οὗ μηδεὶς ἂν ἄλλος ἀξιώσειεν. τίς γὰρ ἂν τῶν εὖ φρονούντων συμφορὰς ἐπαινεῖν ἐπιχειρήσειεν; ἀλλὰ δῆλον, ὅτι δι’ ἀσθένειαν ἐνταῦθα καταφεύγουσιν.", "st": "10.10"}, {"sp": "N", "t": "ἔστι γὰρ τῶν μὲν τοιούτων συγγραμμάτων μία τις ὁδός, ἣν οὔθ’ εὑρεῖν οὔτε μαθεῖν οὔτε μιμήσασθαι δύσκολόν ἐστιν· οἱ δὲ κοινοὶ πιστοὶ καὶ τούτοις ὅμοιοι τῶν λόγων διὰ πολλῶν ἰδεῶν καὶ καιρῶν δυσκαταμαθήτων εὑρίσκονταί τε καὶ λέγονται, καὶ τοσούτῳ χαλεπωτέραν ἔχουσι τὴν σύνθεσιν, ὅσῳ περ τὸ σεμνύνεσθαι τοῦ σκώπτειν καὶ τὸ σπουδάζειν τοῦ παίζειν ἐπιπονώτερόν ἐστιν. σημεῖον δὲ μέγιστον·", "st": "10.11"}, {"sp": "N", "t": "τῶν μὲν γὰρ τοὺς βομβυλιοὺς καὶ τοὺς ἅλας καὶ τὰ τοιαῦτα βουληθέντων ἐπαινεῖν οὐδεὶς πώποτε λόγων ἠπόρησεν, οἱ δὲ περὶ τῶν ὁμολογουμένων ἀγαθῶν ἢ καλῶν ἢ τῶν διαφερόντων ἐπ’ ἀρετῇ λέγειν ἐπιχειρήσαντες πολὺ καταδεέστερον τῶν ὑπαρχόντων ἅπαντες εἰρήκασιν.", "st": "10.12"}, {"sp": "N", "t": "οὐ γὰρ τῆς αὐτῆς γνώμης ἐστὶν ἀξίως εἰπεῖν περὶ ἑκατέρων αὐτῶν, ἀλλὰ τὰ μὲν μικρὰ ῥᾴδιον τοῖς λόγοις ὑπερβαλέσθαι, τῶν δὲ χαλεπὸν τοῦ μεγέθους ἐφικέσθαι· καὶ περὶ μὲν τῶν δόξαν ἐχόντων σπάνιον εὑρεῖν, ἃ μηδεὶς πρότερον εἴρηκε, περὶ δὲ τῶν φαύλων καὶ ταπεινῶν ὅ τι ἄν τις τύχῃ φθεγξάμενος ἅπαν ἴδιόν ἐστιν.", "st": "10.13"}, {"sp": "N", "t": "διὸ καὶ τὸν γράψαντα περὶ τῆς Ἑλένης ἐπαινῶ μάλιστα τῶν εὖ λέγειν τι βουληθέντων, ὅτι περὶ τοιαύτης ἐμνήσθη γυναικός, ἣ καὶ τῷ γένει καὶ τῷ κάλλει καὶ τῇ δόξῃ πολὺ διήνεγκεν. οὐ μὴν ἀλλὰ καὶ τοῦτον μικρόν τι παρέλαθεν· φησὶ μὲν γὰρ ἐγκώμιον γεγραφέναι περὶ αὐτῆς, τυγχάνει δ’ ἀπολογίαν εἰρηκὼς ὑπὲρ τῶν ἐκείνῃ πεπραγμένων.", "st": "10.14"}, {"sp": "N", "t": "ἔστι δ’ οὐκ ἐκ τῶν αὐτῶν ἰδεῶν οὐδὲ περὶ τῶν αὐτῶν ἔργων ὁ λόγος, ἀλλὰ πᾶν τοὐναντίον· ἀπολογεῖσθαι μὲν γὰρ προσήκει περὶ τῶν ἀδικεῖν αἰτίαν ἐχόντων, ἐπαινεῖν δὲ τοὺς ἐπ’ ἀγαθῷ τινὶ διαφέροντας. ἵνα δὲ μὴ δοκῶ τὸ ῥᾷστον ποιεῖν, ἐπιτιμᾶν τοῖς ἄλλοις μηδὲν ἐπιδεικνὺς τῶν ἐμαυτοῦ, πειράσομαι περὶ τῆς αὐτῆς ταύτης εἰπεῖν, παραλιπὼν ἅπαντα τὰ τοῖς ἄλλοις εἰρημένα.", "st": "10.15"}, {"sp": "N", "t": "τὴν μὲν οὖν ἀρχὴν τοῦ λόγου ποιήσομαι τὴν ἀρχὴν τοῦ γένους αὐτῆς. πλείστων γὰρ ἡμιθέων ὑπὸ Διὸς γεννηθέντων μόνης ταύτης γυναικὸς πατὴρ ἠξίωσε κληθῆναι. σπουδάσας δὲ μάλιστα περί τε τὸν ἐξ Ἀλκμήνης καὶ τοὺς ἐκ Λήδας, τοσούτῳ μᾶλλον Ἑλένην Ἡρακλέους προὐτίμησεν ὥστε τῷ μὲν ἰσχὺν ἔδωκεν, ἣ βίᾳ τῶν ἄλλων κρατεῖν δύναται, τῇ δὲ κάλλος ἀπένειμεν, ὃ καὶ τῆς ῥώμης αὐτῆς ἄρχειν πέφυκεν.", "st": "10.16"}, {"sp": "N", "t": "εἰδὼς δὲ τὰς ἐπιφανείας καὶ τὰς λαμπρότητας οὐκ ἐκ τῆς ἡσυχίας, ἀλλ’ ἐκ τῶν πολέμων καὶ τῶν ἀγώνων γιγνομένας, βουλόμενος αὐτῶν μὴ μόνον τὰ σώματ’ εἰς θεοὺς ἀναγαγεῖν ἀλλὰ καὶ τὰς δόξας ἀειμνήστους καταλιπεῖν, τοῦ μὲν ἐπίπονον καὶ φιλοκίνδυνον τὸν βίον κατέστησε, τῆς δὲ περίβλεπτον καὶ περιμάχητον τὴν φύσιν ἐποίησεν.", "st": "10.17"}, {"sp": "N", "t": "καὶ πρῶτον μὲν Θησεύς, ὁ λεγόμενος μὲν Αἰγέως, γενόμενος δ’ ἐκ Ποσειδῶνος, ἰδὼν αὐτὴν οὔπω μὲν ἀκμάζουσαν, ἤδη δὲ τῶν ἄλλων διαφέρουσαν, τοσοῦτον ἡττήθη τοῦ κάλλους ὁ κρατεῖν τῶν ἄλλων εἰθισμένος, ὥσθ’ ὑπαρχούσης αὐτῷ καὶ πατρίδος μεγίστης καὶ βασιλείας ἀσφαλεστάτης ἡγησάμενος οὐκ ἄξιον εἶναι ζῆν ἐπὶ τοῖς παροῦσιν ἀγαθοῖς ἄνευ τῆς πρὸς ἐκείνην οἰκειότητος,", "st": "10.18"}, {"sp": "N", "t": "ἐπειδὴ παρὰ τῶν κυρίων οὐχ οἷός τ’ ἦν αὐτὴν λαβεῖν, ἀλλ’ ἐπέμενον τήν τε τῆς παιδὸς ἡλικίαν καὶ τὸν χρησμὸν τὸν παρὰ τῆς Πυθίας, ὑπεριδὼν τὴν ἀρχὴν τὴν Τυνδάρεω καὶ καταφρονήσας τῆς ῥώμης τῆς Κάστορος καὶ Πολυδεύκους καὶ πάντων τῶν ἐν Λακεδαίμονι δεινῶν ὀλιγωρήσας, βίᾳ λαβὼν αὐτὴν εἰς Ἄφιδναν τῆς Ἀττικῆς κατέθετο,", "st": "10.19"}, {"sp": "N", "t": "καὶ τοσαύτην χάριν ἔσχε Πειρίθῳ τῷ μετασχόντι τῆς ἁρπαγῆς, ὥστε βουληθέντος αὐτοῦ μνηστεῦσαι Κόρην τὴν Διὸς καὶ Δήμητρος, καὶ παρακαλοῦντος ἐπὶ τὴν εἰς Ἅιδου κατάβασιν, ἐπειδὴ συμβουλεύων οὐχ οἷός τ’ ἦν ἀποτρέπειν, προδήλου τῆς συμφορᾶς οὔσης ὅμως αὐτῷ συνηκολούθησε, νομίζων ὀφείλειν τοῦτον τὸν ἔρανον, μηδενὸς ἀποστῆναι τῶν ὑπὸ Πειρίθου προσταχθέντων ἀνθ’ ὧν ἐκεῖνος αὐτῷ συνεκινδύνευσεν.", "st": "10.20"}, {"sp": "N", "t": "εἰ μὲν οὖν ὁ ταῦτα πράξας εἷς ἦν τῶν τυχόντων ἀλλὰ μὴ τῶν πολὺ διενεγκόντων, οὐκ ἄν πω δῆλος ἦν ὁ λόγος, πότερον Ἑλένης ἔπαινος ἢ κατηγορία Θησέως ἐστίν· νῦν δὲ τῶν μὲν ἄλλων τῶν εὐδοκιμησάντων εὑρήσομεν τὸν μὲν ἀνδρίας, τὸν δὲ σοφίας, τὸν δ’ ἄλλου τινὸς τῶν τοιούτων μερῶν ἀπεστερημένον, τοῦτον δὲ μόνον οὐδ’ ἑνὸς ἐνδεᾶ γενόμενον, ἀλλὰ παντελῆ τὴν ἀρετὴν κτησάμενον.", "st": "10.21"}, {"sp": "N", "t": "δοκεῖ δέ μοι πρέπειν περὶ αὐτοῦ καὶ διὰ μακροτέρων εἰπεῖν· ἡγοῦμαι γὰρ ταύτην μεγίστην εἶναι πίστιν τοῖς βουλομένοις Ἑλένην ἐπαινεῖν, ἢν ἐπιδείξωμεν τοὺς ἀγαπήσαντας καὶ θαυμάσαντας ἐκείνην αὐτοὺς τῶν ἄλλων θαυμαστοτέρους ὄντας. ὅσα μὲν γὰρ ἐφ’ ἡμῶν γέγονεν, εἰκότως ἂν ταῖς δόξαις ταῖς ἡμετέραις αὐτῶν διακρίνοιμεν, περὶ δὲ τῶν οὕτω παλαιῶν προσήκει τοῖς κατ’ ἐκεῖνον τὸν χρόνον εὖ φρονήσασιν ὁμονοοῦντας ἡμᾶς φαίνεσθαι.", "st": "10.22"}, {"sp": "N", "t": "κάλλιστον μὲν οὖν ἔχω περὶ Θησέως τοῦτ’ εἰπεῖν, ὅτι κατὰ τὸν αὐτὸν χρόνον Ἡρακλεῖ γενόμενος ἐνάμιλλον τὴν αὑτοῦ δόξαν πρὸς τὴν ἐκείνου κατέστησεν. οὐ γὰρ μόνον τοῖς ὅπλοις ἐκοσμήσαντο παραπλησίοις, ἀλλὰ καὶ τοῖς ἐπιτηδεύμασιν ἐχρήσαντο τοῖς αὐτοῖς, πρέποντα τῇ συγγενείᾳ ποιοῦντες. ἐξ ἀδελφῶν γὰρ γεγονότες, ὁ μὲν ἐκ Διός, ὁ δ’ ἐκ Ποσειδῶνος, ἀδελφὰς καὶ τὰς ἐπιθυμίας ἔσχον. μόνοι γὰρ οὗτοι τῶν προγεγενημένων ὑπὲρ τοῦ βίου τοῦ τῶν ἀνθρώπων ἀθληταὶ κατέστησαν. συνέβη δὲ τὸν μὲν ὀνομαστοτέρους καὶ μείζους,", "st": "10.23"}, {"sp": "N", "t": "τὸν δ’ ὠφελιμωτέρους καὶ τοῖς Ἕλλησιν οἰκειοτέρους ποιήσασθαι τοὺς κινδύνους. τῷ μὲν γὰρ Εὐρυσθεὺς προσέταττε τάς τε βοῦς τὰς ἐκ τῆς Ἐρυθείας ἀγαγεῖν καὶ τὰ μῆλα τὰ τῶν Ἑσπερίδων ἐνεγκεῖν καὶ τὸν Κέρβερον ἀναγαγεῖν καὶ τοιούτους ἄλλους πόνους, ἐξ ὧν ἤμελλεν οὐ τοὺς ἄλλους ὠφελήσειν ἀλλ’ αὐτὸς κινδυνεύσειν·", "st": "10.24"}, {"sp": "N", "t": "ὁ δ’ αὐτὸς αὑτοῦ κύριος ὢν τούτους προῃρεῖτο τῶν ἀγώνων ἐξ ὧν ἤμελλεν ἢ τῶν Ἑλλήνων ἢ τῆς αὑτοῦ πατρίδος εὐεργέτης γενήσεσθαι. καὶ τόν τε ταῦρον τὸν ἀνεθέντα μὲν ὑπὸ Ποσειδῶνος, τὴν δὲ χώραν λυμαινόμενον, ὃν πάντες οὐκ ἐτόλμων ὑπομένειν, μόνος χειρωσάμενος μεγάλου φόβου καὶ πολλῆς ἀπορίας τοὺς οἰκοῦντας τὴν πόλιν ἀπήλλαξεν·", "st": "10.25"}, {"sp": "N", "t": "καὶ μετὰ ταῦτα Λαπίθαις σύμμαχος γενόμενος, στρατευσάμενος ἐπὶ Κενταύρους τοὺς διφυεῖς, οἳ καὶ τάχει καὶ ῥώμῃ καὶ τόλμῃ διενεγκόντες τὰς μὲν ἐπόρθουν, τὰς δ’ ἤμελλον, ταῖς δ’ ἠπείλουν τῶν πόλεων, τούτους μάχῃ νικήσας εὐθὺς μὲν αὐτῶν τὴν ὕβριν ἔπαυσεν, οὐ πολλῷ δ’ ὕστερον τὸ γένος ἐξ ἀνθρώπων ἠφάνισεν.", "st": "10.26"}, {"sp": "N", "t": "περὶ δὲ τοὺς αὐτοὺς χρόνους τὸ τέρας τὸ τραφὲν μὲν ἐν Κρήτῃ, γενόμενον δ’ ἐκ Πασιφάης τῆς Ἡλίου θυγατρός, ᾧ κατὰ μαντείαν δασμὸν τῆς πόλεως δὶς ἑπτὰ παῖδας ἀποστελλούσης, ἰδὼν αὐτοὺς ἀγομένους καὶ πανδημεὶ προπεμπομένους ἐπὶ θάνατον ἄνομον καὶ προῦπτον καὶ πενθουμένους ἔτι ζῶντας, οὕτως ἠγανάκτησεν ὥσθ’ ἡγήσατο κρεῖττον εἶναι τεθνάναι μᾶλλον ἢ ζῆν ἄρχων τῆς πόλεως τῆς οὕτως οἰκτρὸν τοῖς ἐχθροῖς φόρον ὑποτελεῖν ἠναγκασμένης.", "st": "10.27"}, {"sp": "N", "t": "σύμπλους δὲ γενόμενος, καὶ κρατήσας φύσεως ἐξ ἀνδρὸς μὲν καὶ ταύρου μεμιγμένης, τὴν δ’ ἰσχὺν ἐχούσης οἵαν προσήκει τὴν ἐκ τοιούτων σωμάτων συγκειμένην, τοὺς μὲν παῖδας διασώσας τοῖς γονεῦσιν ἀπέδωκε, τὴν δὲ πόλιν οὕτως ἀνόμου καὶ δεινοῦ καὶ δυσαπαλλάκτου προστάγματος ἠλευθέρωσεν.", "st": "10.28"}, {"sp": "N", "t": "ἀπορῶ δ’ ὅ τι χρήσωμαι τοῖς ἐπιλοίποις· ἐπιστὰς γὰρ ἐπὶ τὰ Θησέως ἔργα καὶ λέγειν ἀρξάμενος περὶ αὐτῶν ὀκνῶ μὲν μεταξὺ παύσασθαι καὶ παραλιπεῖν τήν τε Σκίρωνος καὶ Κερκύονος καὶ τῶν ἄλλων τῶν τοιούτων παρανομίαν, πρὸς οὓς ἀνταγωνιστὴς γενόμενος ἐκεῖνος πολλῶν καὶ μεγάλων συμφορῶν τοὺς Ἕλληνας ἀπήλλαξεν, αἰσθάνομαι δ’ ἐμαυτὸν ἔξω φερόμενον τῶν καιρῶν καὶ δέδοικα μή τισι δόξω περὶ τούτου μᾶλλον σπουδάζειν ἢ περὶ ἧς τὴν ἀρχὴν ὑπεθέμην.", "st": "10.29"}, {"sp": "N", "t": "ἐξ ἀμφοτέρων οὖν τούτων αἱροῦμαι τὰ μὲν πλεῖστα παραλιπεῖν διὰ τοὺς δυσκόλως ἀκροωμένους, περὶ δὲ τῶν ἄλλων ὡς ἂν δύνωμαι συντομώτατα διελθεῖν, ἵνα τὰ μὲν ἐκείνοις, τὰ δ’ ἐμαυτῷ χαρίσωμαι, καὶ μὴ παντάπασιν ἡττηθῶ τῶν εἰθισμένων φθονεῖν καὶ τοῖς λεγομένοις ἅπασιν ἐπιτιμᾶν.", "st": "10.30"}, {"sp": "N", "t": "τὴν μὲν οὖν ἀνδρίαν ἐν τούτοις ἐπεδείξατο τοῖς ἔργοις ἐν οἷς αὐτὸς καθ’ αὑτὸν ἐκινδύνευσε, τὴν δ’ ἐπιστήμην ἣν εἶχε πρὸς τὸν πόλεμον, ἐν ταῖς μάχαις αἷς μεθ’ ὅλης τῆς πόλεως ἠγωνίσατο, τὴν δ’ εὐσέβειαν τὴν πρὸς τοὺς θεοὺς ἔν τε ταῖς Ἀδράστου καὶ ταῖς τῶν παίδων τῶν Ἡρακλέους ἱκετείαις, τοὺς μὲν γὰρ μάχῃ νικήσας Πελοποννησίους διέσωσε, τῷ δὲ τοὺς ὑπὸ τῇ Καδμείᾳ τελευτήσαντας βίᾳ Θηβαίων θάψαι παρέδωκε, τὴν δ’ ἄλλην ἀρετὴν καὶ τὴν σωφροσύνην ἔν τε τοῖς προειρημένοις καὶ μάλιστ’ ἐν οἷς τὴν πόλιν διῴκησεν.", "st": "10.31"}, {"sp": "N", "t": "ὁρῶν γὰρ τοὺς βίᾳ τῶν πολιτῶν ἄρχειν ζητοῦντας ἑτέροις δουλεύοντας καὶ τοὺς ἐπικίνδυνον τὸν βίον τοῖς ἄλλοις καθιστάντας αὐτοὺς περιδεῶς ζῶντας, καὶ πολεμεῖν ἀναγκαζομένους μετὰ μὲν τῶν πολιτῶν πρὸς τοὺς ἐπιστρατευομένους, μετὰ δ’ ἄλλων τινῶν πρὸς τοὺς συμπολιτευομένους,", "st": "10.32"}, {"sp": "N", "t": "ἔτι δὲ συλῶντας μὲν τὰ τῶν θεῶν, ἀποκτείνοντας δὲ τοὺς βελτίστους τῶν πολιτῶν, ἀπιστοῦντας δὲ τοῖς οἰκειοτάτοις, οὐδὲν δὲ ῥᾳθυμότερον ζῶντας τῶν ἐπὶ θανάτῳ συνειλημμένων, ἀλλὰ τὰ μὲν ἔξω ζηλουμένους, αὐτοὺς δὲ παρ’ αὑτοῖς μᾶλλον τῶν ἄλλων λυπουμένους·", "st": "10.33"}, {"sp": "N", "t": "τί γάρ ἐστιν ἄλγιον ἢ ζῆν ἀεὶ δεδιότα μή τις αὑτὸν τῶν παρεστώτων ἀποκτείνῃ, καὶ μηδὲν ἧττον φοβούμενον τοὺς φυλάττοντας ἢ τοὺς ἐπιβουλεύοντας; τούτων ἁπάντων καταφρονήσας καὶ νομίσας οὐκ ἄρχοντας ἀλλὰ νοσήματα τῶν πόλεων εἶναι τοὺς τοιούτους, ἐπέδειξεν ὅτι ῥᾴδιόν ἐστιν ἅμα τυραννεῖν καὶ μηδὲν χεῖρον διακεῖσθαι τῶν ἐξ ἴσου πολιτευομένων.", "st": "10.34"}, {"sp": "N", "t": "καὶ πρῶτον μὲν τὴν πόλιν σποράδην καὶ κατὰ κώμας οἰκοῦσαν εἰς ταὐτὸν συναγαγὼν τηλικαύτην ἐποίησεν ὥστ’ ἔτι καὶ νῦν ἀπ’ ἐκείνου τοῦ χρόνου μεγίστην τῶν Ἑλληνίδων εἶναι· μετὰ δὲ ταῦτα κοινὴν τὴν πατρίδα καταστήσας καὶ τὰς ψυχὰς τῶν συμπολιτευομένων ἐλευθερώσας ἐξ ἴσου τὴν ἅμιλλαν αὐτοῖς περὶ τῆς ἀρετῆς ἐποίησε, πιστεύων μὲν ὁμοίως αὐτῶν προέξειν ἀσκούντων ὥσπερ ἀμελούντων, εἰδὼς δὲ τὰς τιμὰς ἡδίους οὔσας τὰς παρὰ τῶν μέγα φρονούντων ἢ τὰς παρὰ τῶν δουλευόντων.", "st": "10.35"}, {"sp": "N", "t": "τοσούτου δ’ ἐδέησεν ἀκόντων τι ποιεῖν τῶν πολιτῶν ὥσθ’ ὁ μὲν τὸν δῆμον καθίστη κύριον τῆς πολιτείας, οἱ δὲ μόνον αὐτὸν ἄρχειν ἠξίουν, ἡγούμενοι πιστοτέραν καὶ κοινοτέραν εἶναι τὴν ἐκείνου μοναρχίαν τῆς αὑτῶν δημοκρατίας. οὐ γὰρ ὥσπερ ἕτεροι τοὺς μὲν πόνους ἄλλοις προσέταττε, τῶν δ’ ἡδονῶν αὐτὸς μόνος ἀπέλαυεν, ἀλλὰ τοὺς μὲν κινδύνους ἰδίους ἐποιεῖτο, τὰς δ’ ὠφελείας ἅπασιν εἰς τὸ κοινὸν ἀπεδίδου.", "st": "10.36"}, {"sp": "N", "t": "καὶ γάρ τοι διετέλεσε τὸν βίον οὐκ ἐπιβουλευόμενος ἀλλ’ ἀγαπώμενος, οὐδ’ ἐπακτῷ δυνάμει τὴν ἀρχὴν διαφυλάττων, ἀλλὰ τῇ τῶν πολιτῶν εὐνοίᾳ δορυφορούμενος, τῇ μὲν ἐξουσίᾳ τυραννῶν, ταῖς δ’ εὐεργεσίαις δημαγωγῶν· οὕτω γὰρ νομίμως καὶ καλῶς διῴκει τὴν πόλιν ὥστ’ ἔτι καὶ νῦν ἴχνος τῆς ἐκείνου πραότητος ἐν τοῖς ἤθεσιν ἡμῶν καταλελεῖφθαι.", "st": "10.37"}, {"sp": "N", "t": "τὴν δὴ γεννηθεῖσαν μὲν ὑπὸ Διός, κρατήσασαν δὲ τοιαύτης ἀρετῆς καὶ σωφροσύνης, πῶς οὐκ ἐπαινεῖν χρὴ καὶ τιμᾶν καὶ νομίζειν πολὺ τῶν πώποτε γενομένων διενεγκεῖν; οὐ γὰρ δὴ μάρτυρά γε πιστότερον οὐδὲ κριτὴν ἱκανώτερον ἕξομεν ἐπαγαγέσθαι περὶ τῶν Ἑλένῃ προσόντων ἀγαθῶν τῆς Θησέως διανοίας. ἵνα δὲ μὴ δοκῶ δι’ ἀπορίαν περὶ τὸν αὐτὸν τόπον διατρίβειν, μηδ’ ἀνδρὸς ἑνὸς δόξῃ καταχρώμενος ἐπαινεῖν αὐτήν, βούλομαι καὶ περὶ τῶν ἐχομένων διελθεῖν.", "st": "10.38"}, {"sp": "N", "t": "μετὰ γὰρ τὴν Θησέως εἰς Ἅιδου κατάβασιν ἐπανελθούσης αὖθις εἰς Λακεδαίμονα καὶ πρὸς τὸ μνηστεύεσθαι λαβούσης ἡλικίαν ἅπαντες οἱ τότε βασιλεύοντες καὶ δυναστεύοντες τὴν αὐτὴν γνώμην ἔσχον περὶ αὐτῆς· ἐξὸν γὰρ αὐτοῖς λαμβάνειν ἐν ταῖς αὑτῶν πόλεσι γυναῖκας τὰς πρωτευούσας, ὑπεριδόντες τοὺς οἴκοι γάμους ἦλθον ἐκείνην μνηστεύσοντες.", "st": "10.39"}, {"sp": "N", "t": "οὔπω δὲ κεκριμένου τοῦ μέλλοντος αὐτῇ συνοικήσειν ἀλλ’ ἔτι κοινῆς τῆς τύχης οὔσης οὕτω πρόδηλος ἦν ἅπασιν ἐσομένη περιμάχητος ὥστε συνελθόντες πίστεις ἔδοσαν ἀλλήλοις ἦ μὴν βοηθήσειν, εἴ τις ἀποστεροίη τὸν ἀξιωθέντα λαβεῖν αὐτήν, νομίζων ἕκαστος τὴν ἐπικουρίαν ταύτην αὑτῷ παρασκευάζειν.", "st": "10.40"}, {"sp": "N", "t": "τῆς μὲν οὖν ἰδίας ἐλπίδος πλὴν ἑνὸς ἀνδρὸς ἅπαντες ἐψεύσθησαν, τῆς δὲ κοινῆς δόξης ἧς ἔσχον περὶ ἐκείνης οὐδεὶς αὐτῶν διήμαρτεν. οὐ πολλοῦ γὰρ χρόνου διελθόντος, γενομένης ἐν θεοῖς περὶ κάλλους ἔριδος ἧς Ἀλέξανδρος ὁ Πριάμου κατέστη κριτής, καὶ διδούσης Ἥρας μὲν ἁπάσης αὐτῷ τῆς Ἀσίας βασιλεύειν, Ἀθηνᾶς δὲ κρατεῖν ἐν τοῖς πολέμοις,", "st": "10.41"}, {"sp": "N", "t": "Ἀφροδίτης δὲ τὸν γάμον τὸν Ἑλένης, τῶν μὲν σωμάτων οὐ δυνηθεὶς λαβεῖν διάγνωσιν ἀλλ’ ἡττηθεὶς τῆς τῶν θεῶν ὄψεως, τῶν δὲ δωρεῶν ἀναγκασθεὶς γενέσθαι κριτής, εἵλετο τὴν οἰκειότητα τὴν Ἑλένης ἀντὶ τῶν ἄλλων ἁπάντων, οὐ πρὸς τὰς ἡδονὰς ἀποβλέψας, — καίτοι καὶ τοῦτο τοῖς εὖ φρονοῦσι πολλῶν αἱρετώτερόν ἐστιν,", "st": "10.42"}, {"sp": "N", "t": "ἀλλ’ ὅμως οὐκ ἐπὶ τοῦθ’ ὥρμησεν, ἀλλ’ ἐπεθύμησε Διὸς γενέσθαι κηδεστής, νομίζων πολὺ μείζω καὶ καλλίω ταύτην εἶναι τὴν τιμὴν ἢ τὴν τῆς Ἀσίας βασιλείαν, καὶ μεγάλας μὲν ἀρχὰς καὶ δυναστείας καὶ φαύλοις ἀνθρώποις ποτὲ παραγίγνεσθαι, τοιαύτης δὲ γυναικὸς οὐδένα τῶν ἐπιγιγνομένων ἀξιωθήσεσθαι, πρὸς δὲ τούτοις οὐδὲν ἂν κτῆμα κάλλιον καταλιπεῖν τοῖς παισὶν ἢ παρασκευάσας αὐτοῖς ὅπως μὴ μόνον πρὸς πατρὸς ἀλλὰ καὶ πρὸς μητρὸς ἀπὸ Διὸς ἔσονται γεγονότες.", "st": "10.43"}, {"sp": "N", "t": "ἠπίστατο γὰρ τὰς μὲν ἄλλας εὐτυχίας ταχέως μεταπιπτούσας, τὴν δ’ εὐγένειαν ἀεὶ τοῖς αὐτοῖς παραμένουσαν, ὥστε ταύτην μὲν τὴν αἵρεσιν ὑπὲρ ἅπαντος τοῦ γένους ἔσεσθαι, τὰς δ’ ἑτέρας δωρεὰς ὑπὲρ τοῦ χρόνου μόνον τοῦ καθ’ αὑτόν.", "st": "10.44"}, {"sp": "N", "t": "τῶν μὲν οὖν εὖ φρονούντων οὐδεὶς ἂν τοῖς λογισμοῖς τούτοις ἐπιτιμήσειεν, τῶν δὲ μηδὲν πρὸ τοῦ πράγματος ἐνθυμουμένων ἀλλὰ τὸ συμβαῖνον μόνον σκοπουμένων ἤδη τινὲς ἐλοιδόρησαν αὐτόν· ὧν τὴν ἄνοιαν ἐξ ὧν ἐβλασφήμησαν περὶ ἐκείνου ῥᾴδιον ἅπασι καταμαθεῖν.", "st": "10.45"}, {"sp": "N", "t": "πῶς γὰρ οὐ καταγέλαστον πεπόνθασιν, εἰ τὴν αὑτῶν φύσιν ἱκανωτέραν εἶναι νομίζουσι τῆς ὑπὸ τῶν θεῶν προκριθείσης; οὐ γὰρ δή που περὶ ὧν εἰς τοσαύτην ἔριν κατέστησαν τὸν τυχόντα διαγνῶναι κύριον ἐποίησαν, ἀλλὰ δῆλον ὅτι τοσαύτην ἔσχον σπουδὴν ἐκλέξασθαι, κριτὴν τὸν βέλτιστον, ὅσηνπερ περὶ αὐτοῦ τοῦ πράγματος ἐπιμέλειαν ἐποιήσαντο.", "st": "10.46"}, {"sp": "N", "t": "χρὴ δὲ σκοπεῖν ὁποῖός τις ἦν καὶ δοκιμάζειν αὐτὸν οὐκ ἐκ τῆς ὀργῆς τῆς τῶν ἀποτυχουσῶν, ἀλλ’ ἐξ ὧν ἅπασαι βουλευσάμεναι προείλοντο τὴν ἐκείνου διάνοιαν. κακῶς μὲν γὰρ παθεῖν ὑπὸ τῶν κρειττόνων οὐδὲν κωλύει καὶ τοὺς μηδὲν ἐξημαρτηκότας· τοιαύτης δὲ τιμῆς τυχεῖν ὥστε θνητὸν ὄντα θεῶν γενέσθαι κριτὴν, οὐχ οἷόν τε μὴ οὐ τὸν πολὺ τῇ γνώμῃ διαφέροντα.", "st": "10.47"}, {"sp": "N", "t": "θαυμάζω δ’ εἴ τις οἴεται κακῶς βεβουλεῦσθαι τὸν μετὰ ταύτης ζῆν ἑλόμενον, ἧς ἕνεκα πολλοὶ τῶν ἡμιθέων ἀποθνῄσκειν ἠθέλησαν. πῶς δ’ οὐκ ἂν ἦν ἀνόητος, εἰ τοὺς θεοὺς εἰδὼς περὶ κάλλους φιλονικοῦντας αὐτὸς κάλλους κατεφρόνησε, καὶ μὴ ταύτην ἐνόμισε μεγίστην εἶναι τῶν δωρεῶν, περὶ ἧς κἀκείνας ἑώρα μάλιστα σπουδαζούσας;", "st": "10.48"}, {"sp": "N", "t": "τίς δ’ ἂν τὸν γάμον τὸν Ἑλένης ὑπερεῖδεν, ἧς ἁρπασθείσης οἱ μὲν Ἕλληνες οὕτως ἠγανάκτησαν ὥσπερ ὅλης τῆς Ἑλλάδος πεπορθημένης, οἱ δὲ βάρβαροι τοσοῦτον ἐφρόνησαν, ὅσον περ ἂν εἰ πάντων ἡμῶν ἐκράτησαν. δῆλον δ’ ὡς ἑκάτεροι διετέθησαν· πολλῶν γὰρ αὐτοῖς πρότερον ἐγκλημάτων γενομένων περὶ μὲν τῶν ἄλλων ἡσυχίαν ἦγον, ὑπὲρ δὲ ταύτης τηλικοῦτον συνεστήσαντο πόλεμον οὐ μόνον τῷ μεγέθει τῆς ὀργῆς ἀλλὰ καὶ τῷ μήκει τοῦ χρόνου καὶ τῷ πλήθει τῶν παρασκευῶν ὅσος οὐδεὶς πώποτε γέγονεν.", "st": "10.49"}, {"sp": "N", "t": "ἐξὸν δὲ τοῖς μὲν ἀποδοῦσιν Ἑλένην ἀπηλλάχθαι τῶν παρόντων κακῶν, τοῖς δ’ ἀμελήσασιν ἐκείνης ἀδεῶς οἰκεῖν τὸν ἐπίλοιπον χρόνον, οὐδέτεροι ταῦτ’ ἠθέλησαν· ἀλλ’ οἱ μὲν περιεώρων καὶ πόλεις ἀναστάτους γιγνομένας καὶ τὴν χώραν πορθουμένην, ὥστε μὴ προέσθαι τοῖς Ἕλλησιν αὐτήν, οἱ δ’ ᾑροῦντο μένοντες ἐπὶ τῆς ἀλλοτρίας καταγηράσκειν καὶ μηδέποτε τοὺς αὑτῶν ἰδεῖν μᾶλλον ἢ ’κείνην καταλιπόντες εἰς τὰς αὑτῶν πατρίδας ἀπελθεῖν.", "st": "10.50"}, {"sp": "N", "t": "καὶ ταῦτ’ ἐποίουν οὐχ ὑπὲρ Ἀλεξάνδρου καὶ Μενελάου φιλονικοῦντες, ἀλλ’ οἱ μὲν ὑπὲρ τῆς Ἀσίας, οἱ δ’ ὑπὲρ τῆς Εὐρώπης, νομίζοντες, ἐν ὁποτέρᾳ τὸ σῶμα τοὐκείνης κατοικήσειε, ταύτην εὐδαιμονεστέραν τὴν χώραν ἔσεσθαι.", "st": "10.51"}, {"sp": "N", "t": "τοσοῦτος δ’ ἔρως ἐνέπεσε τῶν πόνων καὶ τῆς στρατείας ἐκείνης οὐ μόνον τοῖς Ἕλλησι καὶ τοῖς βαρβάροις ἀλλὰ καὶ τοῖς θεοῖς, ὥστ’ οὐδὲ τοὺς ἐξ αὑτῶν γεγονότας ἀπέτρεψαν τῶν ἀγώνων τῶν περὶ Τροίαν, ἀλλὰ Ζεὺς μὲν προειδὼς τὴν Σαρπηδόνος εἱμαρμένην, Ἠὼς δὲ τὴν Μέμνονος, Ποσειδῶν δὲ τὴν Κύκνου, Θέτις δὲ τὴν Ἀχιλλέως, ὅμως αὐτοὺς συνεξώρμησαν καὶ συνεξέπεμψαν,", "st": "10.52"}, {"sp": "N", "t": "ἡγούμενοι κάλλιον αὐτοῖς εἶναι τεθνάναι μαχομένοις περὶ τῆς Διὸς θυγατρὸς μᾶλλον ἢ ζῆν ἀπολειφθεῖσι τῶν περὶ ἐκείνης κινδύνων. καὶ τί δεῖ θαυμάζειν, ἃ περὶ τῶν παίδων διενοήθησαν; αὐτοὶ γὰρ πολὺ μείζω καὶ δεινοτέραν ἐποιήσαντο παράταξιν τῆς πρὸς Γίγαντας αὐτοῖς γενομένης· πρὸς μὲν γὰρ ἐκείνους μετ’ ἀλλήλων ἐμαχέσαντο, περὶ δὲ ταύτης πρὸς σφᾶς αὐτοὺς ἐπολέμησαν.", "st": "10.53"}, {"sp": "N", "t": "εὐλόγως δὲ κἀκεῖνοι ταῦτ’ ἔγνωσαν, κἀγὼ τηλικαύταις ὑπερβολαῖς ἔχω χρήσασθαι περὶ αὐτῆς· κάλλους γὰρ πλεῖστον μέρος μετέσχεν, ὃ σεμνότατον καὶ τιμιώτατον καὶ θειότατον τῶν ὄντων ἐστίν. ῥᾴδιον δὲ γνῶναι τὴν δύναμιν αὐτοῦ· τῶν μὲν γὰρ ἀνδρίας ἢ σοφίας ἢ δικαιοσύνης μὴ μετεχόντων πολλὰ φανήσεται τιμώμενα μᾶλλον ἢ τούτων ἕκαστον, τῶν δὲ κάλλους ἀπεστερημένων οὐδὲν εὑρήσομεν ἀγαπώμενον ἀλλὰ πάντα καταφρονούμενα, πλὴν ὅσα ταύτης τῆς ἰδέας κεκοινώνηκε, καὶ τὴν ἀρετὴν διὰ τοῦτο μάλιστ’ εὐδοκιμοῦσαν, ὅτι κάλλιστον τῶν ἐπιτηδευμάτων ἐστίν.", "st": "10.54"}, {"sp": "N", "t": "γνοίη δ’ ἄν τις κἀκεῖθεν ὅσον διαφέρει τῶν ὄντων, ἐξ ὧν αὐτοὶ διατιθέμεθα πρὸς ἕκαστον αὐτῶν. τῶν μὲν γὰρ ἄλλων ὧν ἂν ἐν χρείᾳ γενώμεθα, τυχεῖν μόνον βουλόμεθα, περαιτέρω δὲ περὶ αὐτῶν οὐδὲν τῇ ψυχῇ προσπεπόνθαμεν· τῶν δὲ καλῶν ἔρως ἡμῖν ἐγγίγνεται, τοσούτῳ μείζω τοῦ βούλεσθαι ῥώμην ἔχων, ὅσῳ περ καὶ τὸ πρᾶγμα κρεῖττόν ἐστιν.", "st": "10.55"}, {"sp": "N", "t": "καὶ τοῖς μὲν κατὰ σύνεσιν ἢ κατ’ ἄλλο τι προέχουσι φθονοῦμεν, ἢν μὴ τῷ ποιεῖν ἡμᾶς εὖ καθ’ ἑκάστην τὴν ἡμέραν προσαγάγωνται καὶ στέργειν σφᾶς αὐτοὺς ἀναγκάσωσι· τοῖς δὲ καλοῖς εὐθὺς ἰδόντες εὖνοι γιγνόμεθα, καὶ μόνους αὐτοὺς ὥσπερ τοὺς θεοὺς οὐκ ἀπαγορεύομεν θεραπεύοντες,", "st": "10.56"}, {"sp": "N", "t": "ἀλλ’ ἥδιον δουλεύομεν τοῖς τοιούτοις ἢ τῶν ἄλλων ἄρχομεν, πλείω χάριν ἔχοντες τοῖς πολλὰ προστάττουσιν ἢ τοῖς μηδὲν ἐπαγγέλλουσιν. καὶ τοὺς μὲν ὑπ’ ἄλλῃ τινὶ δυνάμει γιγνομένους λοιδοροῦμεν καὶ κόλακας ἀποκαλοῦμεν, τοὺς δὲ τῷ κάλλει λατρεύοντας φιλοκάλους καὶ φιλοπόνους εἶναι νομίζομεν.", "st": "10.57"}, {"sp": "N", "t": "τοσαύτῃ δ’ εὐσεβείᾳ καὶ προνοίᾳ χρώμεθα περὶ τὴν ἰδέαν τὴν τοιαύτην ὥστε καὶ τῶν ἐχόντων τὸ κάλλος τοὺς μὲν μισθαρνήσαντας καὶ κακῶς βουλευσαμένους περὶ τῆς αὑτῶν ἡλικίας μᾶλλον ἀτιμάζομεν ἢ τοὺς εἰς τὰ τῶν ἄλλων σώματ’ ἐξαμαρτόντας· ὅσοι δ’ ἂν τὴν αὑτῶν ὥραν διαφυλάξωσιν ἄβατον τοῖς πονηροῖς ὥσπερ ἱερὸν ποιήσαντες, τούτους εἰς τὸν ἐπίλοιπον χρόνον ὁμοίως τιμῶμεν ὥσπερ τοὺς ὅλην τὴν πόλιν ἀγαθόν τι ποιήσαντας.", "st": "10.58"}, {"sp": "N", "t": "καὶ τὶ δεῖ τὰς ἀνθρωπίνας δόξας λέγοντα διατρίβειν; ἀλλὰ Ζεὺς ὁ κρατῶν πάντων ἐν μὲν τοῖς ἄλλοις τὴν αὑτοῦ δύναμιν ἐνδείκνυται, πρὸς δὲ τὸ κάλλος ταπεινὸς γιγνόμενος ἀξιοῖ πλησιάζειν. Ἀμφιτρύωνι μὲν γὰρ εἰκασθεὶς ὡς Ἀλκμήνην ἦλθε, χρυσὸς δὲ ῥυεὶς Δανάῃ συνεγένετο, κύκνος δὲ γενόμενος εἰς τοὺς Νεμέσεως κόλπους κατέφυγε, τούτῳ δὲ πάλιν ὁμοιωθεὶς Λήδαν ἐνύμφευσεν· ἀεὶ δὲ μετὰ τέχνης ἀλλ’ οὐ μετὰ βίας θηρώμενος φαίνεται τὴν φύσιν τὴν τοιαύτην.", "st": "10.59"}, {"sp": "N", "t": "τοσούτῳ δὲ μᾶλλον προτετίμηται τὸ κάλλος παρ’ ἐκείνοις ἢ παρ’ ἡμῖν ὥστε καὶ ταῖς γυναιξὶ ταῖς αὑτῶν ὑπὸ τούτου κρατουμέναις συγγνώμην ἔχουσι, καὶ πολλὰς ἄν τις ἐπιδείξειε τῶν ἀθανάτων, αἳ θνητοῦ κάλλους ἡττήθησαν, ὧν οὐδεμία λαθεῖν τὸ γεγενημένον ὡς αἰσχύνην ἔχον ἐζήτησεν, ἀλλ’ ὡς καλῶν ὄντων τῶν πεπραγμένων ὑμνεῖσθαι μᾶλλον ἢ σιωπᾶσθαι περὶ αὐτῶν ἠβουλήθησαν. μέγιστον δὲ τῶν εἰρημένων τεκμήριον. πλείους γὰρ ἂν εὕροιμεν διὰ τὸ κάλλος ἀθανάτους γεγενημένους ἢ διὰ τὰς ἄλλας ἀρετὰς ἁπάσας.", "st": "10.60"}, {"sp": "N", "t": "ὧν Ἑλένη τοσούτῳ πλέον ἔσχεν, ὅσῳ περ καὶ τὴν ὄψιν αὐτῶν διήνεγκεν. οὐ γὰρ μόνον ἀθανασίας ἔτυχεν, ἀλλὰ καὶ τὴν δύναμιν ἰσόθεον λαβοῦσα πρῶτον μὲν τοὺς ἀδελφοὺς ἤδη κατεχομένους ὑπὸ τῆς πεπρωμένης εἰς θεοὺς ἀνήγαγε, βουλομένη δὲ πιστὴν ποιῆσαι τὴν μεταβολὴν οὕτως οὕτως αὐτοῖς τὰς τιμὰς ἐναργεῖς ἔδωκεν ὥσθ’ ὁρωμένους ὑπὸ τῶν ἐν τῇ θαλάττῃ κινδυνευόντων σῴζειν, οἵτινες ἂν αὐτοὺς εὐσεβῶς κατακαλέσωνται.", "st": "10.61"}, {"sp": "N", "t": "μετὰ δὲ ταῦτα τοσαύτην Μενελάω χάριν ἀπέδωκεν ὑπὲρ τῶν πόνων καὶ τῶν κινδύνων οὓς δι’ ἐκείνην ὑπέμεινεν, ὥστε τοῦ γένους ἅπαντος τοῦ Πελοπιδῶν διαφθαρέντος καὶ κακοῖς ἀνηκέστοις περιπεσόντος οὐ μόνον αὐτὸν τῶν συμφορῶν τούτων ἀπήλλαξεν ἀλλὰ καὶ θεὸν ἀντὶ θνητοῦ ποιήσασα σύνοικον αὑτῇ καὶ πάρεδρον εἰς ἅπαντα τὸν αἰῶνα κατεστήσατο.", "st": "10.62"}, {"sp": "N", "t": "καὶ τούτοις ἔχω τὴν πόλιν τὴν Σπαρτιατῶν τὴν μάλιστα τὰ παλαιὰ διασῴζουσαν ἔργῳ παρασχέσθαι μαρτυροῦσαν· ἔτι γὰρ καὶ νῦν ἐν Θεράπναις τῆς Λακωνικῆς θυσίας αὐτοῖς ἁγίας καὶ πατρίας ἀποτελοῦσιν οὐχ ὡς ἥρωσιν ἀλλ’ ὡς θεοῖς ἀμφοτέροις οὖσιν.", "st": "10.63"}, {"sp": "N", "t": "ἐνεδείξατο δὲ καὶ Στησιχόρῳ τῷ ποιητῇ τὴν αὑτῆς δύναμιν· ὅτε μὲν γὰρ ἀρχόμενος τῆς ᾠδῆς ἐβλασφήμησέ τι περὶ αὐτῆς, ἀνέστη τῶν ὀφθαλμῶν ἐστερημένος, ἐπειδὴ δὲ γνοὺς τὴν αἰτίαν τῆς συμφορᾶς τὴν καλουμένην παλινῳδίαν ἐποίησε, πάλιν αὐτὸν εἰς τὴν αὐτὴν φύσιν κατέστησεν.", "st": "10.64"}, {"sp": "N", "t": "λέγουσι δέ τινες καὶ τῶν Ὁμηριδῶν ὡς ἐπιστᾶσα τῆς νυκτὸς Ὁμήρῳ προσέταξε ποιεῖν περὶ τῶν στρατευσαμένων ἐπὶ Τροίαν, βουλομένη τὸν ἐκείνων θάνατον ζηλωτότερον ἢ τὸν βίον τὸν τῶν ἄλλων καταστῆσαι· καὶ μέρος μέν τι καὶ διὰ τὴν Ὁμήρου τέχνην, μάλιστα δὲ διὰ ταύτην οὕτως ἐπαφρόδιτον καὶ παρὰ πᾶσιν ὀνομαστὴν αὐτοῦ γενέσθαι τὴν ποίησιν.", "st": "10.65"}, {"sp": "N", "t": "ὡς οὖν καὶ δίκην λαβεῖν καὶ χάριν ἀποδοῦναι δυναμένην, τοὺς μὲν τοῖς χρήμασι προέχοντας ἀναθήμασι καὶ θυσίαις καὶ ταῖς ἄλλαις προσόδοις ἱλάσκεσθαι καὶ τιμᾶν αὐτὴν χρή, τοὺς δὲ φιλοσόφους πειρᾶσθαί τι λέγειν περὶ αὐτῆς ἄξιον τῶν ὑπαρχόντων ἐκείνῃ· τοῖς γὰρ πεπαιδευμένοις πρέπει τοιαύτας ποιεῖσθαι τὰς ἀπαρχάς.", "st": "10.66"}, {"sp": "N", "t": "πολὺ δὲ πλείω τὰ παραλελειμμένα τῶν εἰρημένων ἐστίν. χωρὶς γὰρ τεχνῶν καὶ φιλοσοφιῶν καὶ τῶν ἄλλων ὠφελειῶν, ἃς ἔχοι τις ἂν εἰς ἐκείνην καὶ τὸν πόλεμον τὸν Τρωϊκὸν ἀνενεγκεῖν, δικαίως ἂν καὶ τοῦ μὴ δουλεύειν ἡμᾶς τοῖς βαρβάροις Ἑλένην αἰτίαν εἶναι νομίζοιμεν. εὑρήσομεν γὰρ τοὺς Ἕλληνας δι’ αὐτὴν ὁμονοήσαντας καὶ κοινὴν στρατείαν ἐπὶ τοὺς βαρβὰρους ποιησαμένους, καὶ τότε πρῶτον τὴν Εὐρώπην τῆς Ἀσίας τρόπαιον στήσασαν·", "st": "10.67"}, {"sp": "N", "t": "ἐξ ὧν τοσαύτης μεταβολῆς ἐτύχομεν ὥστε τὸν μὲν ἐπέκεινα χρόνον οἱ δυστυχοῦντες ἐν τοῖς βαρβάροις τῶν Ἑλληνίδων πόλεων ἄρχειν ἠξίουν, καὶ Δαναὸς μὲν ἐξ Αἰγύπτου φυγὼν Ἄργος κατέσχε, Κάδμος δὲ Σιδώνιος Θηβῶν ἐβασίλευσε, Κᾶρες δὲ τὰς νήσους κατῴκουν, Πελοποννήσου δὲ συμπάσης ὁ Ταντάλου Πέλοψ ἐκράτησεν, μετὰ δ’ ἐκεῖνον τὸν πόλεμον τοσαύτην ἐπίδοσιν τὸ γένος ἡμῶν ἔλαβεν ὥστε καὶ πόλεις μεγάλας καὶ χώραν πολλὴν ἀφελέσθαι τῶν βαρβάρων.", "st": "10.68"}, {"sp": "N", "t": "ἢν οὖν τινὲς βούλωνται ταῦτα διεργάζεσθαι καὶ μηκύνειν, οὐκ ἀπορήσουσιν ἀφορμῆς, ὅθεν Ἑλένην ἔξω τῶν εἰρημένων ἕξουσιν ἐπαινεῖν, ἀλλὰ πολλοῖς καὶ καινοῖς λόγοις ἐντεύξονται περὶ αὐτῆς.", "st": "10.69"}, {"sp": "HDR", "t": "Βούσιρις", "st": "11"}, {"sp": "N", "t": "τὴν μὲν ἐπιείκειαν τὴν σήν, ὦ Πολύκρατες, καὶ τὴν τοῦ βίου μεταβολὴν παρ’ ἄλλων πυνθανόμενος οἶδα· τῶν δὲ λόγων τινὰς ὧν γέγραφας, αὐτὸς ἀνεγνωκὼς ἥδιστα μὲν ἄν σοι περὶ ὅλης ἐπαρρησιασάμην τῆς παιδεύσεως περὶ ἣν ἠνάγκασαι διατρίβειν· ἡγοῦμαι γὰρ τοῖς ἀναξίως μὲν δυστυχοῦσιν, ἐκ δὲ φιλοσοφίας χρηματίζεσθαι ζητοῦσιν, ἅπαντας τοὺς πλείω πεπραγματευμένους καὶ μᾶλλον ἀπηκριβωμένους προσήκειν ἐθελοντὰς τοῦτον εἰσφέρειν τὸν ἔρανον·", "st": "11.1"}, {"sp": "N", "t": "ἐπειδὴ δ’ οὔπω περιτετυχήκαμεν ἀλλήλοις, περὶ μὲν τῶν ἄλλων, ἤν ποτ’ εἰς ταὐτὸν ἔλθωμεν, τόθ’ ἡμῖν ἐξέσται διὰ πλειόνων ποιήσασθαι τὴν συνουσίαν, ἃ δ’ ἐν τῷ παρόντι δυναίμην ἂν εὐεργετῆσαί σε, ταῦτα δ’ ᾠήθην χρῆναι σοὶ μὲν ἐπιστεῖλαι, πρὸς δὲ τοὺς ἄλλους ὡς οἷόν τε μάλιστ’ ἀποκρύψασθαι.", "st": "11.2"}, {"sp": "N", "t": "γιγνώσκω μὲν οὖν ὅτι τοῖς πλείστοις τῶν νουθετουμένων ἔμφυτόν ἐστι μὴ πρὸς τὰς ὠφελείας ἀποβλέπειν, ἀλλὰ τοσούτῳ χαλεπώτερον ἀκούειν τῶν λεγομένων, ὅσῳ περ ἂν αὐτῶν τις ἀκριβέστερον ἐξετάζῃ τὰς ἁμαρτίας· ὅμως δ’ οὐκ ὀκνητέον ὑπομένειν τὴν ἀπέχθειαν ταύτην τοῖς εὐνοϊκῶς πρός τινας ἔχουσιν, ἀλλὰ πειρατέον μεθιστάναι τὴν δόξαν τῶν οὕτω πρὸς τοὺς συμβουλεύοντας διακειμένων.", "st": "11.3"}, {"sp": "N", "t": "αἰσθόμενος οὖν οὐχ ἥκιστά σε μεγαλαυχούμενον ἐπί τε τῇ Βουσίριδος ἀπολογίᾳ καὶ τῇ Σωκράτους κατηγορίᾳ, πειράσομαί σοι ποιῆσαι καταφανὲς ὅτι πολὺ τοῦ δέοντος ἐν ἀμφοτέροις τοῖς λόγοις διήμαρτες. ἁπάντων γὰρ εἰδότων ὅτι δεῖ τοὺς μὲν εὐλογεῖν τινὰς βουλομένους πλείω τῶν ὑπαρχόντων ἀγαθῶν αὐτοῖς προσόντ’ ἀποφαίνειν, τοὺς δὲ κατηγοροῦντας τἀναντία τούτων ποιεῖν,", "st": "11.4"}, {"sp": "N", "t": "τοσούτου δεῖς οὕτω κεχρῆσθαι τοῖς λόγοις, ὥσθ’ ὑπὲρ μὲν Βουσίριδος ἀπολογήσασθαι φάσκων, οὐχ ὅπως τῆς ὑπαρχούσης αὐτὸν διαβολῆς ἀπήλλαξας, ἀλλὰ καὶ τηλικαύτην αὐτῷ τὸ μέγεθος παρανομίαν προσῆψας ἧς οὐκ ἔσθ’ ὅπως ἄν τις δεινοτέραν ἐξευρεῖν δυνηθείη· τῶν γὰρ ἄλλων τῶν ἐπιχειρησάντων ἐκεῖνον λοιδορεῖν τοσοῦτον μόνον περὶ αὐτοῦ βλασφημούντων, ὡς ἔθυε τῶν ξένων τοὺς ἀφικνουμένους, σὺ καὶ κατεσθίειν αὐτὸν τοὺς ἀνθρώπους ᾐτιάσω· Σωκράτους δὲ κατηγορεῖν ἐπιχειρήσας, ὥσπερ ἐγκωμιάσαι βουλόμενος Ἀλκιβιάδην ἔδωκας αὐτῷ μαθητήν, ὃν ὑπ’ ἐκείνου μὲν οὐδεὶς ᾔσθετο παιδευόμενον, ὅτι δὲ πολὺ διήνεγκε τῶν ἄλλων ἅπαντες ἂν ὁμολογήσειαν.", "st": "11.5"}, {"sp": "N", "t": "τοιγαροῦν εἰ γένοιτ’ ἐξουσία τοῖς τετελευτηκόσι βουλεύσασθαι περὶ τῶν εἰρημένων, ὁ μὲν ἄν σοι τοσαύτην ἔχοι χάριν ὑπὲρ τῆς κατηγορίας, ὅσην οὐδενὶ τῶν ἐπαινεῖν αὐτὸν εἰθισμένων, ὁ δ’ εἰ καὶ περὶ τοὺς ἄλλους πραότατος ἦν, ἀλλ’ οὖν ἐπί γε τοῖς ὑπὸ σοῦ λεγομένοις οὕτως ἂν ἀγανακτήσειεν ὥστε μηδεμιᾶς ἀποσχέσθαι τιμωρίας. καίτοι πῶς οὐκ αἰσχύνεσθαι μᾶλλον ἢ σεμνύνεσθαι προσήκει τὸν παρὰ τοῖς λοιδορουμένοις ὑφ’ αὑτοῦ μᾶλλον ἀγαπώμενον ἢ παρὰ τοῖς ἐγκωμιαζομένοις;", "st": "11.6"}, {"sp": "N", "t": "οὕτω δ’ ἠμέλησας εἰ μηδὲν ὁμολογούμενον ἐρεῖς, ὥστε φῂς μὲν αὐτὸν τὴν Αἰόλου καὶ τὴν Ὀρφέως ζηλῶσαι δόξαν, ἀποφαίνεις δ’ οὐδὲν τῶν αὐτῶν ἐκείνοις ἐπιτηδεύσαντα. πότερα γὰρ τοῖς περὶ Αἰόλου λεγομένοις αὐτὸν παρατάξωμεν; ἀλλ’ ἐκεῖνος μὲν τῶν ξένων τοὺς ἐπὶ τὴν χώραν ἐκπίπτοντας εἰς τὰς αὑτῶν πατρίδας ἀπέστελλεν, ὁ δ’ εἰ χρὴ τοῖς ὑπὸ σοῦ λεγομένοις πιστεύειν, θύσας κατήσθιεν.", "st": "11.7"}, {"sp": "N", "t": "ἢ τοῖς Ὀρφέως ἔργοις ὁμοιώσωμεν; ἀλλ’ ὁ μὲν ἐξ Ἅιδου τοὺς τεθνεῶτας ἀνῆγεν, ὁ δὲ πρὸ μοίρας τοὺς ζῶντας ἀπώλλυεν. ὥσθ’ ἡδέως ἂν εἰδείην τί ποτ’ ἂν ἐποίησεν, εἰ καταφρονῶν αὐτῶν ἐτύγχανεν, ὃς θαυμάζων τὴν ἀρετὴν τὴν ἐκείνων ἅπαντα φαίνεται τἀναντία διαπραττόμενος. ὃ δὲ πάντων ἀτοπώτατον, ὅτι περὶ τὰς γενεαλογίας ἐσπουδακὼς ἐτόλμησας εἰπεῖν, ὡς τούτους ἐζήλωσεν ὧν οὐδ’ οἱ πατέρες πω κατ’ ἐκεῖνον τὸν χρόνον γεγονότες ἦσαν.", "st": "11.8"}, {"sp": "N", "t": "ἵνα δὲ μὴ δοκῶ τὸ προχειρότατον ποιεῖν, ἐπιλαμβάνεσθαι τῶν εἰρημένων μηδὲν ἐπιδεικνὺς τῶν ἐμαυτοῦ, πειράσομαί σοι διὰ βραχέων δηλῶσαι περὶ τὴν αὐτὴν ὑπόθεσιν, καίπερ οὐ σπουδαίαν οὖσαν οὐδὲ σεμνοὺς λόγους ἔχουσαν, ἐξ ὧν ἔδει καὶ τὸν ἔπαινον καὶ τὴν ἀπολογίαν ποιήσασθαι.", "st": "11.9"}, {"sp": "N", "t": "περὶ μὲν οὖν τῆς Βουσίριδος εὐγενείας τίς οὐκ ἂν δυνηθείη ῥᾳδίως εἰπεῖν; ὃς πατρὸς μὲν ἦν Ποσειδῶνος, μητρὸς δὲ Λιβύης τῆς Ἐπάφου τοῦ Διός, ἥν φασι πρώτην γυναῖκα βασιλεύσασαν ὁμώνυμον αὑτῇ τὴν χώραν καταστῆσαι. τυχὼν δὲ τοιούτων προγόνων οὐκ ἐπὶ τούτοις μόνοις μέγ’ ἐφρόνησεν, ἀλλ’ ᾠήθη δεῖν καὶ τῆς ἀρετῆς τῆς αὑτοῦ μνημεῖον εἰς ἅπαντα τὸν χρόνον καταλιπεῖν.", "st": "11.10"}, {"sp": "N", "t": "τὴν μὲν οὖν μητρῴαν ἀρχὴν ὑπερεῖδεν ἐλάττω νομίσας ἢ κατὰ τὴν αὑτοῦ φύσιν εἶναι, πλείστους δὲ καταστρεψάμενος καὶ μεγίστην δύναμιν κτησάμενος ἐν Αἰγύπτῳ κατεστήσατο τὴν βασιλείαν, οὐκ ἐκ τῶν παρουσῶν μόνον ἀλλ’ ἐξ ἁπασῶν προκρίνας τὴν ἐκεῖ πολὺ διαφέρειν οἴκησιν.", "st": "11.11"}, {"sp": "N", "t": "ἑώρα γὰρ τοὺς μὲν ἄλλους τόπους οὐκ εὐκαίρως οὐδ’ εὐαρμόστως πρὸς τὴν τοῦ σύμπαντος φύσιν ἔχοντας, ἀλλὰ τοὺς μὲν ὑπ’ ὄμβρων κατακλυζομένους, τοὺς δ’ ὑπὸ καυμάτων διαφθειρομένους, ταύτην δὲ τὴν χώραν ἐν καλλίστῳ μὲν τοῦ κόσμου κειμένην, πλεῖστα δὲ καὶ παντοδαπώτατα φέρειν δυναμένην, ἀθανάτῳ δὲ τείχει τῷ Νείλῳ τετειχισμένην,", "st": "11.12"}, {"sp": "N", "t": "ὃς οὐ μόνον φυλακὴν ἀλλὰ καὶ τροφὴν ἱκανὴν αὐτῇ παρέχειν πέφυκεν, ἀνάλωτος μὲν ὢν καὶ δύσμαχος τοῖς ἐπιβουλεύουσιν, εὐαγωγὸς δὲ καὶ πρὸς πολλὰ χρήσιμος τοῖς ἐντὸς αὐτοῦ κατοικοῦσιν. πρὸς γὰρ τοῖς προειρημένοις καὶ τὴν δύναμιν αὐτῶν πρὸς τὴν τῆς γῆς ἐργασίαν ἰσόθεον πεποίηκεν· τῶν γὰρ ὄμβρων καὶ τῶν αὐχμῶν τοῖς μὲν ἄλλοις ὁ Ζεὺς ταμίας ἐστίν, ἐκείνων δ’ ἕκαστος ἀμφοτέρων τούτων αὐτὸς αὑτῷ κύριος καθέστηκεν.", "st": "11.13"}, {"sp": "N", "t": "εἰς τοσαύτην δ’ ὑπερβολὴν εὐδαιμονίας ἥκουσιν, ὥστε τῇ μὲν ἀρετῇ καὶ τῇ φύσει τῆς χώρας καὶ τῷ πλήθει τῶν πεδίων ἤπειρον καρποῦνται, τῇ δὲ τῶν περιόντων διαθέσει καὶ τῇ τῶν ἐλλειπόντων κομιδῇ διὰ τὴν τοῦ ποταμοῦ δύναμιν νῆσον οἰκοῦσιν· κύκλῳ γὰρ αὐτὴν περιέχων καὶ πᾶσαν διαρρέων πολλὴν αὐτοῖς εὐπορίαν ἀμφοτέρων τούτων πεποίηκεν.", "st": "11.14"}, {"sp": "N", "t": "ἤρξατο μὲν οὖν ἐντεῦθεν, ὅθεν περ χρὴ τοὺς εὖ φρονοῦντας, ἅμα τόν τε τόπον ὡς κάλλιστον καταλαβεῖν καὶ τροφὴν ἱκανὴν τοῖς περὶ αὑτὸν ἐξευρεῖν. μετὰ δὲ ταῦτα διελόμενος χωρὶς ἑκάστους τοὺς μὲν ἐπὶ τὰς ἱερωσύνας κατέστησε, τοὺς δ’ ἐπὶ τὰς τέχνας ἔτρεψε, τοὺς δὲ τὰ περὶ τὸν πόλεμον μελετᾶν ἠνάγκασεν, ἡγούμενος τὰ μὲν ἀναγκαῖα καὶ τὰς περιουσίας ἔκ τε τῆς χώρας καὶ τῶν τεχνῶν δεῖν ὑπάρχειν, τούτων δ’ εἶναι φυλακὴν ἀσφαλεστάτην τήν τε περὶ τὸν πόλεμον ἐπιμέλειαν καὶ τὴν πρὸς τοὺς θεοὺς εὐσέβειαν.", "st": "11.15"}, {"sp": "N", "t": "ἅπαντας δὲ τοὺς ἀριθμοὺς περιλαβὼν ἐξ ὧν ἄριστ’ ἄν τις τὰ κοινὰ διοικήσειεν, ἀεὶ τοῖς αὐτοῖς τὰς αὐτὰς πράξεις μεταχειρίζεσθαι προσέταξεν, εἰδὼς τοὺς μὲν μεταβαλλομένους τὰς ἐργασίας οὐδὲ πρὸς ἓν τῶν ἔργων ἀκριβῶς ἔχοντας, τοὺς δ’ ἐπὶ ταῖς αὐταῖς πράξεσι συνεχῶς διαμένοντας εἰς ὑπερβολὴν ἕκαστον ἀποτελοῦντας.", "st": "11.16"}, {"sp": "N", "t": "τοιγαροῦν καὶ πρὸς τὰς τέχνας εὑρήσομεν αὐτοὺς πλέον διαφέροντας τῶν περὶ τὰς αὐτὰς ἐπιστήμας ἢ τοὺς ἄλλους δημιουργοὺς τῶν ἰδιωτῶν, καὶ πρὸς τὴν σύνταξιν δι’ ἧς τήν τε βασιλείαν καὶ τὴν ἄλλην πολιτείαν διαφυλάττουσιν, οὕτω καλῶς ἔχοντας ὥστε καὶ τῶν φιλοσόφων τοὺς ὑπὲρ τῶν τοιούτων λέγειν ἐπιχειροῦντας καὶ μάλιστ’ εὐδοκιμοῦντας τὴν ἐν Αἰγύπτῳ προαιρεῖσθαι πολιτείαν, καὶ Λακεδαιμονίους μέρος τι τῶν ἐκεῖθεν μιμουμένους ἄριστα διοικεῖν τὴν αὑτῶν πόλιν.", "st": "11.17"}, {"sp": "N", "t": "καὶ γὰρ τὸ μηδένα τῶν μαχίμων ἄνευ τῆς τῶν ἀρχόντων γνώμης ἀποδημεῖν καὶ τὰ συσσίτια καὶ τὴν τῶν σωμάτων ἄσκησιν, ἔτι δὲ τὸ μηδενὸς τῶν ἀναγκαίων ἀποροῦντας τῶν κοινῶν προσταγμάτων ἀμελεῖν, μηδ’ ἐπὶ ταῖς ἄλλαις τέχναις διατρίβειν, ἀλλὰ τοῖς ὅλοις καὶ ταῖς στρατείαις προσέχειν τὸν νοῦν, ἐκεῖθεν ἅπαντα ταῦτ’ εἰλήφασιν.", "st": "11.18"}, {"sp": "N", "t": "τοσούτῳ δὲ χεῖρον κέχρηνται τούτοις τοῖς ἐπιτηδεύμασιν, ὅσον οὗτοι μὲν ἅπαντες στρατιῶται καταστάντες βίᾳ τὰ τῶν ἄλλων λαμβάνειν ἀξιοῦσιν, ἐκεῖνοι δ’ οὕτως οἰκοῦσιν ὥσπερ χρὴ τοὺς μήτε τῶν ἰδίων ἀμελοῦντας μήτε τοῖς ἀλλοτρίοις ἐπιβουλεύοντας. γνοίη δ’ ἄν τις ἐνθένδε τὸ διάφορον ἑκατέρας τῆς πολιτείας.", "st": "11.19"}, {"sp": "N", "t": "εἰ μὲν γὰρ ἅπαντες μιμησαίμεθα τὴν Λακεδαιμονίων ἀργίαν καὶ πλεονεξίαν, εὐθὺς ἂν ἀπολοίμεθα καὶ διὰ τὴν ἔνδειαν τῶν καθ’ ἡμέραν καὶ διὰ τὸν πόλεμον τὸν πρὸς ἡμᾶς αὐτούς· εἰ δὲ τοῖς Αἰγυπτίων νόμοις χρῆσθαι βουληθεῖμεν, καὶ τοῖς μὲν ἐργάζεσθαι, τοῖς δὲ τὰ τούτων σῴζειν δόξειεν, ἕκαστοι τὴν αὑτῶν ἔχοντες εὐδαιμόνως ἂν τὸν βίον διατελοῖμεν.", "st": "11.20"}, {"sp": "N", "t": "καὶ μὲν δὴ καὶ τῆς περὶ τὴν φρόνησιν ἐπιμελείας εἰκότως ἄν τις ἐκεῖνον αἴτιον νομίσειεν. τοῖς γὰρ ἱερεῦσι παρεσκεύασεν εὐπορίαν μὲν ταῖς ἐκ τῶν ἱερῶν προσόδοις, σωφροσύνην δὲ ταῖς ἁγνείαις ταῖς ὑπὸ τῶν νόμων προστεταγμέναις, σχολὴν δὲ ταῖς τῶν κινδύνων καὶ τῶν ἄλλων ἔργων ἀτελείαις·", "st": "11.21"}, {"sp": "N", "t": "μεθ’ ὧν ἐκεῖνοι βιοτεύοντες τοῖς μὲν σώμασιν ἰατρικὴν ἐξεῦρον ἐπικουρίαν, οὐ διακεκινδυνευμένοις φαρμάκοις χρωμένην ἀλλὰ τοιούτοις, ἃ τὴν μὲν ἀσφάλειαν ὁμοίαν ἔχει τῇ τροφῇ τῇ καθ’ ἡμέραν, τὰς δ’ ὠφελείας τηλικαύτας ὥστ’ ἐκείνους ὁμολογουμένως ὑγιεινοτάτους εἶναι καὶ μακροβιωτάτους, ταῖς δὲ ψυχαῖς φιλοσοφίας ἄσκησιν κατέδειξαν, ἣ καὶ νομοθετῆσαι καὶ τὴν φύσιν τῶν ὄντων ζητῆσαι δύναται.", "st": "11.22"}, {"sp": "N", "t": "καὶ τοὺς μὲν πρεσβυτέρους ἐπὶ τὰ μέγιστα τῶν πραγμάτων ἔταξεν, τοὺς δὲ νεωτέρους ἀμελήσαντας τῶν ἡδονῶν ἐπ’ ἀστρολογίᾳ καὶ λογισμοῖς καὶ γεωμετρίᾳ διατρίβειν ἔπεισεν, ὧν τὰς δυνάμεις οἱ μὲν ὡς πρὸς ἔνια χρησίμους ἐπαινοῦσιν, οἱ δ’ ὡς πλεῖστα πρὸς ἀρετὴν συμβαλλομένας ἀποφαίνειν ἐπιχειροῦσιν.", "st": "11.23"}, {"sp": "N", "t": "μάλιστα δ’ ἄξιον ἐπαινεῖν καὶ θαυμάζειν τὴν εὐσέβειαν αὐτῶν καὶ τὴν περὶ τοὺς θεοὺς θεραπείαν. ὅσοι μὲν γὰρ σφᾶς αὐτοὺς οὕτω κατεσχημάτισαν ὥστ’ ἢ κατὰ σοφίαν ἢ κατ’ ἄλλην τιν’ ἀρετὴν ὑπολαμβάνεσθαι μειζόνως ἢ κατὰ τὴν ἀξίαν, οὗτοι μὲν βλάπτουσι τοὺς ἐξαπατηθέντας· ὅσοι δὲ τῶν θείων πραγμάτων οὕτω προέστησαν ὥστε καὶ τὰς ἐπιμελείας καὶ τὰς τιμωρίας εἶναι δοκεῖν ἀκριβεστέρας τῶν συμβαινόντων, οἱ δὲ τοιοῦτοι πλεῖστα τὸν βίον τὸν τῶν ἀνθρώπων ὠφελοῦσιν.", "st": "11.24"}, {"sp": "N", "t": "καὶ γὰρ τὴν ἀρχὴν οἱ τὸν φόβον ἡμῖν ἐνεργασάμενοι τοῦτον αἴτιοι γεγόνασι τοῦ μὴ παντάπασι θηριωδῶς διακεῖσθαι πρὸς ἀλλήλους. ἐκεῖνοι τοίνυν οὕτως ἁγίως περὶ ταῦτα καὶ σεμνῶς ἔχουσιν ὥστε καὶ τοὺς ὅρκους πιστοτέρους εἶναι τοὺς ἐν τοῖς ἐκείνων ἱεροῖς ἢ τοὺς παρὰ τοῖς ἄλλοις καθεστῶτας, καὶ τῶν ἁμαρτημάτων ἕκαστον οἴεσθαι παραχρῆμα δώσειν δίκην, ἀλλ’ οὐ διαλήσειν τὸν παρόντα χρόνον, οὐδ’ εἰς τοὺς παῖδας ἀναβληθήσεσθαι τὰς τιμωρίας.", "st": "11.25"}, {"sp": "N", "t": "καὶ ταῦτ’ εἰκότως δοξάζουσιν· πολλὰς γὰρ αὐτοῖς καὶ παντοδαπὰς ἀσκήσεις τῆς ὁσιότητος ἐκεῖνος κατέστησεν, ὅστις καὶ τῶν ζῴων τῶν παρ’ ἡμῖν καταφρονουμένων ἔστιν ἃ σέβεσθαι καὶ τιμᾶν ἐνομοθέτησεν, οὐκ ἀγνοῶν τὴν δύναμιν αὐτῶν, ἀλλ’ ἅμα μὲν ἐθίζειν οἰόμενος δεῖν τὸν ὄχλον ἐμμένειν ἅπασι τοῖς ὑπὸ τῶν ἀρχόντων παραγγελλομένοις,", "st": "11.26"}, {"sp": "N", "t": "ἅμα δὲ βουλόμενος πεῖραν λαμβάνειν ἐν τοῖς φανεροῖς, ἥντινα περὶ τῶν ἀφανῶν διάνοιαν ἔχουσιν. ἐνόμιζε γὰρ τοὺς μὲν τούτων ὀλιγωροῦντας τυχὸν καὶ τῶν μειζόνων καταφρονήσειν, τοὺς δ’ ἐπὶ πάντων ὁμοίως ἐμμένοντας τῇ τάξει βεβαίως ἔσεσθαι τὴν αὑτῶν εὐσέβειαν ἐπιδεδειγμένους.", "st": "11.27"}, {"sp": "N", "t": "ἔχοι δ’ ἄν τις μὴ σπεύδειν ὡρμημένος πολλὰ καὶ θαυμαστὰ περὶ τῆς ὁσιότητος αὐτῶν διελθεῖν, ἣν οὔτε μόνος οὔτε πρῶτος ἐγὼ τυγχάνω καθεωρακώς, ἀλλὰ πολλοὶ καὶ τῶν ὄντων καὶ τῶν προγεγενημένων, ὧν καὶ Πυθαγόρας ὁ Σάμιός ἐστιν· ὃς ἀφικόμενος εἰς Αἴγυπτον καὶ μαθητὴς ἐκείνων γενόμενος τήν τ’ ἄλλην φιλοσοφίαν πρῶτος εἰς τοὺς Ἕλληνας ἐκόμισε, καὶ τὰ περὶ τὰς θυσίας καὶ τὰς ἁγιστείας τὰς ἐν τοῖς ἱεροῖς ἐπιφανέστερον τῶν ἄλλων ἐσπούδασεν, ἡγούμενος, εἰ καὶ μηδὲν αὐτῷ διὰ ταῦτα πλέον γίγνοιτο παρὰ τῶν θεῶν, ἀλλ’ οὖν παρά γε τοῖς ἀνθρώποις ἐκ τούτων μάλιστ’ εὐδοκιμήσειν.", "st": "11.28"}, {"sp": "N", "t": "ὅπερ αὐτῷ καὶ συνέβη· τοσοῦτον γὰρ εὐδοξίᾳ τοὺς ἄλλους ὑπερέβαλεν, ὥστε καὶ τοὺς νεωτέρους ἅπαντας ἐπιθυμεῖν αὐτοῦ μαθητὰς εἶναι, καὶ τοὺς πρεσβυτέρους ἥδιον ὁρᾶν τοὺς παῖδας τοὺς αὑτῶν ἐκείνῳ συγγιγνομένους ἢ τῶν οἰκείων ἐπιμελουμένους. καὶ τούτοις οὐχ οἷόν τ’ ἀπιστεῖν· ἔτι γὰρ καὶ νῦν τοὺς προσποιουμένους ἐκείνου μαθητὰς εἶναι μᾶλλον σιγῶντας θαυμάζουσιν ἢ τοὺς ἐπὶ τῷ λέγειν μεγίστην δόξαν ἔχοντας.", "st": "11.29"}, {"sp": "N", "t": "ἴσως ἂν οὖν τοῖς εἰρημένοις ἀπαντήσειας, ὅτι τὴν μὲν χώραν καὶ τοὺς νόμους καὶ τὴν εὐσέβειαν, ἔτι δὲ τὴν φιλοσοφίαν ἐπαινῶ τὴν Αἰγυπτίων, ὡς δὲ τούτων αἴτιος ἦν, ὃν ὑπεθέμην, οὐδεμίαν ἔχω λέγειν ἀπόδειξιν. ἐγὼ δ’ εἰ μὲν ἄλλος τίς μοι τὸν τρόπον τοῦτον ἐπέπληττεν, ἡγούμην ἂν αὐτὸν πεπαιδευμένως ἐπιτιμᾶν· σοὶ δ’ οὐ προσήκει ταύτην ποιεῖσθαι τὴν ἐπίληψιν.", "st": "11.30"}, {"sp": "N", "t": "βουληθεὶς γὰρ Βούσιριν εὐλογεῖν προείλου λέγειν, ὡς τόν τε Νεῖλον περὶ τὴν χώραν περιέρρηξε καὶ τῶν ξένων τοὺς ἀφικνουμένους θύων κατήσθιεν· ὡς δὲ ταῦτ’ ἐποίησεν οὐδεμίαν πίστιν εἴρηκας. καίτοι πῶς οὐ καταγέλαστόν ἐστι ταῦτα παρὰ τῶν ἄλλων ἀπαιτεῖν, οἷς αὐτὸς μηδὲ κατὰ μικρὸν τυγχάνεις κεχρημένος;", "st": "11.31"}, {"sp": "N", "t": "ἀλλὰ τοσούτῳ πλέον ἡμῶν ἀπέχεις τοῦ πιστὰ λέγειν, ὅσον ἐγὼ μὲν οὐδενὸς αὐτὸν αἰτιῶμαι τῶν ἀδυνάτων ἀλλὰ νόμων καὶ πολιτείας, αἵπερ εἰσὶ πράξεις τῶν ἀνδρῶν τῶν καλῶν κἀγαθῶν· σὺ δὲ τοιούτων δημιουργὸν ἀποφαίνεις, ὧν οὐδέτερον οὐδεὶς ἂν ἀνθρώπων ποιήσειεν, ἀλλὰ τὸ μὲν τῆς τῶν θηρίων ὠμότητος, τὸ δὲ τῆς τῶν θεῶν δυνάμεως ἔργον ἐστίν.", "st": "11.32"}, {"sp": "N", "t": "ἔπειτ’ εἰ καὶ τυγχάνομεν ἀμφότεροι ψευδῆ λέγοντες, ἀλλ’ οὖν ἐγὼ μὲν κέχρημαι τούτοις τοῖς λόγοις, οἷσπερ χρὴ τοὺς ἐπαινοῦντας, σὺ δ’ οἷς προσήκει τοὺς λοιδοροῦντας· ὥστ’ οὐ μόνον τῆς ἀληθείας αὐτῶν ἀλλὰ καὶ τῆς ἰδέας ὅλης δι’ ἧς εὐλογεῖν δεῖ, φαίνει διημαρτηκώς.", "st": "11.33"}, {"sp": "N", "t": "χωρὶς δὲ τούτων εἰ δεῖ τῶν σῶν ἀπαλλαγέντα τὸν ἐμὸν λόγον ἐξετάζειν, οὐδεὶς ἂν αὐτῷ δικαίως ἐπιπλήξειεν. εἰ μὲν γὰρ ἄλλος τις ἦν φανερὸς ὁ ταῦτα πράξας, ἁγώ φημι γεγενῆσθαι δι’ ἐκεῖνον, ὁμολογῶ λίαν εἶναι τολμηρός, εἰ περὶ ὧν ἅπαντες ἐπίστανται,", "st": "11.34"}, {"sp": "N", "t": "περὶ τούτων μεταπείθειν ἐπιχειρῶ. νῦν δ’ ἐν κοινῷ τῶν πραγμάτων ὄντων καὶ δοξάσαι δέον περὶ αὐτῶν, τίν’ ἄν τις τῶν ἐκεῖ καθεστώτων ἐκ τῶν εἰκότων σκοπούμενος αἰτιώτερον εἶναι νομίσειεν ἢ τὸν ἐκ Ποσειδῶνος μὲν γεγονότα, πρὸς δὲ μητρὸς ἀπὸ Διὸς ὄντα, μεγίστην δὲ δύναμιν τῶν καθ’ αὑτὸν κτησάμενον καὶ παρὰ τοῖς ἄλλοις ὀνομαστότατον γεγενημένον; οὐ γὰρ δή που τοὺς ἁπάντων τούτων ἀπολελειμμένους προσήκει μᾶλλον ἢ κεῖνον τηλικούτων ἀγαθῶν εὑρετὰς γενέσθαι.", "st": "11.35"}, {"sp": "N", "t": "καὶ μὲν δὴ καὶ τοῖς χρόνοις ῥᾳδίως ἄν τις τοὺς λόγους τοὺς τῶν λοιδορούντων ἐκεῖνον ψευδεῖς ὄντας ἐπιδείξειεν. οἱ γὰρ αὐτοὶ τῆς τε Βουσίριδος ξενοφονίας κατηγοροῦσι καί φασιν αὐτὸν ὑφ’ Ἡρακλέους ἀποθανεῖν·", "st": "11.36"}, {"sp": "N", "t": "ὁμολογεῖται δὲ παρὰ πάντων τῶν λογοποιῶν Περσέως τοῦ Διὸς καὶ Δανάης Ἡρακλέα μὲν εἶναι τέτταρσι γενεαῖς νεώτερον, Βούσιριν δὲ πλέον ἢ διακοσίοις ἔτεσι πρεσβύτερον. καίτοι τὸν βουλόμενον ἀπολύσασθαι τὴν ὑπὲρ ἐκείνου διαβολὴν πῶς οὐκ ἄτοπόν ἐστι ταύτην τὴν πίστιν παραλιπεῖν, τὴν οὕτως ἐναργῆ καὶ τηλικαύτην δύναμιν ἔχουσαν;", "st": "11.37"}, {"sp": "N", "t": "ἀλλὰ γὰρ οὐδέν σοι τῆς ἀληθείας ἐμέλησεν, ἀλλὰ ταῖς τῶν ποιητῶν βλασφημίαις ἐπηκολούθησας, οἳ δεινότερα μὲν πεποιηκότας καὶ πεπονθότας ἀποφαίνουσι τοὺς ἐκ τῶν ἀθανάτων γεγονότας ἢ τοὺς ἐκ τῶν ἀνθρώπων τῶν ἀνοσιωτάτων, τοιούτους δὲ λόγους περὶ αὐτῶν τῶν θεῶν εἰρήκασιν, οἵους οὐδεὶς ἂν περὶ τῶν ἐχθρῶν εἰπεῖν τολμήσειεν· οὐ γὰρ μόνον κλοπὰς καὶ μοιχείας καὶ παρ’ ἀνθρώποις θητείας αὐτοῖς ὠνείδισαν, ἀλλὰ καὶ παίδων βρώσεις καὶ πατέρων ἐκτομὰς καὶ μητέρων δεσμοὺς καὶ πολλὰς ἄλλας ἀνομίας κατ’ αὐτῶν ἐλογοποίησαν.", "st": "11.38"}, {"sp": "N", "t": "ὑπὲρ ὧν τὴν μὲν ἀξίαν δίκην οὐκ ἔδοσαν, οὐ μὴν ἀτιμώρητοί γε διέφυγον, ἀλλ’ οἱ μὲν αὐτῶν ἀλῆται καὶ τῶν καθ’ ἡμέραν ἐνδεεῖς κατέστησαν, οἱ δ’ ἐτυφλώθησαν, ἄλλος δὲ φεύγων τὴν πατρίδα καὶ τοῖς οἰκειοτάτοις πολεμῶν ἅπαντα τὸν χρόνον διετέλεσεν, Ὀρφεὺς δ’ ὁ μάλιστα τούτων τῶν λόγων ἁψάμενος, διασπασθεὶς τὸν βίον ἐτελεύτησεν· ὥστ’ ἢν σωφρονῶμεν,", "st": "11.39"}, {"sp": "N", "t": "οὐ μιμησόμεθα τοὺς λόγους τοὺς ἐκείνων, οὐδὲ περὶ μὲν τῆς πρὸς ἀλλήλους κακηγορίας νομοθετήσομεν, τῆς δ’ εἰς τοὺς θεοὺς παρρησίας ὀλιγωρήσομεν, ἀλλὰ φυλαξόμεθα καὶ νομιοῦμεν ὁμοίως ἀσεβεῖν τούς τε λέγοντας τὰ τοιαῦτα καὶ τοὺς πιστεύοντας αὐτοῖς.", "st": "11.40"}, {"sp": "N", "t": "ἐγὼ μὲν οὖν οὐχ ὅπως τοὺς θεούς, ἀλλ’ οὐδὲ τοὺς ἐξ ἐκείνων γεγονότας οὐδεμιᾶς ἡγοῦμαι κακίας μετασχεῖν, ἀλλ’ αὐτούς τε πάσας ἔχοντας τὰς ἀρετὰς φῦναι καὶ τοῖς ἄλλοις τῶν καλλίστων ἐπιτηδευμάτων ἡγεμόνας καὶ διδασκάλους γεγενῆσθαι. καὶ γὰρ ἄλογον, εἰ τῆς μὲν ἡμετέρας εὐπαιδίας εἰς τοὺς θεοὺς τὴν αἰτίαν ἀναφέρομεν, τῆς δὲ σφετέρας αὐτῶν μηδὲν αὐτοὺς φροντίζειν νομίζοιμεν.", "st": "11.41"}, {"sp": "N", "t": "ἀλλ’ εἰ μὲν ἡμῶν τις τῆς τῶν ἀνθρώπων φύσεως κατασταίη κύριος, οὐδ’ ἂν τοὺς οἰκέτας ἐάσειεν εἶναι πονηρούς· ἐκείνων δὲ καταγιγνώσκομεν ὡς καὶ τοὺς ἐξ αὑτῶν γεγονότας περιεῖδον οὕτως ἀσεβεῖς καὶ παρανόμους ὄντας. καὶ σὺ μὲν οἴει καὶ τοὺς μηδὲν προσήκοντας, ἤν σοι πλησιάσωσι, βελτίους ποιήσειν, τοὺς δὲ θεοὺς οὐδεμίαν ἡγεῖ τῆς τῶν παίδων ἀρετῆς ἔχειν ἐπιμέλειαν.", "st": "11.42"}, {"sp": "N", "t": "καίτοι κατὰ τὸν σὸν λόγον δυοῖν τοῖν αἰσχίστοιν οὐ διαμαρτάνουσιν· εἰ μὲν γὰρ μηδὲν δέονται χρηστοὺς αὐτοὺς εἶναι, χείρους εἰσὶ τῶν ἀνθρώπων τὴν διάνοιαν, εἰ δὲ βούλονται μέν, ἀποροῦσι δ’ ὅπως ποιήσωσιν, ἐλάττω τῶν σοφιστῶν τὴν δύναμιν ἔχουσιν.", "st": "11.43"}, {"sp": "N", "t": "πολλῶν δ’ ἐνόντων εἰπεῖν ἐξ ὧν ἄν τις καὶ τὸν ἔπαινον καὶ τὴν ἀπολογίαν μηκύνειεν, οὐχ ἡγοῦμαι δεῖν μακρολογεῖν· οὐ γὰρ ἐπίδειξιν τοῖς ἄλλοις ποιούμενος, ἀλλ’ ὑποδεῖξαί σοι βουλόμενος ὡς χρὴ τούτων ἑκάτερον ποιεῖν, διείλεγμαι περὶ αὐτῶν, ἐπεὶ τόν γε λόγον ὃν σὺ γέγραφας, οὐκ ἀπολογίαν ὑπὲρ Βουσίριδος, ἀλλ’ ὁμολογίαν τῶν ἐπικαλουμένων δικαίως ἄν τις εἶναι νομίσειεν.", "st": "11.44"}, {"sp": "N", "t": "οὐ γὰρ ἀπολύεις αὐτὸν τῶν αἰτιῶν, ἀλλ’ ἀποφαίνεις ὡς καὶ τῶν ἄλλων τινὲς ταὐτὰ πεποιήκασι, ῥᾳθυμοτάτην τοῖς ἁμαρτάνουσιν εὑρίσκων καταφυγήν. εἰ γὰρ τῶν μὲν ἀδικημάτων μὴ ῥᾴδιον εὑρεῖν ὃ μήπω τυγχάνει γεγενημένον, τοὺς δ’ ἐφ’ ἑκάστοις αὐτῶν ἁλισκομένους μηδὲν ἡγοίμεθα δεινὸν ποιεῖν, ὅταν ἕτεροι ταὐτὰ φαίνωνται διαπεπραγμένοι, πῶς οὐκ ἂν καὶ τὰς ἀπολογίας ἅπασι ῥᾳδίας ποιήσαιμεν, καὶ τοῖς βουλομένοις εἶναι πονηροῖς πολλὴν ἐξουσίαν παρασκευάσαιμεν;", "st": "11.45"}, {"sp": "N", "t": "μάλιστα δ’ ἂν κατίδοις τὴν εὐήθειαν τῶν εἰρημένων ἐπὶ σαυτοῦ θεωρήσας. ἐνθυμήθητι γάρ· εἰ μεγάλων καὶ δεινῶν αἰτιῶν περὶ σὲ γεγονυιῶν τοῦτόν τις τὸν τρόπον σοι συνείποι, πῶς ἂν διατεθείης; ἐγὼ μὲν γὰρ οἶδ’ ὅτι μᾶλλον ἂν αὐτὸν μισήσειας ἢ τοὺς κατηγοροῦντας. καίτοι πῶς οὐκ αἰσχρὸν τοιαύτας ὑπὲρ τῶν ἄλλων ποιεῖσθαι τὰς ἀπολογίας, ἐφ’ αἷς ὑπὲρ σαυτοῦ λεγομέναις μάλιστ’ ἂν ὀργισθείης;", "st": "11.46"}, {"sp": "N", "t": "σκέψαι δὲ κἀκεῖνο καὶ δίελθε πρὸς αὑτόν. εἴ τις τῶν σοι συνόντων ἐπαρθείη ποιεῖν ἃ σὺ τυγχάνεις εὐλογῶν, πῶς οὐκ ἂν ἀθλιώτατος εἴη καὶ τῶν νῦν ὄντων καὶ τῶν πώποτε γεγενημένων; ἆρ’ οὖν χρὴ τοιούτους λόγους γράφειν οἷς τοῦτο προσέσται μέγιστον ἀγαθόν, ἢν μηδένα πεῖσαι τῶν ἀκουσάντων δυνηθῶσιν;", "st": "11.47"}, {"sp": "N", "t": "ἀλλὰ γὰρ ἴσως ἂν εἴποις ὡς οὐδὲ σὲ τοῦτο παρέλαθεν, ἀλλ’ ἐβουλήθης τοῖς φιλοσόφοις παράδειγμα καταλιπεῖν ὡς χρὴ περὶ τῶν αἰσχρῶν αἰτιῶν καὶ δυσχερῶν πραγμάτων ποιεῖσθαι τὰς ἀπολογίας. ἀλλ’ εἰ καὶ πρότερον ἠγνόεις, οἶμαί σοι νῦν γεγενῆσθαι φανερὸν ὅτι πολὺ θᾶττον ἄν τις σωθείη μηδὲν φθεγξάμενος ἢ τοῦτον τὸν τρόπον ἀπολογησάμενος.", "st": "11.48"}, {"sp": "N", "t": "καὶ μὲν δὴ καὶ τοῦτο δῆλον, ὅτι τῆς φιλοσοφίας ἐπικήρως διακειμένης καὶ φθονουμένης διὰ τοὺς τοιούτους τῶν λόγων ἔτι μᾶλλον αὐτὴν μισήσουσιν. ἢν οὖν ἐμοὶ πείθῃ, μάλιστα μὲν οὐ ποιήσει τοῦ λοιποῦ πονηρὰς ὑποθέσεις, εἰ δὲ μή, τοιαῦτα ζητήσεις λέγειν ἐξ ὧν μήτ’ αὐτὸς χείρων εἶναι δόξεις μήτε τοὺς μιμουμένους λυμανεῖ μήτε τὴν περὶ τοὺς λόγους παίδευσιν διαβαλεῖς.", "st": "11.49"}, {"sp": "N", "t": "καὶ μὴ θαυμάσῃς, εἰ νεώτερος ὢν καὶ μηδέν σοι προσήκων οὕτω προχείρως ἐπιχειρῶ σε νουθετεῖν· ἡγοῦμαι γὰρ οὐ τῶν πρεσβυτάτων οὐδὲ τῶν οἰκειοτάτων, ἀλλὰ τῶν πλεῖστ’ εἰδότων καὶ βουλομένων ὠφελεῖν ἔργον εἶναι περὶ τῶν τοιούτων συμβουλεύειν.", "st": "11.50"}, {"sp": "HDR", "t": "Πλαταϊκός", "st": "14"}, {"sp": "N", "t": "εἰδότες ὑμᾶς, ὦ ἄνδρες Ἀθηναῖοι, καὶ τοῖς ἀδικουμένοις προθύμως βοηθεῖν εἰθισμένους καὶ τοῖς εὐεργέταις μεγίστην χάριν ἀποδιδόντας, ἥκομεν ἱκετεύσοντες μὴ περιιδεῖν ἡμᾶς εἰρήνης οὔσης ἀναστάτους ὑπὸ Θηβαίων γεγενημένους. πολλῶν δ’ ἤδη πρὸς ὑμᾶς καταφυγόντων καὶ διαπραξαμένων ἅπανθ’ ὅσων ἐδεήθησαν, ἡγούμεθα μάλισθ’ ὑμῖν προσήκειν περὶ τῆς ἡμετέρας πόλεως ποιήσασθαι πρόνοιαν·", "st": "14.1"}, {"sp": "N", "t": "οὔτε γὰρ ἂν ἀδικώτερον οὐδένας ἡμῶν εὕροιτε τηλικαύταις συμφοραῖς περιπεπτωκότας, οὔτ’ ἐκ πλείονος χρόνου πρὸς τὴν ὑμετέραν πόλιν οἰκειότερον διακειμένους. ἔτι δὲ τοιούτων δεησόμενοι πάρεσμεν ἐν οἷς κίνδυνος μὲν οὐδεὶς ἔνεστιν, ἅπαντες δ’ ἄνθρωποι νομιοῦσιν ὑμᾶς πειθομένους ὁσιωτάτους καὶ δικαιοτάτους εἶναι τῶν Ἑλλήνων.", "st": "14.2"}, {"sp": "N", "t": "εἰ μὲν οὖν μὴ Θηβαίους ἑωρῶμεν ἐκ παντὸς τρόπου παρεσκευασμένους πείθειν ὑμᾶς, ὡς οὐδὲν εἰς ἡμᾶς ἐξημαρτήκασι, διὰ βραχέων ἂν ἐποιησάμεθα τοὺς λόγους· ἐπειδὴ δ’ εἰς τοῦθ’ ἥκομεν ἀτυχίας ὥστε μὴ μόνον ἡμῖν εἶναι τὸν ἀγῶνα πρὸς τούτους, ἀλλὰ καὶ τῶν ῥητόρων πρὸς τοὺς δυνατωτάτους, οὓς ἀπὸ τῶν ἡμετέρων αὑτοῖς οὗτοι παρεσκευάσαντο συνηγόρους, ἀναγκαῖον διὰ μακροτέρων δηλῶσαι περὶ αὐτῶν.", "st": "14.3"}, {"sp": "N", "t": "χαλεπὸν μὲν οὖν μηδὲν καταδεέστερον εἰπεῖν ὧν πεπόνθαμεν· ποῖος γὰρ ἂν λόγος ἐξισωθείη ταῖς ἡμετέραις δυσπραξίαις, ἢ τίς ἂν ῥήτωρ ἱκανὸς γένοιτο κατηγορῆσαι τῶν Θηβαίοις ἡμαρτημένων; ὅμως δὲ πειρατέον οὕτως ὅπως ἂν δυνώμεθα φανερὰν καταστῆσαι τὴν τούτων παρανομίαν.", "st": "14.4"}, {"sp": "N", "t": "πολὺ δὲ μάλιστ’ ἀγανακτοῦμεν ὅτι τοσούτου δέομεν τῶν ἴσων ἀξιοῦσθαι τοῖς ἄλλοις Ἕλλησιν, ὥστ’ εἰρήνης οὔσης καὶ συνθηκῶν γεγενημένων οὐχ ὅπως τῆς κοινῆς ἐλευθερίας μετέχομεν, ἀλλ’ οὐδὲ δουλείας μετρίας τυχεῖν ἠξιώθημεν.", "st": "14.5"}, {"sp": "N", "t": "δεόμεθ’ οὖν ὑμῶν, ὦ ἄνδρες Ἀθηναῖοι, μετ’ εὐνοίας ἀκροάσασθαι τῶν λεγομένων, ἐνθυμηθέντας ὅτι πάντων ἂν ἡμῖν ἀλογώτατον εἴη συμβεβηκός, εἰ τοῖς μὲν ἅπαντα τὸν χρόνον δυσμενῶς πρὸς τὴν πόλιν ὑμῶν διακειμένοις αἴτιοι γεγένησθε τῆς ἐλευθερίας, ἡμεῖς δὲ μηδ’ ἱκετεύοντες ὑμᾶς τῶν αὐτῶν τοῖς ἐχθίστοις τύχοιμεν.", "st": "14.6"}, {"sp": "N", "t": "περὶ μὲν οὖν τῶν γεγενημένων οὐκ οἶδ’ ὅ τι δεῖ μακρολογεῖν· τίς γὰρ οὐκ οἶδεν ὅτι καὶ τὴν χώραν ἡμῶν κατανενέμηνται καὶ τὴν πόλιν κατεσκάφασιν; ἃ δὲ λέγοντες ἐλπίζουσιν ἐξαπατήσειν ὑμᾶς, περὶ τούτων πειρασόμεθα διδάσκειν.", "st": "14.7"}, {"sp": "N", "t": "ἐνίοτε μὲν γὰρ ἐπιχειροῦσι λέγειν, ὡς διὰ τοῦτο πρὸς ἡμᾶς οὕτω προσηνέχθησαν, ὅτι συντελεῖν αὐτοῖς οὐκ ἠθέλομεν. ὑμεῖς δ’ ἐνθυμεῖσθε πρῶτον μὲν εἰ δίκαιόν ἐστιν ὑπὲρ τηλικούτων ἐγκλημάτων οὕτως ἀνόμους καὶ δεινὰς ποιεῖσθαι τὰς τιμωρίας, ἔπειτ’ εἰ προσήκειν ὑμῖν δοκεῖ μὴ πεισθεῖσαν τὴν Πλαταιέων πόλιν, ἀλλὰ βιασθεῖσαν Θηβαίοις συντελεῖν. ἐγὼ μὲν γὰρ οὐδένας ἡγοῦμαι τολμηροτέρους εἶναι τούτων, οἵτινες τὰς μὲν ἰδίας ἡμῶν ἑκάστων πόλεις ἀφανίζουσι, τῆς δὲ σφετέρας αὐτῶν πολιτείας οὐδὲν δεομένους κοινωνεῖν ἀναγκάζουσιν.", "st": "14.8"}, {"sp": "N", "t": "πρὸς δὲ τούτοις οὐδ’ ὁμολογούμενα φαίνονται διαπραττόμενοι πρός τε τοὺς ἄλλους καὶ πρὸς ἡμᾶς. ἐχρῆν γὰρ αὐτούς, ἐπειδὴ πείθειν ἡμῶν τὴν πόλιν οὐχ οἷοί τ’ ἦσαν, ὥσπερ τοὺς Θεσπιέας καὶ τοὺς Ταναγραίους, συντελεῖν μόνον εἰς τὰς Θήβας ἀναγκάζειν· οὐδὲν γὰρ ἂν τῶν ἀνηκέστων κακῶν ἦμεν πεπονθότες. νῦν δὲ φανεροὶ γεγόνασιν οὐ τοῦτο διαπράξασθαι βουληθέντες, ἀλλὰ τῆς χώρας ἡμῶν ἐπιθυμήσαντες.", "st": "14.9"}, {"sp": "N", "t": "θαυμάζω δὲ πρὸς τί τῶν γεγενημένων ἀναφέροντες καὶ πῶς ποτε τὸ δίκαιον κρίνοντες ταῦτα φήσουσι προστάττειν ἡμῖν. εἰ μὲν γὰρ τὰ πάτρια σκοποῦσιν, οὐ τῶν ἄλλων αὐτοῖς ἀρκτέον, ἀλλὰ πολὺ μᾶλλον Ὀρχομενίοις φόρον οἰστέον· οὕτω γὰρ εἶχε τὸ παλαιόν· εἰ δὲ τὰς συνθήκας ἀξιοῦσιν εἶναι κυρίας, ὅπερ ἐστὶ δίκαιον, πῶς οὐχ ὁμολογήσουσιν ἀδικεῖν καὶ παραβαίνειν αὐτάς; ὁμοίως γὰρ τάς τε μικρὰς τῶν πόλεων καὶ τὰς μεγάλας αὐτονόμους εἶναι κελεύουσιν.", "st": "14.10"}, {"sp": "N", "t": "οἶμαι δὲ περὶ μὲν τούτων οὐ τολμήσειν αὐτοὺς ἀναισχυντεῖν, ἐπ’ ἐκεῖνον δὲ τρέψεσθαι τὸν λόγον, ὡς μετὰ Λακεδαιμονίων ἐπολεμοῦμεν, καὶ πάσῃ τῇ συμμαχίᾳ διαφθείραντες ἡμᾶς τὰ συμφέροντα πεποιήκασιν.", "st": "14.11"}, {"sp": "N", "t": "ἐγὼ δ’ ἡγοῦμαι μὲν χρῆναι μηδεμίαν μήτ’ αἰτίαν μήτε κατηγορίαν μεῖζον δύνασθαι τῶν ὅρκων καὶ τῶν συνθηκῶν· οὐ μὴν ἀλλ’ εἰ δεῖ τινὰς κακῶς παθεῖν διὰ τὴν Λακεδαιμονίων συμμαχίαν, οὐκ ἂν Πλαταιεῖς ἐξ ἁπάντων τῶν Ἑλλήνων προὐκρίθησαν δικαίως· οὐ γὰρ ἑκόντες, ἀλλ’ ἀναγκασθέντες αὐτοῖς ἐδουλεύομεν.", "st": "14.12"}, {"sp": "N", "t": "τίς γὰρ ἂν πιστεύσειεν εἰς τοῦθ’ ἡμᾶς ἀνοίας ἐλθεῖν ὥστε περὶ πλείονος ποιήσασθαι τοὺς ἐξανδραποδισαμένους ἡμῶν τὴν πατρίδα μᾶλλον ἢ τοὺς τῆς πόλεως τῆς αὑτῶν μεταδόντας; ἀλλὰ γάρ, οἶμαι, χαλεπὸν ἦν νεωτερίζειν αὐτοὺς μὲν μικρὰν πόλιν οἰκοῦντας, ἐκείνων δ’ οὕτω μεγάλην δύναμιν κεκτημένων, ἔτι δὲ πρὸς τούτοις ἁρμοστοῦ καθεστῶτος καὶ φρουρᾶς ἐνούσης καὶ τηλικούτου στρατεύματος ὄντος Θεσπιᾶσιν,", "st": "14.13"}, {"sp": "N", "t": "ὑφ’ ὧν οὐ μόνον ἂν θᾶττον ἢ Θηβαίων διεφθάρημεν, ἀλλὰ καὶ δικαιότερον· τούτους μὲν γὰρ εἰρήνης οὔσης οὐ προσῆκε μνησικακεῖν περὶ τῶν τότε γεγενημένων, ἐκεῖνοι δ’ ἐν τῷ πολέμῳ προδοθέντες εἰκότως ἂν παρ’ ἡμῶν τὴν μεγίστην δίκην ἐλάμβανον.", "st": "14.14"}, {"sp": "N", "t": "ἡγοῦμαι δ’ ὑμᾶς οὐκ ἀγνοεῖν ὅτι πολλοὶ καὶ τῶν ἄλλων Ἑλλήνων τοῖς μὲν σώμασι μετ’ ἐκείνων ἀκολουθεῖν ἠναγκάζοντο, ταῖς δ’ εὐνοίαις μεθ’ ὑμῶν ἦσαν. οὓς τίνα χρὴ προσδοκᾶν γνώμην ἕξειν, ἢν ἀκούσωσιν ὅτι Θηβαῖοι τὸν δῆμον τὸν Ἀθηναίων πεπείκασιν ὡς οὐδενός ἐστι φειστέον τῶν ὑπὸ Λακεδαιμονίοις γενομένων;", "st": "14.15"}, {"sp": "N", "t": "ὁ γὰρ τούτων λόγος οὐδὲν ἄλλ’ ἢ τοῦτο φανήσεται δυνάμενος· οὐ γὰρ ἰδίαν κατηγορίαν ποιούμενοι κατὰ τῆς πόλεως τῆς ἡμετέρας ἀπολωλέκασιν αὐτήν, ἀλλ’ ἣν ὁμοίως καὶ κατ’ ἐκείνων ἕξουσιν εἰπεῖν. ὑπὲρ ὧν βουλεύεσθαι χρὴ καὶ σκοπεῖν, ὅπως μὴ τοὺς πρότερον μισοῦντας τὴν ἀρχὴν τὴν Λακεδαιμονίων ἡ τούτων ὕβρις διαλλάξει καὶ ποιήσει τὴν ἐκείνων συμμαχίαν αὑτῶν νομίζειν εἶναι σωτηρίαν.", "st": "14.16"}, {"sp": "N", "t": "ἐνθυμεῖσθε δ’ ὅτι τὸν πόλεμον ἀνείλεσθε τὸν ὑπογυιότατον οὐχ ὑπὲρ τῆς ὑμετέρας οὐδ’ ὑπὲρ τῆς τῶν συμμάχων ἐλευθερίας, ἅπασι γὰρ ὑπῆρχεν ὑμῖν, ἀλλ’ ὑπὲρ τῶν παρὰ τοὺς ὅρκους καὶ τὰς συνθήκας τῆς αὐτονομίας ἀποστερουμένων. ὃ δὴ καὶ πάντων σχετλιώτατον, εἰ τὰς πόλεις ἃς οὐκ ᾤεσθε δεῖν Λακεδαιμονίοις δουλεύειν, ταύτας περιόψεσθε νῦν ὑπὸ Θηβαίων ἀπολλυμένας· οἳ τοσούτου δέουσι μιμεῖσθαι τὴν πραότητα τὴν ὑμετέραν, ὥσθ’ ὃ δοκεῖ πάντων δεινότατον εἶναι,", "st": "14.17"}, {"sp": "N", "t": "δοριαλώτους γενέσθαι, τοῦτο κρεῖττον ἦν ἡμῖν παθεῖν ὑπὸ ταύτης τῆς πόλεως ἢ τούτων τυχεῖν ὁμόρους ὄντας. οἱ μὲν γὰρ ὑφ’ ὑμῶν κατὰ κράτος ἁλόντες εὐθὺς μὲν ἁρμοστοῦ καὶ δουλείας ἀπηλλάγησαν, νῦν δὲ τοῦ συνεδρίου καὶ τῆς ἐλευθερίας μετέχουσιν· οἱ δὲ τούτων πλησίον οἰκοῦντες οἱ μὲν οὐδὲν ἧττον τῶν ἀργυρωνήτων δουλεύουσι, τοὺς δ’ οὐ πρότερον παύσονται πρὶν ἂν οὕτως ὥσπερ ἡμᾶς διαθῶσιν. καὶ Λακεδαιμονίων μὲν κατηγοροῦσιν,", "st": "14.18"}, {"sp": "N", "t": "ὅτι τὴν Καδμείαν κατέλαβον καὶ φρουρὰς εἰς τὰς πόλεις καθίστασαν, αὐτοὶ δ’ οὐ φύλακας εἰσπέμποντες, ἀλλὰ τῶν μὲν τὰ τείχη κατασκάπτοντες, τοὺς δ’ ἄρδην ἀπολλύοντες οὐδὲν οἴονται δεινὸν ποιεῖν, ἀλλ’ εἰς τοῦτ’ ἀναισχυντίας ἐληλύθασιν, ὥστε τῆς μὲν αὑτῶν σωτηρίας τοὺς συμμάχους ἅπαντας ἀξιοῦσιν ἐπιμελεῖσθαι, τῆς δὲ τῶν ἄλλων δουλείας αὑτοὺς κυρίους καθιστᾶσιν.", "st": "14.19"}, {"sp": "N", "t": "καίτοι τίς οὐκ ἂν μισήσειε τὴν τούτων πλεονεξίαν, οἳ τῶν μὲν ἀσθενεστέρων ἄρχειν ζητοῦσι, τοῖς δὲ κρείττοσιν ἴσον ἔχειν οἴονται δεῖν, καὶ τῇ μὲν ὑμετέρᾳ πόλει τῆς γῆς τῆς ὑπ’ Ὠρωπίων δεδομένης φθονοῦσιν, αὐτοὶ δὲ βία τὴν ἀλλοτρίαν χώραν κατανέμονται;", "st": "14.20"}, {"sp": "N", "t": "καὶ πρὸς τοῖς ἄλλοις κακοῖς λέγουσιν ὡς ὑπὲρ τοῦ κοινοῦ τῶν συμμάχων ταῦτ’ ἔπραξαν. καίτοι χρῆν αὐτούς, ὄντος ἐνθάδε συνεδρίου καὶ τῆς ὑμετέρας πόλεως ἄμεινον βουλεύεσθαι δυναμένης ἢ τῆς Θηβαίων, οὐχ ὑπὲρ τῶν πεπραγμένων ἥκειν ἀπολογησομένους, ἀλλὰ πρὶν ποιῆσαί τι τούτων ἐλθεῖν ὡς ὑμᾶς βουλευσομένους.", "st": "14.21"}, {"sp": "N", "t": "νῦν δὲ τὰς μὲν οὐσίας τὰς ἡμετέρας ἰδίᾳ διηρπάκασι, τῆς δὲ διαβολῆς ἅπασι τοῖς συμμάχοις ἥκουσι μεταδώσοντες. ἣν ὑμεῖς, ἢν σωφρονῆτε, φυλάξεσθε· πολὺ γὰρ κάλλιον τούτους ἀναγκάσαι μιμήσασθαι τὴν ὁσιότητα τὴν ὑμετέραν ἢ τῆς τούτων παρανομίας αὐτοὺς πεισθῆναι μετασχεῖν, οἳ μηδὲν τῶν αὐτῶν τοῖς ἄλλοις γιγνώσκουσιν.", "st": "14.22"}, {"sp": "N", "t": "οἶμαι γὰρ ἅπασι φανερὸν εἶναι διότι προσήκει τοὺς εὖ φρονοῦντας ἐν μὲν τῷ πολέμῳ σκοπεῖν ὅπως ἐκ παντὸς τρόπου πλέον ἕξουσι τῶν ἐχθρῶν, ἐπειδὰν δ’ εἰρήνη γένηται, μηδὲν περὶ πλείονος ποιεῖσθαι τῶν ὅρκων καὶ τῶν συνθηκῶν.", "st": "14.23"}, {"sp": "N", "t": "οὗτοι δὲ τότε μὲν ἐν ἁπάσαις ταῖς πρεσβείαις ὑπὲρ τῆς ἐλευθερίας καὶ τῆς αὐτονομίας ἐποιοῦντο τοὺς λόγους· ἐπειδὴ δὲ νομίζουσιν αὑτοῖς ἄδειαν γεγενῆσθαι, πάντων τῶν ἄλλων ἀμελήσαντες ὑπὲρ τῶν ἰδίων κερδῶν καὶ τῆς αὑτῶν βίας λέγειν τολμῶσι,", "st": "14.24"}, {"sp": "N", "t": "καὶ φασὶ τὸ Θηβαίους ἔχειν τὴν ἡμετέραν, τοῦτο συμφέρον εἶναι τοῖς συμμάχοις, κακῶς εἰδότες ὡς οὐδ’ αὐτοῖς τοῖς παρὰ τὸ δίκαιον πλεονεκτοῦσιν οὐδὲ πώποτε συνήνεγκεν, ἀλλὰ πολλοὶ δὴ τῆς ἀλλοτρίας ἀδίκως ἐπιθυμήσαντες περὶ τῆς αὑτῶν δικαίως εἰς τοὺς μεγίστους κινδύνους κατέστησαν.", "st": "14.25"}, {"sp": "N", "t": "ἀλλὰ μὴν οὐδ’ ἐκεῖνό γ’ ἕξουσι λέγειν, ὡς αὐτοὶ μέν, μεθ’ ὧν ἂν γένωνται, πιστοὶ διατελοῦσιν ὄντες, ἡμᾶς δ’ ἄξιον φοβεῖσθαι, μὴ κομισάμενοι τὴν χώραν πρὸς Λακεδαιμονίους ἀποστῶμεν· εὑρήσετε γὰρ ἡμᾶς μὲν δὶς ἐκπεπολιορκημένους ὑπὲρ τῆς φιλίας τῆς ὑμετέρας, τούτους δὲ πολλάκις εἰς ταύτην τὴν πόλιν ἐξημαρτηκότας.", "st": "14.26"}, {"sp": "N", "t": "καὶ τὰς μὲν παλαιὰς προδοσίας πολὺ ἂν ἔργον εἴη λέγειν· γενομένου δὲ τοῦ Κορινθιακοῦ πολέμου διὰ τὴν ὕβριν τὴν τούτων, καὶ Λακεδαιμονίων μὲν ἐπ’ αὐτοὺς στρατευσάντων, δι’ ὑμᾶς δὲ σωθέντες οὐχ ὅπως τούτων χάριν ἀπέδοσαν, ἀλλ’ ἐπειδὴ διελέλυσθε τὸν πόλεμον, ἀπολιπόντες ὑμᾶς εἰς τὴν Λακεδαιμονίων συμμαχίαν εἰσῆλθον.", "st": "14.27"}, {"sp": "N", "t": "καὶ Χῖοι μὲν καὶ Μυτιληναῖοι καὶ Βυζάντιοι συμπαρέμειναν, οὗτοι δὲ τηλικαύτην πόλιν οἰκοῦντες οὐδὲ κοινοὺς σφᾶς αὐτοὺς παρασχεῖν ἐτόλμησαν, ἀλλ’ εἰς τοῦτ’ ἀνανδρίας καὶ πονηρίας ἦλθον, ὥστ’ ὤμοσαν ἦ μὴν ἀκολουθήσειν μετ’ ἐκείνων ἐφ’ ὑμᾶς τοὺς διασώσαντας τὴν πόλιν αὐτῶν· ὑπὲρ ὧν δόντες τοῖς θεοῖς δίκην καὶ τῆς Καδμείας καταληφθείσης ἠναγκάσθησαν ἐνθάδε καταφυγεῖν. ὅθεν καὶ μάλιστ’ ἐπεδείξαντο τὴν αὑτῶν ἀπιστίαν·", "st": "14.28"}, {"sp": "N", "t": "σωθέντες γὰρ πάλιν διὰ τῆς ὑμετέρας δυνάμεως καὶ κατελθόντες εἰς τὴν αὑτῶν οὐδένα χρόνον ἐνέμειναν, ἀλλ’ εὐθὺς εἰς Λακεδαίμονα πρέσβεις ἀπέστελλον, ἕτοιμοι δουλεύειν ὄντες καὶ μηδὲν κινεῖν τῶν πρότερον πρὸς αὐτοὺς ὡμολογημένων. καὶ τί δεῖ μακρολογεῖν; εἰ γὰρ μὴ προσέταττον ἐκεῖνοι τούς τε φεύγοντας καταδέχεσθαι καὶ τοὺς αὐτόχειρας ἐξείργειν, οὐδὲν ἂν ἐκώλυεν αὐτοὺς μετὰ τῶν ἠδικηκότων ἐφ’ ὑμᾶς τοὺς εὐεργέτας στρατεύεσθαι.", "st": "14.29"}, {"sp": "N", "t": "καὶ τοιοῦτοι μὲν νεωστὶ περὶ τὴν πόλιν τήνδε γεγενημένοι, τὸ δὲ παλαιὸν ἁπάσης τῆς Ἑλλάδος προδόται καταστάντες, αὐτοὶ μὲν ὑπὲρ οὕτως ἑκουσίων σίων καὶ μεγάλων ἀδικημάτων συγγνώμης τυχεῖν ἠξιώθησαν, ἡμῖν δ’ ὑπὲρ ὧν ἠναγκάσθημεν, οὐδεμίαν ἔχειν οἴονται δεῖν, ἀλλὰ τολμῶσιν ὄντες Θηβαῖοι λακωνισμὸν ἑτέροις ὀνειδίζειν, οὓς πάντες ἴσμεν πλεῖστον χρόνον Λακεδαιμονίοις δεδουλευκότας καὶ προθυμότερον ὑπὲρ τῆς ἐκείνων ἀρχῆς ἢ τῆς αὑτῶν σωτηρίας πεπολεμηκότας.", "st": "14.30"}, {"sp": "N", "t": "ποίας γὰρ εἰσβολῆς ἀπελείφθησαν τῶν εἰς ταύτην τὴν χώραν γεγενημένων; ἢ τίνων οὐκ ἐχθίους ὑμῖν καὶ δυσμενέστεροι διετέλεσαν ὄντες; οὐκ ἐν τῷ Λεκελεικῷ πολέμῳ πλειόνων αἴτιοι κακῶν ἐγένοντο τῶν ἄλλων τῶν συνεισβαλόντων; οὐ δυστυχησάντων ὑμῶν μόνοι τῶν συμμάχων ἔθεντο τὴν ψῆφον, ὡς χρὴ τήν τε πόλιν ἐξανδραποδίσασθαι καὶ τὴν χώραν ἀνεῖναι μηλόβοτον ὥσπερ τὸ Κρισαῖον πεδίον;", "st": "14.31"}, {"sp": "N", "t": "ὥστ’ εἰ Λακεδαιμόνιοι τὴν αὐτὴν γνώμην ἔσχον Θηβαίοις, οὐδὲν ἂν ἐκώλυε τοὺς ἅπασι τοῖς Ἕλλησιν αἰτίους τῆς σωτηρίας γενομένους αὐτοὺς ὑπὸ τῶν Ἑλλήνων ἐξανδραποδισθῆναι καὶ ταῖς μεγίσταις συμφοραῖς περιπεσεῖν. καίτοι τίνα τηλικαύτην εὐεργεσίαν ἔχοιεν ἂν εἰπεῖν, ἥτις ἱκανὴ γενήσεται διαλῦσαι τὴν ἔχθραν τὴν ἐκ τούτων δικαίως ἂν ὑπάρχουσαν πρὸς αὐτούς;", "st": "14.32"}, {"sp": "N", "t": "τούτοις μὲν οὖν οὐδεὶς λόγος ὑπολείπεται τηλικαῦτα τὸ μέγεθος ἐξημαρτηκόσι, τοῖς δὲ συναγορεύειν βουλομένοις ἐκεῖνος μόνος, ὡς νῦν μὲν ἡ Βοιωτία προπολεμεῖ τῆς ὑμετέρας χώρας, ἢν δὲ διαλύσησθε τὴν πρὸς τούτους φιλίαν, ἀσύμφορα τοῖς συμμάχοις διαπράξεσθε· μεγάλην γὰρ ἔσεσθαι τὴν ῥοπήν, εἰ μετὰ Λακεδαιμονίων ἡ τούτων γενήσεται πόλις.", "st": "14.33"}, {"sp": "N", "t": "ἐγὼ δ’ οὔτε τοῖς συμμάχοις ἡγοῦμαι λυσιτελεῖν τοὺς ἀσθενεστέρους τοῖς κρείττοσι δουλεύειν, καὶ γὰρ τὸν παρελθόντα χρόνον ὑπὲρ τούτων ἐπολεμήσαμεν, οὔτε Θηβαίους εἰς τοῦτο μανίας ἥξειν ὥστ’ ἀποστάντας τῆς συμμαχίας Λακεδαιμονίοις ἐνδώσειν τὴν πόλιν, οὐχ ὡς πιστεύων τοῖς τούτων ἤθεσιν, ἀλλ’ οἶδ’ ὅτι γιγνώσκουσιν ὡς δυοῖν θάτερον ἀναγκαῖόν ἐστιν αὐτοῖς, ἢ μένοντας ἀποθνῄσκειν καὶ πάσχειν οἷά περ ἐποίησαν, ἢ φεύγοντας ἀπορεῖν καὶ τῶν ἐλπίδων ἁπασῶν ἐστερῆσθαι.", "st": "14.34"}, {"sp": "N", "t": "πότερα γὰρ τὰ πρὸς τοὺς πολίτας αὐτοῖς ἔχει καλῶς, ὧν τοὺς μὲν ἀποκτείναντες, τοὺς δ’ ἐκ τῆς πόλεως ἐκβαλόντες διηρπάκασι τὰς οὐσίας, ἢ τὰ πρὸς τοὺς ἄλλους Βοιωτούς, ὧν οὐκ ἄρχειν μόνον ἀδίκως ἐπιχειροῦσιν, ἀλλὰ τῶν μὲν τὰ τείχη κατεσκάφασι, τῶν δὲ καὶ τὴν χώραν ἀπεστερήκασιν;", "st": "14.35"}, {"sp": "N", "t": "ἀλλὰ μὴν οὐδ’ ἐπὶ τὴν ὑμετέραν πόλιν οἷόν τ’ αὐτοῖς ἐπανελθεῖν ἐστίν, ἣν οὕτω συνεχῶς φανήσονται προδιδόντες. ὥστ’ οὐκ ἔστιν ὅπως βουλήσονται πρὸς ὑμᾶς ὑπὲρ τῆς ἀλλοτρίας διενεχθέντες τὴν αὑτῶν πόλιν οὕτως εἰκῇ καὶ προδήλως ἀποβαλεῖν, ἀλλὰ πολὺ κοσμιώτερον διακείσονται πρὸς ἁπάσας τὰς πράξεις, καὶ τοσούτῳ πλείω ποιήσονται θεραπείαν ὑμῶν, ὅσῳ περ ἂν μᾶλλον περὶ σφῶν αὐτῶν δεδίωσιν.", "st": "14.36"}, {"sp": "N", "t": "ἐπεδείξαντο δ’ ὑμῖν ὡς χρὴ τῇ φύσει χρῆσθαι τῇ τούτων ἐξ ὧν ἔπραξαν περὶ Ὠρωπόν· ὅτε μὲν γὰρ ἐξουσίαν ἤλπισαν αὑτοῖς ἔσεσθαι ποιεῖν, ὅ τι ἂν βουληθῶσιν, οὐχ ὡς συμμάχοις ὑμῖν προσηνέχθησαν, ἀλλ’ ἅπερ ἂν εἰς τοὺς πολεμιωτάτους ἐξαμαρτεῖν ἐτόλμησαν· ἐπειδὴ δ’ ἐκσπόνδους αὐτοὺς ἀντὶ τούτων ἐψηφίσασθε ποιῆσαι, παυσάμενοι τῶν φρονημάτων ἦλθον ὡς ὑμᾶς ταπεινότερον διατεθέντες ἢ νῦν ἡμεῖς τυγχάνομεν ἔχοντες.", "st": "14.37"}, {"sp": "N", "t": "ὥστ’ ἤν τινες ὑμᾶς ἐκφοβῶσι τῶν ῥητόρων ὡς κίνδυνός ἐστι, μὴ μεταβάλωνται καὶ γένωνται μετὰ τῶν πολεμίων, οὐ χρὴ πιστεύειν· τοιαῦται γὰρ αὐτοὺς ἀνάγκαι κατειλήφασιν, ὥστε πολὺ ἂν θᾶττον τὴν ὑμετέραν ἀρχὴν ἢ τὴν Λακεδαιμονίων συμμαχίαν ὑπομείναιεν.", "st": "14.38"}, {"sp": "N", "t": "εἰ δ’ οὖν καὶ τἀναντία μέλλοιεν ἅπαντα πράξειν, οὐδ’ οὕτως ἡγοῦμαι προσήκειν ὑμῖν τῆς Θηβαίων πόλεως πλείω ποιήσασθαι λόγον ἢ τῶν ὅρκων καὶ τῶν συνθηκῶν, ἐνθυμουμένους πρῶτον μὲν ὡς οὐ τοὺς κινδύνους, ἀλλὰ τὰς ἀδοξίας καὶ τὰς αἰσχύνας φοβεῖσθαι πάτριον ὑμῖν ἐστιν, ἔπειθ’ ὅτι συμβαίνει κρατεῖν ἐν τοῖς πολέμοις οὐ τοὺς βίᾳ τὰς πόλεις καταστρεφομένους, ἀλλὰ τοὺς ὁσιώτερον καὶ πραότερον τὴν Ἑλλάδα διοικοῦντας.", "st": "14.39"}, {"sp": "N", "t": "καὶ ταῦτ’ ἐπὶ πλειόνων μὲν ἄν τις παραδειγμάτων ἔχοι διελθεῖν· τὰ δ’ οὖν ἐφ’ ἡμῶν γενόμενα τίς οὐκ οἶδεν, ὅτι καὶ Λακεδαιμόνιοι τὴν δύναμιν τὴν ὑμετέραν ἀνυπόστατον δοκοῦσαν εἶναι κατέλυσαν, μικρὰς μὲν ἀφορμὰς εἰς τὸν πόλεμον τὸν κατὰ θάλατταν τὸ πρῶτον ἔχοντες, διὰ δὲ τὴν δόξαν ταύτην προσαγόμενοι τοὺς Ἕλληνας, καὶ πάλιν ὑμεῖς τὴν ἀρχὴν ἀφείλεσθε τὴν ἐκείνων, ἐξ ἀτειχίστου μὲν τῆς πόλεως ὁρμηθέντες καὶ κακῶς πραττούσης, τὸ δὲ δίκαιον ἔχοντες σύμμαχον;", "st": "14.40"}, {"sp": "N", "t": "καὶ τούτων ὡς οὐ βασιλεὺς αἴτιος ἦν ὁ τελευταῖος χρόνος σαφῶς ἐπέδειξεν· ἔξω γὰρ αὐτοῦ τῶν πραγμάτων γεγενημένου, καὶ τῶν μὲν ὑμετέρων ἀνελπίστως ἐχόντων, Λακεδαιμονίοις δὲ σχεδὸν ἁπασῶν τῶν πόλεων δουλευουσῶν, ὅμως αὐτῶν τοσοῦτον περιεγένεσθε πολεμοῦντες ὥστ’ ἐκείνους ἀγαπητῶς ἰδεῖν τὴν εἰρήνην γενομένην.", "st": "14.41"}, {"sp": "N", "t": "μηδεὶς οὖν ὑμῶν ὀρρωδείτω μετὰ τοῦ δικαίου ποιούμενος τοὺς κινδύνους, μηδ’ οἰέσθω συμμάχων ἀπορήσειν, ἂν τοῖς ἀδικουμένοις ἐθέλητε βοηθεῖν ἀλλὰ μὴ Θηβαίοις μόνοις· οἷς νῦν τἀναντία ψηφισάμενοι πολλοὺς ἐπιθυμεῖν ποιήσετε τῆς ὑμετέρας φιλίας. ἢν γὰρ ἐνδείξησθ’ ὡς ὁμοίως ἅπασιν ὑπὲρ τῶν συνθηκῶν παρεσκεύασθε πολεμεῖν,", "st": "14.42"}, {"sp": "N", "t": "τίνες εἰς τοῦτ’ ἀνοίας ἥξουσιν ὥστε βούλεσθαι μετὰ τῶν καταδουλουμένων εἶναι μᾶλλον ἢ μεθ’ ὑμῶν τῶν ὑπὲρ τῆς αὑτῶν ἐλευθερίας ἀγωνιζομένων; εἰ δὲ μή, τί λέγοντες, ἢν πάλιν γένηται πόλεμος, ἀξιώσετε προσάγεσθαι τοὺς Ἕλληνας, εἰ τὴν αὐτονομίαν προτείνοντες ἐκδώσετε πορθεῖν Θηβαίοις ἥντιν’ ἂν βούλωνται τῶν πόλεων;", "st": "14.43"}, {"sp": "N", "t": "πῶς δ’ οὐ τἀναντία φανήσεσθε πράττοντες ὑμῖν αὐτοῖς, εἰ Θηβαίους μὲν μὴ διακωλύσετε παραβαίνοντας τοὺς ὅρκους καὶ τὰς συνθήκας, πρὸς δὲ Λακεδαιμονίους ὑπὲρ τῶν αὐτῶν τούτων προσποιήσεσθε πολεμεῖν; καὶ τῶν μὲν κτημάτων τῶν ὑμετέρων αὐτῶν ἀπέστητε, βουλόμενοι τὴν συμμαχίαν ὡς μεγίστην ποιῆσαι, τούτους δὲ τὴν ἀλλοτρίαν ἔχειν ἐάσετε καὶ τοιαῦτα ποιεῖν ἐξ ὧν ἅπαντες χείρους εἶναι νομιοῦσιν ὑμᾶς;", "st": "14.44"}, {"sp": "N", "t": "ὃ δὲ πάντων δεινότατον, εἰ τοῖς μὲν συνεχῶς μετὰ Λακεδαιμονίων γεγενημένοις δεδογμένον ὑμῖν ἐστὶ βοηθεῖν, ἤν τι παράσπονδον αὐτοῖς ἐκεῖνοι προστάττωσιν, ἡμᾶς δ’ οἳ τὸν μὲν πλεῖστον χρόνον μεθ’ ὑμῶν ὄντες διατετελέκαμεν, τὸν δὲ τελευταῖον μόνον πόλεμον ὑπὸ Λακεδαιμονίοις ἠναγκάσθημεν γενέσθαι, διὰ ταύτην τὴν πρόφασιν ἀθλιώτατα πάντων ἀνθρώπων περιόψεσθε διακειμένους.", "st": "14.45"}, {"sp": "N", "t": "τίνας γὰρ ἂν ἡμῶν εὕροι τις δυστυχεστέρους, οἵτινες καὶ πόλεως καὶ χώρας καὶ χρημάτων ἐν μιᾷ στερηθέντες ἡμέρᾳ, πάντων τῶν ἀναγκαίων ὁμοίως ἐνδεεῖς ὄντες ἀλῆται καὶ πτωχοὶ καθέσταμεν, ἀποροῦντες ὅποι τραπώμεθα, καὶ πάσας τὰς οἰκήσεις δυσχεραίνοντες· ἤν τε γὰρ δυστυχοῦντας καταλάβωμεν, ἀλγοῦμεν ἀναγκαζόμενοι πρὸς τοῖς οἰκείοις κακοῖς καὶ τῶν ἀλλοτρίων κοινωνεῖν·", "st": "14.46"}, {"sp": "N", "t": "ἤν θ’ ὡς εὖ πράττοντας ἔλθωμεν, ἔτι χαλεπώτερον ἔχομεν, οὐ ταῖς ἐκείνων φθονοῦντες εὐπορίαις, ἀλλὰ μᾶλλον ἐν τοῖς τῶν πέλας ἀγαθοῖς τὰς ἡμετέρας αὐτῶν συμφορὰς καθορῶντες, ἐφ’ αἷς ἡμεῖς οὐδεμίαν ἡμέραν ἀδακρυτὶ διάγομεν ἀλλὰ πενθοῦντες τὴν πατρίδα καὶ θρηνοῦντες τὴν μεταβολὴν τὴν γεγενημένην ἅπαντα τὸν χρόνον διατελοῦμεν.", "st": "14.47"}, {"sp": "N", "t": "τίνα γὰρ ἡμᾶς οἴεσθε γνώμην ἔχειν ὁρῶντας καὶ τοὺς γονέας αὑτῶν ἀναξίως γηροτροφουμένους καὶ τοὺς παῖδας οὐκ ἐπὶ ταῖς ἐλπίσιν αἷς ἐποιησάμεθα παιδευομένους, ἀλλὰ πολλοὺς μὲν μικρῶν ἕνεκα συμβολαίων δουλεύοντας, ἄλλους δ’ ἐπὶ θητείαν ἰόντας, τοὺς δ’ ὅπως ἕκαστοι δύνανται τὰ καθ’ ἡμέραν ποριζομένους, ἀπρεπῶς καὶ τοῖς τῶν προγόνων ἔργοις καὶ ταῖς αὑτῶν ἡλικίαις καὶ τοῖς φρονήμασι τοῖς ἡμετέροις;", "st": "14.48"}, {"sp": "N", "t": "ὃ δὲ πάντων ἄλγιστον, ὅταν τις ἴδῃ χωριζομένους ἀπ’ ἀλλήλων μὴ μόνον πολίτας ἀπὸ πολιτῶν ἀλλὰ καὶ γυναῖκας ἀπ’ ἀνδρῶν καὶ θυγατέρας ἀπὸ μητέρων καὶ πᾶσαν τὴν συγγένειαν διαλυομένην, ὃ πολλοῖς τῶν ἡμετέρων πολιτῶν διὰ τὴν ἀπορίαν συμβέβηκεν· ὁ γὰρ κοινὸς βίος ἀπολωλὼς ἰδίας τὰς ἐλπίδας ἕκαστον ἡμῶν ἔχειν πεποίηκεν.", "st": "14.49"}, {"sp": "N", "t": "οἶμαι δ’ ὑμᾶς οὐδὲ τὰς ἄλλας αἰσχύνας ἀγνοεῖν τὰς διὰ πενίαν καὶ φυγὴν γιγνομένας, ἃς ἡμεῖς τῇ μὲν διανοίᾳ χαλεπώτερον τῶν ἄλλων φέρομεν, τῷ δὲ λόγῳ παραλείπομεν, αἰσχυνόμενοι λίαν ἀκριβῶς τὰς ἡμετέρας αὐτῶν ἀτυχίας ἐξετάζειν.", "st": "14.50"}, {"sp": "N", "t": "ὧν αὐτοὺς ὑμᾶς ἀξιοῦμεν ἐνθυμουμένους ἐπιμέλειάν τινα ποιήσασθαι περὶ ἡμῶν. καὶ γὰρ οὐδ’ ἀλλότριοι τυγχάνομεν ὑμῖν ὄντες, ἀλλὰ ταῖς μὲν εὐνοίαις ἅπαντες οἰκεῖοι, τῇ δὲ συγγενείᾳ τὸ πλῆθος ἡμῶν· διὰ γὰρ τὰς ἐπιγαμίας τὰς δοθείσας ἐκ πολιτίδων ὑμετέρων γεγόναμεν· ὥστ’ οὐχ οἷόν θ’ ὑμῖν ἀμελῆσαι περὶ ὧν ἐληλύθαμεν δεησόμενοι. καὶ γὰρ ἂν πάντων εἴη δεινότατον,", "st": "14.51"}, {"sp": "N", "t": "εἰ πρότερον μὲν ἡμῖν μετέδοτε τῆς πατρίδος τῆς ὑμετέρας αὐτῶν, νῦν δε μηδὲ τὴν ἡμετέραν ἀποδοῦναι δόξειεν ὑμῖν. ἔπειτ’ οὐδ’ εἰκὸς ἕνα μὲν ἕκαστον ἐλεεῖσθαι τῶν παρὰ τὸ δίκαιον δυστυχούντων, ὅλην δὲ πόλιν οὕτως ἀνόμως διεφθαρμένην μηδὲ κατὰ μικρὸν οἴκτου δυνηθῆναι τυχεῖν, ἄλλως τε καὶ παρ’ ὑμᾶς καταφυγοῦσαν, οἷς οὐδὲ τὸ πρότερον αἰσχρῶς οὐδ’ ἀκλεῶς ἀπέβη τοὺς ἱκέτας ἐλεήσασιν.", "st": "14.52"}, {"sp": "N", "t": "ἐλθόντων γὰρ Ἀργείων ὡς τοὺς προγόνους ὑμῶν καὶ δεηθέντων ἀνελέσθαι τοὺς ὑπὸ τῇ Καδμείᾳ τελευτήσαντας, πεισθέντες ὑπ’ ἐκείνων καὶ Θηβαίους ἀναγκάσαντες βουλεύσασθαι νομιμώτερον οὐ μόνον αὐτοὶ κατ’ ἐκείνους τοὺς καιροὺς εὐδοκίμησαν, ἀλλὰ καὶ τῇ πόλει δόξαν ἀείμνηστον εἰς ἅπαντα τὸν χρόνον κατέλιπον, ἧς οὐκ ἄξιον προδότας γενέσθαι. καὶ γὰρ αἰσχρὸν φιλοτιμεῖσθαι μὲν ἐπὶ τοῖς τῶν προγόνων ἔργοις, φαίνεσθαι δ’ ἐκείνοις τἀναντία περὶ τῶν ἱκετῶν πράττοντας.", "st": "14.53"}, {"sp": "N", "t": "καίτοι πολὺ περὶ μειζόνων καὶ δικαιοτέρων ἥκομεν ποιησόμενοι τὰς δεήσεις· οἱ μὲν γὰρ ἐπὶ τὴν ἀλλοτρίαν στρατεύσαντες ἱκέτευον ὑμᾶς, ἡμεῖς δὲ τὴν ἡμετέραν αὐτῶν ἀπολωλεκότες, κἀκεῖνοι μὲν παρεκάλουν ἐπὶ τὴν τῶν νεκρῶν ἀναίρεσιν, ἡμεῖς δ’ ἐπὶ τὴν τῶν λοιπῶν σωτηρίαν.", "st": "14.54"}, {"sp": "N", "t": "ἔστι δ’ οὐκ ἴσον κακὸν οὐδ’ ὅμοιον τοὺς τεθνεῶτας ταφῆς εἴργεσθαι καὶ τοὺς ζῶντας πατρίδος ἀποστερεῖσθαι καὶ τῶν ἄλλων ἀγαθῶν ἁπάντων, ἀλλὰ τὸ μὲν δεινότερον τοῖς κωλύουσιν ἢ τοῖς ἀτυχοῦσι, τὸ δὲ μηδεμίαν ἔχοντα καταφυγὴν ἀλλ’ ἄπολιν γενόμενον καθ’ ἑκάστην τὴν ἡμέραν κακοπαθεῖν καὶ τοὺς αὑτοῦ περιορᾶν μὴ δυνάμενον ἐπαρκεῖν, τί δεῖ λέγειν ὅσον τὰς ἄλλας συμφορὰς ὑπερβέβληκεν;", "st": "14.55"}, {"sp": "N", "t": "ὑπὲρ ὧν ἅπαντας ὑμᾶς ἱκετεύομεν ἀποδοῦναι τὴν χώραν ἡμῖν καὶ τὴν πόλιν, τοὺς μὲν πρεσβυτέρους ὑπομιμνῄσκοντες, ὡς οἰκτρὸν τοὺς τηλικούτους ὁρᾶσθαι δυστυχοῦντας καὶ τῶν καθ’ ἡμέραν ἀποροῦντας, τοὺς δὲ νεωτέρους ἀντιβολοῦντες καὶ δεόμενοι βοηθῆσαι τοῖς ἡλικιώταις καὶ μὴ περιιδεῖν ἔτι πλείω κακὰ τῶν εἰρημένων παθόντας.", "st": "14.56"}, {"sp": "N", "t": "ὀφείλετε δὲ μόνοι τῶν Ἑλλήνων τοῦτον τὸν ἔρανον, ἀναστάτοις ἡμῖν γεγενημένοις ἐπαμῦναι. καὶ γὰρ τοὺς ἡμετέρους προγόνους φασὶν ἐκλιπόντων τῶν ὑμετέρων πατέρων ἐν τῷ Περσικῷ πολέμῳ ταύτην τὴν χώραν μόνους τῶν ἔξω Πελοποννήσου κοινωνοὺς ἐκείνοις τῶν κινδύνων γενομένους συνανασῶσαι τὴν πόλιν αὐτοῖς· ὥστε δικαίως ἂν τὴν αὐτὴν εὐεργεσίαν ἀπολάβοιμεν ἥνπερ αὐτοὶ τυγχάνομεν εἰς ὑμᾶς ὑπάρξαντες.", "st": "14.57"}, {"sp": "N", "t": "εἰ δ’ οὖν καὶ μηδὲν ὑμῖν τῶν σωμάτων τῶν ἡμετέρων δέδοκται φροντίζειν, ἀλλὰ τήν γε χώραν οὐ πρὸς ὑμῶν ἐστὶν ἀνέχεσθαι πεπορθημένην, ἐν ᾗ μέγιστα σημεῖα τῆς ἀρετῆς τῆς ὑμετέρας καὶ τῶν ἄλλων τῶν συναγωνισαμένων καταλείπεται·", "st": "14.58"}, {"sp": "N", "t": "τὰ μὲν γὰρ ἄλλα τρόπαια πόλει πρὸς πόλιν γέγονεν, ἐκεῖνα δ’ ὑπὲρ ἁπάσης τῆς Ἑλλάδος πρὸς ὅλην τὴν ἐκ τῆς Ἀσίας δύναμιν ἕστηκεν. ἃ Θηβαῖοι μὲν εἰκότως ἀφανίζουσι, τὰ γὰρ μνημεῖα τῶν τότε γενομένων αἰσχύνη τούτοις ἐστίν, ὑμῖν δὲ προσήκει διασῴζειν· ἐξ ἐκείνων γὰρ τῶν ἔργων ἡγεμόνες κατέστητε τῶν Ἑλλήνων.", "st": "14.59"}, {"sp": "N", "t": "ἄξιον δὲ καὶ τῶν θεῶν καὶ τῶν ἡρώων μνησθῆναι τῶν ἐκεῖνον τὸν τόπον κατεχόντων καὶ μὴ περιορᾶν τὰς τιμὰς αὐτῶν καταλυομένας, οἷς ὑμεῖς καλλιερησάμενοι τοιοῦτον ὑπέστητε κίνδυνον, ὃς καὶ τούτους καὶ τοὺς ἄλλους ἅπαντας Ἕλληνας ἠλευθέρωσεν. χρὴ δὲ καὶ τῶν προγόνων ποιήσασθαί τινα πρόνοιαν καὶ μὴ παραμελῆσαι μηδὲ τῆς περὶ ἐκείνους εὐσεβείας,", "st": "14.60"}, {"sp": "N", "t": "οἳ πῶς ἂν διατεθεῖεν, εἴ τις ἄρα τοῖς ἐκεῖ φρόνησίς ἐστι περὶ τῶν ἐνθάδε γιγνομένων, εἰ κυρίων ὑμῶν ὄντων αἴσθοιντο τοὺς μὲν δουλεύειν τοῖς βαρβάροις ἀξιώσαντας δεσπότας τῶν ἄλλων καθισταμένους, ἡμᾶς δὲ τοὺς ὑπὲρ τῆς ἐλευθερίας συναγωνισαμένους μόνους τῶν Ἑλλήνων ἀναστάτους γεγενημένους, καὶ τοὺς μὲν τῶν συγκινδυνευσάντων τάφους μὴ τυγχάνοντας τῶν νομιζομένων σπάνει τῶν ἐποισόντων, Θηβαίους δὲ τοὺς τἀναντία παραταξαμένους κρατοῦντας τῆς χώρας ἐκείνης;", "st": "14.61"}, {"sp": "N", "t": "ἐνθυμεῖσθε δ’ ὅτι Λακεδαιμονίων μεγίστην ἐποιεῖσθε κατηγορίαν, ὅτι Θηβαίοις χαριζόμενοι τοῖς τῶν Ἑλλήνων προδόταις ἡμᾶς τοὺς εὐεργέτας διέφθειραν. μὴ τοίνυν ἐάσητε ταύτας τὰς βλασφημίας περὶ τὴν ὑμετέραν γενέσθαι πόλιν, μηδὲ τὴν ὕβριν τὴν τούτων ἀντὶ τῆς παρούσης ἕλησθε δόξης.", "st": "14.62"}, {"sp": "N", "t": "πολλῶν δ’ ἐνόντων εἰπεῖν ἐξ ὧν ἄν τις ὑμᾶς ἐπαγάγοι μᾶλλον φροντίσαι τῆς ἡμετέρας σωτηρίας οὐ δύναμαι πάντα περιλαβεῖν, ἀλλ’ αὐτοὺς χρὴ καὶ τὰ παραλελειμμένα συνιδόντας καὶ μνησθέντας μάλιστα μὲν τῶν ὅρκων καὶ τῶν συνθηκῶν, ἔπειτα δὲ καὶ τῆς ἡμετέρας εὐνοίας καὶ τῆς τούτων ἔχθρας, ψηφίσασθαί τι περὶ ἡμῶν δίκαιον.", "st": "14.63"}, {"sp": "HDR", "t": "Περὶ τοῦ ζεύγους", "st": "16"}, {"sp": "N", "t": "… περὶ μὲν οὖν τοῦ ζεύγους τῶν ἵππων, ὡς οὐκ ἀφελόμενος ὁ πατὴρ Τεισίαν εἶχεν, ἀλλὰ πριάμενος παρὰ τῆς πόλεως τῆς Ἀργείων, τῶν τε πρέσβεων τῶν ἐκεῖθεν ἡκόντων καὶ τῶν ἄλλων τῶν εἰδότων ἀκηκόατε μαρτυρούντων· τὸν αὐτὸν δὲ τρόπον ἅπαντές εἰσιν εἰθισμένοι με συκοφαντεῖν.", "st": "16.1"}, {"sp": "N", "t": "τὰς μὲν γὰρ δίκας ὑπὲρ τῶν ἰδίων ἐγκλημάτων λαγχάνουσι, τὰς δὲ κατηγορίας ὑπὲρ τῶν τῆς πόλεως πραγμάτων ποιοῦνται, καὶ πλείω χρόνον διατρίβουσι τὸν πατέρα μου διαβάλλοντες ἢ περὶ ὧν ἀντώμοσαν διδάσκοντες, καὶ τοσοῦτον καταφρονοῦσι τῶν νόμων ὥστε περὶ ὧν ὑμᾶς ὑπ’ ἐκείνου φασὶν ἠδικῆσθαι, τούτων αὐτοὶ δίκην παρ’ ἐμοῦ λαβεῖν ἀξιοῦσιν.", "st": "16.2"}, {"sp": "N", "t": "ἐγὼ δ’ ἡγοῦμαι μὲν οὐδὲν προσήκειν τὰς κοινὰς αἰτίας τοῖς ἰδίοις ἀγῶσιν· ἐπειδὴ δὲ Τεισίας πολλάκις ὀνειδίζει μοι τὴν φυγὴν τὴν τοῦ πατρὸς καὶ μᾶλλον ὑπὲρ τῶν ὑμετέρων ἢ τῶν αὑτοῦ σπουδάζει πραγμάτων, ἀνάγκη πρὸς ταῦτα τὴν ἀπολογίαν ποιεῖσθαι· καὶ γὰρ ἂν αἰσχυνοίμην, εἴ τῳ δόξαιμι τῶν πολιτῶν ἧττον φροντίζειν τῆς ἐκείνου δόξης ἢ τῶν ἐμαυτοῦ κινδύνων.", "st": "16.3"}, {"sp": "N", "t": "πρὸς μὲν οὖν τοὺς πρεσβυτέρους βραχὺς ἂν ἐξήρκει λόγος· ἅπαντες γὰρ ἴσασιν ὅτι διὰ τοὺς αὐτοὺς ἄνδρας ἥ τε δημοκρατία κατελύθη κἀκεῖνος ἐκ τῆς πόλεως ἐξέπεσεν· τῶν δὲ νεωτέρων ἕνεκα, οἳ τῶν μὲν πραγμάτων ὕστεροι γεγόνασι τῶν δὲ διαβαλλόντων πολλάκις ἀκηκόασι, πορρωτέρωθεν ἄρξομαι διδάσκειν.", "st": "16.4"}, {"sp": "N", "t": "οἱ γὰρ τὸ πρῶτον ἐπιβουλεύσαντες τῷ δήμῳ καὶ καταστήσαντες τοὺς τετρακοσίους, ἐπειδὴ παρακαλούμενος ὁ πατὴρ οὐκ ἤθελε γενέσθαι μετ’ αὐτῶν, ὁρῶντες αὐτὸν καὶ πρὸς τὰς πράξεις ἐρρωμένως ἔχοντα καὶ πρὸς τὸ πλῆθος πιστῶς διακείμενον, οὐχ ἡγοῦντ’ οὐδὲν οἷοί τ’ εἶναι κινεῖν τῶν καθεστώτων, πρὶν ἐκποδὼν ἐκεῖνος αὐτοῖς γένοιτο.", "st": "16.5"}, {"sp": "N", "t": "εἰδότες δὲ τὴν πόλιν τῶν μὲν περὶ τοὺς θεοὺς μάλιστ’ ἂν ὀργισθεῖσαν, εἴ τις εἰς τὰ μυστήρια φαίνοιτ’ ἐξαμαρτάνων, τῶν δ’ ἄλλων εἴ τις τὴν δημοκρατίαν τολμῴη καταλύειν, ἀμφοτέρας ταύτας συνθέντες τὰς αἰτίας εἰσήγγελλον εἰς τὴν βουλήν, λέγοντες ὡς ὁ πατὴρ μὲν συνάγοι τὴν ἑταιρείαν ἐπὶ νεωτέροις πράγμασιν, οὗτοι δ’ ἐν τῇ Πουλυτίωνος οἰκίᾳ συνδειπνοῦντες τὰ μυστήρια ποιήσειαν.", "st": "16.6"}, {"sp": "N", "t": "ὀρθῆς δὲ τῆς πόλεως γενομένης διὰ τὸ μέγεθος τῶν αἰτιῶν καὶ διὰ ταχέων συλλεγείσης ἐκκλησίας οὕτω σαφῶς ἐπέδειξεν αὐτοὺς ψευδομένους, ὥστε παρὰ μὲν τῶν κατηγόρων ἡδέως ἂν ὁ δῆμος δίκην ἔλαβε, τὸν δ’ εἰς Σικελίαν στρατηγὸν ἐχειροτόνησεν. μετὰ δὲ ταῦθ’ ὁ μὲν ἐξέπλευσεν ὡς ἀπηλλαγμένος ἤδη τῆς διαβολῆς, οἱ δὲ συστήσαντες τὴν βουλὴν καὶ τοὺς ῥήτορας ὑφ’ αὑτοῖς ποιησάμενοι πάλιν ἤγειρον τὸ πρᾶγμα καὶ μηνυτὰς εἰσέπεμπον.", "st": "16.7"}, {"sp": "N", "t": "καὶ τί δεῖ μακρολογεῖν; οὐ γὰρ πρότερον ἐπαύσαντο, πρὶν τόν τε πατέρ’ ἐκ τοῦ στρατοπέδου μετεπέμψαντο, καὶ τῶν φίλων αὐτοῦ τοὺς μὲν ἀπέκτειναν, τοὺς δ’ ἐκ τῆς πόλεως ἐξέβαλον. πυθόμενος δὲ τήν τε τῶν ἐχθρῶν δύναμιν καὶ τὰς τῶν ἐπιτηδείων συμφοράς, καὶ νομίζων δεινὰ πάσχειν ὅτι παρόντα μὲν αὐτὸν οὐκ ἔκρινον, ἀπόντος δὲ κατεγίγνωσκον, οὐδ’ ὣς ἀπελθεῖν ἠξίωσεν εἰς τοὺς πολεμίους·", "st": "16.8"}, {"sp": "N", "t": "ἀλλ’ ἐκεῖνος μὲν τοσαύτην πρόνοιαν ἔσχεν ὑπὲρ τοῦ μηδὲ φεύγων μηδὲν ἐξαμαρτεῖν εἰς τὴν πόλιν, ὥστ’ εἰς Ἄργος ἐλθὼν ἡσυχίαν εἶχεν, οἱ δ’ εἰς τοσοῦτον ὕβρεως ἦλθον, ὥστ’ ἔπεισαν ὑμᾶς ἐλαύνειν αὐτὸν ἐξ ἁπάσης τῆς Ἑλλάδος καὶ στηλίτην ἀναγράφειν καὶ πρέσβεις πέμποντας ἐξαιτεῖν παρ’ Ἀργείων. ἀπορῶν δ’ ὅ τι χρήσαιτο τοῖς παροῦσι κακοῖς καὶ πανταχόθεν εἰργόμενος καὶ σωτηρίας οὐδεμιᾶς ἄλλης αὐτῷ φαινομένης τελευτῶν ἐπὶ Λακεδαιμονίους ἠναγκάσθη καταφυγεῖν.", "st": "16.9"}, {"sp": "N", "t": "καὶ τὰ μὲν γενόμενα ταῦτ’ ἐστίν· τοσοῦτον δὲ τοῖς ἐχθροῖς τῆς ὕβρεως περίεστιν, ὥσθ’ οὕτως ἀνόμως τοῦ πατρὸς ἐκπεσόντος ὡς δεινὰ δεδρακότος αὐτοῦ κατηγοροῦσι, καὶ διαβάλλειν ἐπιχειροῦσιν ὡς Δεκέλειάν τ’ ἐπετείχισε καὶ τὰς νήσους ἀπέστησε καὶ τῶν πολεμίων διδάσκαλος κατέστη.", "st": "16.10"}, {"sp": "N", "t": "καὶ ἐνίοτε μὲν αὐτοῦ προσποιοῦνται καταφρονεῖν, λέγοντες ὡς οὐδὲν διέφερε τῶν ἄλλων, νυνὶ δ’ ἁπάντων αὐτὸν τῶν γεγενημένων αἰτιῶνται καί φασι παρ’ ἐκείνου μαθεῖν Λακεδαιμονίους ὡς χρὴ πολεμεῖν, οἳ καὶ τοὺς ἄλλους διδάσκειν τέχνην ἔχουσιν. ἐγὼ δ’ εἴ μοι χρόνος ἱκανὸς γένοιτο, ῥᾳδίως ἂν αὐτὸν ἐπιδείξαιμι τὰ μὲν δικαίως πράξαντα, τῶν δ’ ἀδίκως αἰτίαν ἔχοντα. πάντων δ’ ἂν εἴη δεινότατον, εἰ τοῦ πατρὸς μετὰ τὴν φυγὴν δωρεὰν λαβόντος ἐγὼ διὰ τὴν ἐκείνου φυγὴν ζημιωθείην.", "st": "16.11"}, {"sp": "N", "t": "ἡγοῦμαι δ’ αὐτὸν παρ’ ὑμῶν δικαίως ἂν πλείστης συγγνώμης τυγχάνειν· ὑπὸ γὰρ τῶν τριάκοντ’ ἐκπεσόντες ταῖς αὐταῖς ἐκείνῳ συμφοραῖς ἐχρήσασθε. ἐξ ὧν ἐνθυμεῖσθαι χρή, πῶς ἕκαστος ὑμῶν διέκειτο καὶ τίνα γνώμην εἶχε καὶ ποῖον κίνδυνον οὐκ ἂν ὑπέμεινεν ὥστε παύσασθαι μὲν μετοικῶν, κατελθεῖν δ’ εἰς τὴν πατρίδα, τιμωρήσασθαι δὲ τοὺς ἐκβαλόντας.", "st": "16.12"}, {"sp": "N", "t": "ἐπὶ τίνα δ’ ἢ πόλιν ἢ φίλον ἢ ξένον οὐκ ἤλθετε δεησόμενοι συγκαταγαγεῖν ὑμᾶς; τίνος δ’ ἀπέσχεσθε πειρώμενοι κατελθεῖν; οὐ καταλαβόντες τὸν Πειραιᾶ καὶ τὸν σῖτον τὸν ἐν τῇ χώρᾳ διεφθείρετε καὶ τὴν γῆν ἐτέμνετε καὶ τὰ προάστεια ἐνεπρήσατε καὶ τελευτῶντες τοῖς τείχεσι προσεβάλετε;", "st": "16.13"}, {"sp": "N", "t": "καὶ ταῦθ’ οὕτω σφόδρ’ ἐνομίζετε χρῆναι ποιεῖν, ὥστε τοῖς ἡσυχίαν ἄγουσι τῶν συμφυγάδων μᾶλλον ὠργίζεσθε ἢ τοῖς αἰτίοις τῶν συμφορῶν γεγενημένοις. ὥστ’ οὐκ εἰκὸς ἐπιτιμᾶν τοῖς τῶν αὐτῶν ὑμῖν ἐπιθυμοῦσιν, οὐδὲ κακοὺς ἄνδρας νομίζειν, ὅσοι φεύγοντες κατελθεῖν ἐζήτησαν, ἀλλὰ πολὺ μᾶλλον ὅσοι μένοντες φυγῆς ἄξι’ ἐποίησαν· οὐδ’ ἐντεῦθεν ἀρξαμένους κρίνειν, ὁποῖός τις ἦν ὁ πατὴρ πολίτης, ὅτ’ οὐδὲν αὐτῷ τῆς πόλεως προσῆκεν,", "st": "16.14"}, {"sp": "N", "t": "ἀλλ’ ἐπ’ ἐκείνου τοῦ χρόνου σκοπεῖν οἷος ἦν πρὶν φυγεῖν περὶ τὸ πλῆθος, καὶ ὅτι διακοσίους ὁπλίτας ἔχων τὰς μεγίστας πόλεις τῶν ἐν Πελοποννήσῳ Λακεδαιμονίων μὲν ἀπέστησεν, ὑμῖν δὲ συμμάχους ἐποίησε, καὶ εἰς οἵους κινδύνους αὐτοὺς κατέστησε, καὶ ὡς περὶ Σικελίαν ἐστρατήγησεν. τούτων μὲν γὰρ ἐκείνῳ προσήκει χάριν ὑμᾶς ἔχειν· τῶν δ’ ἐν τῇ συμφορᾷ γενομένων τοὺς ἐκβαλόντας αὐτὸν δικαίως ἂν αἰτίους νομίζοιτε.", "st": "16.15"}, {"sp": "N", "t": "ἀναμνήσθητε δὲ πρὸς ὑμᾶς αὐτούς, ἐπειδὴ κατῆλθεν, ὡς πόλλ’ ἀγαθὰ τὴν πόλιν ἐποίησεν, ἔτι δὲ πρότερον, ὡς ἐχόντων τῶν πραγμάτων αὐτὸν κατεδέξασθε, καταλελυμένου μὲν τοῦ δήμου, στασιαζόντων δὲ τῶν πολιτῶν, διαφερομένων δὲ τῶν στρατιωτῶν πρὸς τὰς ἀρχὰς τὰς ἐνθάδε καθεστηκυίας, εἰς τοῦτο δὲ μανίας ἀμφοτέρων ἀφιγμένων ὥστε μηδετέροις μηδεμίαν ἐλπίδ’ εἶναι σωτηρίας·", "st": "16.16"}, {"sp": "N", "t": "οἱ μὲν γὰρ τοὺς ἔχοντας τὴν πόλιν ἐχθροὺς ἐνόμιζον μᾶλλον ἢ Λακεδαιμονίους, οἱ δὲ τοὺς ἐκ Δεκελείας μετεπέμποντο, ἡγούμενοι κρεῖττον εἶναι τοῖς πολεμίοις τὴν πατρίδα παραδοῦναι μᾶλλον ἢ τοῖς ὑπὲρ τῆς πόλεως στρατευομένοις τῆς πολιτείας μεταδοῦναι.", "st": "16.17"}, {"sp": "N", "t": "τοιαύτην μὲν οὖν τῶν πολιτῶν γνώμην ἐχόντων, κρατούντων δὲ τῶν πολεμίων καὶ τῆς γῆς καὶ τῆς θαλάττης, ἔτι δὲ χρημάτων ὑμῖν μὲν οὐκ ὄντων, ἐκείνοις δὲ βασιλέως παρέχοντος, πρὸς δὲ τούτοις ἐνενήκοντα νεῶν ἐκ Φοινίκης εἰς Ἄσπενδον ἡκουσῶν καὶ παρεσκευασμένων Λακεδαιμονίοις βοηθεῖν, ἐν τοσαύταις συμφοραῖς καὶ τοιούτοις κινδύνοις τῆς πόλεως οὔσης,", "st": "16.18"}, {"sp": "N", "t": "μεταπεμψαμένων αὐτὸν τῶν στρατιωτῶν οὐκ ἐσεμνύνατ’ ἐπὶ τοῖς παροῦσιν, οὐδ’ ἐμέμψατο περὶ τῶν γεγενημένων, οὐδ’ ἐβουλεύσατο περὶ τῶν μελλόντων, ἀλλ’ εὐθὺς εἵλετο μετὰ τῆς πόλεως ὁτιοῦν πάσχειν μᾶλλον ἢ μετὰ Λακεδαιμονίων εὐτυχεῖν, καὶ πᾶσι φανερὸν ἐποίησεν ὅτι τοῖς ἐκβαλοῦσιν ἀλλ’ οὐχ ὑμῖν ἐπολέμει, καὶ ὅτι κατελθεῖν ἀλλ’ οὐκ ἀπολέσαι τὴν πόλιν ἐπεθύμει.", "st": "16.19"}, {"sp": "N", "t": "γενόμενος δὲ μεθ’ ὑμῶν ἔπεισε μὲν Τισσαφέρνην μὴ παρέχειν χρήματα Λακεδαιμονίοις, ἔπαυσε δὲ τοὺς συμμάχους ὑμῶν ἀφισταμένους, διέδωκε δὲ παρ’ αὑτοῦ μισθὸν τοῖς στρατιώταις, ἀπέδωκε δὲ τῷ δήμῳ τὴν πολιτείαν, διήλλαξε δὲ τοὺς πολίτας, ἀπέστρεψε δὲ τὰς ναῦς τὰς Φοινίσσας.", "st": "16.20"}, {"sp": "N", "t": "καὶ μετὰ ταῦτα καθ’ ἕκαστον μέν, ὅσας τριήρεις ἔλαβεν ἢ μάχας ἐνίκησεν ἢ πόλεις κατὰ κράτος εἷλεν ἢ λόγῳ πείσας φίλας ὑμῖν ἐποίησε, πολὺ ἂν ἔργον εἴη λέγειν· πλείστων δὲ κινδύνων τῇ πόλει κατ’ ἐκεῖνον τὸν καιρὸν γενομένων οὐδεπώποτε τοῦ πατρὸς ἡγουμένου τρόπαιον ὑμῶν ἔστησαν οἱ πολέμιοι.", "st": "16.21"}, {"sp": "N", "t": "περὶ μὲν οὖν τῶν ἐστρατηγημένων οἶδα μὲν ὅτι πολλὰ παραλείπω, διὰ τοῦτο δ’ οὐκ ἀκριβῶς εἴρηκα περὶ αὐτῶν, ὅτι σχεδὸν ἅπαντες μνημονεύετε τὰ πραχθέντα. λοιδοροῦσι δὲ λίαν ἀσελγῶς καὶ θρασέως καὶ τὸν ἄλλον βίον τὸν τοῦ πατρός, καὶ οὐκ αἰσχύνονται τοιαύτῃ παρρησίᾳ χρώμενοι περὶ τοῦ τεθνεῶτος, ἣν ἔδεισαν ἂν ποιήσασθαι περὶ ζῶντος, ἀλλ’ εἰς τοσοῦτον ἀνοίας ἐληλύθασιν,", "st": "16.22"}, {"sp": "N", "t": "ὥστ’ οἴονται καὶ παρ’ ὑμῖν καὶ παρὰ τοῖς ἄλλοις εὐδοκιμήσειν, ἢν ὡς ἂν δύνωνται πλεῖστα περὶ αὐτοῦ βλασφημήσωσιν, ὥσπερ οὐ πάντας εἰδότας ὅτι καὶ τοῖς φαυλοτάτοις τῶν ἀνθρώπων ἔξεστιν οὐ μόνον περὶ τῶν ἀνδρῶν τῶν ἀρίστων ἀλλὰ καὶ περὶ τῶν θεῶν ὑβριστικοὺς λόγους εἰπεῖν.", "st": "16.23"}, {"sp": "N", "t": "ἴσως μὲν οὖν ἀνόητόν ἐστιν ἁπάντων τῶν εἰρημένων φροντίζειν· ὅμως δ’ οὐχ ἥκιστ’ ἐπιθυμῶ περὶ τῶν ἐπιτηδευμάτων τῶν τοῦ πατρὸς διελθεῖν πρὸς ὑμᾶς, μικρὸν προλαβὼν καὶ τῶν προγόνων ἐπιμνησθείς, ἵν’ ἐπίστησθ’ ὅτι πόρρωθεν ἡμῖν ὑπάρχει μέγιστα καὶ κάλλιστα τῶν πολιτῶν.", "st": "16.24"}, {"sp": "N", "t": "ὁ γὰρ πατὴρ πρὸς μὲν ἀνδρῶν ἦν Εὐπατριδῶν, ὧν τὴν εὐγένειαν ἐξ αὐτῆς τῆς ἐπωνυμίας ῥᾴδιον γνῶναι, πρὸς γυναικῶν δ’ Ἀλκμεωνιδῶν, οἳ τοῦ μὲν πλούτου μέγιστον μνημεῖον κατέλιπον, ἵππων γὰρ ζεύγει πρῶτος Ἀλκμέων τῶν πολιτῶν Ὀλυμπίασιν ἐνίκησε, τὴν δ’ εὔνοιαν ἣν εἶχον εἰς τὸ πλῆθος, ἐν τοῖς τυραννικοῖς ἐπεδείξαντο· συγγενεῖς γὰρ ὄντες Πεισιστράτου καὶ πρὶν εἰς τὴν ἀρχὴν καταστῆναι μάλιστ’ αὐτῷ χρώμενοι τῶν πολιτῶν, οὐκ ἠξίωσαν μετασχεῖν τῆς ἐκείνου τυραννίδος, ἀλλ’ εἵλοντο φυγεῖν μᾶλλον ἢ τοὺς πολίτας ἰδεῖν δουλεύοντας.", "st": "16.25"}, {"sp": "N", "t": "τετταράκοντα δ’ ἔτη τῆς στάσεως γενομένης ὑπὸ μὲν τῶν τυράννων τοσούτῳ μᾶλλον τῶν ἄλλων ἐμισήθησαν, ὥσθ’ ὁπότε τἀκείνων κρατήσειεν, οὐ μόνον τὰς οἰκίας αὐτῶν κατέσκαπτον ἀλλὰ καὶ τοὺς τάφους ἀνώρυττον, ὑπὸ δὲ τῶν συμφυγάδων οὕτω σφόδρ’ ἐπιστεύθησαν, ὥσθ’ ἅπαντα τοῦτον τὸν χρόνον ἡγούμενοι τοῦ δήμου διετέλεσαν. καὶ τὸ τελευταῖον Ἀλκιβιάδης καὶ Κλεισθένης, ὁ μὲν πρὸς πατρός, ὁ δὲ πρὸς μητρὸς ὢν πρόπαππος τοῦ πατρὸς τοὐμοῦ, στρατηγήσαντες τῆς φυγῆς κατήγαγον τὸν δῆμον καὶ τοὺς τυράννους ἐξέβαλον,", "st": "16.26"}, {"sp": "N", "t": "καὶ κατέστησαν ἐκείνην τὴν δημοκρατίαν, ἐξ ἧς οἱ πολῖται πρὸς μὲν ἀνδρίαν οὕτως ἐπαιδεύθησαν ὥστε τοὺς βαρβάρους τοὺς ἐπὶ πᾶσαν ἐλθόντας τὴν Ἑλλάδα μόνοι νικᾶν μαχόμενοι, περὶ δὲ δικαιοσύνης τοσαύτην δόξαν ἔλαβον ὥσθ’ ἑκόντας αὐτοῖς τοὺς Ἕλληνας ἐγχειρίσαι τὴν ἀρχὴν τῆς θαλάττης, τὴν δὲ πόλιν τηλικαύτην τὸ μέγεθος ἐποίησαν καὶ τῇ δυνάμει καὶ ταῖς ἄλλαις κατασκευαῖς ὥστε τοὺς φάσκοντας αὐτὴν ἄστυ τῆς Ἑλλάδος εἶναι καὶ τοιαύταις ὑπερβολαῖς εἰθισμένους χρῆσθαι δοκεῖν ἀληθῆ λέγειν.", "st": "16.27"}, {"sp": "N", "t": "τὴν μὲν οὖν φιλίαν τὴν πρὸς τὸν δῆμον οὕτω παλαιὰν καὶ γνησίαν καὶ διὰ τὰς μεγίστας εὐεργεσίας γεγενημένην παρὰ τῶν προγόνων παρέλαβεν· αὐτὸς δὲ κατελείφθη μὲν ὀρφανός, ὁ γὰρ πατὴρ αὐτοῦ μαχόμενος ἐν Κορωνείᾳ τοῖς πολεμίοις ἀπέθανεν, ἐπετροπεύθη δ’ ὑπὸ Περικλέους, ὃν πάντες ἂν ὁμολογήσειαν καὶ σωφρονέστατον καὶ δικαιότατον καὶ σοφώτατον γενέσθαι τῶν πολιτῶν. ἡγοῦμαι γὰρ καὶ τοῦτ’ εἶναι τῶν καλῶν, ἐκ τοιούτων γενόμενον ὑπὸ τοιούτοις ἤθεσιν ἐπιτροπευθῆναι καὶ τραφῆναι καὶ παιδευθῆναι.", "st": "16.28"}, {"sp": "N", "t": "δοκιμασθεὶς δ’ οὐκ ἐνδεέστερος ἐγένετο τῶν προειρημένων, οὐδ’ ἠξίωσεν αὐτὸς μὲν ῥᾳθύμως ζῆν, σεμνύνεσθαι δ’ ἐπὶ ταῖς τῶν προγόνων ἀρεταῖς, ἀλλ’ εὐθὺς οὕτω μέγ’ ἐφρόνησεν, ὥστ’ ᾠήθη δεῖν δι’ αὑτὸν καὶ τἀκείνων ἔργα μνημονεύεσθαι. καὶ πρῶτον μέν, ὅτε Φορμίων ἐξήγαγεν ἐπὶ Θρᾴκης χιλίους Ἀθηναίων, ἐπιλεξάμενος τοὺς ἀρίστους, μετὰ τούτων στρατευσάμενος τοιοῦτος ἦν ἐν τοῖς κινδύνοις ὥστε στεφανωθῆναι καὶ πανοπλίαν λαβεῖν παρὰ τοῦ στρατηγοῦ.", "st": "16.29"}, {"sp": "N", "t": "καίτοι τί χρὴ τὸν τῶν μεγίστων ἐπαίνων ἄξιον; οὐ μετὰ μὲν τῶν βελτίστων ἐκ τῆς πόλεως στρατευόμενον ἀριστείων ἀξιοῦσθαι, πρὸς δὲ τοὺς κρατίστους τῶν Ἑλλήνων ἀντιστρατηγοῦντ’ ἐν ἅπασι τοῖς κινδύνοις αὐτῶν φαίνεσθαι περιγιγνόμενον; ἐκεῖνος τοίνυν τῶν μὲν νέος ὢν ἔτυχε, τὰ δ’ ἐπειδὴ πρεσβύτερος ἦν ἔπραξεν.", "st": "16.30"}, {"sp": "N", "t": "μετὰ δὲ ταῦτα τὴν μητέρα τὴν ἐμὴν ἔγημεν· ἡγοῦμαι γὰρ καὶ ταύτην ἀριστεῖον αὐτὸν λαβεῖν. ὁ γὰρ πατὴρ αὐτῆς Ἱππόνικος, πλούτῳ μὲν πρῶτος ὢν τῶν Ἑλλήνων, γένει δ’ οὐδενὸς ὕστερος τῶν πολιτῶν, τιμώμενος δὲ καὶ θαυμαζόμενος μάλιστα τῶν ἐφ’ αὑτοῦ, μετὰ προικὸς δὲ πλείστης καὶ δόξης μεγίστης ἐκδιδοὺς τὴν θυγατέρα, καὶ τοῦ γάμου τυχεῖν εὐχομένων μὲν ἁπάντων, ἀξιούντων δὲ τῶν πρώτων, τὸν πατέρα τὸν ἐμὸν ἐξ ἁπάντων ἐκλεξάμενος κηδεστὴν ἐπεθύμησε ποιήσασθαι.", "st": "16.31"}, {"sp": "N", "t": "περὶ δὲ τοὺς αὐτοὺς χρόνους ὁρῶν τὴν ἐν Ὀλυμπίᾳ πανήγυριν ὑπὸ πάντων ἀνθρώπων ἀγαπωμένην καὶ θαυμαζομένην, καὶ τοὺς Ἕλληνας ἐπίδειξιν ἐν αὐτῇ ποιουμένους πλούτου καὶ ῥώμης καὶ παιδεύσεως, καὶ τούς τ’ ἀθλητὰς ζηλουμένους καὶ τὰς πόλεις ὀνομαστὰς γιγνομένας τὰς τῶν νικώντων, καὶ πρὸς τούτοις ἡγούμενος τὰς μὲν ἐνθάδε λῃτουργίας ὑπὲρ τῶν ἰδίων πρὸς τοὺς πολίτας εἶναι, τὰς δ’ εἰς ἐκείνην τὴν πανήγυριν ὑπὲρ τῆς πόλεως εἰς ἅπασαν τὴν Ἑλλάδα γίγνεσθαι,", "st": "16.32"}, {"sp": "N", "t": "ταῦτα διανοηθείς, οὐδενὸς ἀφυέστερος οὐδ’ ἀρρωστότερος τῷ σώματι γενόμενος τοὺς μὲν γυμνικοὺς ἀγῶνας ὑπερεῖδεν, εἰδὼς ἐνίους τῶν ἀθλητῶν καὶ κακῶς γεγονότας καὶ μικρὰς πόλεις οἰκοῦντας καὶ ταπεινῶς πεπαιδευμένους, ἱπποτροφεῖν δ’ ἐπιχειρήσας, ὃ τῶν εὐδαιμονεστάτων ἔργον ἐστί, φαῦλος δ’ οὐδεὶς ἂν ποιήσειεν, οὐ μόνον τοὺς ἀνταγωνιστὰς ἀλλὰ καὶ τοὺς πώποτε νικήσαντας ὑπερεβάλετο.", "st": "16.33"}, {"sp": "N", "t": "ζεύγη γὰρ καθῆκε τοσαῦτα μὲν τὸν ἀριθμὸν ὅσοις οὐδ’ αἱ μέγισται τῶν πόλεων ἠγωνίσαντο, τοιαῦτα δὲ τὴν ἀρετὴν ὥστε καὶ πρῶτος καὶ δεύτερος γενέσθαι καὶ τρίτος. χωρὶς δὲ τούτων ἐν ταῖς θυσίαις καὶ ταῖς ἄλλαις ταῖς περὶ τὴν ἑορτὴν δαπάναις οὕτως ἀφειδῶς διέκειτο καὶ μεγαλοπρεπῶς ὥστε φαίνεσθαι τὰ κοινὰ τὰ τῶν ἄλλων ἐλάττω τῶν ἰδίων τῶν ἐκείνου. κατέλυσε δὲ τὴν θεωρίαν, τὰς μὲν τῶν προτέρων εὐτυχίας μικρὰς πρὸς τὰς αὑτοῦ δόξαι ποιήσας, τοὺς δ’ ἐφ’ αὑτοῦ νικήσαντας παύσας ζηλουμένους, τοῖς δὲ μέλλουσιν ἱπποτροφεῖν οὐδεμίαν ὑπερβολὴν καταλιπών.", "st": "16.34"}, {"sp": "N", "t": "περὶ δὲ τῶν ἐνθάδε χορηγιῶν καὶ γυμνασιαρχιῶν καὶ τριηραρχιῶν αἰσχύνομαι λέγειν· τοσοῦτον γὰρ ἐν τοῖς ἄλλοις διήνεγκεν, ὥσθ’ οἱ μὲν ἐνδεεστέρως ἐκείνου λῃτουργήσαντες ἐκ τούτων σφᾶς αὐτοὺς ἐγκωμιάζουσιν, ὑπὲρ ἐκείνου δ’ εἴ τις καὶ τῶν τηλικούτων χάριν ἀπαιτοίη, περὶ μικρῶν ἂν δόξειε τοὺς λόγους ποιεῖσθαι.", "st": "16.35"}, {"sp": "N", "t": "πρὸς δὲ τὴν πολιτείαν, οὐδὲ γὰρ τοῦτο παραλειπτέον, ὥσπερ οὐδ’ ἐκεῖνος αὐτῆς ἠμέλησεν, ἀλλὰ τοσούτῳ τῶν μάλιστ’ εὐδοκιμησάντων ἀμείνων περὶ τὸν δῆμον γέγονεν, ὅσον τοὺς μὲν ἄλλους εὑρήσεθ’ ὑπὲρ αὑτῶν στασιάσαντας, ἐκεῖνον δ’ ὑπὲρ ὑμῶν κινδυνεύοντα. οὐ γὰρ ἀπελαυνόμενος ἀπὸ τῆς ὀλιγαρχίας ἀλλὰ παρακαλούμενος ἦν δημοτικός· καὶ πολλάκις ἐκγενόμενον αὐτῷ μὴ μόνον μετ’ ὀλίγων τῶν ἄλλων ἄρχειν ἀλλὰ καὶ τούτων αὐτῶν πλέον ἔχειν, οὐκ ἠθέλησεν, ἀλλ’ εἵλεθ’ ὑπὸ τῆς πόλεως ἀδικηθῆναι μᾶλλον ἢ τὴν πολιτείαν προδοῦναι.", "st": "16.36"}, {"sp": "N", "t": "καὶ ταῦθ’ ἕως μὲν συνεχῶς ἐδημοκρατεῖσθ’ οὐδεὶς ἂν ὑμᾶς λέγων ἔπεισεν· νῦν δ’ αἱ στάσεις αἱ γενόμεναι σαφῶς ἐπέδειξαν καὶ τοὺς δημοτικοὺς καὶ τοὺς ὀλιγαρχικοὺς καὶ τοὺς οὐδετέρων ἐπιθυμοῦντας καὶ τοὺς ἀμφοτέρων μετέχειν ἀξιοῦντας. ἐν αἷς δὶς ὑπὸ τῶν ἐχθρῶν τῶν ὑμετέρων ἐξέπεσεν· καὶ τὸ μὲν πρότερον, ἐπειδὴ τάχιστ’ ἐκεῖνον ἐκποδὼν ἐποιήσαντο, τὸν δῆμον κατέλυσαν, τὸ δ’ ὕστερον οὐκ ἔφθασαν ὑμᾶς καταδουλωσάμενοι, καὶ πρώτου τῶν πολιτῶν αὐτοῦ φυγὴν κατέγνωσαν· οὕτω σφόδρ’ ἥ τε πόλις τῶν τοῦ πατρὸς κακῶν ἀπέλαυσε κἀκεῖνος τῶν τῆς πόλεως συμφορῶν ἐκοινώνησεν.", "st": "16.37"}, {"sp": "N", "t": "καίτοι πολλοὶ τῶν πολιτῶν πρὸς αὐτὸν δυσκόλως εἶχον ὡς πρὸς τυραννεῖν ἐπιβουλεύοντα, οὐκ ἐκ τῶν ἔργων σκοποῦντες, ἀλλ’ ἡγούμενοι τὸ μὲν πρᾶγμ’ ὑπὸ πάντων ζηλοῦσθαι, δύνασθαι δ’ ἂν ἐκεῖνον μάλιστα διαπράξασθαι. διὸ καὶ δικαίως ἂν αὐτῷ πλείω χάριν ἔχοιτε, ὅτι τὴν μὲν αἰτίαν μόνος τῶν πολιτῶν ἄξιος ἦν ταύτην ἔχειν, τῆς δὲ πολιτείας ἴσον ᾤετο δεῖν καὶ τοῖς ἄλλοις μετεῖναι.", "st": "16.38"}, {"sp": "N", "t": "διὰ δὲ τὸ πλῆθος τῶν ἐνόντων εἰπεῖν ὑπὲρ τοῦ πατρὸς ἀπορῶ, τίνος ἐν τῷ παρόντι πρέπει μνησθῆναι καὶ ποῖ’ αὐτῶν χρὴ παραλιπεῖν· ἀεὶ γάρ μοι δοκεῖ μεῖζον εἶναι τὸ μήπω πεφρασμένον τῶν ἤδη πρὸς ὑμᾶς εἰρημένων. ἐπεὶ καὶ τοῦθ’ ἡγοῦμαι πᾶσιν εἶναι φανερὸν ὅτι τοῦτον ἀναγκαῖόν ἐστιν εὐνούστατον εἶναι ταῖς τῆς πόλεως εὐτυχίαις, ὅτῳ πλεῖστον μέρος καὶ τῶν ἀγαθῶν καὶ τῶν κακῶν μέτεστιν.", "st": "16.39"}, {"sp": "N", "t": "ἐκείνου τοίνυν εὖ μὲν πραττούσης τῆς πόλεως τίς εὐδαιμονέστερος ἢ θαυμαστότερος ἢ ζηλωτότερος ἦν τῶν πολιτῶν, δυστυχησάσης δὲ τίς ἐλπίδων μειζόνων ἢ χρημάτων πλειόνων ἢ δόξης καλλίονος ἐστερήθη; οὐ τὸ τελευταῖον ἐπειδὴ κατέστησαν οἱ τριάκονθ’ οἱ μὲν ἄλλοι τὴν πόλιν ἔφυγον, ἐκεῖνος δὲ ἐξ ἁπάσης τῆς Ἑλλάδος ἐξέπεσεν; οὐ Λακεδαιμόνιοι καὶ Λύσανδρος ὁμοίως ἔργον ἐποιήσαντ’ ἐκεῖνον ἀποκτεῖναι καὶ τὴν ὑμετέραν καταλῦσαι δύναμιν, οὐδεμίαν ἡγούμενοι πίστιν ἕξειν παρὰ τῆς πόλεως, εἰ τὰ τείχη καταβάλοιεν, εἰ μὴ καὶ τὸν ἀναστῆσαι δυνάμενον ἀπολέσαιεν;", "st": "16.40"}, {"sp": "N", "t": "ὥστ’ οὐ μόνον ἐξ ὧν ὑμᾶς εὖ πεποίηκεν ἀλλὰ καὶ ἐξ ὧν δι’ ὑμᾶς κακῶς πέπονθε ῥᾴδιον γνῶναι τὴν εὔνοιαν τὴν ἐκείνου. φαίνεται γὰρ τῷ δήμῳ βοηθῶν, τῆς αὐτῆς πολιτείας ὑμῖν ἐπιθυμῶν, ὑπὸ τῶν αὐτῶν κακῶς πάσχων, ἅμα τῇ πόλει δυστυχῶν, τοὺς αὐτοὺς ἐχθροὺς καὶ φίλους ὑμῖν νομίζων, ἐκ παντὸς τρόπου κινδυνεύων τὰ μὲν ὑφ’ ὑμῶν, τὰ δὲ δι’ ὑμᾶς,", "st": "16.41"}, {"sp": "N", "t": "τὰ δ’ ὑπὲρ ὑμῶν, τὰ δὲ μεθ’ ὑμῶν, ἀνόμοιος πολίτης Χαρικλεῖ τῷ τούτου κηδεστῇ γεγενημένος, ὃς τοῖς μὲν πολεμίοις δουλεύειν ἐπεθύμει, τῶν δὲ πολιτῶν ἄρχειν ἠξίου, καὶ φεύγων μὲν ἡσυχίαν εἶχε, κατελθὼν δὲ κακῶς ἐποίει τὴν πόλιν. καίτοι πῶς ἂν γένοιτ’ ἢ φίλος πονηρότερος ἢ ἐχθρὸς ἐλάττονος ἄξιος;", "st": "16.42"}, {"sp": "N", "t": "εἶτα σὺ κηδεστὴς μὲν ὢν ἐκείνου, βεβουλευκὼς δ’ ἐπὶ τῶν τριάκοντα τολμᾷς ἑτέροις μνησικακεῖν, καὶ οὐκ αἰσχύνει τὰς συνθήκας παραβαίνων δι’ ἃς αὐτὸς οἰκεῖς τὴν πόλιν, οὐδ’ ἐνθυμεῖ διότι, ὁπόταν δόξῃ τῶν παρεληλυθότων τιμωρίαν ποιεῖσθαι, σοὶ καὶ προτέρῳ καὶ μᾶλλον ἢ ’μοὶ κινδυνεύειν ὑπάρχει;", "st": "16.43"}, {"sp": "N", "t": "οὐ γὰρ δήπου παρ’ ἐμοῦ μὲν ὑπὲρ ὧν ὁ πατὴρ ἔπραξε δίκην λήψονται, σοὶ δὲ καὶ ὧν αὐτὸς ἡμάρτηκας συγγνώμην ἕξουσιν. ἀλλὰ μὴν οὐδ’ ὁμοίας ἐκείνῳ φανήσει τὰς προφάσεις ἔχων· οὐ γὰρ ἐκπεσὼν ἐκ τῆς πατρίδος ἀλλὰ συμπολιτευόμενος, οὐδ’ ἀναγκασθεὶς ἀλλ’ ἑκών, οὐδ’ ἀμυνόμενος ἀλλ’ ὑπάρχων ἠδίκεις αὐτούς, ὥστ’ οὐδ’ ἀπολογίας σοι προσήκει τυχεῖν παρ’ αὐτῶν.", "st": "16.44"}, {"sp": "N", "t": "ἀλλὰ γὰρ περὶ μὲν τῶν Τεισίᾳ πεπολιτευμένων ἴσως πότ’ ἐν τοῖς τούτου κινδύνοις ἐγγενήσεται καὶ διὰ μακροτέρων εἰπεῖν· ὑμᾶς δ’ ἀξιῶ μὴ προέσθαι με τοῖς ἐχθροῖς μηδ’ ἀνηκέστοις συμφοραῖς περιβαλεῖν. ἱκανῶς γὰρ καὶ νῦν πεπείραμαι κακῶν, ὃς εὐθὺς μὲν γενόμενος ὀρφανὸς κατελείφθην, τοῦ μὲν πατρὸς φυγόντος, τῆς δὲ μητρὸς τελευτησάσης, οὔπω δὲ τέτταρ’ ἔτη γεγονὼς διὰ τὴν τοῦ πατρὸς φυγὴν περὶ τοῦ σώματος εἰς κίνδυνον κατέστην,", "st": "16.45"}, {"sp": "N", "t": "ἔτι δὲ παῖς ὢν ὑπὸ τῶν τριάκοντ’ ἐκ τῆς πόλεως ἐξέπεσον. κατελθόντων δὲ τῶν ἐκ Πειραιῶς καὶ τῶν ἄλλων κομιζομένων τὰς οὐσίας ἐγὼ μόνος τὴν γῆν, ἣν ἡμῖν ἀπέδωκεν ὁ δῆμος ἀντὶ τῶν δημευθέντων χρημάτων, διὰ τὴν τῶν ἐχθρῶν δύναμιν ἀπεστερήθην. τοσαῦτα δὲ προδεδυστυχηκὼς καὶ δὶς τὴν οὐσίαν ἀπολωλεκὼς νυνὶ πέντε ταλάντων φεύγω δίκην. καὶ τὸ μὲν ἔγκλημ’ ἐστὶ περὶ χρημάτων, ἀγωνίζομαι δ’ εἰ χρὴ μετεῖναί μοι τῆς πόλεως.", "st": "16.46"}, {"sp": "N", "t": "τῶν γὰρ αὐτῶν τιμημάτων ἐπιγεγραμμένων οὐ περὶ τῶν αὐτῶν ἅπασιν ὁ κίνδυνός ἐστιν, ἀλλὰ τοῖς μὲν χρήματα κεκτημένοις περὶ ζημίας, τοῖς δ’ ἀπόρως ὥσπερ ἐγὼ διακειμένοις περὶ ἀτιμίας, ἣν ἐγὼ φυγῆς μείζω συμφορὰν νομίζω· πολὺ γὰρ ἀθλιώτερον παρὰ τοῖς αὑτοῦ πολίταις ἠτιμωμένον οἰκεῖν ἢ παρ’ ἑτέροις μετοικεῖν.", "st": "16.47"}, {"sp": "N", "t": "δέομαι δ’ οὖν ὑμῶν βοηθῆσαί μοι καὶ μὴ περιιδεῖν ὑπὸ τῶν ἐχθρῶν ὑβρισθέντα μηδὲ τῆς πατρίδος στερηθέντα μηδ’ ἐπὶ τοιαύταις τύχαις περίβλεπτον γενόμενον. δικαίως δ’ ἂν ὑφ’ ὑμῶν ἐξ αὐτῶν τῶν ἔργων ἐλεηθείην, εἰ καὶ τῷ λόγῳ τυγχάνω μὴ δυνάμενος ἐπὶ τοῦθ’ ὑμᾶς ἄγειν, εἴπερ χρὴ τούτους ἐλεεῖν, τοὺς ἀδίκως μὲν κινδυνεύοντας, περὶ δὲ τῶν μεγίστων ἀγωνιζομένους, ἀναξίως δ’ αὑτῶν καὶ τῶν προγόνων πράττοντας, πλείστων δὲ χρημάτων ἀπεστερημένους καὶ μεγίστῃ μεταβολῇ τοῦ βίου κεχρημένους.", "st": "16.48"}, {"sp": "N", "t": "πολλὰ δ’ ἔχων ἐμαυτὸν ὀδύρασθαι μάλιστ’ ἐπὶ τούτοις ἀγανακτῶ, πρῶτον μὲν εἰ τούτῳ δώσω δίκην παρ’ οὗ λαβεῖν μοι προσήκει, δεύτερον δ’ εἰ διὰ τὴν τοῦ πατρὸς νίκην τὴν Ὀλυμπίασιν ἀτιμωθήσομαι, δι’ ἣν τοὺς ἄλλους ὁρῶ δωρεὰς λαμβάνοντας,", "st": "16.49"}, {"sp": "N", "t": "πρὸς δὲ τούτοις εἰ Τεισίας μὲν μηδὲν ἀγαθὸν ποιήσας τὴν πόλιν καὶ ἐν δημοκρατίᾳ καὶ ἐν ὀλιγαρχίᾳ μέγα δυνήσεται, ἐγὼ δ’ εἰ μηδετέρους ἀδικήσας ὑπ’ ἀμφοτέρων κακῶς πείσομαι, καὶ περὶ μὲν τῶν ἄλλων τἀναντία τοῖς τριάκοντα πράξετε, περὶ δ’ ἐμοῦ τὴν αὐτὴν ἐκείνοις γνώμην ἕξετε, καὶ τότε μὲν μεθ’ ὑμῶν, νῦν δ’ ὑφ’ ὑμῶν τῆς πόλεως στερήσομαι.", "st": "16.50"}, {"sp": "HDR", "t": "Τραπεζιτικός", "st": "17"}, {"sp": "N", "t": "ὁ μὲν ἀγών μοι μέγας ἐστίν, ὦ ἄνδρες δικασταί. οὐ γὰρ μόνον περὶ πολλῶν χρημάτων κινδυνεύω, ἀλλὰ καὶ περὶ τοῦ μὴ δοκεῖν ἀδίκως τῶν ἀλλοτρίων ἐπιθυμεῖν· ὃ ἐγὼ περὶ πλείστου ποιοῦμαι. οὐσία μὲν γὰρ ἱκανή μοι καταλειφθήσεται καὶ τούτων στερηθέντι· εἰ δὲ δόξαιμι μηδὲν προσῆκον τοσαῦτα χρήματ’ ἐγκαλέσαι, διαβληθείην ἂν τὸν ἅπαντα βίον.", "st": "17.1"}, {"sp": "N", "t": "ἔστι δ’, ὦ ἄνδρες δικασταί, πάντων χαλεπώτατον τοιούτων ἀντιδίκων τυχεῖν. τὰ μὲν γὰρ συμβόλαια τὰ πρὸς τοὺς ἐπὶ ταῖς τραπέζαις ἄνευ μαρτύρων γίγνεται, τοῖς ἀδικουμένοις δὲ πρὸς τοιούτους ἀνάγκη κινδυνεύειν, οἳ καὶ φίλους πολλοὺς κέκτηνται καὶ χρήματα πολλὰ διαχειρίζουσι καὶ πιστοὶ διὰ τὴν τέχνην δοκοῦσιν εἶναι. ὅμως δὲ καὶ τούτων ὑπαρχόντων ἡγοῦμαι φανερὸν πᾶσι ποιήσειν ὅτι ἀποστεροῦμαι τῶν χρημάτων ὑπὸ Πασίωνος.", "st": "17.2"}, {"sp": "N", "t": "ἐξ ἀρχῆς οὖν ὑμῖν, ὅπως ἂν δύνωμαι, διηγήσομαι τὰ πεπραγμένα. ἐμοὶ γάρ, ὦ ἄνδρες δικασταί, πατὴρ μέν ἐστι Σωπαῖος, ὃν οἱ πλέοντες εἰς τὸν Πόντον ἅπαντες ἴσασιν οὕτως οἰκείως πρὸς Σάτυρον διακείμενον, ὥστε πολλῆς μὲν χώρας ἄρχειν, ἁπάσης δὲ τῆς δυνάμεως ἐπιμελεῖσθαι τῆς ἐκείνου.", "st": "17.3"}, {"sp": "N", "t": "πυνθανόμενος δὲ καὶ περὶ τῆσδε τῆς πόλεως καὶ περὶ τῆς ἄλλης Ἑλλάδος ἐπεθύμησ’ ἀποδημῆσαι. γεμίσας οὖς ὁ πατήρ μου δύο ναῦς σίτου καὶ χρήματα δοὺς ἐξέπεμψεν ἅμα κατ’ ἐμπορίαν καὶ κατὰ θεωρίαν· συστήσαντος δέ μοι Πυθοδώρου τοῦ Φοίνικος Πασιωνα ἐχρώμην τῇ τούτου τραπέζῃ.", "st": "17.4"}, {"sp": "N", "t": "χρόνῳ δ’ ὕστερον διαβολῆς πρὸς Σάτυρον γενομένης ὡς καὶ ὁ πατὴρ οὑμὸς ἐπιβουλεύοι τῇ ἀρχῇ, κἀγὼ τοῖς φυγάσι συγγιγνοίμην, τὸν μὲν πατέρα μου συλλαμβάνει, ἐπιστέλλει δὲ τοῖς ἐνθάδ’ ἐπιδημοῦσιν ἐκ τοῦ Πόντου τά τε χρήματα παρ’ ἐμοῦ παραλαβεῖν καὶ αὐτὸν εἰσπλεῖν κελεύειν· ἐὰν δὲ τούτων μηδὲν ποιῶ,", "st": "17.5"}, {"sp": "N", "t": "παρ’ ὑμῶν ἐξαιτεῖν. ἐν τοσούτοις δὲ κακοῖς ὤν, ὦ ἄνδρες δικασταί, λέγω πρὸς Πασίωνα τὰς ἐμαυτοῦ συμφοράς· οὕτω γὰρ οἰκείως πρὸς αὐτὸν διεκείμην ὥστε μὴ μόνον περὶ χρημάτων ἀλλὰ καὶ περὶ τῶν ἄλλων τούτῳ μάλιστα πιστεύειν. ἡγούμην δ’ εἰ μὲν προοίμην ἅπαντα τὰ χρήματα, κινδυνεύειν, εἴ τι πάθοι ’κεῖνος, στερηθεὶς καὶ τῶν ἐνθάδε καὶ τῶν ἐκεῖ, πάντων ἐνδεὴς γενήσεσθαι· εἰ δ’ ὁμολογῶν εἶναι ἐπιστείλαντος Σατύρου μὴ παραδοίην, εἰς τὰς μεγίστας διαβολὰς ἐμαυτὸν καὶ τὸν πατέρα καταστήσειν πρὸς Σάτυρον.", "st": "17.6"}, {"sp": "N", "t": "βουλευομένοις οὖν ἡμῖν ἐδόκει βέλτιστον εἶναι προσομολογεῖν πάντα ποιεῖν, ὅσα Σάτυρος προσέταττε, καὶ τὰ μὲν φανερὰ τῶν χρημάτων παραδοῦναι, περὶ δὲ τῶν παρὰ τούτῳ κειμένων μὴ μόνον ἔξαρνον εἶναι ἀλλὰ καὶ ὀφείλοντά με καὶ τούτῳ καὶ ἑτέροις ἐπὶ τόκῳ φαίνεσθαι καὶ πάντα ποιεῖν ἐξ ὧν ἐκεῖνοι μάλιστ’ ἤμελλον πεισθήσεσθαι μὴ εἶναί μοι χρήματα.", "st": "17.7"}, {"sp": "N", "t": "τότε μὲν οὖν, ὦ ἄνδρες δικασταί, ἐνόμιζόν μοι Πασίωνα δι’ εὔνοιαν ἅπαντα ταῦτα συμβουλεύειν· ἐπειδὴ δὲ πρὸς τοὺς παρὰ Σατύρου διεπραξάμην, ἔγνων αὐτὸν ἐπιβουλεύοντα τοῖς ἐμοῖς. βουλομένου γὰρ ἐμοῦ κομίσασθαι τἀμαυτοῦ καὶ πλεῖν εἰς Βυζάντοιν, ἡγησάμενος οὗτος κάλλιστον αὑτῷ καιρὸν παραπεπτωκέναι — τὰ μὲν γὰρ χρήματα πόλλ’ εἶναι τὰ παρ’ αὑτῷ κείμενα καὶ ἄξι’ ἀναισχυντίας, ἐμὲ δὲ πολλῶν ἀκουόντων ἔξαρνον γεγενῆσθαι μηδὲν κεκτῆσθαι, πᾶσί τε φανερὸν ἀπαιτούμενον καὶ ἑτέροις προσομολογοῦντα ὀφείλειν—", "st": "17.8"}, {"sp": "N", "t": "καὶ πρὸς τούτοις, ὦ ἄνδρες δικασταί, ἐνόμιζεν, εἰ μὲν αὐτοῦ μένειν ἐπιχειροίην, ἐκδοθήσεσθαι, μ’ ὑπὸ τῆς πόλεως Σατύρῳ, εἰ δ’ ἄλλοσέ ποι τραποίμην, οὐδὲν μελήσειν αὑτῷ τῶν ἐμῶν λόγων, εἰ δ’ εἰσπλευσοίμην εἰς τὸν Πόντον, ἀποθανεῖσθαί με μετὰ τοῦ πατρός· ταῦτα διαλογιζόμενος διενοεῖτό μ’ ἀποστερεῖν τὰ χρήματα. καὶ πρὸς μὲν ἐμὲ προσεποιεῖτ’ ἀπορεῖν ἐν τῷ παρόντι καὶ οὐκ ἂν ἔχειν ἀποδοῦναι· ἐπειδὴ δὲ βουλόμενος εἰδέναι σαφῶς τὸ πρᾶγμα προσπέμπω Φιλόμηλον αὐτῷ καὶ Μενέξενον ἀπαιτήσοντας, ἔξαρνος γίγνεται πρὸς αὐτοὺς μηδὲν ἔχειν τῶν ἐμῶν.", "st": "17.9"}, {"sp": "N", "t": "πανταχόθεν δέ μοι τοσούτων κακῶν προσπεπτωκότων τίν’ οἴεσθέ με γνώμην ἔχειν, ᾧ γ’ ὑπῆρχε σιγῶντι μὲν ὑπὸ τούτου ἀπεστερῆσθαι τῶν χρημάτων, λέγοντι δὲ ταῦτα μὲν μηδὲν μᾶλλον κομίσασθαι, πρὸς Σάτυρον δ’ εἰς τὴν μεγίστην διαβολὴν καὶ ἐμαυτὸν καὶ τὸν πατέρα καταστῆσαι; κράτιστον οὖν ἡγησάμην ἡσυχίαν ἄγειν.", "st": "17.10"}, {"sp": "N", "t": "μετὰ δὲ ταῦτ’, ὦ ἄνδρες δικασταί, ἀφικνοῦνταί μοι οἱ ἀπαγγέλλοντες ὅτι ὁ πατὴρ ἀφεῖται, καὶ Σατύρῳ οὕτως ἁπάντων μεταμέλει τῶν πεπραγμένων, ὥστε πίστεις τὰς μεγίστας αὐτῷ δεδωκὼς εἴη, καὶ τὴν ἀρχὴν ἔτι μείζω πεποιηκὼς ἧς εἶχε πρότερον, καὶ τὴν ἀδελφὴν τὴν ἐμὴν εἰληφὼς γυναῖκα τῷ αὑτοῦ υἱεῖ. πυθόμενος δὲ ταῦτα Πασίων καὶ εἰδὼς ὅτι φανερῶς ἤδη πράξω περὶ τῶν ἐμαυτοῦ, ἀφανίζει Κίττον τὸν παῖδα, ὃς συνῄδει περὶ τῶν χρημάτων.", "st": "17.11"}, {"sp": "N", "t": "ἐπειδὴ δ’ ἐγὼ προσελθὼν ἐξῄτουν αὐτόν, ἡγούμενος ἔλεγχον ἂν τοῦτον σαφέστατον γενέσθαι περὶ ὧν ἐνεκάλουν, λέγει λόγον πάντων δεινότατον, ὡς ἐγὼ καὶ Μενέξενος διαφθείραντες καὶ πείσαντες αὐτὸν ἐπὶ τῇ τραπέζῃ καθήμενον ἓξ τάλαντ’ ἀργυρίου λάβοιμεν παρ’ αὐτοῦ· ἵνα δὲ μηδεὶς ἔλεγχος μηδὲ βάσανος γένοιτο περὶ αὐτῶν, ἔφασκεν ἡμᾶς ἀφανίσαντας τὸν παῖδ’ ἀντεγκαλεῖν αὑτῷ καὶ ἐξαιτεῖν τοῦτον, ὃν αὐτοὶ ἠφανίσαμεν. καὶ ταῦτα λέγων καὶ ἀγανακτῶν καὶ δακρύων εἷλκέ με πρὸς τὸν πολέμαρχον, ἐγγυητὰς αἰτῶν, καὶ οὐ πρότερον ἀφῆκεν, ἕως αὐτῷ κατέστησ’ ἓξ ταλάντῶν ἐγγυητάς. καί μοι κάλει τούτων μάρτυρας.", "st": "17.12"}, {"sp": "N", "t": "<em>Μάρτυρες<\/em>", "st": "17.12"}, {"sp": "N", "t": "τῶν μὲν μαρτύρων ἀκηκόατε, ὦ ἄνδρες δικασταί· ἐγὼ δὲ τὰ μὲν ἀπολωλεκὼς ἤδη, περὶ δὲ τῶν αἰσχίστας αἰτίας ἔχων, αὐτὸς μὲν εἰς Πελοπόννησον ᾠχόμην ζητήσων, Μενέξενος δ’ εὑρίσκει τὸν παῖδ’ ἐνθάδε, καὶ ἐπιλαβόμενος ἠξίου αὐτὸν βασανίζεσθαι καὶ περὶ τῆς παρακαταθήκης καὶ περὶ ὧν οὗτος ἡμᾶς ᾐτιάσατο.", "st": "17.13"}, {"sp": "N", "t": "Πασίων δ’ εἰς τοῦτο τόλμης ἀφίκεθ’ ὥστ’ ἀφῃρεῖτ’ αὐτὸν ὡς ἐλεύθερον ὄντα, καὶ οὐκ ᾐσχύνετ’ οὐδ’ ἐδεδοίκει, ὃν ἔφασκεν ὑφ’ ἡμῶν ἠνδραποδίσθαι καὶ παρ’ οὗ τοσαῦτα χρήμαθ’ ἡμᾶς ἔχειν, τοῦτον ἐξαιρούμενος εἰς ἐλευθερίαν καὶ κωλύων βασανίζεσθαι. ὃ δὲ πάντων δεινότατον· κατεγγυῶντος γὰρ Μενεξένου πρὸς τὸν πολέμαρχον τὸν παῖδα, Πασίων αὐτὸν ἑπτὰ ταλάντων διηγγυήσατο. καί μοι τούτων ἀνάβητε μάρτυρες.", "st": "17.14"}, {"sp": "N", "t": "<em>Μάρτυρες<\/em>", "st": "17.14"}, {"sp": "N", "t": "τούτων τοίνυν αὐτῷ πεπραγμένων, ὦ ἄνδρες δικασταί, ἡγούμενος περὶ μὲν τῶν παρεληλυθότων φανερῶς ἡμαρτηκέναι, οἰόμενος δ’ ἐκ τῶν λοιπῶν ἐπανορθώσεσθαι, προσῆλθεν ἡμῖν φάσκων ἕτοιμος εἶναι παραδοῦναι βασανίζειν τὸν παῖδα. ἑλόμενοι δὲ βασανιστὰς ἀπηντήσαμεν εἰς τὸ Ἡφαιστεῖον. κἀγὼ μὲν ἠξίουν αὐτοὺς μαστιγοῦν τὸν ἐκδοθέντα καὶ στρεβλοῦν, ἕως τἀληθῆ δόξειεν αὐτοῖς λέγειν· Πασίων δ’ οὑτοσὶ οὐ δημοκοίνους ἔφασκεν αὐτοὺς ἑλέσθαι, ἀλλ’ ἐκέλευε λόγῳ πυνθάνεσθαι παρὰ τοῦ παιδός,", "st": "17.15"}, {"sp": "N", "t": "εἴ τι βούλοιντο. διαφερομένων δ’ ἡμῶν οἱ βασανισταὶ αὐτοὶ μὲν οὐκ ἔφασαν βασανιεῖν, ἔγνωσαν δὲ Πασίων’ ἐμοὶ παραδοῦναι τὸν παῖδα. οὗτος δ’ οὕτω σφόδρ’ ἔφευγε τὴν βάσανον, ὥστε περὶ μὲν τῆς παραδόσεως οὐκ ἤθελεν αὐτοῖς πείθεσθαι, τὸ δ’ ἀργύριον ἕτοιμος ἦν ἀποτίνειν, εἰ καταγνοῖεν αὐτοῦ. καί μοι κάλει τούτων μάρτυρας.", "st": "17.16"}, {"sp": "N", "t": "<em>Μάρτυρες<\/em>", "st": "17.16"}, {"sp": "N", "t": "ἐπειδὴ τοίνυν ἐκ τῶν συνόδων, ὦ ἄνδρες δικασταί, πάντες αὐτοῦ κατεγίγνωσκον ἀδικεῖν καὶ δεινὰ ποιεῖν, ὅστις τὸν παῖδα, ὃ ἔφασκον ἐγὼ συνειδέναι περὶ τῶν χρημάτων, πρῶτον μὲν αὐτὸς ἀφανίσας ὑφ’ ἡμῶν αὐτὸν ᾐτιᾶτ’ ἠφανίσθαι, ἔπειτα δὲ συλληφθέντα ὡς ἐλεύθερον ὄντα διεκώλυσε βασανίζεσθαι, μετὰ δὲ ταῦθ’ ὡς δοῦλον ἐκδοὺς καὶ βασανιστὰς ἑλόμενος λόγῳ μὲν ἐκέλευσε βασανίζειν, ἔργῳ δ’ οὐκ εἴα, διὰ ταῦθ’ ἡγούμενος οὐδεμίαν αὑτῷ σωτηρίαν εἶναι, ἐάνπερ εἰς ὑμᾶς εἰσέλθῃ, προσπέμπων ἐδεῖτό μου εἰς ἱερὸν ἐλθόνθ’ ἑαυτῷ συγγενέσθαι.", "st": "17.17"}, {"sp": "N", "t": "καὶ ἐπειδὴ ἤλθομεν εἰς ἀκρόπολιν, ἐγκαλυψάμενος ἔκλαε καὶ ἔλεγεν, ὡς ἠναγκάσθη μὲν δι’ ἀπορίαν ἔξαρνος γενέσθαι, ὀλίγου δὲ χρόνου πειράσοιτο τὰ χρήματ’ ἀποδοῦναι· ἐδεῖτο δέ μου συγγνώμην ἔχειν αὐτῷ καὶ συγκρύψαι τὴν συμφοράν, ἵνα μὴ παρακαταθήκας δεχόμενος φανερὸς γένηται τοιαῦτ’ ἐξημαρτηκώς. ἡγούμενος δ’ αὐτῷ μεταμέλειν τῶν πεπραγμένων συνεχώρουν καὶ ἐκέλευον αὐτὸν ἐξευρεῖν, ὅντιν’ ἂν βούληται τρόπον, ὅπως τούτῳ τε καλῶς ἕξει κἀγὼ τἀμαυτοῦ κομιοῦμαι.", "st": "17.18"}, {"sp": "N", "t": "τρίτῃ δ’ ἡμέρᾳ συνελθόντες πίστιν τ’ ἔδομεν ἀλλήλοις ἦ μὴν σιωπήσεσθαι τὰ πραχθέντα, ἣν οὗτος ἔλυσεν, ὡς ὑμεῖς αὐτοὶ προιόντος τοῦ λόγου γνώσεσθε, καὶ ὡμολόγησεν εἰς τὸν Πόντον μοι συμπλευσεῖσθαι κἀκεῖ τὸ χρυσίον ἀποδώσειν, ἵν’ ὡς πορρωτάτω ἀπὸ τῆσδε τῆς πόλεως διαλύσειε τὸ συμβόλαιον, καὶ τῶν μὲν ἐνθάδε μηδεὶς εἰδείη τὸν τρόπον τῆς ἀπαλλαγῆς, ἐκπλεύσαντι δ’ αὐτῷ ἐξείη λέγειν ὅ τι αὐτὸς βούλοιτο· εἰ δὲ μὴ ταῦτα ποιήσειε, δίαιταν ἐπὶ ῥητοῖς ἐπέτρεπε Σατύρῳ, ἐφ’ ᾧτε καταγιγνώσκειν ἡμιόλι’ αὐτοῦ τὰ χρήματα.", "st": "17.19"}, {"sp": "N", "t": "ταῦτα δὲ συγγράψαντες καὶ ἀναγαγόντες εἰς ἀκρόπολιν Πύρωνα Φεραῖον ἄνδρα, εἰθισμένον εἰσπλεῖν εἰς τὸν Πόντον, δίδομεν αὐτῷ φυλάττειν τὰς συνθήκας, προστάξαντες αὐτῷ, ἐὰν μὲν διαλλαγῶμεν πρὸς ἡμᾶς αὐτούς, κατακαῦσαι τὸ γραμματεῖον, εἰ δὲ μή, Σατύρω ἀποδοῦναι.", "st": "17.20"}, {"sp": "N", "t": "τὰ μὲν οὖν ἡμέτερ’, ὦ ἄνδρες δικασταί, οὕτω διεπέπρακτο· Μενέξενος δ’ ὀργιζόμενος ὑπὲρ τῆς αἰτίας ἧς κἀκεῖνον Πασίων ᾐτιάσατο, λαχὼν δίκην ἐξῄτει τὸν Κίττον, ἀξιῶν τὴν αὐτὴν Πασίωνι ψευδομένῳ γίγνεσθαι ζημίαν ἧσπερ ἂν αὐτὸς ἐτύγχανεν, εἴ τι τούτων ἐφαίνετο ποιήσας. καὶ οὗτος, ὦ ἄνδρες δικασταί, ἐδεῖτο μου ἀπαλλάττειν Μενέξενον, λέγων ὅτι οὐδὲν αὐτῷ πλέον ἔσται, εἰ τὰ μὲν χρήματ’ ἐκ τῶν συγγεγραμμένων εἰς τὸν Πόντον εἰσπλεύσας ἀποδώσει, αὐτὸς δ’ ὁμοίως ἐνθάδε καταγέλαστος ἔσοιτο· ὁ γὰρ παῖς, ἐὰν βασανίζηται,, περὶ πάντων τἀληθῆ κατεπεῖ.", "st": "17.21"}, {"sp": "N", "t": "ἐγὼ δ’ ἠξίουν πρὸς μὲν Μενέξενον πράττειν ὅ τι βούλοιτο, πρὸς δ’ ἐμὲ ποιεῖν αὐτὸν τὰ συγκείμενα. ἐν ἐκείνῳ μὲν οὖν τῷ χρόνῳ ταπεινὸς ἦν, οὐκ ἔχων ὅ τι χρήσαιτο τοῖς αὑτοῦ κακοῖς. καὶ γὰρ οὐ μόνον περὶ τῆς βασάνου καὶ τῆς δίκης ἐκείνης ἐδεδοίκει τῆς εἰληγμένης, ἀλλὰ καὶ περὶ τοῦ γραμματείου, ὅπως μὴ ὑπὸ τοῦ Μενεξένου συλληφθήσοιτο.", "st": "17.22"}, {"sp": "N", "t": "ἀπορῶν δὲ καὶ οὐδεμίαν ἄλλην εὑρίσκων ἀπαλλαγήν, πείσας τοῦ ξένου τοὺς παῖδας διαφθείρει τὸ γραμματεῖον, ὃ ἔδει Σάτυρον λαβεῖν, εἰ μή μ’ ἀπαλλάξειεν οὗτος. καὶ οὐκ ἔφθη διαπραξάμενος ταῦτα καὶ θρασύτατος ἁπάντων ἀνθρώπων ἐγένετο, καὶ οὔτ’ εἰς τὸν Πόντον ἔφη μοι συμπλευσεῖσθαι οὔτ’ εἶναι πρός ἔμ’ αὐτῷ συμβόλαιον οὐδέν, ἀνοίγειν τ’ ἐκέλευε τὸ γραμματεῖον ἐναντιόν μαρτύρων. τί ἂν ὑμῖν τὰ πολλὰ λέγοιμι, ὦ ἄνδρες δικασταί; εὑρέθη γάρ ἐν τὦ γραμματείῳ γεγραμμένος ἀφειμένος ἁπάντων τῶν ἐγκλημάτων ὑπ’ ἐμοῦ.", "st": "17.23"}, {"sp": "N", "t": "τὰ μὲν οὖν γεγενημένα, ὡς ἀκριβέστατα οἶός τ’ ἦν, ἅπανθ’ ὑμῖν εἴρηκα. ἡγοῦμαι δὲ Πασίων’, ὦ ἄνδρες δικασταί, ἐκ τοῦ διεφθαρμένου γραμματείου τὴν ἀπολογίαν ποιήσεσθαι καὶ τοὺτοις ἰσχυριεῖσθαι μάλιστα. ὑμεῖς οὖν μοι τὸν νοῦν προσέχετε· οἶμαι γὰρ ἐξ αὐτῶν τούτων φανερὰν ὑμῖν ποιήσειν τὴν τούτου πονηρίαν.", "st": "17.24"}, {"sp": "N", "t": "πρῶτον δ’ ἐκ τούτου σκοπεῖσθε. ὅτε γὰρ ἐδίδομεν τῷ ξένῳ τὴν συνθήκην, καθ’ ἣν οὗτος μὲν ἀφεῖσθαί φησι τῶν ἐγκλημάτων, ἐγὼ δ’ ὡς ἔδει με παρὰ τοὺτου κομίσασθαι τὸ χρυσίον, ἐκελεύομεν τὸν ξένον, ἐὰν μὲν διαλλαγῶμεν πρὸς ἡμᾶς αὐτούς, κατακαῦσαι τὸ γραμματεῖον, εἰ δὲ μή, Σατύρῳ ἀποδοῦναι· καὶ ταῦτα ῥηθῆναι ὑπ’ ἀμφοτέρων ἡμῶν ὁμολογεῖται.", "st": "17.25"}, {"sp": "N", "t": "καίτοι τί μαθόντες, ὦ ἄνδρες δικασταί, προσετάττομεν ἀποδοῦναι Σατύρω τὸ γραμματεῖον, ἂν μὴ διαλλαγῶμεν, εἴπερ ἀπηλλαγμένος ἤδη Πασίων ἦν ἐγκλημάτων καὶ τέλος εἶχεν ἡμῖν τὸ πρᾶγμα; ἀλλὰ δῆλον ὅτι ταύτας τὰς συνθήκας ἐποιησάμεθ’ ὡς ὑπολοίπων ὄντων ἡμῖν ἔτι πραγμάτων, περί ὦν ἔδει τοῦτον πρὸς ἐμὲ κατὰ τὸ γραμματεῖον διαλύσασθαι.", "st": "17.26"}, {"sp": "N", "t": "ἔπειτ’ ἐγὼ μέν, ὦ ἄνδρες δικασταί ἔχω τὰς αἰτίας εἰπεῖν δι’ ἃς οὗτος ὡμολόγησεν ἀποδώσειν τὸ χρυσίον· ἐπεὶ γὰρ ἡμεῖς τε τῶν πρὸς Σάτυρον διαβολῶν ἀπηλλάγημεν καὶ τὸν Κιττον οὐχ οἶός τ’ ἐγένετ’ ἀφανίσαι, τὸν συνειδότα περὶ τῆς παρακαταθήκης, ἡγησάμενος, εἰ μὲν ἐκδοίη τὸν παῖδα βασανίσαι,", "st": "17.27"}, {"sp": "N", "t": "φανερός γενήσεσθαι πανουργῶν, εἰ δὲ μὴ ποιήσειε ταῦτ’, ὀφλήσειν τὴν δίκην, ἐβουλήθη πρὸς ἐμὲ ἀπαλλαγὴν ποιήσασθαι. τοῦτον δὲ κελεύσατ’ ἀποδεῖξαι, τι κερδαίνων ἤ τίνα κίνδυνον φοβηθεὶς ἀφῆκ’ αὐτὸν τῶν ἐγκλημάτων; ἐάν δὲ μηδὲν ἔχῃ τούτων ὑμῖν ἀποφαίνειν, πῶς οὐκ ἄν δικαίως ἐμοὶ μᾶλλον ἢ τούτῳ περὶ τοῦ γραμματείου πιστεύοιτε;", "st": "17.28"}, {"sp": "N", "t": "καὶ μὲν δή, ὦ ἄνδρες δικασταί, καὶ τόδε ῥᾴδιον πᾶσι γνῶναι, ὅτι ἐμοὶ μέν, ὃς ἐνεκάλουν, εἰ τοὺς ἐλέγχους ἐφοβούμην, ἐξῆν καὶ μηδεμίαν συνθήκην ποιησάμενον χαίρειν ἐᾶν τὸ πρᾶγμα· τούτῳ δὲ διά τε τὴν βάσανον καὶ τοὺς ἀγῶνας τοὺς ἐν ὑμῖν οὐχ οἶόν τ’ ἦν ὁπότε βούλοιτ’ ἀπηλλάχθαι τῶν κινδύνων, εἰ μὴ πείσειεν ἐμὲ τὸν ἐγκαλοῦντα. ὥστ’ οὐκ ἐμὲ περὶ τῆς ἀφέσεως ἀλλὰ τοῦτον περὶ τῆς ἀποδόσεως τῶν χρημάτων ἔδει τὰς συνθήκας ποιεῖσθαι. ἔτι δὲ κἀκεῖν’ ὑπερφυές,", "st": "17.29"}, {"sp": "N", "t": "εἰ πρὶν μὲν συγγράψασθαι τὸ γραμματεῖον οὕτω σφόδρ’ ἠπίστησα τοῖς πράγμασιν ὥστε μὴ μόνον ἀφεῖναι Πασίωνα τῶν ἐγκλημάτων ἀλλὰ καὶ συνθήκας περὶ αὐτῶν ποιήσασθαι ἐπειδὴ δὲ τοιοῦτον ἔλεγχον κατ’ ἐμαυτοῦ συνεγραψάμην, τηνικαῦτ’ ἐπεθύμησ’ εἰς ὑμᾶς εἰσελθεῖν. καίτοι τίς ἄν οὕτω περί τῶν αὑτοῦ πραγμάτων βουλεύσαιτο;", "st": "17.30"}, {"sp": "N", "t": "ὃ δὲ πάντων μέγιστον τεκμήριον ὡς οὐκ ἀφειμὲνος ἦν Πασίων ἐν ταῖς συνθήκαις ἀλλ’ ὡμολογηκὼς ἀποδώσειν τὸ χρυσίον· ὅτε γὰρ Μενέξενος ἔλαχεν αὑτῷ τὴν δίκην, οὔπω διεφθαρμένου τοῦ γραμματείου, προσπέμπων Ἀγύρριον, ὄντ’ ἀμφοτέροις ἡμῖν ἐπιτήδειον, ἠξίου μ’ ἤ Μενέξενον ἀπαλλάττειν ἢ τὰς συνθήκας τὰς γεγενημένας πρὸς αὑτὸν ἀναιρεῖν.", "st": "17.31"}, {"sp": "N", "t": "καίτοι, ὦ ἄνδρες δικασταί, οἴεσθ’ ἂν αὐτὸν ἐπιθυμεῖν ἀναιρεθῆναι ταύτας τὰς συνθήκας, ἐξ ὧν ψευδομένους ἡμᾶς ἔμελλεν ἐξελέγξειν; οὔκουν ἐπειδή γε μετεγράφησαν, τούτους ἔλεγε τοὺς λόγους, ἀλλὰ περὶ ἁπάντων εἰς ἐκείνας κατέφευγε καὶ ἀνοίγειν ἐκέλευε τὸ γραμματεῖον. ὡς οὖν τὸ πρῶτον ἀναιρεῖν ἐζήτει τὰς συνθήκας, αὐτὸν Ἀγύρριον μαρτυροῦντα παρέξομαι. καί μοι ἀνάβηθι.", "st": "17.32"}, {"sp": "N", "t": "<em>Μαρτυρία<\/em>", "st": "17.32"}, {"sp": "N", "t": "ὅτι μὲν τοίνυν συνθήκας δ’ ἐποιησάμεθ’ οὐχ ὡς Πασίων ἐπιχειρήσει λέγειν, ἀλλ’ ὡς ἐγὼ πρὸς ὑμᾶς εἴρηκα, ἱκανῶς ἐπιδεδεῖχθαι νομίζω. οὐκ ἄξιον δὲ θαυμάζειν, ὦ ἄνδρες δικασταί, εἰ τὸ γραμματεῖον διέφθειρεν, οὐ μόνον διὰ τοῦτο, ὅτι πολλὰ τοιαῦτ’ ἤδη γέγονεν, ἀλλ’ ὅτι καὶ τῶν χρωμένων τινὲς Πασίωνι πολὺ δεινότερα τούτων πεποιήκασι. Πυθόδωρον γὰρ τὸν σκηνίτην καλούμενον, ὃς ὑπὲρ Πασίωνος ἅπαντα καὶ λέγει καὶ πράττει, τίς οὐκ οἶδεν ὑμῶν πέρυσιν ἀνοίξαντα τὰς ὑδρίας καὶ τοὺς κριτὰς ἐξελόντα τοὺς ὑπὸ τῆς βουλῆς εἰσβληθέντας;", "st": "17.33"}, {"sp": "N", "t": "καίτοι ὅστις μικρων ἕνεκα καὶ περὶ τοῦ σώματος κινδυνεύων ταύτας ὑπανοίγειν ἐτόλμησεν, αἳ σεσημασμέναι μὲν ἦσαν ὑπὸ τῶν χορηγῶν, ἐφυλάττοντο δ’ ὑπὸ τῶν ταμιῶν, ἔκειντο δ’ ἐν ἀκροπόλει, τί δεῖ θαυμάζειν, εἰ γραμματείδιον παρ’ ἀνθρώπῳ ξένῳ κείμενον τοσαῦτα μέλλοντες χρήματα κερδαίνειν μετέγραψαν, ἢ τοὺς παῖδας αὐτοῦ πείσαντες ἢ ἄλλῳ τρόπῳ, ᾧ ἠδύναντο, μηχανησάμενοι; περὶ μὲν οὖν τούτων οὐκ οἶδ’ ὅ τι δεῖ πλείω λέγειν.", "st": "17.34"}, {"sp": "N", "t": "ἤδη δέ τινας Πασίων ἐπεχείρησε πείθειν, ὡς τὸ παράπαν οὐδ’ ἦν ἐνθάδε μοι χρήματα, λέγων ὡς παρὰ Στρατοκλέους ἐδανεισάμην τριακοσίους στατῆρας. ἄξιον οὖν καὶ περὶ τούτων ἀκοῦσαι, ἵν’ ἐπίστησθ’, οἵοις τεκμηρίοις ἐπαρθεὶς ἀποστερεῖ με τῶν χρημάτων. ἐγὼ γάρ, ὦ ἄνδρες δικασταί, μέλλοντος Στρατοκλέους εἰσπλεῖν εἰς τὸν Πόντον, βουλόμενος ἐκεῖθεν ὡς πλεῖστ’ ἐκκομίσασθαι τῶν χρημάτων, ἐδεήθην Στρατοκλέους τὸ μὲν αὑτοῦ χρυσίον ἐμοὶ καταλιπεῖν, ἐν δὲ τῷ Πόντῳ παρὰ τοῦ πατρὸς τοὐμοῦ κομίσασθαι,", "st": "17.35"}, {"sp": "N", "t": "νομίζων μεγάλα κερδαίνειν, εἰ κατὰ πλοῦν μὴ κινδυνεύοι τὰ χρήματα, ἄλλως τε καὶ Δακεδαιμονίων ἀρχόντων κατ’ ἐκεῖνον τὸν χρόνον τῆς θαλάττης. τούτῳ μὲν οὖν οὐδὲν ἡγοῦμαι τοῦτ’ εἶναι σημεῖον, ὡς οὐκ ἦν ἐνθάδε μοι χρήματα. ἐμοὶ δὲ μέγιστ’ ἔσται τεκμήρια τὰ πρὸς Στρατοκλέα πραχθέντα, ὡς ἦν μοι παρὰ τούτῳ χρυσίον.", "st": "17.36"}, {"sp": "N", "t": "ἐρωτῶντος γὰρ Στρατοκλέους, ὅστις αὐτῷ ἀποδώσει τὰ χρήματα, ἐὰν ὁ πατὴρ οὑμὸς μὴ ποιήσῃ τὰ ἐπεσταλμένα, αὐτὸς δ’ ἐκπλεύσας ἐνθάδ’ ἐμὲ μὴ καταλάβῃ, Πασίων’ αὐτῷ συνέστησα, καὶ ὡμολόγησεν οὗτος αὐτῷ καὶ τὸ ἀρχαῖον καὶ τοὺς τόκους τοὺς γιγνομένους ἀποδώσειν. δώσειν. καίτοι εἰ μηδὲν ἔκειτο παρ’ αὐτῷ τῶν ἐμῶν, οἴεσθ’ ἄν αὐτὸν οὕτω ῥᾳδίως τοσούτων χρημάτων ἐγγυητήν μου γενέσθαι; καί μοι ἀνάβητε, μάρτυρες.", "st": "17.37"}, {"sp": "N", "t": "<em>Μάρτυρες<\/em>", "st": "17.37"}, {"sp": "N", "t": "ἴσως τοίνυν, ὦ ἄνδρες δικασταί, καὶ τούτων ὑμῖν μάρτυρας παρέξεται, ὡς ἔξαρνος ἐγενόμην πρὸς τοὺς ὑπὲρ Σατύρου πράττοντας μηδὲν κεκτῆσθαι πλὴν ὧν ἐκείνοις παρεδίδουν, καὶ ὡς αὐτὸς ἐπελαμβάνετο τῶν χρημάτων τῶν ἐμῶν ὁμολογοῦντος ἐμοῦ ὀφείλειν τριακοσίας δραχμάς, καὶ ὅτι Ἱππολαΐδαν, ξένον ὄντ’ ἐμαυτοῦ καὶ ἐπιτήδειον, περιεώρων παρὰ τούτου δανειζόμενον.", "st": "17.38"}, {"sp": "N", "t": "ἐγὼ δ’, ὦ ἄνδρες δικασταί, καταστὰς εἰς συμφορὰς οἵας ὑμῖν διηγησάμην, καὶ τῶν μὲν οἴκοι πάντων ἀπεστερημένος, τὰ δ’ ἐνθάδ’ ἀναγκαζόμενος παραδιδόναι τοῖς ἥκουσιν, ὑπολοίπου δ’ οὐδενὸς ὄντος μοι, πλὴν εἰ δυνηθείην λαθεῖν περιποιησάμενος τὸ χρυσίον τὸ παρὰ τούτῳ κείμενον, ὁμολογῶ καὶ τούτῳ προσομολογῆσαι τριακοσίας δραχμὰς καὶ περὶ τῶν ἄλλων τοιαῦτα πράττειν καὶ λέγειν ἐξ ὧν ἐκείνους μάλιστ’ ἄν πείθειν ὠόμην μηδὲν εἶναί μοι.", "st": "17.39"}, {"sp": "N", "t": "καὶ ταῦθ’ ὡς οὐ δι’ ἀπορίαν ἐγίγνετο, ἀλλ’ ἵνα πιστευθείην ὑπ’ ἐκείνων, ῥᾳδίως γνώσεσθε. πρῶτον μὲν γὰρ ὑμῖν μάρτυρας παρέξομαι τοὺς εἰδότας πολλά μοι χρήματ’ ἐκ τοῦ Πόντου κομισθέντα, ἔπειτα δὲ τοὺς ὁρῶντάς με τῇ τούτου τραπέζῃ χρώμενον, ἔτι δὲ παρ’ ὧν ἐχρυσώνησ’ ὑπ’ ἐκεῖνον τὸν χρόνον πλέον ἢ χιλίους στατῆρας.", "st": "17.40"}, {"sp": "N", "t": "πρὸς δὲ τούτοις εἰσφορᾶς ἡμῖν προσταχθείσης καὶ ἑτέρων ἐπιγραφέων γενομένων ἐγὼ πλεῖστον εἰσήνεγκα τῶν ξένων, αὐτός θ’ αἱρεθεὶς ἐμαυτῷ μὲν ἐπέγραψα τὴν μεγίστην εἰσφοράν, ὑπὲρ Πασίωνος δ’ ἐδεόμην τῶν συνεπιγραφέων, λέγων ὅτι τοῖς ἐμοῖς χρήμασι τυγχάνει χρώμενος. καί μοι ἀνάβητε μάρτυρες.", "st": "17.41"}, {"sp": "N", "t": "<em>Μάρτυρες<\/em>", "st": "17.41"}, {"sp": "N", "t": "αὐτὸν τοίνυν Πασίων’ ἔργῳ παρέξομαι τούτοις συμμαρτυροῦντα. ὁλκάδα γάρ, ἐφ’ ᾗ πολλὰ χρήματ’ ἦν ἐγὼ δεδωκώς, ἔφηνέ τις ὡς οὖσαν ἀνδρὸς Δηλίου. ἀμφισβητοῦντος δ’ ἐμοῦ καὶ καθέλκειν ἀξιοῦντος οὕτω τὴν βουλὴν διέθεσαν οἱ βουλόμενοι συκοφαντεῖν, ὥστε τὸ μὲν πρῶτον παρὰ μικρὸν ἦλθον ἄκριτος ἀποθανεῖν, τελευτῶντες δ’ ἐπείσθησαν ἐγγυητὰς παρ’ ἐμοῦ δέξασθαι.", "st": "17.42"}, {"sp": "N", "t": "καὶ Φίλιππος μὲν ὤν μοι ξένος πατρικός, κληθεὶς καὶ ὑπακούσας, δείσας τὸ μέγεθος τοῦ κινδύνου ἀπιὼν ᾤχετο· Πασίων δ’ Ἀρχέστρατόν μοι τὸν ἀπὸ τῆς τραπέζης ἑπτὰ ταλάντων ἐγγυητὴν παρέσχεν. καίτοι εἰ μικρῶν ἀπεστερεῖτο καὶ μηδὲν ᾔδει μ’ ἐνθάδε κεκτημένον, οὐκ ἂν δήπου τοσούτων χρημάτων ἐγγυητής μου κατέστη.", "st": "17.43"}, {"sp": "N", "t": "ἀλλὰ δῆλον ὅτι τὰς μὲν τριακοσίας δραχμὰς ἐνεκάλεσεν ἐμοὶ χαριζόμενος, τῶν δ’ ἑπτὰ ταλάντων ἐγγυητής μοι ἐγένεθ’ ἡγούμενος πίστιν ἔχειν ἱκανὴν τὸ χρυσίον τὸ παρ’ αὑτῷ κείμενον. ὡς μὲν τοίνυν ἦν τέ μοι πολλὰ χρήματ’ ἐνθάδε καὶ ταῦτ’ ἐπὶ τῇ τούτου τραπέζῃ κεῖταί μοι, καὶ ἐκ τῶν ἔργων τῶν Πασίωνος ὑμῖν δεδήλωκα καὶ παρὰ τῶν ἄλλων τῶν εἰδότων ἀκηκόατε.", "st": "17.44"}, {"sp": "N", "t": "δοκεῖτε δέ μοι, ὦ ἄνδρες δικασταί, ἄριστ’ ἂν γνῶναι περὶ ὧν ἀμφισβητοῦμεν, ἀναμνησθέντες ἐκεῖνον τὸν χρόνον, καὶ τὰ πράγματα πῶς εἶχεν ἡμῖν, ὅτ’ ἐγὼ Μενέξενον καὶ Φιλόμηλον προσέπεμψ’ ἀπαιτήσοντας τὴν παρακαταθήκην, καὶ Πασίων τὸ πρῶτον ἐτόλμησεν ἔξαρνος γενέσθαι. εὑρήσετε γὰρ τὸν μὲν πατέρα μου συνειλημμένον καὶ τὴν οὐσίαν ἅπασαν ἀφῃρημένον, ἐμοὶ δ’ οὐχ οἷόν τ’ ὂν διὰ τὰς παρούσας τύχας οὔτ’ αὐτοῦ μένειν οὔτ’ εἰς τὸν Πόντον εἰσπλεῖν.", "st": "17.45"}, {"sp": "N", "t": "καίτοι πότερον εἰκὸς ἔμ’ ἐν τοσούτοις ὄντα κακοῖς ἀδίκως ἐγκαλεῖν, ἢ Πασίωνα καὶ διὰ τὸ μέγεθος τῶν ἡμετέρων συμφορῶν καὶ διὰ τὸ πλῆθος τῶν χρημάτων ἐπαρθῆναι τὴν ἀποστέρησιν ποιήσασθαι; τίς δὲ πώποτ’ εἰς τοσοῦτον συκοφαντίας ἀφίκετο ὥστε αὐτὸς περὶ τοῦ σώματος κινδυνεύων τοῖς ἀλλοτρίοις ἐπιβουλεύειν; μετὰ ποίας δ’ ἂν ἐλπίδος ἢ τί διανοηθεὶς ἀδίκως ἦλθον ἐπὶ τοῦτον; πότερον ὡς δείσας τὴν δύναμιν τὴν ἐμὴν ἤμελλεν εὐθύς μοι δώσειν ἀργύριον; ἀλλ’ οὐχ οὕτως ἑκάτερος ἡμῶν ἔπραττεν.", "st": "17.46"}, {"sp": "N", "t": "ἀλλ’ εἰς ἀγῶνα καταστὰς ᾤμην καὶ παρὰ τὸ δίκαιον πλέον ἕξειν Πασίωνος παρ’ ὑμῖν; ὃς οὐδὲ μένειν ἐνθάδε παρεσκευαζόμην, δεδιὼς μή μ’ ἐξαιτήσειε Σάτυρος παρ’ ὑμῶν. ἀλλ’ ἵνα μηδὲν διαπραττόμενος ἐχθρὸς τούτῳ κατασταίην, ᾧ μάλιστ’ ἐτύγχανον πάντων τῶν ἐν τῇ πόλει χρώμενος; καὶ τίς ἂν ὑμῶν ἀξιώσειε καταγνῶναί μου τοσαύτην μανίαν καὶ ἀμαθίαν;", "st": "17.47"}, {"sp": "N", "t": "ἐνθυμηθῆναι δ’ ἄξιόν ἐστιν, ὦ ἄνδρες δικασταί, τὴν ἀτοπίαν καὶ τὴν ἀπιστίαν ὧν ἑκάστοτε Πασίων ἐπεχείρει λέγειν. ὅτε μὲν γὰρ οὕτως ἔπραττον, ὥστ’ οὐδ’ ἄν, εἰ προσωμολόγει μ’ ἀποστερεῖν τῶν χρημάτων, οἷός τ’ ἂν ἦν παρ’ αὐτοῦ δίκην λαβεῖν, τότε μὲν αἰτιᾶταί μ’ ἀδίκως ἐγκαλεῖν ἐπιχειρῆσαι· ἐπειδὴ δ’ ἐγώ τε τῶν πρὸς Σάτυρον διαβολῶν ἀπηλλάγην καὶ τοῦτον ἅπαντες ὀφλήσειν τὴν δίκην ἐνόμιζον, τηνικαῦτά μέ φησιν ἀφεῖναι πάντων τῶν ἐγκλημάτων αὐτόν. καίτοι πῶς ἂν τούτων ἀλογώτερα γένοιτο;", "st": "17.48"}, {"sp": "N", "t": "ἀλλὰ γὰρ ἴσως περὶ τούτων μόνον ἀλλ’ οὐ καὶ περὶ τῶν ἄλλων ἐναντί’ αὐτὸς αὑτῷ καὶ λέγων καὶ πράττων φανερός ἐστιν· ὃς τὸν μὲν παῖδα, ὃν αὐτὸς ἠφάνισεν, ὑφ’ ἡμῶν ἔφασκεν ἀνδραποδισθῆναι, τὸν αὐτὸν δὲ τοῦτον ἀπεγράψατο μὲν ἐν τοῖς τιμήμασιν ὡς δοῦλον μετὰ τῶν οἰκετῶν τῶν ἄλλων, ἐπεὶ δ’ αὐτὸν ἠξίου Μενέξενος βασανίζειν, ἀφῃρεῖθ’ ὡς ἐλεύθερον ὄντα.", "st": "17.49"}, {"sp": "N", "t": "πρὸς δὲ τούτοις ἀποστερῶν αὐτὸς τὴν παρακαταθήκην, ἐτόλμησεν ἡμῖν ἐγκαλεῖν ὡς ἔχομεν ἓξ τάλαντ’ ἀπὸ τῆς τούτου τραπέζης. καίτοι ὅστις περὶ πραγμάτων οὕτω φανερῶν ἐπεχείρει ψεύδεσθαι, πῶς χρὴ πιστεύειν αὐτῷ περὶ ὧν μόνος πρὸς μόνον ἔπραξεν;", "st": "17.50"}, {"sp": "N", "t": "τὸ τελευταῖον τοίνυν, ὦ ἄνδρες δικασταί, ὁμολογήσας ὡς Σάτυρον εἰσπλευσεῖσθαι καὶ ποιήσειν ἅττ’ ἂν ἐκεῖνος γνῷ, καὶ ταῦτ’ ἐξηπάτησε, καὶ αὐτὸς μὲν οὐκ ἤθελεν εἰσπλεῦσαι πολλάκις ἐμοῦ προκαλεσαμένου, εἰσέπεμψε δὲ τὸν Κίττον· ὃς ἐλθὼν ἐκεῖσ’ ἔλεγεν ὅτι ἐλεύθερος εἴη καὶ τὸ γένος Μιλήσιος, εἰσπέμψειε δ’ αὐτὸν Πασίων διδάξοντα περὶ τῶν χρημάτων.", "st": "17.51"}, {"sp": "N", "t": "ἀκούσας δὲ Σάτυρος ἀμφοτέρων ἡμῶν δικάζειν μὲν οὐκ ἠξίου περὶ τῶν ἐνθάδε γενομένων συμβολαίων, ἄλλως τε καὶ μὴ παρόντος τούτου μηδὲ μέλλοντος ποιήσειν ἃ ἐκεῖνος δικάσειεν, οὕτω δὲ σφόδρ’ ἐνόμιζεν ἀδικεῖσθαί με, ὥστε συγκαλέσας τοὺς ναυκλήρους ἐδεῖτ’ αὐτῶν βοηθεῖν ἐμοὶ καὶ μὴ περιορᾶν ἀδικούμενον, καὶ πρὸς τὴν πόλιν συγγράψας ἐπιστολὴν ἔδωκε φέρειν Θενοτίμῳ τῷ Καρκίνου. καί μοι ἀνάγνωθι αὐτοῖς.", "st": "17.52"}, {"sp": "N", "t": "<em>Ἐπιστολή<\/em>", "st": "17.52"}, {"sp": "N", "t": "οὕτω τοίνυν, ὦ ἄνδρες δικασταί, πολλῶν μοι τῶν δικαίων ὑπαρχόντων, ἐκεῖν’ ἡγοῦμαι μέγιστον εἶναι τεκμήριον ὡς ἀποστερεῖ με Πασίων τῶν χρημάτων, ὅτι τὸν παῖδ’ οὐκ ἠθέλησε βασανίζειν ἐκδοῦναι τὸν συνειδότα περὶ τῆς παρακαταθήκης. καίτοι περὶ τῶν πρὸς τοὺς ἐπὶ ταῖς τραπέζαις συμβολαίων τίς ἂν ἔλεγχος ἰσχυρότερος τούτου γένοιτο; οὐ γὰρ δὴ μάρτυράς γ’ αὐτῶν ποιούμεθα.", "st": "17.53"}, {"sp": "N", "t": "ὁρῶ δὲ καὶ ὑμᾶς καὶ περὶ τῶν ἰδίων καὶ περὶ τῶν δημοσίων οὐδὲν πιστότερον οὐδ’ ἀληθέστερον βασάνου νομίζοντας, καὶ μάρτυρας μὲν ἡγουμένους οἷόν τ’ εἶναι καὶ τῶν μὴ γενομένων παρασκευάσασθαι, τὰς δὲ βασάνους φανερῶς ἐπιδεικνύναι, ὁπότεροι τἀληθῆ λέγουσιν. ἃ οὗτος εἰδὼς ἠβουλήθη εἰκάζειν ὑμᾶς περὶ τοῦ πράγματος μᾶλλον ἢ σαφῶς εἰδέναι. οὐ γὰρ δὴ τοῦτό γ’ ἂν εἰπεῖν ἔχοι, ὡς ἔλαττον ἔμελλεν ἕξειν ἐν τῇ βασάνῳ, καὶ διὰ τοῦτ’ οὐκ εἰκὸς ἦν αὐτὸν ἐκδοῦναι.", "st": "17.54"}, {"sp": "N", "t": "πάντες γὰρ ἐπίστασθ’ ὅτι κατειπὼν μὲν ἤμελλε τὸν ἐπίλοιπον χρόνον ὑπὸ τούτου κάκιστ’ ἀνθρώπων ἀπολεῖσθαι, διακαρτερήσας δὲ καὶ ἐλεύθερος ἔσεσθαι καὶ μεθέξειν ὧν οὗτός μ’ ἀπεστέρησεν. ἀλλ’ ὅμως τοσούτῳ μέλλων πλέον ἕξειν, συνειδὼς αὑτῷ τὰ πεπραγμένα, ὑπέμεινε καὶ δίκας φεύγειν καὶ τὰς ἄλλας αἰτίας ἔχειν, ὥστε μηδεμίαν βάσανον περὶ τοῦ πράγματος τούτου γενέσθαι.", "st": "17.55"}, {"sp": "N", "t": "ἐγὼ οὖ ὑμῶν δέομαι μεμνημένους τούτων καταψηφίσασθαι Πασίωνος, καὶ μὴ τοσαύτην πονηρίαν ἐμοῦ καταγνῶναι, ὡς οἰκῶν ἐν τῷ Πόντῳ καὶ τοσαύτην οὐσίαν κεκτημένος ὥστε καὶ ἑτέρους εὖ ποιεῖν δύνασθαι, Πασίων’ ἦλθον συκοφαντήσων καὶ ψευδεῖς αὐτῷ παρακαταθήκας ἐγκαλῶν.", "st": "17.56"}, {"sp": "N", "t": "ἄξιον δὲ καὶ Σατύρου καὶ τοῦ πατρὸς ἐνθυμηθῆναι, οἳ πάντα τὸν χρόνον περὶ πλείστου τῶν Ἑλλήνων ὑμᾶς ποιοῦνται, καὶ πολλάκις ἤδη διὰ σπάνιν σίτου τὰς τῶν ἄλλων ἐμπόρων ναῦς κενὰς ἐκπέμποντες ὑμῖν ἐξαγωγὴν ἔδοσαν· καὶ ἐν τοῖς ἰδίοις συμβολαίοις, ὧν ἐκεῖνοι κριταὶ γίγνονται, οὐ μόνον ἴσον ἀλλὰ καὶ πλέον ἔχοντες ἀπέρχεσθε.", "st": "17.57"}, {"sp": "N", "t": "ὥστ’ οὐκ ἂν εἰκότως περὶ ὀλίγου ποιήσαισθε τὰς ἐκείνων ἐπιστολάς. δέομαι οὖν ὑμῶν καὶ ὑπὲρ ἐμαυτοῦ καὶ ὑπὲρ ἐκείνων τὰ δίκαια ψηφίσασθαι καὶ μὴ τοὺς Πασίωνος λόγους ψευδεῖς ὄντας πιστοτέρους ἡγεῖσθαι τῶν ἐμῶν.", "st": "17.58"}, {"sp": "HDR", "t": "Παραγραφὴ πρὸς Καλλίμαχον", "st": "18"}, {"sp": "N", "t": "εἰ μὲν καὶ ἄλλοι τινὲς ἦσαν ἠγωνισμένοι τοιαύτην παραγραφήν, ἀπ’ αὐτοῦ τοῦ πράγματος ἠρχόμην ἂν τοὺς λόγους ποιεῖσθαι· νῦν δ’ ἀνάγκη περὶ τοῦ νόμου πρῶτον εἰπεῖν καθ’ ὃν εἰσεληλύθαμεν, ἵν’ ἐπιστάμενοι περὶ ὧν ἀμφισβητοῦμεν, τὴν ψῆφον φέρητε, καὶ μηδεὶς ὑμῶν θαυμάσῃ διότι φεύγων τὴν δίκην πρότερος λέγω τοῦ διώκοντος.", "st": "18.1"}, {"sp": "N", "t": "ἐπειδὴ γὰρ ἐκ Πειραιέως κατελθόντες ἐνίους ἑωρᾶτε τῶν πολιτῶν συκοφαντεῖν ὡρμημένους καὶ τὰς συνθήκας λύειν ἐπιχειροῦντας, βουλόμενοι τούτους τε παῦσαι καὶ τοῖς ἄλλοις ἐπιδεῖξαι ὅτι οὐκ ἀναγκασθέντες ἐποιήσασθ’ αὐτὰς ἀλλ’ ἡγούμενοι τῇ πόλει συμφέρειν, εἰπόντος Ἀρχίνου νόμον ἔθεσθε, ἄν τις δικάζηται παρὰ τοὺς ὅρκους, ἐξεῖναι τῷ φεύγοντι παραγράψασθαι, τοὺς δ’ ἄρχοντας περὶ τούτου πρῶτον εἰσάγειν, λέγειν δὲ πρότερον τὸν παραγραψάμενον,", "st": "18.2"}, {"sp": "N", "t": "ὁπότερος δ’ ἂν ἡττηθῇ, τὴν ἐπωβελίαν ὀφείλειν, ἵν’ οἱ τολμῶντες μνησικακεῖν μὴ μόνον ἐπιορκοῦντες ἐξελέγχοιντο μηδὲ τὴν παρὰ τῶν θεῶν τιμωρίαν ὑπομένοιεν ἀλλὰ καὶ παραχρῆμα ζημιοῖντο. δεινὸν οὖν ἡγησάμην, εἰ τῶν νόμων οὕτως ἐχόντων ἐγὼ περιόψομαι τὸν μὲν συκοφάντην ἐν τριάκοντα δραχμαῖς κινδυνεύοντα, ἐμαυτὸν δὲ περὶ τῆς οὐσίας ἁπάσης ἀγωνιζόμενον.", "st": "18.3"}, {"sp": "N", "t": "ἀποδείξω δὲ Καλλίμαχον οὐ μόνον παρὰ τὰς συνθήκας δικαζόμενον, ἀλλὰ καὶ περὶ τῶν ἐγκλημάτων ψευδόμενον, καὶ προσέτι δίαιταν ἡμῖν γεγενημένην περὶ αὐτῶν. βούλομαι δ’ ἐξ ἀρχῆς ὑμῖν διηγήσασθαι τὰ πραχθέντα· ἂν γὰρ τοῦτο μάθητε ὡς οὐδὲν ὑπ’ ἐμοῦ κακὸν πέπονθεν, ἡγοῦμαι ταῖς τε συνθήκαις ὑμᾶς ἥδιον βοηθήσειν καὶ τούτῳ μᾶλλον ὀργιεῖσθαι.", "st": "18.4"}, {"sp": "N", "t": "ἦρχον μὲν γὰρ οἱ δέκα οἱ μετὰ τοὺς τριάκοντα καταστάντες, ὄντος δέ μοι Πατροκλέους ἐπιτηδείου, τοῦ τότε βασιλεύοντος, ἔτυχον μετ’ αὐτοῦ βαδίζων. ἐκεῖνος δ’ ἐχθρὸς ὢν Καλλιμάχῳ τῷ νῦν ἐμὲ διώκοντι τὴν δίκην, ἀπήντησεν ἀργύριον φέροντι. λαβόμενος δ’ αὐτοῦ Πάμφιλον ἔφασκεν αὐτὸ καταλιπεῖν καὶ δημόσιον γίγνεσθαι· ἐκεῖνον γὰρ εἶναι τῶν ἐν Πειραιεῖ.", "st": "18.5"}, {"sp": "N", "t": "ἀμφισβητοῦντος δὲ τούτου καὶ λοιδορίας αὐτοῖς γενομένης ἄλλοι τε πολλοὶ συνέδραμον, καὶ κατὰ τύχην Ῥίνων εἷς τῶν δέκα γενόμενος προσῆλθεν. εὐθὺς οὖν πρὸς αὐτὸν τὴν φάσιν τῶν χρημάτων ὁ Πατροκλῆς ἐποιεῖτο· ὁ δ’ ὡς τοὺς συνάρχοντας ἦγεν ἀμφοτέρους. ἐκεῖνοι δ’ εἰς τὴν βουλὴν περὶ αὐτῶν ἀπέδοσαν· κρίσεως δὲ γενομένης ἔδοξε τὰ χρήματα δημόσι’ εἶναι. μετὰ δὲ ταῦτ’,", "st": "18.6"}, {"sp": "N", "t": "ἐπειδὴ κατῆλθον οἱ φεύγοντες ἐκ Πειραιέως, οὗτος ἐνεκάλει τῷ Πατροκλεῖ καὶ δίκας ἐλάγχανεν ὡς αἰτίῳ τῆς συμφορᾶς γεγενημένῳ· διαλλαγεὶς δὲ πρὸς ἐκεῖνον καὶ πραξάμενος αὐτὸν δέκα μνᾶς ἀργυρίου Λυσίμαχον ἐσυκοφάντει· λαβὼν δὲ καὶ παρὰ τούτου διακοσίας δραχμὰς ἐμοὶ πράγματα παρεῖχεν. καὶ τὸ μὲν πρῶτον ἐνεκάλει φάσκων με συμπράττειν ἐκείνοις, τελευτῶν δ’ εἰς τοῦτ’ ἀναιδείας ἦλθεν ὥσθ’ ἁπάντων με τῶν γεγενημένων ᾐτιᾶτο· ἅπερ ἴσως καὶ νῦν τολμήσει κατηγορεῖν.", "st": "18.7"}, {"sp": "N", "t": "ἐγὼ δ’ ὑμῖν παρέξομαι μάρτυρας πρῶτον μὲν τοὺς ἐξ ἀρχῆς παραγενομένους, ὡς οὔτ’ ἐπελαβόμην οὔτ’ ἐφηψάμην τῶν χρημάτων, ἔπειτα Ῥίνωνα καὶ τοὺς συνάρχοντας, ὡς οὐκ ἐγὼ τὴν φάσιν ἀλλὰ Πατροκλῆς ἐποιήσατο πρὸς αὐτούς, ἔτι δὲ τοὺς βουλευτάς, ὡς ἐκεῖνος ἦν ὁ κατηγορῶν. καί μοι κάλει τούτων μάρτυρας.", "st": "18.8"}, {"sp": "N", "t": "<em>Μάρτυρες<\/em>", "st": "18.8"}, {"sp": "N", "t": "οὕτω τοίνυν πολλῶν παραγενομένων τοῖς πραχθεῖσιν, ὥσπερ οὐδενὸς συνειδότος αὐτὸς μὲν οὗτος ἐφιστάμενος εἰς τοὺς ὄχλους καὶ καθίζων ἐπὶ τοῖς ἐργαστηρίοις λόγους ἐποιεῖτο ὡς δεινὰ πεπονθὼς ὑπ’ ἐμοῦ καὶ τῶν χρημάτων ἀπεστερημένος, τῶν δὲ χρωμένων τινὲς τούτῳ προσιόντες μοι συνεβούλευον ἀπαλλάττεσθαι τῆς πρὸς τοῦτον διαφορᾶς καὶ μὴ βούλεσθαι κακῶς ἀκούειν μηδὲ κινδυνεύειν περὶ πολλῶν χρημάτων, μηδ’ εἰ σφόδρα πιστεύω τῷ πράγματι, λέγοντες ὡς πολλὰ παρὰ γνώμην ἐν τοῖς δικαστηρίοις ἀποβαίνει,", "st": "18.9"}, {"sp": "N", "t": "καὶ ὅτι τύχῃ μᾶλλον ἢ τῷ δικαίῳ κρίνεται τὰ παρ’ ὑμῖν, ὥστε λυσιτελεῖν μοι μίκρ’ ἀναλώσαντι μεγάλων ἐγκλημάτων ἀπαλλαγῆναι μᾶλλον ἢ μηδὲν ἀποτείσαντι κινδυνεύειν περὶ τηλικούτων. τί δ’ ἂν ὑμῖν τὰ πολλὰ καθ’ ἕκαστον διηγοίμην; οὐδὲν γὰρ παρέλιπον τῶν εἰθισμένων περὶ τῶν τοιούτων λέγεσθαι. τελευτῶν δ’ οὖν ἐπείσθην, ἅπαντα γὰρ εἰρήσεται τἀληθῆ πρὸς ὑμᾶς, δοῦναι τούτῳ διακοσίας δραχμάς. ἵνα δὲ μὴ πάλιν ἐξείη συκοφαντεῖν αὐτῷ, δίαιταν ἐπὶ ῥητοῖς ἐπετρέψαμεν Νικομάχῳ Βατῆθεν. …", "st": "18.10"}, {"sp": "N", "t": "<em>Μάρτυρες<\/em>", "st": "18.10"}, {"sp": "N", "t": "τὸ μὲν τοίνυν πρῶτον ἐνέμεινε τοῖς ὡμολογημένοις, ὕστερον δ’ ἐπιβουλεύσας μετὰ Ξενοτίμου, τοῦ τοὺς νόμους διαφθείροντος καὶ τὰ δικαστήρια δεκάζοντος καὶ τὰς ἀρχὰς λυμαινομένου καὶ πάντων κακῶν αἰτίου, λαγχάνει μοι δίκην μυρίων δραχμῶν. προβαλλομένου δ’ ἐμοῦ μάρτυρα, ὡς οὐκ εἰσαγώγιμος ἦν ἡ δίκη διαίτης γεγενημένης, ἐκείνῳ μὲν οὐκ ἐπεξῆλθεν,", "st": "18.11"}, {"sp": "N", "t": "εἰδὼς ὅτι, εἰ μὴ μεταλάβοι τὸ πέμπτον μέρος τῶν ψήφων, τὴν ἐπωβελίαν ὀφλήσει, πείσας δὲ τὴν ἀρχὴν πάλιν τὴν αὐτὴν δίκην ἐγράψατο, ὡς ἐν τοῖς πρυτανείοις μόνον κινδυνεύσων. ἀπορῶν δ’ ὅ τι χρησαίμην τοῖς κακοῖς, ἡγησάμην εἶναι κράτιστον ἐξ ἴσου καταστήσαντ’ ἀμφοτέροις τὸν κίνδυνον εἰσελθεῖν εἰς ὑμᾶς. καὶ τὰ μὲν γενόμενα ταῦτ’ ἐστίν.", "st": "18.12"}, {"sp": "N", "t": "πυνθάνομαι δὲ Καλλίμαχον οὐ μόνον περὶ τῶν ἐγκλημάτων διανοεῖσθαι ψευδῆ λέγειν, ἀλλὰ καὶ τὴν δίαιταν μέλλειν ἔξαρνον εἶναι καὶ παρεσκευάσθαι λέγειν τοιούτους λόγους, ὡς οὐκ ἄν ποτ’ ἐπέτρεψε Νικομάχῳ δίαιταν, ὃν ἠπίστατο πάλαι χρώμενον ἡμῖν, καὶ ὡς οὐκ ἐικὸς ἦν αὐτὸν ἀντὶ μυρίων δραχμῶν διακοσίας ἐθελῆσαι λαβεῖν.", "st": "18.13"}, {"sp": "N", "t": "ὑμεῖς δ’ ἐνθυμεῖσθε πρῶτον μὲν ὅτι τὴν δίαιταν οὐκ ἀμφισβητοῦντες ἀλλ’ ἐπὶ ῥητοῖς ἐπετρέψαμεν, ὥστ’ οὐδὲν ἄτοπον ἐποίησεν, εἰ Νικόμαχον εἵλετο διαιτητήν, ἀλλὰ πολὺ μᾶλλον εἰ περὶ τῶν πραγμάτων ὡμολογηκὼς περὶ τοῦ διαιτητοῦ διεφέρετο. ἔπειτ’ ὀφειλομένων μὲν αὐτῷ μυρίων δραχμῶν οὐκ εἰκὸς ἦν αὐτὸν ἐπὶ δυοῖν μναῖν ποιήσασθαι τὴν διαλλαγήν· ἀδίκως δ’ αἰτιώμενον καὶ συκοφαντοῦντα οὐδὲν θαυμαστὸν τοσοῦτον ἐθελῆσαι λαβεῖν. ἔτι δ’, εἰ μεγάλ’ ἐγκαλῶν ὀλίγ’ ἐπράξατο, οὐ τούτῳ τοῦτο τεκμήριόν ἐστιν, ὡς ἡ δίαιτα οὐ γέγονεν, ἀλλὰ πολὺ μᾶλλον ἡμῖν, ὡς καὶ τὴν ἀρχὴν οὐ δικαίως ἐνεκάλεσεν.", "st": "18.14"}, {"sp": "N", "t": "θαυμάζω δ’ εἰ αὑτὸν μὲν ἱκανὸν γνῶναι νομίζει ὅτι οὐκ εἰκὸς ἀντὶ μυρίων δραχμῶν διακοσίας ἐθελῆσαι λαβεῖν, ἐμὲ δ’ οὐκ ἂν οἴεται τοῦτ’ ἐξευρεῖν, εἴπερ ἠβουλόμην ψευδῆ λέγειν, ὅτι πλέον ἔδει φάσκειν τούτων δεδωκέναι. ἀξιῶ δ’, ὅσον περ ἂν τούτῳ σημεῖον ἦν ὡς ἡ δίαιτα οὐ γέγονεν, ἑλόντι τὰ διαμαρτυρηθέντα, τοσοῦτον ἐμοὶ γενέσθαι τεκμήριον ὡς ἀληθῆ λέγω περὶ αὐτῆς, ἐπειδὴ τῷ μάρτυρι φανερός ἐστιν οὐδ’ ἐπεξελθεῖν ἀξιώσας.", "st": "18.15"}, {"sp": "N", "t": "ἡγοῦμαι δ’, εἰ μήθ’ ἡ δίαιτα ἐγεγόνει μήτε τῶν πεπραγμένων ἦσαν μάρτυρες, ἔδει δ’ ἐκ τῶν εἰκότων σκοπεῖν, οὐδ’ οὕτω χαλεπῶς ἂν ὑμᾶς γνῶναι τὰ δίκαια. εἰ μὲν γὰρ καὶ τοὺς ἄλλους ἀδικεῖν ἐτόλμων, εἰκότως ἄν μου κατεγιγνώσκετε καὶ περὶ τοῦτον ἐξαμαρτάνειν· νῦν δ’ οὐδένα φανήσομαι τῶν πολιτῶν οὔτε χρήμασι ζημιώσας οὔτε περὶ τοῦ σώματος εἰς κίνδυνον καταστήσας, οὔτ’ ἐκ μὲν τῶν μετεχόντων τῆς πολιτείας ἐξαλείψας, εἰς δὲ τὸν μετὰ Λυσάνδρου κατάλογον ἐγγράψας.", "st": "18.16"}, {"sp": "N", "t": "καίτοι πολλοὺς ἐπῆρεν ἡ τῶν τριάκοντα πονηρία τοιαῦτα ποιεῖν· οὐ γὰρ ὅτι τοὺς ἀδικοῦντας ἐκόλαζον, ἀλλ’ ἐνίοις καὶ προσέταττον ἐξαμαρτάνειν. ἐγὼ μὲν τοίνυν οὐδ’ ἐπὶ τῆς ἐκείνων ἀρχῆς οὐδὲν εὑρεθήσομαι τοιοῦτον ἐργασάμενος· οὗτος δ’ ἀδικηθῆναί φησιν, ὅτ’ ἐξεβέβληντο μὲν οἱ τριάκοντα, ὁ δὲ Πειραιεὺς ἦν κατειλημμένος, ἐκράτει δ’ ὁ δῆμος, περὶ διαλλαγῶν δ’ ἦσαν οἱ λόγοι.", "st": "18.17"}, {"sp": "N", "t": "καίτοι δοκεῖ ἂν ὑμῖν, ὅστις ἐπὶ τῶν τριάκοντα κόσμιον αὑτὸν παρέσχεν, εἰς τοῦτον ἀποθέσθαι τὸν χρόνον ἀδικεῖν, ἐν ᾧ καὶ τοῖς πρότερον ἡμαρτηκόσι μετέμελεν; ὃ δὲ πάντων δεινότατον, εἰ τῶν μὲν ὑπαρχόντων ἐχθρῶν μηδ’ ἀμύνεσθαι μηδέν’ ἠξίωσα, τοῦτον δὲ κακῶς ποιεῖν ἐπεχείρουν, πρὸς ὃν οὐδὲν πώποτέ μοι συμβόλαιον ἐγένετο.", "st": "18.18"}, {"sp": "N", "t": "ὡς μὲν οὖν οὐκ αἴτιός εἰμι Καλλιμάχῳ τῆς τῶν χρημάτων δημεύσεως, ἱκανῶς ἀποδεδεῖχθαί μοι νομίζω· ὡς δ’ οὐκ ἐξῆν αὐτῷ δικάζεσθαι περὶ τῶν τότε γεγενημένων, οὐδ’ εἰ πάντα ταῦτ’ ἦν πεποιηκὼς ἅ φησιν αὐτός, ἐκ τῶν συνθηκῶν γνώσεσθε. καί μοι λαβὲ τὸ βιβλίον.", "st": "18.19"}, {"sp": "N", "t": "<em>Συνθῆκαι<\/em>", "st": "18.19"}, {"sp": "N", "t": "ἆρα μικρῷ τῷ δικαίῳ πιστεύων τὴν παραγραφὴν ἐποιησάμην, ἀλλ’ οὐ τῶν μὲν συνθηκῶν διαρρήδην ἀφιεισῶν τοὺς ἐνδείξαντας ἢ φήναντας ἢ τῶν ἄλλων τι τῶν τοιούτων πράξαντας, ἐμαυτὸν δ’ ἔχων ἀποφαίνειν, ὡς οὔτε ταῦτα πεποίηκα οὔτ’ ἄλλ’ οὐδὲν ἐξήμαρτον; ἀνάγνωθι δή μοι καὶ τοὺς ὅρκους.", "st": "18.20"}, {"sp": "N", "t": "<em>Ὅρκοι<\/em>", "st": "18.20"}, {"sp": "N", "t": "οὐκ οὖν δεινόν, ὦ ἄνδρες δικασταί, οὕτω μὲν τῶν συνθηκῶν ἐχουσῶν, τοιούτων δὲ τῶν ὅρκων γενομένων, τοσοῦτον φρονεῖν Καλλίμαχον ἐπὶ τοῖς λόγοις τοῖς αὑτοῦ ὥσθ’ ἡγεῖσθαι πείσειν ὑμᾶς ἐναντία τούτοις ψηφίσασθαι; καὶ εἰ μὲν ἑώρα μεταμέλον τῇ πόλει τῶν πεπραγμένων, οὐκ ἄξιον ἦν θαυμάζειν αὐτοῦ· νῦν δ’ οὐ μόνον ἐν τῇ θέσει τῶν νόμων ἐπεδείξασθε περὶ πολλοῦ ποιούμενοι τὰς συνθήκας,", "st": "18.21"}, {"sp": "N", "t": "ἀλλὰ καὶ Φίλωνα τὸν ἐκ Κοίλης ἐνδειχθέντα παραπρεσβεύεσθαι, καὶ περὶ μὲν τοῦ πράγματος οὐδὲν ἔχοντ’ ἀπολογήσασθαι, τὰς δὲ συνθήκας παρεχόμενον, ἔδοξεν ὑμῖν ἀφεῖναι καὶ μηδὲ κρίσιν περὶ αὐτοῦ ποιήσασθαι. καὶ ἡ μὲν πόλις οὐδὲ παρὰ τῶν ὁμολογούντων ἐξαμαρτάνειν ἀξιοῖ δίκην λαβεῖν, οὗτος δὲ καὶ τοὺς οὐδὲν ἠδικηκότας τολμᾷ συκοφαντεῖν.", "st": "18.22"}, {"sp": "N", "t": "καὶ μὴν οὐδὲ τάδ’ αὐτὸν λέληθεν, ὅτι Θρασύβουλος καὶ Ἄνυτος μέγιστον μὲν δυνάμενοι τῶν ἐν τῇ πόλει, πολλῶν δ’ ἀπεστερημένοι χρημάτων, εἰδότες δὲ τοὺς ἀπογράψαντας, ὅμως οὐ τολμῶσιν αὐτοῖς δίκας λαγχάνειν οὐδὲ μνησικακεῖν, ἀλλ’ εἰ καὶ περὶ τῶν ἄλλων μᾶλλον ἑτέρων δύνανται διαπράττεσθαι,", "st": "18.23"}, {"sp": "N", "t": "ἀλλ’ οὖν περὶ γε τῶν ἐν ταῖς συνθήκαις ἴσον ἔχειν τοῖς ἄλλοις ἀξιοῦσιν. καὶ οὐχ οὗτοι μόνοι ταῦτ’ ἠξιώκασιν, ἀλλ’ οὐδ’ ὑμῶν οὐδεὶς τοιαύτην δίκην εἰσελθεῖν τετόλμηκεν. καίτοι δεινόν, εἰ ἐπὶ μὲν τοῖς ὑμετέροις αὐτῶν πράγμασιν ἐμμένετε τοῖς ὅρκοις, ἐπὶ δὲ τῇ τούτου συκοφαντίᾳ παραβαίνειν ἐπιχειρήσετε, καὶ τὰς μὲν ἰδίας ὁμολογίας δημοσίᾳ κυρίας ἀναγκάζετ’ εἶναι, τὰς δὲ τῆς πόλεως συνθήκας ἰδίᾳ τὸν βουλόμενον λύειν ἐάσετε.", "st": "18.24"}, {"sp": "N", "t": "ὃ δὲ πάντων ἄν τις μάλιστα θαυμάσειεν, εἰ, ὅτε μὲν ἄδηλον ἦν, εἰ συνοίσουσιν αἱ διαλλαγαὶ τῇ πόλει, τοιούτους ὅρκους ἐποιήσασθε περὶ αὐτῶν, ὥστ’ εἰ καὶ μὴ συνέφερεν ἀναγκαῖον εἶναι τοῖς ὡμολογημένοις ἐμμένειν, ἐπειδὴ δ’ οὕτω καλῶς ὑμῖν συμβέβηκεν ὥστε καὶ μηδεμιᾶς πίστεως γεγενημένης ἄξιον εἶναι τὴν παροῦσαν πολιτείαν διαφυλάττειν,", "st": "18.25"}, {"sp": "N", "t": "τηνικαῦτα τοὺς ὅρκους παραβήσεσθε· καὶ τοῖς μὲν εἰρηκόσιν ὡς χρὴ τὰς συνθήκας ἐξαλείφειν ὠργίζεσθε, τουτονὶ δ’, ὃς γεγραμμένας αὐτὰς τολμᾷ παραβαίνειν, ἀζήμιον ἀφήσετε. ἀλλ’ οὔτ’ ἂν δίκαια οὔτ’ ἄξι’ ὑμῶν αὐτῶν οὔτ’ ἂν πρέποντα τοῖς πρότερον ἐγνωσμένοις ποιήσαιτε.", "st": "18.26"}, {"sp": "N", "t": "ἐνθυμεῖσθε δ’ ὅτι περὶ τῶν μεγίστων ἥκετε δικάσοντες· περὶ γὰρ συνθηκῶν τὴν ψῆφον οἴσετε, ἃς οὐδὲ πώποτ’ οὔθ’ ὑμῖν πρὸς ἑτέρους οὔτ’ ἄλλοις πρὸς ὑμᾶς ἐλυσιτέλησε παραβῆναι, τοσαύτην δ’ ἔχουσι δύναμιν ὥστε τὰ πλεῖστα τοῦ βίου καὶ τοῖς Ἕλλησι καὶ τοῖς βαρβάροις διὰ συνθηκῶν εἶναι.", "st": "18.27"}, {"sp": "N", "t": "ταύταις γὰρ πιστεύοντες ὡς ἀλλήλους ἀφικνούμεθα καὶ ποριζόμεθα ὧν ἕκαστοι τυγχάνομεν δεόμενοι· μετὰ τούτων καὶ τὰ συμβόλαια τὰ πρὸς ἡμᾶς αὐτοὺς ποιούμεθα καὶ τὰς ἰδίας ἔχθρας καὶ τοὺς κοινοὺς πολέμους διαλυόμεθα· τούτῳ μόνῳ κοινῷ πάντες ἄνθρωποι διατελοῦμεν χρώμενοι. ὥσθ’ ἅπασι μὲν προσήκει βοηθεῖν αὐταῖς, μάλιστα δ’ ὑμῖν.", "st": "18.28"}, {"sp": "N", "t": "ὑπόγυιον γὰρ ἐστιν, ἐξ οὗ καταπολεμηθέντες, ἐπὶ τοῖς ἐχθροῖς γενόμενοι, πολλῶν ἐπιθυμησάντων διαφθεῖραι τὴν πόλιν, εἰς ὅρκους καὶ συνθήκας κατεφύγομεν, ἅς εἰ Λακεδαιμόνιοι τολμῷεν παραβαίνειν, σφόδρ’ ἂν ἕκαστος ὑμῶν ἀγανακτήσειεν.", "st": "18.29"}, {"sp": "N", "t": "καίτοι πῶς οἷόν τ’ ἐστὶν ἑτέρων κατηγορεῖν οἷς αὐτός τις ἔνοχός ἐστιν; τῷ δ’ ἂν δόξαιμεν ἀδικεῖσθαι παρὰ τὰς συνθήκας κακῶς πάσχοντες, εἰ μηδ’ αὐτοὶ φαινοίμεθ’ αὐτὰς περὶ πολλοῦ ποιούμενοι; τίνας δὲ πίστεις πρὸς τοὺς ἄλλους εὑρήσομεν, εἰ τὰς πρὸς ἡμᾶς αὐτοὺς γεγενημένας οὕτως εἰκῇ λύσομεν;", "st": "18.30"}, {"sp": "N", "t": "ἄξιον δὲ καὶ τῶνδε μνησθῆναι, διότι πολλῶν καὶ καλῶν τοῖς προγόνοις ἐν τῷ πολέμῳ πεπραγμένων οὐχ ἥκισθ’ ἡ πόλις ἐκ τούτων τῶν διαλλαγῶν εὐδοκίμησεν. πρὸς μὲν γὰρ τὸν πόλεμον πολλαὶ πόλεις ἂν εὑρεθεῖεν καλῶς ἠγωνισμέναι, περὶ δὲ στάσεως οὐκ ἔστιν ἣν ἄν τις ἐπιδείξειεν ἄμεινον τῆς ἡμετέρας βεβουλευμένην.", "st": "18.31"}, {"sp": "N", "t": "ἔτι δὲ τῶν μὲν τοιούτων ἔργων, ὅσα μετὰ κινδύνων πέπρακται, τὸ πλεῖστον ἄν τις μέρος τῇ τύχῃ μεταδοίη· τῆς δ’ εἰς ἡμᾶς αὐτοὺς μετριότητος οὐδεὶς ἂν ἄλλ’ ἢ τὴν ἡμετέραν γνώμην αἰτιάσαιτο. ὥστ’ οὐκ ἄξιον προδότας ταύτης τῆς δόξης γενέσθαι.", "st": "18.32"}, {"sp": "N", "t": "καὶ μηδεὶς ἡγείσθω μ’ ὑπερβάλλειν μηδὲ μείζω λέγειν, ὅτι δίκην ἰδίαν φεύγων τούτους εἴρηκα τοὺς λόγους. οὐ γὰρ μόνον περὶ τῶν ἐπιγεγραμμένων χρημάτων ἐστιν οὗτος ὁ ἀγών, ἀλλ’ ἐμοὶ μὲν περὶ τούτων, ὑμῖν δὲ περὶ τῶν ὀλίγῳ πρότερον εἰρημένων· ὑπὲρ ὧν οὐδεὶς οὔτ’ ἂν εἰπεῖν ἀξίως δύναιτο οὔτ’ ἂν τίμημ’ ἱκανὸν ἐπιγράψαιτο.", "st": "18.33"}, {"sp": "N", "t": "τοσοῦτον γὰρ αὕτη διαφέρει τῶν ἄλλων δικῶν, ὥστε τῶν μὲν τοῖς ἀγωνιζομένοις μόνον προσήκει, ταύτῃ δὲ τὸ κοινὸν τῆς πόλεως συγκινδυνεύει. περὶ ταύτης δύ’ ὅρκους ὀμόσαντες δικάζετε, τὸν μὲν, ὅνπερ ἐπὶ ταῖς ἄλλαις εἴθισθε, τὸν δ’ ὃν ἐπὶ ταῖς συνθήκαις ἐποιήσασθε. ταύτην ἀδίκως γνόντες οὐ τοὺς τῆς πόλεως μόνον νόμους ἀλλὰ καὶ τοὺς ἁπάντων κοινοὺς παραβήσεσθε. ὥστ’ οὐκ ἄξιον οὔτε κατὰ χάριν οὔτε κατ’ ἐπιείκειαν οὔτε κατ’ ἄλλ’ οὐδὲν ἢ κατὰ τοὺς ὅρκους περὶ αὐτῶν ψηφίσασθαι.", "st": "18.34"}, {"sp": "N", "t": "ὡς μὲν οὖν χρὴ καὶ συμφέρει καὶ δίκαιον ὑμᾶς ἐστὶν οὕτω περὶ τῶν συνθηκῶν γιγνώσκειν, οὐδ’ αὐτὸν ἡγοῦμαι Καλλίμαχον ἀντερεῖν· οἶμαι δ’ αὐτὸν ὀδυρεῖσθαι τὴν παροῦσαν πενίαν καὶ τὴν γεγενημένην αὑτῷ συμφοράν, καὶ λέξειν ὡς δεινὰ καὶ σχέτλια πείσεται, εἰ τῶν χρημάτων, ὧν ἐπὶ τῆς ὀλιγαρχίας ἀφῃρέθη, τούτων ἐν δημοκρατίᾳ τὴν ἐπωβελίαν ὀφλήσει, καὶ εἰ τότε μὲν διὰ τὴν οὐσίαν τὴν αὑτοῦ φυγεῖν ἠναγκάσθη, νυνὶ δ’ ἐν ᾧ χρόνῳ προσῆκεν αὑτὸν δίκην λαβεῖν, ἅτιμος γενήσεται.", "st": "18.35"}, {"sp": "N", "t": "κατηγορήσει δὲ καὶ τῶν ἐν τῇ μεταστάσει γενομένων, ὡς ἐκ τοὺτων μάλισθ’ ὑμᾶς εἰς ὀργὴν καταστήσων· ἴσως γὰρ τινος ἀκήκοεν, ὡς ὑμεῖς, ὅταν μὴ τοὺς ἀδικοῦντας λάβητε, τοὺς ἐντυγχάνοντας κολάζετε. ἐγὼ δ’ οὔθ’ ὑμᾶς ταύτην ἔχειν τὴν γνώμην ἡγοῦμαι, πρὸς τε τοὺς ὑπειρημένους λόγους ῥᾲδιον ἁντειπεῖν νομίζω.", "st": "18.36"}, {"sp": "N", "t": "πρὸς οὖν τοὺς ὀδυρμούς, ὅτι προσήκει βοηθεῖν ὑμᾶς, οὐχ οἵτινες ἂν δυστυχεστάτους σφᾶς αὐτοὺς ἀποδείξωσιν, ἀλλ’ οἵτινες ἂν περὶ ὧν ἀντωμόσαντο δικαιότερα λέγοντες φάνωνται. περὶ δὲ τῆς ἐπωβελίας, εἰ μὲν ἐγὼ τοὺτων τῶν πραγμάτων αἴτιος ἦν, εἰκότως ἂν αὐτῷ μέλλοντι ζημιώσεσθαι συνήχθεσθε· νῦν δ’ οὗτος ἐστιν ὁ συκοφαντῶν, ὥστ’ οὐδὲν ἂν δικαίως αὐτοῦ λέγοντος ἀποδέχοισθε.", "st": "18.37"}, {"sp": "N", "t": "ἔπειτα κἀκεῖνο χρὴ σκοπεῖν, ὅτι πάντες οἱ κατελθόντες ἐκ Περαίεως ἔχοιεν ἂν τοὺς αὐτοὺς λόγους εἰπεῖν, οὕσπερ οὗτος, ὧν οὐδεὶς ἄλλος τετόλμηκε τοιαύτην δίκην εἰσελθεῖν. Καίτοι χρὴ μισεῖν ὑμᾶς τοὺς τοιούτους καὶ κακοὺς πολίτας νομίζειν, οἵτινες ταῖς μὲν συμφοραῖς ὁμοίας τῷ τῷ πλήθει κέχρηνται, τὰς δὲ τιμωρίας διαφόρους τῶν ἅλλων ἀξιοῦσι ποιεῖσθαι.", "st": "18.38"}, {"sp": "N", "t": "πρὸς δὲ τοὺτοις ἔτι καὶ νῦν ἔξεστιν αὐτῷ, πρὶν ἀποπειραθῆναι τῆς ὑμετὲρας γνώμης, ἁφέντι τὴν δίκην ἀπηλλάχθαι πάντων τῶν πραγμάτων. καίτοι πῶς οὐκ ἄλογόν ἐστιν ἐν τούτῳ τῷ κινδύνῳ ζητεῖν αὐτόν ἐλέου παρ’ ὑμῶν τυγχάνειν, οὗ κύριος αὐτός ἐστι, καὶ εἰς ὃ αὐτὸς αὑτὸν καθίστησι, καὶ ὃ ἔτι καὶ νῦν ἔξεστιν αὐτῷ μὴ κινδυνεύειν;", "st": "18.39"}, {"sp": "N", "t": "ἂν δ’ ἄρα μέμνηται τῶν ἐπὶ τῆς ὀλιγαρχίας γεγενημένων, ἁξιοῦτε αὐτὸν μὴ ’κείνων κατηγορεῖν, ὑπὲρ ὧν οὐδεὶς ἀπολογήσεται, ἀλλ’ ὡς ἐγὼ τὰ χρήματα εἴληφα διδάσκειν, περὶ οὗπερ ὑμᾶς δεῖ ψηφίζεσθαι, μηδ’ ὡς αὐτός δεινὰ πέπονθεν ἀποφαίνειν, ἀλλ’ ὡς ἐγὼ πεποίηκα ἐξελέγχειν, παρ’ οὗπερ ἀξιοῖ τἀπολωλότα κομίζεσθαι·", "st": "18.40"}, {"sp": "N", "t": "ἐπεὶ κακῶς γ’ αὑτὸν πράττοντα ἐπιδεῖξαι καὶ πρὸς ἄλλον ὁντινοῦν ἀγωνιζόμενος τῶν πολιτῶν δύναται. καίτοι χρὴ μέγα παρ’ ὑμῖν δύνασθαι τῶν κατηγοριῶν, οὐχ αἷς ἔξεστι χρῆσθαι καὶ πρὸς τοὺς μηδέν ἡμαρτηκότας, ἀλλ’ ἃς οὐχ οἷ τ’ εἰπεῖν ἀλλ’ ἢ κατὰ τῶν ἠδικηκότων. πρὸς μὲν οὖν τούτους τοὺς λόγους καὶ ταῦτ’ ἴσως ἀρκέσει καὶ τάχ’ ἀντειπεῖν ἐξέσται.", "st": "18.41"}, {"sp": "N", "t": "ἐνθυμεῖσθε δ’, εἰ καὶ τῳ δόξω δὶς περὶ τῶν αὐτῶν λέγειν, ὅτι πολλοὶ προσέχουσι ταύτῃ τῇ δίκῃ τὸν νοῦν, οὐ τῶν ἡμετέρων πραγμάτων φροντίζοντες, ἀλλ’ ἡγούμενοι περὶ τῶν συνθηκῶν εἶναι τὴν κρίσιν. οὓς ὑμεῖς τὰ δίκαια γνόντες ἀδεῶς οἰκεῖν ἐν τῇ πόλει ποιήσετε· εἰ δὲ μή, πῶς οἴεσθε διακείσεσθαι τοὺς ἐν ἄστει μείναντας, ἤν ὁμοίως ἅπασιν ὀργιζόμενοι φαίνησθε τοῖς μετασχοῦσι τῆς πολιτείας;", "st": "18.42"}, {"sp": "N", "t": "τίνα δὲ γνώμην ἕξειν τοὺς μικρὸν ἁμάρτημα σφίσιν αὐτοῖς συνειδότας, ὅταν ὁρῶσι μηδὲ τοὺς κοσμίως πεπολιτευμένους τῶν δικαίων τυγχάνοντας; πόσην δὲ χρὴ προσδοκᾶν ἔσεσθαι ταραχήν, ὅταν οἱ μὲν ἐπαρθῶσι συκοφαντεῖν ὡς ὑμῶν αὐτοῖς ἤδη ταὔτ’ ἐγνωκότων, οἱ δὲ δεδίωσι τὴν παροῦσαν πολιτείαν ὡς οὐδεμιᾶς αὐτοῖς ἔτι καταφυγῆς ὑπαρχούσης;", "st": "18.43"}, {"sp": "N", "t": "ἆρ’ οὐκ ἄξιον φοβεῖσθαι μὴ συγχυθέντων τῶν ὅρκων πάλιν εἰς ταὐτὰ καταστῶμεν ἐξ ὧνπερ ἠναγκάσθημεν τὰς συνθήκας ποιήσασθαι; καὶ μὴν οὐ δεῖ γ’ ὑμᾶς παρ’ ἑτέρων μαθεῖν. ὅσον ἐστὶν ὁμόνοια ἀγαθὸν ἢ στάσις κακόν· οὕτω γὰρ ἀμφοτέρων σφόδρα πεπείρασθε, ὥστε καὶ τοὺς ἄλλους ὑμεῖς ἄριστ’ ἂν διδάξαιτε περὶ αὐτῶν.", "st": "18.44"}, {"sp": "N", "t": "ἵνα δὲ δοκῶ διὰ τοῦτο πολὺν χρόνον περὶ τὰς συνθήκας διατρίβειν, ὅτι ῥᾴδιόν ἐστι περὶ αὐτῶν πολλὰ καὶ δίκαια εἰπεῖν, τοσοῦτον ὑμῖν ἔτι διακελεύομαι μνημονεύειν, ὅταν φέρητε τὴν ψῆσον, ὅτι πρὶν μὲν ποιήσασθαι ταύτας ἐπολεμοῦμεν, οἱ μὲν τὸν κύκλον ἔχοντες, οἱ δὲ τὸν Πειραιᾶ κατειληφότες, μᾶλλον ἀλλήλους μισοῦντες ἢ τοὺς ὑπὸ τῶν προγόνων πολεμίους ἡμῖν καταλειφθέντας,", "st": "18.45"}, {"sp": "N", "t": "ἐπειδὴ δὲ τὰς πὶστεις ἀλλήλοις ἔδομεν εἰς ταὐτὸν συνελθόντες, οὕτω καλῶς καὶ κοινῶς πολιτευόμεθα, ὤσπερ οὐδεμιᾶς ἡμῖν συμφορᾶς γεγενημένης. καὶ τότε μὲν ἀμαθεστάτους καὶ δυστυχεστάτους πάντες ἡμᾶς ἐνόμιζον· νῦν δ’ εὐδαιμονέστατοι καὶ σωφρονέστατοι τῶν Ἑλλήνων δοκοῦμεν εἶναι.", "st": "18.46"}, {"sp": "N", "t": "ὥστ’ ἄξιον οὐ μόνον τηλικαύταις ζημίαις κολάζειν τοὺς παραβαίνειν τολμῶντας τὰς συνθήκας ἀλλὰ ταῖς ἐσχάταις, ὡς τῶν μεγίστων κακῶν αἰτίους ὄντας, ἄλλως τε καὶ τοὺς ὥσπερ Καλλίμαχος βεβιωκότας. ὃς δέκα μὲν ἔτη συνεχῶς ὑμῖν Λακεδαιμονίων πολεμησάντων οὐδὲ μίαν παρέσχεν αὑτὸν ἡμέραν τάξαι τοῖς στρατηγοῖς,", "st": "18.47"}, {"sp": "N", "t": "ἀλλ’ ἐκεῖνον μὲν τὸν χρόνον διετέλεσεν ἀποδιδράσκων καὶ τὴν οὐσίαν ἀποκρυπτόμενος, ἐπειδὴ δ’ οἱ τριάκοντα κατέστησαν, τηνικαῦτα κατέπλευσεν εἰς τὴν πόλιν. καὶ φησὶ μὲν εἶναι δημοτικός, τοσούτῳ δὲ μᾶλλον τῶν ἄλλων ἐπεθύμει μετασχεῖν ἐκείνης τῆς πολιτείας, ὥστ’ οὐδ’ εἰ κακῶς ἔπαθεν, ἠξίωσεν ἀπελθεῖν, ἀλλ’ ᾑρεῖτο μετὰ τῶν ἡμαρτηκότων εἰς αὑτὸν πολιορκεῖσθαι μᾶλλον ἢ μεθ’ ὑμῶν τῶν συνηδικημένων πολιτεύεσθαι.", "st": "18.48"}, {"sp": "N", "t": "καὶ μέχρι τῆς ἡμέρας ἐκείνης παρέμεινε μετέχων τῆς πολιτείας, ἐν ᾗ προσβαλεῖν ἠμέλλετε πρὸς τὸ τεῖχος· τότε δ’ ἐξῆλθεν, οὐ τὰ παρόντα μισήσας ἀλλὰ δείσας τὸν ἐπιόντα κίνδυνον, ὡς ὕστερον ἐδήλωσεν. ἐπειδὴ γὰρ Λακεδαιμονίων ἐθόντων ὁ δῆμος ἐν τῷ Πειραιεῖ κατεκλείσθη, πάλιν ἐκεῖθεν διαδρὰς ἐν Βοιωτοῖς διῃτᾶτο· ὥστ’ αὐτῷ προσήκει μετὰ τῶν αὐτομόλων ἀναγεγράφθαι πολὺ μᾶλλον ἢ τῶν φυγόντων ὀνομάζεσθαι.", "st": "18.49"}, {"sp": "N", "t": "καὶ τοιοῦτος γεγενημένος καὶ περὶ τοὺς ἐκ Πειραιέως καὶ περὶ τοὺς ἐν ἄστει μείναντας καὶ περὶ πᾶσαν τὴν πόλιν, οὐκ ἀγαπᾷ τῶν ἴσων τυγχάνειν τοῖς ἄλλοις ἀλλὰ ζητεῖ πλέον ἔχειν ὑμῶν, ὥπερ ἢ μόνος ἀδικηθεὶς ἢ βέλτιστος ὢν πολιτῶν ἢ μεγίσταις συμφοραῖς δι’ ὑμᾶς κεχρημένος ἢ πλείστων ἀγαθῶν αἴτιος τῇ πόλει γεγενημένος.", "st": "18.50"}, {"sp": "N", "t": "ἠβουλόμην δ’ ἂν ὑμᾶς ὁμοίως ἐμοὶ γιγνώσκειν αὐτόν, ἵν’ αὐτῷ μὴ τῶν ἀπολωλότων συνήχθεσθε ἀλλὰ τῶν ὑπολοίπων ἐφθονεῖτε. νῦν δὲ περὶ μὲν τῶν ἄλλων ὅσοις ἐπιβεβούλευκε, καὶ δὶκας οἵας δεδίκασται καὶ γραφὰς ἃς εἰσελήλυθε, καὶ μεθ’ ὧν συνέστηκε καὶ καθ’ ὧν τὰ ψευδῆ μεμαρτύρηκεν, οὐδ’ ἂν δὶς τοσοῦτον ὕδωρ ἱκανὸν διηγήσασθαι γένοιτο·", "st": "18.51"}, {"sp": "N", "t": "ἓν δὲ μόνον ἀκούσαντες τῶν τούτῳ πεπραγμένων ῥᾳδίως καὶ τὴν ἄλλην αὐτοῦ πονηρίαν γνώσεσθε. Κρατῖνος γὰρ ἠμφισβήτησε χωρίου τῷ τούτου κηδεστῇ. μάχης δ’ αὐτοῖς γενομένης, ὑποκρυψάμενοι θεράπαιναν ᾐτιῶντο τὸν Κρατῖνον συντρῖψαι τῆς κεφαλῆς αὐτῆς, ἐκ δὲ τραύματος φάσκοντες ἀποθανεῖν τὴν ἄνθρωπον λαγχάνουσιν αὐτῷ φόνου δίκην ἐπὶ Παλλαδίῳ.", "st": "18.52"}, {"sp": "N", "t": "πυθόμενος δ’ ὁ Κρατῖνος τὰς τούτων ἐπιβουλὰς τὸν μὲν ἄλλον χρόνον ἡσυχίαν ἦγεν, ἵνα μὴ μεταθεῖντο τὸ πρᾶγμα μηδ’ ἑτέρους λόγους ἐξευρίσκοιεν, ἀλλ’ ἐπ’ αὐτοφώρῳ ληφθεῖεν κακουργοῦντες· ἐπειδὴ δ’ ὁ κηδεστὴς μὲν ἦν ὁ τούτου κατηγορηκώς, οὗτος δὲ μεμαρτυρηκὼς ἦ μὴν τεθνάναι τὴν ἄνθρωπον,", "st": "18.53"}, {"sp": "N", "t": "ἐλθόντες εἰς τὴν οἰκίαν ἵν’ ἦν κεκρυμμένη, βίᾳ λαβόντες αὐτὴν καὶ ἀγαγόντες ἐπὶ τὸ δικαστήριον ζῶσαν ἅπασι τοῖς παροῦσιν ἐπέδειξαν. ὥσθ’ ἑπτακοσίων μὲν δικαζόντων, τεττάρων δὲ καὶ δέκα μαρτυρησάντων ἅπερ οὗτος, οὐδεμίαν ψῆφον μετέλαβε. καί μοι κάλει τούτων μάρτυρας.", "st": "18.54"}, {"sp": "N", "t": "<em>Μάρτυρες<\/em>", "st": "18.54"}, {"sp": "N", "t": "τίς οὖν ἀξίως δύναιτο κατηγορῆσαι τῶν τούτω πεπραγμένων; ἢ τίς ἂν εὑρεῖν ἔχοι παράδειγμα μεῖζον ἀδικίας καὶ συκοφαντίας καὶ πονηρίας; ἔνια μὲν γὰρ τῶν ἀδικημάτων οὐκ ἂν ὅλον τὸν τρόπον δηλώσειε τῶν ἀδικησάντων, ἐκ δὲ τῶν τοιούτων ἔγρων ἅπαντα τὸν βίον τῶν ἐξαμαρτανόντων ῥᾴδιον κατιδεῖν ἐστίν.", "st": "18.55"}, {"sp": "N", "t": "ὅστις γὰρ τοὺς ζῶντας τεθνάναι μαρτυρεῖ, τίνος ἂν ὑμῖν ἀποσχέσθαι δοκεῖ; ἣ ὅστις ἐπὶ τοῖς ἀλλοτρίοις πράγμασιν οὕτω πονηρός ἐστι, τί οὐκ ἂν ἐπὶ τοῖς αὑτοῦ τολμήσειεν; πῶς δὲ χρὴ τούτῳ πιστεύειν ὑπὲρ αὑτοῦ λέγοντι, ὃς ὑπὲρ ἑτέρων ἐπιορκῶν ἐξελέγχεται; τίς δὲ πώποτε φανερώτερον ἐπεδείχθη τὰ ψευδῆ μαρτυρῶν; τοὺς μὲν γὰρ ἄλλους ἐκ τῶν λεγομένων κρίνετε, τὴν δὲ τούτου μαρτυρίαν, ὅτι ψευδὴς ἦν, εἶδον οἱ δικάζοντες.", "st": "18.56"}, {"sp": "N", "t": "καὶ τοιαῦθ’ ἡμαρτηκὼς ἐπιχειρήσει λέγειν, ὡς ψευδόμεθα, ὅμοιον ἐργαζόμενος, ὥσπερ ἂν εἴ τῳ Φρυνώνδας πανουργίαν ὀνειδίσειεν ἢ Φιλουργὸς ὁ τὸ Γοργόνειον ὑφελόμενος τοὺς ἄλλους ἱεροσύλους ἔφασκεν εἶναι. τίνα δὲ προσήκει τῶν μὴ γενομένων παρασχέσθαι μάρτυρας μᾶλλον ἢ τοῦτον, ὃς αὐτὸς ἑτέροις τὰ ψευδῆ τολμᾷ μαρτυρεῖν;", "st": "18.57"}, {"sp": "N", "t": "ἀλλὰ γὰρ Καλλιμάχου μὲν ἐξέσται πολλάκις κατηγορεῖν, οὕτω γὰρ παρεσκεύασται πολιτεύεσθαι, περὶ δ’ ἐμαυτοῦ τὰς μὲν ἄλλας ἁπάσας παραλείψω λειτουργίας, ἧς δ’ οὐ μόνον ἄν μοι δικαίως ἔχοιτε χάριν ἀλλὰ καὶ τεκμηρίῳ χρήσαισθε περὶ τοῦ παντὸς πράγματος, ταύτης δὲ μνησθήσομαι πρὸς ὑμᾶς.", "st": "18.58"}, {"sp": "N", "t": "ὅτε γὰρ ἡ πόλις ἀπώλεσε τὰς ναῦς τὰς ἐν Ἐλλησπόντῳ καὶ τῆς δυνάμεως ἐστερήθη, τῶν μὲν πλείστων τριηράρχων τοσοῦτον διήνεγκον, ὅτι μετ’ ὀλίγων ἔσωσα τὴν ναῦν, αὐτῶν δὲ τούτων, ὅτι καταπλεύσας εἰς τὸν Πειραιᾶ μόνος οὐ κατέλυσα τὴν τριηραρχίαν,", "st": "18.59"}, {"sp": "N", "t": "ἀλλὰ τῶν ἄλλων ἀσμένως ἀπαλλαττομένων τῶν λῃτουργιῶν καὶ πρὸς τὰ παρόντ’ ἀθύμως διακειμένων, καὶ τῶν μὲν ἀνηλωμένων αὐτοῖς μεταμέλον, τὰ δὲ λοιπὰ ἀποκρυπτομένων, καὶ νομιζόντων τὰ μὲν κοινὰ διεφθάρθαι, τὰ δ’ ἴδια σκοπουμένων, οὐ τὴν αὐτὴν ἐκείνοις γνώμην ἔσχον, ἀλλὰ πείσας τὸν ἀδελφὸν συντριηραρχεῖν, παρ’ ἡμῶν αὐτῶν μισθὸν διδόντες τοῖς ναύταις κακῶς ἐποιοῦμεν τοὺς πολεμίους.", "st": "18.60"}, {"sp": "N", "t": "τὸ δὲ τελευταῖον πρὸ εἰπόντος Λυσάνδρου, εἴ τις εἰσάγοι σῖτον ὡς ὑμᾶς, θάνατον τὴν ζημίαν, οὕτω φιλοτίμως εἴχομεν πρὸς τὴν πόλιν, ὥστε τῶν ἄλλων οὐδὲ τὸν σφέτερον αὐτῶν εἰσάγειν τολμώντων ἡμεῖς τὸν ὡς ἐκείνους εἰσπλέοντα λαμβάνοντες εἰς τὸν Πειραιᾶ κατήγομεν. ἀνθ’ ὧν ὑμεῖς ἐψηφίσασθ’ ἡμᾶς στεφανῶσαι καὶ πρόσθε τῶν ἐπωνύμων ἀνειπεῖν ὡς μεγάλων ἀγαθῶν αἰτίους ὄντας.", "st": "18.61"}, {"sp": "N", "t": "καίτοι χρὴ τούτους δημοτικοὺς νομίζειν, οὐχ ὅσοι κρατοῦντος τοῦ δήμου μετασχεῖν τῶν πραγμάτων ἐπεθύμησαν, ἀλλ’ οἳ δυστυχησάσης τῆς πόλεως προκινδυνεύειν ὑμῶν ἠθέλησαν, καὶ χάριν ἔχειν, οὐκ εἴ τις αὐτὸς κακῶς πέπονθεν, ἀλλ’ εἴ τις ὑμᾶς εὖ πεποίηκε, καὶ πένητας γενομένους ἐλεεῖν οὐ τοὺς ἀπολωλεκότας τὴν οὐσίαν ἀλλὰ τοὺς εἰς ὑμᾶς ἀνηλωκότας.", "st": "18.62"}, {"sp": "N", "t": "ὧν εἷς ἐγὼ φανήσομαι γεγενημένος, ὃς πάντων ἂν εἴην δυστυχέστατος, εἰ πολλὰ τῶν ἐμαυτοῦ δεδαπανημένος εἰς τὴν πόλιν εἶτα δόξαιμι τοῖς ἀλλοτρίοις ἐπιβουλεύειν καὶ περὶ μηδενὸς ποιεῖσθαι τὰς παρ’ ὑμῖν διαβολάς, ὃς οὐ μόνον τὴν οὐσίαν ἀλλὰ καὶ τὴν ψυχὴν τὴν ἐμαυτοῦ περὶ ἐλάττονος φαίνομαι ποιούμενος τοῦ παρ’ ὑμῖν εὐδοκιμεῖν.", "st": "18.63"}, {"sp": "N", "t": "τῷ δ’ οὐκ ἂν ὑμῶν μεταμελήσειεν, εἰ καὶ μὴ παραχρῆμα ἀλλ’ ὀλίγον ὕστερον, εἰ τὸν μὲν συκοφάντην ἴδοιτε πλούσιον γεγενημένον, ἐμὲ δ’ ἐξ ὧν ὑπέλιπον λῃτουργῶν, καὶ τούτων ἐκπεπτωκότα; καὶ τὸν μὲν μηδὲ πώποτε ὑπὲρ ὑμῶν κινδυνεύσαντα μεῖζον καὶ τῶν νόμων καὶ τῶν συνθηκῶν δυνάμενον,", "st": "18.64"}, {"sp": "N", "t": "ἐμὲ δὲ τὸν οὕτω πρόθυμον περὶ τὴν πόλιν γεγενημένον μηδὲ τῶν δικαίων ἀξιούμενον τυγχάνειν; τίς δ’ οὐκ ἂν ὑμῖν ἐπιτιμήσειεν, εἰ πεισθέντες ὑπὸ τῶν Καλλιμάχου λόγων τοσαύτην πονηρίαν ἡμῶν καταγνοίητε, οὓς ἐκ τῶν ἔργων κρίναντες δι’ ἀνδραγαθίαν ἐστεφανώσατε, ὅτ’ οὐδ’ οὕτω ῥᾴδιον ἦν ὥσπερ νῦν τυχεῖν ταύτης τῆς τιμῆς;", "st": "18.65"}, {"sp": "N", "t": "τοὐναντίον δ’ ἡμῖν συμβέβηκεν ἢ τοῖς ἄλλοις· οἱ μὲν γὰρ ἄλλοι τοὺς εἰληφότας τὰς δωρεὰς ὑπομιμνῄσκουσιν, ἡμεῖς δ’ ὑμᾶς τοὺς δεδωκότας ἀξιοῦμεν μνημονεύειν, ἵν’ ὑμῖν τεκμήριον τῶν εἰρημένων ἁπάντων καὶ τῶν ἐπιτηδευμάτων τῶν ἡμετέρων γένηται.", "st": "18.66"}, {"sp": "N", "t": "δῆλον δ’ ὅτι ταύτης τῆς τιμῆς ἀξίους ἡμᾶς αὐτοὺς παρείχομεν, οὐχ ἵν’ ὀλιγαρχίας γενομένης τἀλλότρια διαρπάζοιμεν, ἀλλ’ ἵνα σωθείσης τῆς πόλεως οἵ τ’ ἄλλοι τὰ σφέτερ’ αὐτῶν ἔχοιεν, ἡμῖν τε παρὰ τῷ πλήθει τῶν πολιτῶν χάρις ὀφείλοιτο· ἣν ὑμᾶς νῦν ἀπαιτοῦμεν, οὐ πλέον ἔχειν τοῦ δικαίου ζητοῦντες, ἀλλ’ ἀποφαίνοντες μὲν ὡς οὐδὲν ἀδικοῦμεν, ἀξιοῦντες δὲ τοῖς ὅρκοις καὶ ταῖς συνθήκαις ἐμμένειν.", "st": "18.67"}, {"sp": "N", "t": "καὶ γὰρ ἄν εἴη δεινὸν εἰ τοὺς μὲν ἠδικηκότας τιμωρίας ἀφεῖναι κύριαι γένοιντο, ἐφ’ ἡμῖν δὲ τοῖς εὖ πεποιηκόσιν ἄκυροι κατασταθεῖεν. ἄξιον δὲ τὴν παροῦσαν τύχην διαφυλάττειν, ἐνθυμουμένους, ὅτι ἑτέρας μὲν πόλεις ἐποίησαν ἤδη συνθῆκαι μᾶλλον στασιάσαι, τὴν δ’ ἡμετέραν μᾶλλον ὁμονοεῖν. ὧν χρὴ μεμνημένους ἅμα τά τε δίκαια καὶ τὰ συμφέροντα ψηφίσασθαι.", "st": "18.68"}, {"sp": "HDR", "t": "Αἰγινητικός", "st": "19"}, {"sp": "N", "t": "ἐνόμιζον μέν, ὦ ἄνδρες Αἰγινῆται, οὕτω καλῶς βεβουλεῦσθαι περὶ τῶν αὑτοῦ Θρασύλοχον ὥστε μηδέν’ ἄν ποτ’ ἐλθεῖν ἐναντία πράξοντα ταῖς διαθήκαις αἷς ἐκεῖνος κατέλιπεν· ἐπειδὴ δὲ τοῖς ἀντιδίκοις τοιαύτη γνώμη παρέστηκεν ὥστε καὶ πρὸς οὕτως ἐχούσας αὐτὰς ἀμφισβητεῖν, ἀναγκαίως ἔχει παρ’ ὑμῶν πειρᾶσθαι τῶν δικαίων τυγχάνειν.", "st": "19.1"}, {"sp": "N", "t": "τοὐναντίον δὲ πέπονθα τοῖς πλείστοις τῶν ἀνθρώπων. τοὺς μὲν γὰρ ἄλλους ὁρῶ χαλεπῶς φέροντας, ὅταν ἀδίκως περί τινος κινδυνεύωσιν, ἐγὼ δ’ ὀλίγου δέω χάριν ἔχειν τούτοις, ὅτι μ’ εἰς τουτονὶ τὸν ἀγῶνα κατέστησαν. ἀκρίτου μὲν γὰρ ὄντος τοῦ πράγματος οὐκ ἂν ἠπίστασθ’ ὁποῖός τις γεγενημένος περὶ τὸν τετελευτηκότα κληρονόμος εἰμὶ τῶν ἐκείνου· πυθόμενοι δὲ τὰ πραχθέντα πάντες εἴσεσθ’ ὅτι δικαίως ἂν καὶ μείζονος ἢ τοσαύτης δωρεᾶς ἠξιώθην.", "st": "19.2"}, {"sp": "N", "t": "χρῆν μέντοι καὶ τὴν ἀμφισβητοῦσαν τῶν χρημάτων μὴ παρ’ ὑμῶν πειρᾶσθαι λαμβάνειν τὴν οὐσίαν, ἣν Θρασύλοχος κατέλιπεν, ἀλλὰ περὶ ἐκεῖνον χρηστὴν οὖσαν οὕτως ἀξιοῦν αὐτῆς ἐπιδικάζεσθαι. νῦν δ’ αὐτῇ τοσούτου δεῖ μεταμέλειν ὧν εἰς ζῶντ’ ἐξήμαρτεν, ὥστε καὶ τεθνεῶτος αὐτοῦ πειρᾶται τήν τε διαθήκην ἄκυρον ἅμα καὶ τὸν οἶκον ἔρημον ποιῆσαι.", "st": "19.3"}, {"sp": "N", "t": "θαυμάζω δὲ καὶ τῶν πραττόντων ὑπὲρ αὐτῆς, εἰ διὰ τοῦτ’ οἴονται καλὸν εἶναι τὸν κίνδυνον, ὅτι μὴ κατορθώσαντες οὐδὲν μέλλουσιν ἀποτείσειν. ἐγὼ μὲν γὰρ ἡγοῦμαι μεγάλην εἶναι καὶ ταύτην ζημίαν, ἂν ἐξελεγχθέντες ὡς ἀδίκως ἀμφισβητοῦσιν, ἔπειθ’ ὑμῖν δόξωσι χείρους εἶναι. τὴν μὲν οὖν τούτων κακίαν ἐξ αὐτῶν τῶν ἔργων γνώσεσθ’, ἐπειδὰν διὰ τέλους ἀκούσητε τῶν πεπραγμένων· ὅθεν δ’, οἶμαι, τάχιστ’ ἂν ὑμᾶς μαθεῖν περὶ ὧν ἀμφισβητοῦμεν, ἐντεῦθεν ἄρξομαι διηγεῖσθαι.", "st": "19.4"}, {"sp": "N", "t": "Θράσυλλος γὰρ ὁ πατὴρ τοῦ καταλιπόντος τὴν διαθήκην παρὰ μὲν τῶν προγόνων οὐδεμίαν οὐσίαν παρέλαβεν, ξένος δὲ Πολεμαινέτῳ τῷ μάντει γενόμενος οὕτως οἰκείως διετέθη πρὸς αὐτὸν ὥστ’ ἀποθνῄσκων ἐκεῖνος τάς τε βίβλους τὰς περὶ τῆς μαντικῆς αὐτῷ κατέλιπε καὶ τῆς οὐσίας μέρος τι τῆς νῦν οὔσης ἔδωκεν.", "st": "19.5"}, {"sp": "N", "t": "λαβὼν δὲ Θράσυλλος ταύτας ἀφορμὰς ἐχρῆτο τῇ τέχνῃ· πλάνης δὲ γενόμενος καὶ διαιτηθεὶς ἐν πολλαῖς πόλεσιν ἄλλαις τε γυναιξὶ συνεγένετο, ὧν ἔνιαι καὶ παιδάρι’ ἀπέδειξαν ἃ ’κεῖνος οὐδὲ πώποτε γνήσι’ ἐνόμισε, καὶ δὴ καὶ τὴν ταύτης μητέρ’ ἐν τούτοις τοῖς χρόνοις ἔλαβεν.", "st": "19.6"}, {"sp": "N", "t": "ἐπειδὴ δ’ οὐσίαν τε πολλὴν ἐκτήσατο καὶ τὴν πατρίδ’ ἐπόθεσεν, ἐκείνης μὲν καὶ τῶν ἄλλων ἀπηλλάγη, καταπλεύσας δ’ εἰς Σίφνον ἔγημεν ἀδελφὴν τοῦ πατρὸς τοὐμοῦ, πλούτῳ μὲν αὐτὸς πρῶτος ὢν τῶν πολιτῶν, γένει δὲ καὶ τοῖς ἄλλοις ἀξιώμασιν εἰδὼς τὴν ἡμετέραν οἰκίαν προέχουσαν.", "st": "19.7"}, {"sp": "N", "t": "οὕτω δὲ σφόδρ’ ἠγάπησε τὴν τοῦ πατρὸς φιλίαν, ὥστ’ ἀποθανούσης ἐκείνης ἄπαιδος αὖθις ἠγάγετ’ ἀνεψιὰν τοῦ πατρός, οὐ βουλόμενος διαλύσασθαι τὴν πρὸς ἡμᾶς οἰκειότητα. οὐ πολὺν δὲ χρόνον συνοικήσας ταῖς αὐταῖς τύχαις ἐχρήσατο καὶ περὶ ταύτην, αἷσπερ καὶ περὶ τὴν προτέραν.", "st": "19.8"}, {"sp": "N", "t": "μετὰ δὲ ταῦτ’ ἔγημεν ἐκ Σερίφου παρ’ ἀνθρώπων πολὺ πλείονος ἀξίων ἢ κατὰ τὴν αὑτῶν πόλιν, ἐξ ἧς ἐγένετο Σώπολις καὶ Θρασύλοχος καὶ θυγάτηρ ἡ νῦν ἐμοὶ συνοικοῦσα. Θράσυλλος μὲν οὖν τούτους μόνους παῖδας γνησίους καταλιπὼν καὶ κληρονόμους τῶν αὑτοῦ καταστήσας τὸν βίον ἐτελεύτησεν.", "st": "19.9"}, {"sp": "N", "t": "ἐγὼ δὲ καὶ Θρασύλοχος τοσαύτην φιλίαν παρὰ τῶν πατέρων παραλαβόντες ὅσην ὀλίγῳ πρότερον διηγησάμην, ἔτι μείζω τῆς ὑπαρχούσης αὐτὴν ἐποιήσαμεν. ἕως μὲν γὰρ παῖδες ἦμεν, περὶ πλείονος ἡμᾶς αὐτοὺς ἡγούμεθα ἢ τοὺς ἀδελφούς, καὶ οὔτε θυσίαν οὔτε θεωρίαν οὔτ’ ἄλλην ἑορτὴν οὐδεμίαν χωρὶς ἀλλήλων ἤγομεν· ἐπειδὴ δ’ ἄνδρες ἐγενόμεθα, οὐδὲν πώποτ’ ἐναντίον ἡμῖν αὐτοῖς ἐπράξαμεν, ἀλλὰ καὶ τῶν ἰδίων ἐκοινωνοῦμεν καὶ πρὸς τὰ τῆς πόλεως ὁμοίως διεκείμεθα καὶ φίλοις καὶ ξένοις τοῖς αὐτοῖς ἐχρώμεθα.", "st": "19.10"}, {"sp": "N", "t": "καὶ τί δεῖ λέγειν τὰς οἴκοι χρήσεις; ἀλλ’ οὐδὲ φυγόντες ἀπ’ ἀλλήλων ἠξιώσαμεν γενέσθαι. τὸ δὲ τελευταῖον φθόῃ σχόμενον αὐτὸν καὶ πολὺν χρόνον ἀσθενήσαντα, καὶ τοῦ μὲν ἀδελφοῦ Σωπόλιδος αὐτῷ πρότερον τετελευτηκότος, τῆς δὲ μητρὸς καὶ τῆς ἀδελφῆς οὔπω παρουσῶν, μετὰ τοσαύτης ἐρημίας γενόμενον οὕτως ἐπιπόνως καὶ καλῶς αὐτὸν ἐθεράπευσα, ὥστ’ ἐκεῖνον μὴ νομίζειν ἀξίαν μοι δύνασθαι χάριν ἀποδοῦναι τῶν πεπραγμένων.", "st": "19.11"}, {"sp": "N", "t": "ὅμως δ’ οὐδὲν ἐνέλιπεν, ἀλλ’ ἐπειδὴ πονηρῶς διέκειτο καὶ οὐδεμίαν ἐλπίδ’ εἶχε τοῦ βίου, παρακαλέσας μάρτυρας υἱόν μ’ ἐποιήσατο καὶ τὴν ἀδελφὴν τὴν αὑτοῦ καὶ τὴν οὐσίαν ἔδωκεν. καί μοι λαβὲ τὰς διαθήκας.", "st": "19.12"}, {"sp": "N", "t": "<em>Διαθῆκαι<\/em>", "st": "19.12"}, {"sp": "N", "t": "ἀνάγνωθι δή μοι καὶ τὸν νόμον τὸν Αἰγινητῶν· κατὰ γὰρ τοῦτον ἔδει ποιεῖσθαι τὰς διαθήκας· ἐνθάδε γὰρ μετῳκοῦμεν.", "st": "19.12"}, {"sp": "N", "t": "<em>Νόμος<\/em>", "st": "19.12"}, {"sp": "N", "t": "κατὰ τουτονὶ τὸν νόμον, ὦ ἄνδρες Αἰγινῆται, υἱόν μ’ ἐποιήσατο Θρασύλοχος, πολίτην μὲν αὑτοῦ καὶ φίλον ὄντα, γεγονότα δ’ οὐδενὸς χεῖρον Σιφνίων, πεπαιδευμένον δ’ ὁμοίως αὑτῷ καὶ τεθραμμένον. ὥστ’ οὐκ οἶδ’ ὅπως ἂν μᾶλλον κατὰ τὸν νόμον ἔπραξεν, ὃς τοὺς ὁμοίους κελεύει παῖδας εἰσποιεῖσθαι. λαβὲ δή μοι καὶ τὸν Κείων νόμον, καθ’ ὃν ἡμεῖς ἐπολιτευόμεθα.", "st": "19.13"}, {"sp": "N", "t": "<em>Νόμος<\/em>", "st": "19.13"}, {"sp": "N", "t": "εἰ μὲν τοίνυν, ὦ ἄνδρες Αἰγινῆται, τούτοις μὲν τοῖς νόμοις ἠναντιοῦντο, τὸν δὲ παρ’ αὑτοῖς κείμενον σύνδικον εἶχον, ἧττον ἄξιον ἦν θαυμάζειν αὐτῶν· νῦν δὲ κἀκεῖνος ὁμοίως τοῖς ἀνεγνωσμένοις κεῖται. καί μοι λαβὲ τὸ βιβλίον.", "st": "19.14"}, {"sp": "N", "t": "<em>Νόμος<\/em>", "st": "19.14"}, {"sp": "N", "t": "τί οὖν ὑπόλοιπόν ἐστιν αὐτοῖς, ὅπου τὰς μὲν διαθήκας αὐτοὶ προσομολογοῦσι Θρασύλοχον καταλιπεῖν, τῶν δὲ νόμων τούτοις μὲν οὐδείς, ἐμοὶ δὲ πάντες βοηθοῦσι, πρῶτον μὲν ὁ παρ’ ὑμῖν τοῖς μέλλουσι διαγνώσεσθαι περὶ τοῦ πράγματος, ἔπειθ’ ὁ Σιφνίων, ὅθεν ἦν ὁ τὴν διαθήκην καταλιπών, ἔτι δ’ ὁ παρ’ αὐτοῖς τοῖς ἀμφισβητοῦσι κείμενος; καίτοι τίνος ἂν ὑμῖν ἀποσχέσθαι δοκοῦσιν, οἵτινες ζητοῦσι πείθειν ὑμᾶς, ὡς χρὴ τὰς διαθήκας ἀκύρους ποιῆσαι τῶν μὲν νόμων οὕτως ἐχόντων, ὑμῶν δὲ κατ’ αὐτοὺς ὀμωμοκότων ψηφιεῖσθαι;", "st": "19.15"}, {"sp": "N", "t": "περὶ μὲν οὖν αὐτοῦ τοῦ πράγματος ἱκανῶς ἀποδεδεῖχθαι νομίζω· ἵνα δὲ μηδεὶς οἴηται μήτ’ ἐμὲ διὰ μικρὰς προφάσεις ἔχειν τὸν κλῆρον μήτε ταύτην ἐπιεικῆ γεγενημένην περὶ Θρασύλοχον ἀποστερεῖσθαι τῶν χρημάτων, βούλομαι καὶ περὶ τούτων εἰπεῖν. αἰσχυνθείην γὰρ ἂν ὑπὲρ τοῦ τετελευτηκότος, εἰ μὴ πάντες πεισθείητε, μὴ μόνον ὡς κατὰ τοὺς νόμους ἀλλ’ ὡς καὶ δικαίως ταῦτ’ ἔπραξεν. ῥᾳδίας δ’ ἡγοῦμαι τὰς ἀποδείξεις εἶναι.", "st": "19.16"}, {"sp": "N", "t": "τοσοῦτον γὰρ διηνέγκαμεν ὥσθ’ αὕτη μὲν ἡ κατὰ γένος ἀμφισβητοῦσα πάντα τὸν χρόνον διετέλεσε καὶ πρὸς αὐτὸν ἐκεῖνον καὶ πρὸς Σώπολιν καὶ πρὸς τὴν μητέρ’ αὐτῶν διαφερομένη καὶ δυσμενῶς ἔχουσα, ἐγὼ δ’ οὐ μόνον περὶ Θρασύλοχον καὶ τὸν ἀδελφὸν ἀλλὰ καὶ περὶ αὐτὴν τὴν οὐσίαν, ἧς ἀμφισβητοῦμεν, φανήσομαι πλείστου τῶν φίλων ἄξιος γεγενημένος.", "st": "19.17"}, {"sp": "N", "t": "καὶ περὶ μὲν τῶν παλαιῶν πολὺ ἂν ἔργον εἴη λέγειν· ὅτε δὲ Πασῖνος Πάρον κατέλαβεν, ἔτυχεν αὐτοῖς ὑπεκκείμενα τὰ πλεῖστα τῆς οὐσίας παρὰ τοῖς ξένοις τοῖς ἐμοῖς· ᾠόμεθα γὰρ μάλιστα ταύτην τὴν νῆσον ἀσφαλῶς ἔχειν. ἀπορούντων δ’ ἐκείνων καὶ νομιζόντων αὔτ’ ἀπολωλέναι, πλεύσας ἐγὼ τῆς νυκτὸς ἐξεκόμισ’ αὐτοῖς τὰ χρήματα, κινδυνεύσας περὶ τοῦ σώματος· ἐφρουρεῖτο μὲν γὰρ ἡ χώρα,", "st": "19.18"}, {"sp": "N", "t": "συγκατειληφότες δ’ ἦσάν τινες τῶν ἡμετέρων φυγάδων τὴν πόλιν, οἳ μιᾶς ἡμέρας ἀπέκτειναν αὐτόχειρες γενόμενοι τόν τε πατέρα τὸν ἐμὸν καὶ τὸν θεῖον καὶ τὸν κηδεστὴν καὶ πρὸς τούτοις ἀνεψιοὺς τρεῖς. ἀλλ’ ὅμως οὐδέν με τούτων ἀπέτρεψεν, ἀλλ’ ᾠχόμην πλέων, ἡγούμενος ὁμοίως με δεῖν ὑπὲρ ἐκείνων κινδυνεύειν ὥσπερ ὑπὲρ ἐμαυτοῦ.", "st": "19.19"}, {"sp": "N", "t": "μετὰ δὲ ταῦτα φυγῆς ἡμῖν γενομένης ἐκ τῆς πόλεως μετὰ τοιούτου θορύβου καὶ δέους ὥστ’ ἐνίους καὶ τῶν σφετέρων αὐτῶν ἀμελεῖν, οὐδ’ ἐν τούτοις τοῖς κακοῖς ἠγάπησα, εἰ τοὺς οἰκείους τοὺς ἐμαυτοῦ διασῶσαι δυνηθείην, ἀλλ’ εἰδὼς Σώπολιν μὲν ἀποδημοῦντα, αὐτὸν δ’ ἐκεῖνον ἀρρώστως διακείμενον, συνεξεκόμισ’ αὐτῷ καὶ τὴν μητέρα καὶ τὴν ἀδελφὴν καὶ τὴν οὐσίαν ἅπασαν. καίτοι τίνα δικαιότερον αὐτὴν ἔχειν προσήκει ἢ τὸν τότε μὲν συνδιασώσαντα, νῦν δὲ παρὰ τῶν κυρίων εἰληφότα;", "st": "19.20"}, {"sp": "N", "t": "τὰ μὲν τοίνυν εἰρημέν’ ἐστὶν ἐν οἷς ἐκινδύνευσα μὲν, φλαῦρον δ’ οὐδὲν ἀπέλαυσα· ἔχω δὲ καὶ τοιαῦτ’ εἰπεῖν, ἐξ ὧν ἐκείνῳ χαριζόμενος αὐτὸς ταῖς μεγίσταις συμφοραῖς περιέπεσον. ἐπειδὴ γὰρ ἤλθομεν εἰς Μῆλον, αἰσθόμενος, ὅτι μέλλοιμεν αὐτοῦ καταμένειν, μένειν, ἐδεῖτό μου συμπλεῖν εἰς Τροιζῆνα καὶ μηδαμῶς αὐτὸν ἀπολιπεῖν, λέγων τὴν ἀρρωστίαν τοῦ σώματος καὶ τὸ πλῆθος τῶν ἐχθρῶν, καὶ ὅτι χωρὶς ἐμοῦ γενόμενος οὐδὲν ἕξοι χρῆσθαι τοῖς αὑτοῦ πράγμασιν.", "st": "19.21"}, {"sp": "N", "t": "φοβουμένης δὲ τῆς μητρός, ὅτι τὸ χωρίον ἐπυνθάνετο νοσῶδες εἶναι, καὶ τῶν ξένων συμβουλευόντων αὐτοῦ μένειν, ὅμως ἔδοξεν ἡμῖν ἐκείνῳ χαριστέον εἶναι. καὶ μετὰ ταῦτ’ οὐκ ἔφθημεν εἰς Τροιζῆν’ ἐλθόντες καὶ τοιαύταις νόσοις ἐλήφθημεν, ἐξ ὧν αὐτὸς μὲν παρὰ μικρὸν ἦλθον ἀποθανεῖν, ἀδελφὴν δὲ κόρην τετρακαιδεκέτιν γεγονυῖαν ἐντὸς τριάκονθ’ ἡμερῶν κατέθαψα, τὴν δὲ μητέρ’ οὐδὲ πένθ’ ἡμέραις ἐκείνης ὕστερον. καίτοι τίν’ οἴεσθέ με γνώμην ἔχειν τοσαύτης μοι μεταβολῆς τοῦ βίου γεγενημένης;", "st": "19.22"}, {"sp": "N", "t": "ὃς τὸν μὲν ἄλλον χρόνον ἀπαθὴς ἦν κακῶν, νεωστὶ δ’ ἐπειρώμην φυγῆς καὶ τοῦ παρ’ ἑτέροις μὲν μετοικεῖν, στέρεσθαι δὲ τῶν ἐμαυτοῦ, πρὸς δὲ τούτοις ὁρῶν τὴν μητέρα τὴν αὑτοῦ καὶ τὴν ἀδελφὴν ἐκ μὲν τῆς πατρίδος ἐκπεπτωκυίας, ἐπὶ δὲ ξένης καὶ παρ’ ἀλλοτρίοις τὸν βίον τελευτώσας. ὥστ’ οὐδεὶς ἄν μοι δικαίως φθονήσειεν, εἴ τι τῶν Θρασυλόχου πραγμάτων ἀγαθὸν ἀπολέλαυκα· καὶ γὰρ ἵνα χαρισαίμην ἐκείνῳ, κατοικισάμενος ἐν Τροιζῆνι τοιαύταις ἐχρησάμην συμφοραῖς, ὧν οὐδέποτ’ ἂν ἐπιλαθέσθαι δυνηθείην.", "st": "19.23"}, {"sp": "N", "t": "καὶ μὴν οὐδὲ τοῦθ’ ἕξουσιν εἰπεῖν ὡς εὖ μὲν πράττοντος Θρασυλόχου πάντα ταῦθ’ ὑπέμενον, δυστυχήσαντα δ’ αὐτὸν ἀπέλιπον· ἐν αὐτοῖς γὰρ τούτοις ἔτι σαφέστερον καὶ μᾶλλον ἐνεπεδειξάμην τὴν εὔνοιαν ἣν εἶχον εἰς ἐκεῖνον. ἐπειδὴ γὰρ εἰς Αἴγιναν κατοικισάμενος ἠσθένησε ταύτην τὴν νόσον ἐξ ἧσπερ ἀπέθανεν, οὕτως αὐτὸν ἐθεράπευσα ὡς οὐκ οἶδ’ ὅστις πώποθ’ ἕτερος ἕτερον, τὸν μὲν πλεῖστον τοῦ χρόνου πονηρῶς μὲν ἔχοντα, περιιέναι δ’ ἔτι δυνάμενον, ἓξ μῆνας δὲ συνεχῶς ἐν τῇ κλίνῃ κείμενον.", "st": "19.24"}, {"sp": "N", "t": "καὶ τούτων τῶν ταλαιπωριῶν οὐδεὶς τῶν συγγενῶν μετασχεῖν ἠξίωσεν, ἀλλ’ οὐδ’ ἐπισκεψόμενος ἀφίκετο πλὴν τῆς μητρὸς καὶ τῆς ἀδελφῆς, αἳ πλέον θάτερον ἐποίησαν· ἀσθενοῦσαι γὰρ ἦλθον ἐκ Τροιζῆνος, ὥστ’ αὐταὶ θεραπείας ἐδέοντο. ἀλλ’ ὅμως ἐγώ, τοιούτων τῶν ἄλλων περὶ αὐτὸν γεγενημένων, οὐκ ἀπεῖπον οὐδ’ ἀπέστην ἀλλ’ ἐνοσήλευον αὐτὸν μετὰ παιδὸς ἑνός·", "st": "19.25"}, {"sp": "N", "t": "οὐδὲ γὰρ τῶν οἰκετῶν οὐδεὶς ὑπέμεινεν. καὶ γὰρ φύσει χαλεπὸς ὢν ἔτι δυσκολώτερον διὰ τὴν νόσον διέκειτο, ὥστ’ οὐκ ἐκείνων ἄξιον θαυμάζειν, εἰ μὴ παρέμενον, ἀλλὰ πολὺ μᾶλλον, ὅπως ἐγὼ τοιαύτην νόσον θεραπεύων ἀνταρκεῖν ἠδυνάμην· ὃς ἔμπυος μὲν ἦν πολὺν χρόνον, ἐκ δὲ τῆς κλίνης οὐκ ἠδύνατο κινεῖσθαι,", "st": "19.26"}, {"sp": "N", "t": "τοιαῦτα δ’ ἔπασχεν ὥσθ’ ἡμᾶς μηδεμίαν ἡμέραν ἀδακρύτους διάγειν, ἀλλὰ θρηνοῦντες διετελοῦμεν καὶ τοὺς πόνους τοὺς ἀλλήλων καὶ τὴν φυγὴν καὶ τὴν ἐρημίαν τὴν ἡμετέραν αὐτῶν. καὶ ταῦτ’ οὐδένα χρόνον διέλειπεν· οὐδὲ γὰρ ἀπελθεῖν οἷόν τ’ ἦν ἢ δοκεῖν ἀμελεῖν, ὅ μοι πολὺ δεινότερον ἦν τῶν κακῶν τῶν παρόντων.", "st": "19.27"}, {"sp": "N", "t": "ἠβουλόμην δ’ ἂν ὑμῖν οἷός τ’ εἶναι ποιῆσαι φανερὸν οἷος περὶ αὐτὸν ἐγενόμην· οἶμαι γὰρ οὐδ’ ἂν τὴν φωνὴν ὑμᾶς ἀνασχέσθαι τῶν ἀντιδίκων. νῦν δὲ τὰ χαλεπώτατα τῶν ἐν τῇ θεραπείᾳ καὶ δυσχερέστατα καὶ πόνους ἀηδεστάτους ἔχοντα καὶ πλείστης ἐπιμελείας δεηθέντ’ οὐκ εὐδιήγητ’ ἐστίν. ἀλλ’ ὑμεῖς αὐτοὶ σκοπεῖτε, μετὰ πόσων ἄν τις ἀγρυπνιῶν καὶ ταλαιπωριῶν τοιοῦτον νόσημα τοσοῦτον χρόνον θεραπεύσειεν.", "st": "19.28"}, {"sp": "N", "t": "ἐγὼ μὲν γὰρ οὕτω κακῶς διετέθην, ὥσθ’ ὅσοι περ εἰσῆλθον τῶν φίλων, ἔφασαν δεδιέναι, μὴ κἀγὼ προσαπόλωμαι, καὶ συνεβούλευόν μοι φυλάττεσθαι, λέγοντες ὡς οἱ πλεῖστοι τῶν θεραπευσάντων ταύτην τὴν νόσον αὐτοὶ προσδιεφθάρησαν. πρὸς οὓς ἐγὼ τοιαῦτ’ ἀπεκρινάμην ὅτι πολὺ ἂν θᾶττον ἑλοίμην ἀποθανεῖν ἢ ’κεῖνον περιιδεῖν δι’ ἔνδειαν τοῦ θεραπεύσοντος πρὸ μοίρας τελευτήσαντα.", "st": "19.29"}, {"sp": "N", "t": "καὶ τοιούτῳ μοι γεγενημένῳ τετόλμηκεν ἀμφισβητεῖν τῶν χρημάτων ἡ μηδ’ ἐπισκέψασθαι πώποτ’ αὐτὸν ἀξιώσασα, τοσοῦτον μὲν χρόνον ἀσθενήσαντα, πυνθανομένη δὲ καθ’ ἑκάστην τὴν ἡμέραν, ὡς διέκειτο, ῥᾳδίας δ’ οὔσης αὐτῇ τῆς πορείας. εἶτα νῦν αὐτὸν ἀδελφίζειν ἐπιχειρήσουσιν, ὥσπερ οὐχ ὅσῳ περ ἂν οἰκειότερον προσείπωσι τὸν τεθνεῶτα, τοσούτῳ δόξουσαν αὐτὴν μείζω καὶ δεινότερ’ ἐξαμαρτεῖν·", "st": "19.30"}, {"sp": "N", "t": "ἥτις οὐδ’ ἐπειδὴ τελευτᾶν ἤμελλε τὸν βίον, ὁρῶσα τοὺς πολίτας τοὺς ἡμετέρους, ὅσοι περ ἦσαν ἐν Τροιζῆνι, διαπλέοντας εἰς Αἴγιναν, ἵν’ αὐτὸν συγκαταθάψειαν, οὐδ’ εἰς τοῦτον τὸν καιρὸν ἀπήντησεν, ἀλλ’ οὕτως ὠμῶς καὶ σχετλίως εἶχεν, ὥστ’ ἐπὶ μὲν τὸ κῆδος οὐκ ἠξίωσεν ἀφικέσθαι, τῶν δὲ καταλειφθέντων οὐδὲ δέχ’ ἡμέρας διαλιποῦσ’ ἦλθεν ἀμφισβητοῦσα, ὥσπερ τῶν χρημάτων ἀλλ’ οὐκ ἐκείνου συγγενὴς οὖσα.", "st": "19.31"}, {"sp": "N", "t": "καὶ εἰ μὲν ὁμολογήσει τοσαύτην ἔχθραν ὑπάρχειν αὑτῇ πρὸς ἐκεῖνον ὥστ’ εἰκότως ταῦτα ποιεῖν, οὐκ ἂν κακῶς εἴη βεβουλευμένος, εἰ τοῖς φίλοις ἠβουλήθη μᾶλλον ἢ ταύτῃ τὴν οὐσίαν καταλιπεῖν· εἰ δὲ μηδεμιᾶς διαφορᾶς οὔσης οὕτως ἀμελὴς καὶ κακὴ περὶ αὐτὸν ἐγένετο, πολὺ ἂν δήπου δικαιότερον στερηθείη τῶν αὑτῆς ἢ τῶν ἐκείνου κληρονόμος γίγνοιτο.", "st": "19.32"}, {"sp": "N", "t": "ἐνθυμεῖσθε δ’ ὅτι τὸ μὲν ταύτης μέρος οὔτ’ ἐν τῇ νόσῳ θεραπείας ἔτυχεν οὔτ’ ἀποθανὼν τῶν νομιζομένων ἠξιώθη, δι’ ἐμὲ δ’ ἀμφότερα ταῦτ’ αὐτῷ γεγένηται. καίτοι δίκαιόν ἐστιν ὑμᾶς τὴν ψῆφον φέρειν, οὐκ εἴ τινες γένει μέν φασι προσήκειν, ἐν δὲ τοῖς ἔργοις ὅμοιοι τοῖς ἐχθροῖς γεγόνασιν, ἀλλὰ πολὺ μᾶλλον ὅσοι μηδὲν ὄνομα συγγενείας ἔχοντες οἰκειοτέρους σφᾶς αὐτοὺς ἐν ταῖς συμφοραῖς τῶν ἀναγκαίων παρέσχον.", "st": "19.33"}, {"sp": "N", "t": "λέγουσι δ’ ὡς τὰς μὲν διαθήκας οὐκ ἀπιστοῦσι Θρασύλοχον καταλιπεῖν, οὐ μέντοι καλῶς οὐδ’ ὀρθῶς φασὶν αὐτὰς ἔχειν. καίτοι, ὦ ἄνδρες Αἰγινῆται, πῶς ἄν τις ἄμεινον ἢ μᾶλλον συμφερόντως περὶ τῶν αὑτοῦ πραγμάτων ἐβουλεύσατο; ὃς οὔτ’ ἔρημον τὸν οἶκον κατέλιπε τοῖς τε φίλοις χάριν ἀπέδωκεν, ἔτι δὲ τὴν μητέρα καὶ τὴν ἀδελφὴν οὐ μόνον τῶν αὑτοῦ κυρίας ἀλλὰ καὶ τῶν ἐμῶν κατέστησε, τὴν μὲν ἐμοὶ συνοικίσας, τῇ δ’ υἱόν μ’ εἰσποιήσας;", "st": "19.34"}, {"sp": "N", "t": "ἆρ’ ἂν ἐκείνως ἄμεινον ἔπραξεν, εἰ μήτε τῆς μητρὸς τὸν ἐπιμελησόμενον κατέστησε, μήτ’ ἐμοῦ μηδεμίαν μνείαν ἐποιήσατο, τὴν δ’ ἀδελφὴν ἐπὶ τῇ τύχῃ κατέλιπε, καὶ τὸν οἶκον ἀνώνυμον τὸν αὑτοῦ περιεῖδε γενόμενον;", "st": "19.35"}, {"sp": "N", "t": "ἀλλὰ γὰρ ἴσως ἀνάξιος ἦν υἱὸς εἰσποιηθῆναι Θρασυλόχῳ καὶ λαβεῖν αὐτοῦ τὴν ἀδελφήν. ἀλλὰ πάντες ἂν μαρτυρήσειαν Σίφνιοι τοὺς προγόνους τοὺς ἐμοὺς καὶ γένει καὶ πλούτῳ καὶ δόξῃ καὶ τοῖς ἄλλοις ἅπασι πρώτους εἶναι τῶν πολιτῶν. τίνες γὰρ ἢ μειζόνων ἀρχῶν ἠξιώθησαν ἢ πλείω χρήματ’ εἰσήνεγκαν ἢ κάλλιον ἐχορήγησαν ἢ μεγαλοπρεπέστερον τὰς ἄλλας λῃτουργίας ἐλῃτούργησαν; ἐκ ποίας δ’ οἰκίας τῶν ἐν Σίφνῳ πλείους βασιλεῖς γεγόνασιν;", "st": "19.36"}, {"sp": "N", "t": "ὥστε Θρασύλοχός τ’ εἰ καὶ μηδὲ πώποτ’ αὐτῷ διελέχθην, εἰκότως ἂν ἠβουλήθη μοι διὰ ταῦτα δοῦναι τὴν ἀδελφήν, ἐγώ τ’ εἰ καὶ μηδέν μοι τούτων ὑπῆρχεν, ἀλλὰ φαυλότατος ἦν τῶν πολιτῶν, δικαίως ἂν παρ’ αὐτοῦ διὰ τὰς εὐεργεσίας τὰς εἰς ἐκεῖνον τῶν μεγίστων ἠξιώθην.", "st": "19.37"}, {"sp": "N", "t": "οἶμαι τοίνυν αὐτὸν καὶ Σωπόλιδι τἀδελφῷ μάλιστα κεχαρίσθαι ταῦτα διαθέμενον. καὶ γὰρ ἐκεῖνος ταύτην μὲν ἐμίσει καὶ κακόνουν τοῖς αὑτοῦ πράγμασιν ἡγεῖτο, ἐμὲ δὲ περὶ πλείστου τῶν αὑτοῦ φίλων ἐποιεῖτο. ἐδήλωσε δ’ ἐν ἄλλοις τε πολλοῖς καὶ ὅτ’ ἔδοξε τοῖς συμφυγάσιν ἐπιχειρεῖν τῇ πόλει μετὰ τῶν ἐπικούρων. αἱρεθεὶς γὰρ ἄρχειν αὐτοκράτωρ ἐμὲ καὶ γραμματέα προσείλετο καὶ τῶν χρημάτων ταμίαν ἁπάντων κατέστησε, καὶ ὅτ’ ἠμέλλομεν κινδυνεύειν, αὐτὸς αὑτῷ με παρετάξατο.", "st": "19.38"}, {"sp": "N", "t": "καὶ σκέψασθ’ ὡς σφόδρ’ αὐτῷ συνήνεγκεν· δυστυχησάντων γὰρ ἡμῶν ἐν τῇ προσβολῇ τῇ πρὸς τὴν πόλιν καὶ τῆς ἀναχωρήσεως οὐχ οἵας ἠβουλόμεθα γενομένης, τετρωμένον αὐτὸν καὶ βαδίζειν οὐ δυνάμενον ἀλλ’ ὀλιγοψυχοῦντα ἀπεκόμισ’ ἐπὶ τὸ πλοῖον μετὰ τοῦ θεράποντος τοὐμαυτοῦ, φέρων ἐπὶ τῶν ὤμων, ὥστ’ ἐκεῖνον πολλάκις καὶ πρὸς πολλοὺς εἰπεῖν ὅτι μόνος ἀνθρώπων αἴτιος εἴην αὑτῷ τῆς σωτηρίας.", "st": "19.39"}, {"sp": "N", "t": "καίτοι τίς ἂν μείζων ταύτης εὐεργεσία γένοιτο; ἐπειδὴ τοίνυν εἰς Λυκίαν ἐκπλεύσας ἀπέθανεν, αὕτη μὲν οὐ πολλαῖς ἡμέραις ὕστερον μετὰ τὴν ἀγγελίαν ἔθυε καὶ ἑώρταζε καὶ οὐδὲ τὸν ἀδελφὸν ᾐσχύνετο τὸν ἔτι ζῶντα, οὕτως ὀλίγον φροντίζουσα τοῦ τεθνεῶτος, ἐγὼ δ’ ἐπένθησ’ αὐτόν, ὥσπερ τοὺς οἰκείους νόμος ἐστίν.", "st": "19.40"}, {"sp": "N", "t": "καὶ ταῦτα πάντ’ ἐποίουν διὰ τὸν τρόπον τὸν ἐμαυτοῦ καὶ τὴν φιλίαν τὴν πρὸς ἐκείνους ἀλλ’ οὐ ταυτησὶ τῆς δίκης ἕνεκα· οὐ γὰρ ᾤμην αὐτοὺς οὕτω δυστυχήσειν ὥστ’ ἄπαιδας ἀμφοτέρους τελευτήσαντας εἰς ἔλεγχον καταστήσειν, ὁποῖός τις ἕκαστος ἡμῶν περὶ αὐτοὺς ἐγένετο.", "st": "19.41"}, {"sp": "N", "t": "πρὸς μὲν οὖν Θρασύλοχόν τε καὶ Σώπολιν ὡς αὕτη τε κἀγὼ διεκείμεθα, σχεδὸν ἀκηκόατε· τρέψονται δ’ ἴσως ἐπ’ ἐκεῖνον τὸν λόγον ὅσπερ αὐτοῖς λοιπός ἐστιν, ὡς Θράσυλλος ὁ πατὴρ ὁ ταύτης ἡγοῖτ’ ἂν δεινὰ πάσχειν, εἴ τίς ἐστιν αἴσθησις τοῖς τεθνεῶσι περὶ τῶν ἐνθάδε γιγνομένων, ὁρῶν τὴν μὲν θυγατέρ’ ἀποστερουμένην τῶν χρημάτων, ἐμὲ δὲ κληρονόμον ὧν αὐτὸς ἐκτήσατο γιγνόμενον. ἐγὼ δ’ ἡγοῦμαι μὲν οὐ περὶ τῶν πάλαι τεθνεώτων,", "st": "19.42"}, {"sp": "N", "t": "ἀλλὰ περὶ τῶν ἔναγχος τὸν κλῆρον καταλιπόντων προσήκειν ἡμῖν τοὺς λόγους ποιεῖσθαι. Θράσυλλος μὲν γάρ, οὕσπερ ἠβούλετο, τούτους κυρίους τῶν αὑτοῦ κατέλιπεν· δίκαιον δὲ καὶ Θρασυλόχῳ ταὐτὰ ταῦτ’ ἀποδοθῆναι παρ’ ὑμῶν, καὶ γενέσθαι διαδόχους τῆς κληρονομίας μὴ ταύτην, ἀλλ’ οἷς ἐκεῖνος διέθετο· οὐ μέντ’ ἄν μοι δοκῶ φυγεῖν οὐδὲ τὴν Θρασύλλου γνώμην.", "st": "19.43"}, {"sp": "N", "t": "οἶμαι γὰρ ἂν αὐτὸν πάντων γενέσθαι ταύτῃ χαλεπώτατον δικαστήν, εἴπερ αἴσθοιτο, οἵα περὶ τοὺς παῖδας αὐτοῦ γεγένηται. πολλοῦ γ’ ἂν δεήσειεν ἀχθεσθῆναι κατὰ τοὺς νόμους ὑμῶν ψηφισαμένων, ἀλλὰ πολὺ ἂν μᾶλλον, εἰ τὰς τῶν παίδων διαθήκας ἀκύρους ἴδοι γενομένας. καὶ γὰρ εἰ μὲν εἰς τὸν οἶκον τὸν ἐμὸν δεδωκὼς ἦν Θρασύλοχος τὴν οὐσίαν, τοῦτ’ ἂν ἐπιτιμᾶν εἶχον αὐτῷ· νῦν δ’ εἰς τὸν αὐτῶν μ’ εἰσεποιήσατο, ὥστ’ οὐκ ἐλάττω τυγχάνουσιν εἰληφότες ὧν δεδώκασιν. χωρὶς δὲ τούτων,", "st": "19.44"}, {"sp": "N", "t": "οὐδένα μᾶλλον εἰκός ἐστιν ἢ Θράσυλλον εὔνουν εἶναι τοῖς κατὰ δόσιν ἀμφισβητοῦσιν· καὶ γὰρ αὐτὸς καὶ τὴν τέχνην ἔμαθε παρὰ Πολεμαινέτου τοῦ μάντεως καὶ τὰ χρήματ’ ἔλαβεν οὐ κατὰ γένος ἀλλὰ δι’ ἀρετήν, ὥστ’ οὐκ ἂν δήπου φθονήσειεν, εἴ τις περὶ τοὺς παῖδας αὐτοῦ χρηστὸς γενόμενος τῆς αὐτῆς δωρεᾶς ἧσπερ ἐκεῖνος ἠξιώθη. μεμνῆσθαι δὲ χρὴ καὶ τῶν ἐν ἀρχῇ ῥηθέντων.", "st": "19.45"}, {"sp": "N", "t": "ἐπέδειξα γὰρ ὑμῖν αὐτὸν οὕτω περὶ πολλοῦ τὴν ἡμετέραν οἰκειότητα ποιησάμενον ὥστε γῆμαι καὶ τὴν ἀδελφὴν τὴν τοῦ πατρὸς καὶ τὴν ἀνεψιάν. καίτοι τίσιν ἂν θᾶττον τὴν αὑτοῦ θυγατέρ’ ἐξέδωκεν ἢ τούτοις παρ’ ὧνπερ αὐτὸς λαμβάνειν ἠξίωσεν; ἐκ ποίας δ’ ἂν οἰκίας ἥδιον εἶδεν υἱὸν αὑτῷ κατὰ τοὺς νόμους εἰσποιηθέντα μᾶλλον ἢ ταύτης, ἐξ ἧσπερ καὶ φύσει παῖδας ἐζήτησεν αὑτῷ γενέσθαι;", "st": "19.46"}, {"sp": "N", "t": "ὥστ’ ἂν μὲν ἐμοὶ ψηφίσησθε τὸν κλῆρον, καὶ πρὸς ἐκεῖνον ὑμῖν καλῶς ἕξει καὶ πρὸς τοὺς ἄλλους ἅπαντας οἷς προσήκει τι τούτων τῶν πραγμάτων· ἂν δ’ ὑπὸ ταύτης πεισθέντες ἐξαπατηθῆτε, οὐ μόνον ἔμ’ ἀδικήσετε ἀλλὰ καὶ Θρασύλοχον τὸν τὴν διαθήκην καταλιπόντα καὶ Σώπολιν καὶ τὴν ἀδελφὴν τὴν ἐκείνων, ἣ νῦν ἐμοὶ συνοικεῖ, καὶ τὴν μητέρ’ αὐτῶν, ἣ πασῶν ἂν εἴη δυστυχεστάτη γυναικῶν, εἰ μὴ μόνον ἐξαρκέσειεν αὐτῇ στέρεσθαι τῶν παίδων, ἀλλὰ καὶ τοῦτ’ αὐτῇ προσγένοιτο, ὥστ’ ἐπιδεῖν ἄκυρον μὲν τὴν ἐκείνων γνώμην οὖσαν, ἔρημον δὲ τὸν οἶκον γιγνόμενον,", "st": "19.47"}, {"sp": "N", "t": "καὶ τὴν μὲν ἐπιχαίρουσαν τοῖς αὑτῆς κακοῖς ἐπιδικαζομένην τῶν χρημάτων, ἐμὲ δὲ μηδενὸς δυνάμενον τῶν δικαίων τυχεῖν, ὃς τοιαῦτ’ ἔπραξα περὶ τοὺς ἐκείνης, ὥστ’ εἴ τίς με σκοποῖτο μὴ πρὸς ταύτην ἀλλὰ πρὸς τοὺς πώποτε κατὰ δόσιν ἀμφισβητήσαντας, εὑρεθείην ἂν οὐδενὸς χείρων αὐτῶν περὶ τοὺς φίλους γεγενημένος. καίτοι χρὴ τοὺς τοιούτους τιμᾶν καὶ περὶ πολλοῦ ποιεῖσθαι πολὺ μᾶλλον ἢ τὰς ὑφ’ ἑτέρων δεδομένας δωρεὰς ἀφαιρεῖσθαι.", "st": "19.48"}, {"sp": "N", "t": "ἄξιον δ’ ἐστὶ καὶ τῷ νόμῳ βοηθεῖν καθ’ ὃν ἔξεστιν ἡμῖν καὶ παῖδας εἰσποιήσασθαι καὶ βουλεύσασθαι περὶ τῶν ἡμετέρων αὐτῶν, ἐνθυμηθέντας ὅτι τοῖς ἐρήμοις τῶν ἀνθρώπων ἀντὶ παίδων οὗτός ἐστιν· διὰ γὰρ τοῦτον καὶ οἱ συγγενεῖς καὶ οἱ μηδὲν προσήκοντες μᾶλλον ἀλλήλων ἐπιμελοῦνται.", "st": "19.49"}, {"sp": "N", "t": "ἵνα δὲ παύσωμαι λέγων καὶ μηκέτι πλείω χρόνον διατρίβω, σκέψασθ’ ὡς μεγάλα καὶ δίκαι’ ἥκω πρὸς ὑμᾶς ἔχων, πρῶτον μὲν φιλίαν πρὸς τοὺς καταλιπόντας τὸν κλῆρον παλαιὰν καὶ πατρικὴν καὶ πάντα τὸν χρόνον διατελέσασαν, ἔπειτ’ εὐεργεσίας πολλὰς καὶ μεγάλας καὶ περὶ δυστυχοῦντας ἐκείνους γεγενημένας, πρὸς δὲ τούτοις διαθήκας παρ’ αὐτῶν τῶν ἀντιδίκων ὁμολογουμένας, ἔτι δὲ νόμον ταύταις βοηθοῦντα, ὃς δοκεῖ τοῖς Ἕλλησιν ἅπασι καλῶς κεῖσθαι.", "st": "19.50"}, {"sp": "N", "t": "τεκμήριον δὲ μέγιστον· περὶ γὰρ ἄλλων πολλῶν διαφερόμενοι περὶ τούτου ταὐτὰ γιγνώσκουσιν. δέομαι οὖν ὑμῶν καὶ τούτων μεμνημένους καὶ τῶν ἄλλων τῶν εἰρημένων τὰ δίκαια ψηφίσασθαι, καὶ τοιούτους μοι γενέσθαι δικαστάς, οἵων περ ἂν αὐτοὶ τυχεῖν ἀξιώσαιτε.", "st": "19.51"}, {"sp": "HDR", "t": "Κατὰ Λοχίτου", "st": "20"}, {"sp": "N", "t": "… ὡς μὲν τοίνυν ἔτυπτέ με Λοχίτης, ἄρχων χειρῶν ἀδίκων, ἅπαντες ὑμῖν οἱ παρόντες μεμαρτυρήκασιν. τὸ δ’ ἁμάρτημα τοῦθ’ οὐχ ὅμοιον δεῖ νομίζειν τοῖς ἄλλοις οὐδὲ τὰς τιμωρίας ἴσας ποιεῖσθαι περί τε τοῦ σώματος καὶ τῶν χρημάτων, ἐπισταμένους ὅτι τοῦτο πᾶσιν ἀνθρώποις οἰκειότατόν ἐστι, καὶ τούς τε νόμους ἐθέμεθα καὶ περὶ τῆς ἐλευθερίας μαχόμεθα καὶ τῆς δημοκρατίας ἐπιθυμοῦμεν καὶ τἄλλα πάντα τὰ περὶ τὸν βίον ἕνεκα τούτου πράττομεν. ὥστ’ εἰκὸς ὑμᾶς ἐστὶ τοὺς περὶ τοῦτ’ ἐξαμαρτάνοντας, ὃ περὶ πλείστου ποιεῖσθε, τῇ μεγίστῃ ζημίᾳ κολάζειν.", "st": "20.1"}, {"sp": "N", "t": "εὑρήσετε δὲ καὶ τοὺς θέντας ἡμῖν τοὺς νόμους ὑπὲρ τῶν σωμάτων μάλιστα σπουδάσαντας. πρῶτον μὲν γὰρ περὶ μόνου τούτου τῶν ἀδικημάτων καὶ δίκας καὶ γραφὰς ἄνευ παρακαταβολῆς ἐποίησαν, ἵν’ ὅπως ἂν ἕκαστος ἡμῶν τυγχάνῃ καὶ δυνάμενος καὶ βουλόμενος, οὕτως ἔχῃ τιμωρεῖσθαι τοὺς ἀδικοῦντας. ἔπειτα τῶν μὲν ἄλλων ἐγκλημάτων αὐτῷ τῷ παθόντι μόνον ὁ δράσας ὑπόδικός ἐστιν· περὶ δὲ τῆς ὕβρεως, ὡς κοινοῦ τοῦ πράγματος ὄντος, ἔξεστι τῷ βουλομένῳ τῶν πολιτῶν γραψαμένῳ πρὸς τοὺς θεσμοθέτας εἰσελθεῖν εἰς ὑμᾶς.", "st": "20.2"}, {"sp": "N", "t": "οὕτω δ’ ἡγήσαντο δεινὸν εἶναι τὸ τύπτειν ἀλλήλους, ὥστε καὶ περὶ τῆς κακηγορίας νόμον ἔθεσαν ὃς κελεύει τοὺς λέγοντάς τι τῶν ἀπορρήτων πεντακοσίας δραχμὰς ὀφείλειν. καίτοι πηλίκας τινὰς χρὴ ποιεῖσθαι τὰς τιμωρίας ὑπὲρ τῶν ἔργῳ παθόντων κακῶς, ὅταν ὑπὲρ τῶν λόγῳ μόνον ἀκηκοότων οὕτως ὀργιζόμενοι φαίνησθε;", "st": "20.3"}, {"sp": "N", "t": "θαυμαστὸν δ’ εἰ τοὺς μὲν ἐπὶ τῆς ὀλιγαρχίας ὑβρίσαντας ἀξίους θανάτου νομίζετε, τοὺς δ’ ἐν δημοκρατίᾳ ταὔτ’ ἐκείνοις ἐπιτηδεύοντας ἀζημίους ἀφήσετε. καίτοι δικαίως ἂν μείζονος οὗτοι τιμωρίας τυγχάνοιεν· φανερώτερον γὰρ ἐπιδείκνυνται τὴν αὑτῶν πονηρίαν. ὅστις γὰρ νῦν τολμᾷ παρανομεῖν, ὅτ’ οὐκ ἔξεστι, τί ποτ’ ἂν ἐποίησεν, ὅθ’ οἱ κρατοῦντες τῆς πόλεως καὶ χάριν εἶχον τοῖς τὰ τοιαῦτ’ ἐξαμαρτάνουσιν;", "st": "20.4"}, {"sp": "N", "t": "ἴσως οὖν Λοχίτης ἐπιχειρήσει μικρὸν ποιεῖν τὸ πρᾶγμα, διασύρων τὴν κατηγορίαν καὶ λέγων ὡς οὐδὲν ἐκ τῶν πληγῶν κακὸν ἔπαθον, ἀλλὰ μείζους ποιοῦμαι τοὺς λόγους ἢ κατὰ τὴν ἀξίαν τῶν γεγενημένων. ἐγὼ δ’ εἰ μὲν μηδεμία προσῆν ὕβρις τοῖς πεπραγμένοις, οὐκ ἄν ποτ’ εἰσῆλθον εἰς ὑμᾶς· νῦν δ’ οὐχ ὑπὲρ τῆς ἄλλης βλάβης τῆς ἐκ τῶν πληγῶν γενομένης, ἀλλ’ ὑπὲρ τῆς αἰκίας καὶ τῆς ἀτιμίας ἥκω παρ’ αὐτοῦ δίκην ληψόμενος,", "st": "20.5"}, {"sp": "N", "t": "ὑπὲρ ὧν προσήκει τοῖς ἐλευθέροις μάλιστ’ ὀργίζεσθαι καὶ μεγίστης τυγχάνειν τιμωρίας. ὁρῶ δ’ ὑμᾶς, ὅταν του καταγνῶθ’ ἱεροσυλίαν ἢ κλοπήν, οὐ πρὸς τὸ μέγεθος ὧν ἂν λάβωσι τὴν τίμησιν ποιουμένους, ἀλλ’ ὁμοίως ἁπάντων θάνατον καταγιγνώσκοντας, καὶ νομίζοντας δίκαιον εἶναι τοὺς τοῖς αὐτοῖς ἔργοις ἐπιχειροῦντας ταῖς αὐταῖς ζημίαις κολάζεσθαι.", "st": "20.6"}, {"sp": "N", "t": "χρὴ τοίνυν καὶ περὶ τῶν ὑβριζόντων τὴν αὐτὴν γνώμην ἔχειν, καὶ μὴ τοῦτο σκοπεῖν, εἰ μὴ σφόδρα συνέκοψαν, ἀλλ’ εἰ τὸν νόμον παρέβησαν, μηδ’ ὑπὲρ τοῦ συντυχόντος μόνον ἀλλ’ ὑπὲρ ἅπαντος τοῦ τρόπου δίκην παρ’ αὐτῶν λαμβάνειν,", "st": "20.7"}, {"sp": "N", "t": "ἐνθυμουμένους ὅτι πολλάκις ἤδη μικραὶ προφάσεις μεγάλων κακῶν αἴτιαι γεγόνασι, καὶ διότι διὰ τοὺς τύπτειν τολμῶντας εἰς τοῦτ’ ἤδη τινὲς ὀργῆς προήχθησαν ὥστ’ εἰς τραύματα καὶ θανάτους καὶ φυγὰς καὶ τὰς μεγίστας συμφορὰς ἐλθεῖν· ὧν οὐδὲν διὰ τὸν φεύγοντα τὴν δίκην ἀγένητόν ἐστιν, ἀλλὰ κατὰ μὲν τὸ τούτου μέρος ἅπαντα πέπρακται, διὰ δὲ τὴν τύχην καὶ τὸν τρόπον τὸν ἐμὸν οὐδὲν τῶν ἀνηκέστων συμβέβηκεν.", "st": "20.8"}, {"sp": "N", "t": "ἡγοῦμαι δ’ ὑμᾶς οὕτως ἂν ἀξίως ὀργισθῆναι τοῦ πράγματος, εἰ διεξέλθοιτε πρὸς ὑμᾶς αὐτοὺς ὅσῳ μεῖζόν ἐστι τοῦτο τῶν ἄλλων ἁμαρτημάτων. εὑρήσετε γὰρ τὰς μὲν ἄλλας ἀδικίας μέρος τι τοῦ βίου βλαπτούσας, τὴν δ’ ὕβριν ὅλοις τοῖς πράγμασι λυμαινομένην, καὶ πολλοὺς μὲν οἴκους δι’ αὐτὴν διαφθαρέντας, πολλὰς δὲ πόλεις ἀναστάτους γεγενημένας.", "st": "20.9"}, {"sp": "N", "t": "καὶ τί δεῖ τὰς τῶν ἄλλων συμφορὰς λέγοντα διατρίβειν; αὐτοὶ γὰρ ἡμεῖς δὶς ἤδη τὴν δημοκρατίαν ἐπείδομεν καταλυθεῖσαν καὶ δὶς τῆς ἐλευθερίας ἀπεστερήθημεν, οὐχ ὑπὸ τῶν ταῖς ἄλλαις πονηρίαις ἐνόχων ὄντων, ἀλλὰ διὰ τοὺς καταφρονοῦντας τῶν νόμων καὶ βουλομένους τοῖς μὲν πολεμίοις δουλεύειν,", "st": "20.10"}, {"sp": "N", "t": "τοὺς δὲ πολίτας ὑβρίζειν. ὧν οὗτος εἷς ὢν τυγχάνει. καὶ γὰρ εἰ τῶν τότε κατασταθέντων νεώτερός ἐστιν, ἀλλὰ τόν γε τρόπον ἔχει τὸν ἐξ ἐκείνης τῆς πολιτείας. αὗται γὰρ αἱ φύσεις εἰσὶν αἱ παραδοῦσαι μὲν τὴν δύναμιν τὴν ἡμετέραν τοῖς πολεμίοις, κατασκάψασαι δὲ τὰ τείχη τῆς πατρίδος, πεντακοσίους δὲ καὶ χιλίους ἀκρίτους ἀποκτείνασαι τῶν πολιτῶν.", "st": "20.11"}, {"sp": "N", "t": "ὧν εἰκὸς ὑμᾶς μεμνημένους τιμωρεῖσθαι μὴ μόνον τοὺς τότε λυμηναμένους ἀλλὰ καὶ τοὺς νῦν βουλομένους οὕτω διαθεῖναι τὴν πόλιν, καὶ τοσούτῳ μᾶλλον τοὺς ἐπιδόξους γενήσεσθαι πονηροὺς τῶν πρότερον ἡμαρτηκότων, ὅσῳ περ κρεῖττόν ἐστι τῶν μελλόντων κακῶν ἀποτροπὴν εὑρεῖν ἢ τῶν ἤδη γεγενημένων δίκην λαβεῖν.", "st": "20.12"}, {"sp": "N", "t": "καὶ μὴ περιμείνηθ’ ἕως ἂν ἀθροισθέντες καὶ καιρὸν λαβόντες εἰς ὅλην τὴν πόλιν ἐξαμάρτωσιν, ἀλλ’ ἐφ’ ἧς ἂν ὑμῖν προφάσεως παραδοθῶσιν, ἐπὶ ταύτης αὐτοὺς τιμωρεῖσθε, νομίζοντες εὕρημ’ ἔχειν, ὅταν τινὰ λάβητ’ ἐν μικροῖς πράγμασιν ἐπιδεδειγμένον ἅπασαν τὴν αὑτοῦ πονηρίαν.", "st": "20.13"}, {"sp": "N", "t": "κράτιστον μὲν γὰρ ἦν, εἴ τι προσῆν ἄλλο σημεῖον τοῖς πονηροῖς τῶν ἀνθρώπων, πρὶν ἀδικηθῆναί τινα τῶν πολιτῶν, πρότερον κολάζειν αὐτούς· ἐπειδὴ δ’ οὐχ οἷόν τ’ ἐστὶν αἰσθέσθαι πρὶν κακῶς τινὰς παθεῖν ὑπ’ αὐτῶν, ἀλλ’ οὖν γ’ ἐπειδὰν γνωρισθῶσι, προσήκει πᾶσι μισεῖν τοὺς τοιούτους καὶ κοινοὺς ἐχθροὺς νομίζειν.", "st": "20.14"}, {"sp": "N", "t": "ἐνθυμεῖσθε δ’ ὅτι τῶν μὲν περὶ τὰς οὐσίας κινδύνων οὐ μέτεστι τοῖς πένησι, τῆς δ’ εἰς τὰ σώματ’ αἰκίας ὁμοίως ἅπαντες κοινωνοῦμεν· ὥσθ’ ὅταν μὲν τοὺς ἀποστεροῦντας τιμωρῆσθε, τοὺς πλουσίους μόνον ὠφελεῖτε, ὅταν δὲ τοὺς ὑβρίζοντας κολάζητε,", "st": "20.15"}, {"sp": "N", "t": "ὑμῖν αὐτοῖς βοηθεῖτε. ὧν ἕνεκα δεῖ περὶ πλείστου ποιεῖσθαι ταύτας τῶν δικῶν, καὶ περὶ μὲν τῶν ἄλλων συμβολαίων τοσούτου τιμᾶν, ὅσον προσήκει τῷ διώκοντι κομίσασθαι, περὶ δὲ τῆς ὕβρεως, ὅσον ἀποτείσας ὁ φεύγων παύσεσθαι μέλλει τῆς παρούσης ἀσελγείας.", "st": "20.16"}, {"sp": "N", "t": "ἂν οὖν περιαιρῆτε τὰς οὐσίας τῶν νεανιευομένων εἰς τοὺς πολίτας καὶ μηδεμίαν νομίζηθ’ ἱκανὴν εἶναι ζημίαν, οἵτινες ἂν εἰς τὰ σώματ’ ἐξαμαρτάνοντες τοῖς χρήμασι τὰς δίκας ὑπέχωσιν, ἅπανθ’ ὅσα δεῖ τοὺς καλῶς δικάζοντας διαπράξεσθε·", "st": "20.17"}, {"sp": "N", "t": "καὶ γὰρ περὶ τοῦ παρόντος πράγματος ὀρθῶς γνώσεσθε καὶ τοὺς ἄλλους πολίτας κοσμιωτέρους ποιήσετε καὶ τὸν βίον τὸν ὑμέτερον αὐτῶν ἀσφαλέστερον καταστήσετε. ἔστι δὲ δικαστῶν νοῦν ἐχόντων περὶ τῶν ἀλλοτρίων τὰ δίκαια ψηφιζομένους ἅμα καὶ τὰ σφέτερ’ αὐτῶν εὖ τίθεσθαι.", "st": "20.18"}, {"sp": "N", "t": "καὶ μηδεὶς ὑμῶν εἰς τοῦτ’ ἀποβλέψας, ὅτι πένης εἰμὶ καὶ τοῦ πλήθους εἷς, ἀξιούτω τοῦ τιμήματος ἀφαιρεῖν. οὐ γὰρ δίκαιον ἐλάττους ποιεῖσθαι τὰς τιμωρίας ὑπὲρ τῶν ἀδόξων ἢ τῶν διωνομασμένων, οὐδὲ χείρους ἡγεῖσθαι τοὺς πενομένους ἢ τοὺς πολλὰ κεκτημένους. ὑμᾶς γὰρ ἂν αὐτοὺς ἀτιμάζοιτ’ εἰ τοιαῦτα γιγνώσκοιτε περὶ τῶν πολλῶν. ἔτι δὲ καὶ πάντων ἂν εἴη δεινότατον,", "st": "20.19"}, {"sp": "N", "t": "εἰ δημοκρατουμένης τῆς πόλεως μὴ τῶν αὐτῶν ἅπαντες τυγχάνοιμεν, ἀλλὰ τῶν μὲν ἀρχῶν μετέχειν ἀξιοῖμεν, τῶν δ’ ἐν τοῖς νόμοις δικαίων ἀποστεροῖμεν ἡμᾶς αὐτούς, καὶ μαχόμενοι μὲν ἐθέλοιμεν ἀποθνῄσκειν ὑπὲρ τῆς πολιτείας, ἐν δὲ τῇ ψήφῳ πλέον νέμοιμεν τοῖς τὰς οὐσίας ἔχουσιν.", "st": "20.20"}, {"sp": "N", "t": "οὐκ, ἄν γέ μοι πεισθῆθ’, οὕτω διακείσεσθε πρὸς ὑμᾶς αὐτούς, οὐδὲ διδάξετε τοὺς νεωτέρους καταφρονεῖν τοῦ πλήθους τῶν πολιτῶν, οὐδὲ ἀλλοτρίους ἡγήσεσθ’ εἶναι τοὺς τοιούτους τῶν ἀγώνων, ἀλλ’ ὡς ὑπὲρ αὑτοῦ δικάζων, οὕτως ἕκαστος ὑμῶν οἴσει τὴν ψῆφον. ἅπαντας γὰρ ὁμοίως ἀδικοῦσιν οἱ τολμῶντες τοῦτον τὸν νόμον παραβαίνειν τὸν ὑπὲρ τῶν σωμάτων τῶν ὑμετέρων κείμενον.", "st": "20.21"}, {"sp": "N", "t": "ὥστ’ ἂν σωφρονῆτε, παρακαλέσαντες ἀλλήλους ἐνσημανεῖσθε Λοχίτῃ τὴν ὀργὴν τὴν ὑμετέραν αὐτῶν, εἰδότες ὅτι πάντες οἱ τοιοῦτοι τῶν μὲν νόμων τῶν κειμένων καταφρονοῦσι, τὰ δ’ ἐνθάδε γιγνωσκόμενα, ταῦτα νόμους εἶναι νομίζουσιν. ἐγὼ μὲν οὖν ὡς οἷός τ’ ἦν εἴρηκα περὶ τοῦ πράγματος· εἰ δέ τις τῶν παρόντων ἔχει τί μοι συνειπεῖν, ἀναβὰς εἰς ὑμᾶς λεγέτω.", "st": "20.22"}, {"sp": "HDR", "t": "Πρὸς Εὐθύνουν ἀμάρτυρος", "st": "21"}, {"sp": "N", "t": "οὐ προφάσεως ἀπορῶ, δι’ ἥντινα λέγω ὑπὲρ Νικίου τουτουί· καὶ γὰρ φίλος ὤν μοι τυγχάνει καὶ δεόμενος καὶ ἀδικούμενος καὶ ἀδύνατος εἰπεῖν, ὥστε διὰ ταῦτα πάντα ὑπὲρ αὐτοῦ λέγειν ἀναγκάζομαι.", "st": "21.1"}, {"sp": "N", "t": "ὅθεν οὖν τὸ συμβόλαιον αὐτῷ πρὸς Εὐθύνουν γεγένηται, διηγήσομαι ὑμῖν ὡς ἂν δύνωμαι διὰ βραχυτάτων. Νικίας γὰρ οὑτοσί, ἐπειδὴ οἱ τριάκοντα κατέστησαν καὶ αὐτὸν οἱ ἐχθροὶ ἐκ μὲν τῶν μετεχόντων τῆς πολιτείας ἐξήλειφον, εἰς δὲ τὸν μετὰ Λυσάνδρου κατάλογον ἐνέγραφον, δεδιὼς τὰ παρόντα πράγματα τὴν μὲν οἰκίαν ὑπέθηκε, τοὺς δ’ οἰκέτας ἔξω τῆς γῆς ἐξέπεμψε, τὰ δ’ ἔπιπλα ὡς ἐμὲ ἐκόμισε, τρία δὲ τάλαντα ἀργυρίου Εὐθύνῳ φυλάττειν ἔδωκεν, αὐτὸς δ’ εἰς ἀγρὸν ἐλθὼν διῃτᾶτο.", "st": "21.2"}, {"sp": "N", "t": "οὐ πολλῷ δὲ χρόνῳ ὕστερον βουλόμενος ἐκπλεῖν ἀπῄτησε τἀργύριον· Εὐθύνους δὲ τὰ μὲν δύο τάλαντα ἀποδίδωσι, τοῦ δὲ τρίτου ἔξαρνος γίγνεται. ἄλλο μὲν οὖν οὐδὲν εἶχε Νικίας ἐν τῷ τότε χρόνῳ ποιῆσαι, προσιὼν δὲ πρὸς τοὺς ἐπιτηδείους ἐνεκάλει καὶ ἐμέμφετο καὶ ἔλεγεν ἃ πεπονθὼς εἴη. καίτοι οὕτω τοῦτόν τε περὶ πολλοῦ ἐποιεῖτο καὶ τὰ καθεστῶτα ἐφοβεῖτο, ὥστε πολὺ ἂν θᾶττον ὀλίγων στερηθεὶς ἐσιώπησεν ἢ μηδὲν ἀπολέσας ἐνεκάλεσεν.", "st": "21.3"}, {"sp": "N", "t": "τὰ μὲν οὖν γεγενημένα ταῦτ’ ἐστίν. ἀπόρως δ’ ἡμῖν ἔχει τὸ πρᾶγμα. Νικίᾳ γὰρ οὔτε παρακατατιθεμένῳ τὰ χρήματα οὔτε κομιζομένῳ οὐδεὶς οὔτ’ ἐλεύθερος οὔτε δοῦλος παρεγένετο, ὥστε μήτ’ ἐκ βασάνων μήτ’ ἐκ μαρτύρων οἷόν τ’ εἶναι γνῶναι περὶ αὐτῶν, ἀλλ’ ἀνάγκη ἐκ τεκμηρίων καὶ ἡμᾶς διδάσκειν καὶ ὑμᾶς δικάζειν, ὁπότεροι τἀληθῆ λέγουσιν.", "st": "21.4"}, {"sp": "N", "t": "οἶμαι δὴ πάντας εἰδέναι ὅτι μάλιστα συκοφαντεῖν ἐπιχειροῦσιν οἱ λέγειν μὲν δεινοί, ἔχοντες δὲ μηδέν, τοὺς ἀδυνάτους μὲν εἰπεῖν, ἱκανοὺς δὲ χρήματα τελεῖν. Νικίας τοίνυν Εὐθύνου πλείω μὲν ἔχει, ἧττον δὲ δύναται λέγειν· ὥστε οὐκ ἔστι δι’ ὅτι ἂν ἐπήρθη ἀδίκως ἐπ’ Εὐθύνουν ἐλθεῖν.", "st": "21.5"}, {"sp": "N", "t": "ἀλλὰ μὴν καὶ ἐξ αὐτοῦ ἄν τις τοῦ πράγματος γνοίη, ὅτι πολὺ μᾶλλον εἰκὸς ἦν Εὐθύνουν λαβόντα ἐξαρνεῖσθαι ἢ Νικίαν μὴ δόντα αἰτιᾶσθαι. δῆλον γὰρ ὅτι πάντες κέρδους ἕνεκ’ ἀδικοῦσιν. οἱ μὲν οὖν ἀποστεροῦντες ὧνπερ ἕνεκ’ ἀδικοῦσιν ἔχουσιν, οἱ δ’ ἐγκαλοῦντες οὐδ’ εἰ λήψεσθαι μέλλουσιν ἴσασιν.", "st": "21.6"}, {"sp": "N", "t": "πρὸς δὲ τούτοις, ἀκαταστάτως ἐχόντων τῶν ἐν τῇ πόλει καὶ δικῶν οὐκ οὐσῶν τῷ μὲν οὐδὲν ἦν πλέον ἐγκαλοῦντι, τῷ δὲ οὐδὲν ἦν δέος ἀποστεροῦντι. ὥστε τὸν μὲν οὐδὲν ἦν θαυμαστόν, ὅτε καὶ οἱ μετὰ μαρτύρων δανεισάμενοι ἐξηρνοῦντο, τότε ἃ μόνος παρὰ μόνου ἔλαβεν ἀποστερῆσαι· τὸν δ’ οὐκ εἰκός, ὅτε οὐδ’ οἷς δικαίως ὠφείλετο οἷόν τ’ ἦν πράττεσθαι, τότε ἀδίκως ἐγκαλοῦντα οἴεσθαί τι λήψεσθαι.", "st": "21.7"}, {"sp": "N", "t": "ἔτι δ’ εἰ καὶ μηδὲν αὐτὸν ἐκώλυεν, ἀλλὰ καὶ ἐξῆν καὶ ἐβούλετο συκοφαντεῖν, ὡς οὐκ ἂν ἐπ’ Εὐθύνουν ἦλθε ῥᾴδιον γνῶναι. οἱ γὰρ τοιαῦτα πράττειν ἐπιθυμοῦντες οὐκ ἀπὸ τῶν φίλων ἄρχονται ἀλλὰ μετὰ τούτων ἐπὶ τοὺς ἄλλους ἔρχονται, καὶ τούτοις ἐγκαλοῦσιν, οὓς ἂν μήτ’ αἰσχύνωνται μήτε δεδίωσι, καὶ οὓς ἂν ὁρῶσι πλουσίους μέν, ἐρήμους δὲ καὶ ἀδυνάτους πράττειν.", "st": "21.8"}, {"sp": "N", "t": "εὐθύνῳ τοίνυν τἀναντία τούτων ὑπάρχει· ἀνεψιὸς γὰρ ὢν Νικίου τυγχάνει, λέγειν δὲ καὶ πράττειν μᾶλλον δύναται τούτου, ἔτι δὲ χρήματα μὲν ὀλίγα, φίλους δὲ πολλοὺς κέκτηται. ὥστ’ οὐκ ἔστιν ἐφ’ ὅντινα ἂν ἧττον ἢ ἐπὶ τοῦτον ἦλθεν· ἐπεὶ ἔμοιγε δοκεῖ, εἰδότι τὴν τούτων οἰκειότητα, οὐδ’ ἂν Εὐθύνους Νικίαν ἀδικῆσαι, εἰ ἐξῆν ἄλλον τινὰ τοσαῦτα χρήματα ἀποστερῆσαι.", "st": "21.9"}, {"sp": "N", "t": "νῦν δ’ ἀρχαιότερον ἦν αὐτοῖς τὸ πρᾶγμα. ἐγκαλεῖν μὲν γὰρ ἔξεστιν ἐξ ἁπάντων ἐκλεξάμενον, ἀποστερεῖν δ’ οὐχ οἷόν ἄλλον ἢ τὸν παρακαταθέμενον. ὥστε Νικίας μὲν συκοφαντεῖν ἐπιθυμῶν οὐκ ἂν ἐπὶ τοῦτον ἦλθεν, Εὐθύνους δ’ ἀποστερεῖν ἐπιχειρῶν οὐκ ἄλλον εἶχεν.", "st": "21.10"}, {"sp": "N", "t": "ὃ δὲ μέγιστον τεκμήριον καὶ πρὸς ἅπαντα ἱκανόν· ὅτε γὰρ τὸ ἔγκλημα ἐγένετο, ὀλιγαρχία καθειστήκει, ἐν ᾗ οὕτως ἑκάτερος αὐτῶν διέκειτο, ὥστε Νικίας μέν, εἰ καὶ τὸν ἄλλον χρόνον εἴθιστο συκοφαντεῖν, τότ’ ἂν ἐπαύσατο, Εὐθύνους δέ, καὶ εἰ μηδὲ πώποτε διενοήθη ἀδικεῖν,", "st": "21.11"}, {"sp": "N", "t": "τότ’ ἂν ἐπήρθη. ὁ μὲν γὰρ διὰ τὰ ἁμαρτήματα ἐτιμᾶτο, ὁ δὲ διὰ τὰ χρήματα ἐπεβουλεύετο. πάντες γὰρ ἐπίστασθε, ὅτι ἐν ἐκείνῳ τῷ χρόνῳ δεινότερον ἦν πλουτεῖν ἢ ἀδικεῖν· οἱ μὲν γὰρ τὰ ἀλλότρια ἐλάμβανον, οἱ δὲ τὰ σφέτερ’ αὐτῶν ἀπώλλυον. ἐφ’ οἷς γὰρ ἦν ἡ πόλις, οὐ τοὺς ἁμαρτάνοντας ἐτιμωροῦντο, ἀλλὰ τοὺς ἔχοντας ἀφῃροῦντο, καὶ ἡγοῦντο τοὺς μὲν ἀδικοῦντας πιστούς, τοὺς δὲ πλουτοῦντας ἐχθρούς.", "st": "21.12"}, {"sp": "N", "t": "ὥστε μὴ περὶ τοῦτ’ εἶναι Νικίᾳ ὅπως συκοφαντῶν τἀλλότρια λήψοιτο, ἀλλ’ ὅπως μὴ οὐδὲν ἀδικῶν κακόν τι πείσοιτο. τῷ μὲν γὰρ ὅσον Εὐθύνους δυναμένῳ ἐξῆν ἅ τ’ ἔλαβεν ἀποστερεῖν καὶ οἷς μὴ συνέβαλεν ἐγκαλεῖν· οἱ δ’ ὥσπερ Νικίας διακείμενοι ἠναγκάζοντο τοῖς τ’ ὀφείλουσι τὰ χρέα ἀφιέναι καὶ τοῖς συκοφαντοῦσι τὰ αὑτῶν διδόναι.", "st": "21.13"}, {"sp": "N", "t": "καὶ ταῦθ’ ὅτι ἀληθῆ λέγω αὐτὸς ἂν ὑμῖν Εὐθύνους μαρτυρήσειεν· ἐπίσταται γὰρ ὅτι Τιμόδημος τουτονὶ τριάκοντα μνᾶς ἐπράξατο, οὐ χρέος ἐγκαλῶν ἀλλ’ ἀπάξειν ἀπειλῶν. καίτοι πῶς εἰκὸς Νικίαν εἰς τοῦτ’ ἀνοίας ἐλθεῖν, ὥστ’ αὐτὸν περὶ τοῦ σώματος κινδυνεύοντα ἑτέρους συκοφαντεῖν,", "st": "21.14"}, {"sp": "N", "t": "καὶ μὴ δυνάμενον τὰ αὑτοῦ σῴζειν τοῖς ἀλλοτρίοις ἐπιβουλεύειν, καὶ πρὸς τοῖς ὑπάρχουσιν ἐχθροῖς ἑτέρους διαφόρους ποιεῖσθαι, καὶ τούτοις ἀδίκως ἐγκαλεῖν παρ’ ὧν οὐδ’ ὁμολογούντων ἀποστερεῖν οἷός τ’ ἂν ἦν δίκην λαβεῖν, καὶ τότε πλέον ἔχειν ζητεῖν, ὅτε οὐδὲ ἴσον ἐξῆν αὐτῷ, καὶ ὅτε ἃ οὐκ ἔλαβεν ἀποτίνειν ἠναγκάζετο, τότε καὶ ἃ μὴ συνέβαλεν ἐλπίζειν πράξασθαι;", "st": "21.15"}, {"sp": "N", "t": "περὶ μὲν οὖν τούτων ἱκανὰ τὰ εἰρημένα. ἴσως δ’ Εὐθύνους ἐρεῖ, ἃ καὶ πρότερον ἤδη, ὅτι οὐκ ἄν ποτ’ ἀδικεῖν ἐπιχειρῶν τὰ μὲν δύο μέρη τῆς παρακαταθήκης ἀπέδωκε, τὸ δὲ τρίτον μέρος ἀπεστέρησεν, ἀλλ’ εἴτε ἀδικεῖν ἐπεθύμει εἴτε δίκαιος ἐβούλετο εἶναι, περὶ ἁπάντων ἂν τὴν αὐτὴν γνώμην ἔσχεν.", "st": "21.16"}, {"sp": "N", "t": "ἐγὼ δ’ ἡγοῦμαι πάντας ὑμᾶς εἰδέναι ὅτι πάντες ἄνθρωποι, ὅταν περ ἀδικεῖν ἐπιχειρῶσιν, ἅμα καὶ τὴν ἀπολογίαν σκοποῦνται· ὥστ’ οὐκ ἄξιον θαυμάζειν, εἰ τούτων ἕνεκα τῶν λόγων οὕτως Εὐθύνους ἠδίκησεν. ἔτι δ’ ἔχοιμ’ ἂν ἐπιδεῖξαι καὶ ἑτέρους, οἳ χρήματα λαβόντες τὰ μὲν πλεῖστ’ ἀπέδοσαν, ὀλίγα δ’ ἀπεστέρησαν, καὶ ἐν μικροῖς μὲν συμβολαίοις ἀδικήσαντας, ἐν μεγάλοις δὲ δικαίους γενομένους·", "st": "21.17"}, {"sp": "N", "t": "ὥστ’ οὐ μόνος οὐδὲ πρῶτος Εὐθύνους τοιαῦτα πεποίηκεν. ἐνθυμεῖσθαι δὲ χρή, εἰ ἀποδέξεσθε τῶν τὰ τοιαῦτα λεγόντων, ὅτι νόμον θήσετε, πῶς χρὴ ἀδικεῖν· ὥστε τοῦ λοιποῦ χρόνου τὰ μὲν ἀποδώσουσι, τὰ δ’ ὑπολείψονται. λυσιτελήσει γὰρ αὐτοῖς, εἰ μέλλουσιν, οἷς ἂν ἀποδῶσι τεκμηρίοις χρώμενοι, ὧν ἂν ἀποστερῶσι μὴ δώσειν δίκην.", "st": "21.18"}, {"sp": "N", "t": "σκέψασθε δὲ καί, ὡς ὑπὲρ Νικίου ῥᾴδιον εἰπεῖν ὅμοια τῇ Εὐθύνου ἀπολογίᾳ. ὅτε γὰρ ἀπελάμβανε τὰ δύο τάλαντα, οὐδεὶς αὐτῷ παρεγένετο· ὥστ’ εἴπερ καὶ ἐβούλετο καὶ ἐδόκει αὐτῷ συκοφαντεῖν, δῆλον ὅτι οὐδ’ ἂν ταῦτα ὡμολόγει κεκομίσθαι, ἀλλὰ περὶ ἁπάντων ἂν τοὺς αὐτοὺς λόγους ἐποιεῖτο, καὶ περὶ πλειόνων τε χρημάτων Εὐθύνους ἂν ἐκινδύνευεν, καὶ ἅμα οὐκ ἂν εἶχεν οἷσπερ νυνὶ τεκμηρίοις χρῆσθαι.", "st": "21.19"}, {"sp": "N", "t": "καὶ μὲν δὴ καὶ Νικίαν μὲν οὐδ’ ἂν εἷς δύναιτο ἀποδεῖξαι, δι’ ἥντινά δι’ ἥντινά ποτε αἰτίαν ἐνεκάλεσεν, Εὐθύνουν δὲ ῥᾴδιον γνῶναι, ὧν ἕνεκα τοῦτον τὸν τρόπον ἠδίκησεν. ὅτε γὰρ Νικίας ἦν ἐν ταῖς συμφοραῖς, πάντες οἱ συγγενεῖς καὶ οἱ ἐπιτήδειοι ἀκηκοότες ἦσαν ὅτι τὸ ἀργύριον, ὃ ἦν αὐτῷ, τούτῳ παρακατέθετο.", "st": "21.20"}, {"sp": "N", "t": "ἐγίγνωσκεν οὖν Εὐθύνους, ὅτι μὲν ἔκειτο τὰ χρήματα παρ’ αὐτῷ, πολλοὺς ᾐσθημένους, ὁπόσα δὲ οὐδένα πεπυσμένον. ὥσθ’ ἡγεῖτο ἀπὸ μὲν τοῦ ἀριθμοῦ ἀφαιρῶν οὐ γνωσθήσεσθαι, πάντα δ’ ἀποστερῶν καταφανὴς γενήσεσθαι. ἐβούλετο οὖν ἱκανὰ λαβὼν ἀπολογίαν ὑπολείπεσθαι μᾶλλον ἢ μηδὲν ἀποδοὺς μηδ’ ἀρνηθῆναι δύνασθαι.", "st": "21.21"}, {"sp": "HDR", "t": "Ἐπιστολὴ Αʹ: Διονυσίῳ", "st": "ep1"}, {"sp": "N", "t": "<em>Ἰσοκράτης Διονυσίῳ χαιρεῖν<\/em>", "st": "ep1.1"}, {"sp": "N", "t": "εἰ μὲν νεώτερος ἦν, οὐκ ἂν ἐπιστολὴν ἔπεμπον, ἀλλ’ αὐτὸς ἄν σοι πλεύσας ἐνταῦθα διελέχθην· ἐπειδὴ δ’ οὐ κατὰ τοὺς αὐτοὺς χρόνους ὅ τε τῆς ἡλικίας τῆς ἐμῆς καιρὸς καὶ τῶν σῶν πραγμάτων συμβέβηκεν, ἀλλ’ ἐγὼ μὲν προαπείρηκα, τὰ δὲ πράττεσθαι νῦν ἀκμὴν εἴληφεν, ὡς οἷόν τ’ ἐστὶν ἐκ τῶν παρόντων, οὕτω σοι πειράσομαι δηλῶσαι περὶ αὐτῶν.", "st": "ep1.1"}, {"sp": "N", "t": "οἶδα μὲν οὖν ὅτι τοῖς συμβουλεύειν ἐπιχειροῦσι πολὺ διαφέρει μὴ διὰ γραμμάτων ποιεῖσθαι τὴν συνουσίαν ἀλλ’ αὐτοὺς πλησιάσαντας, οὐ μόνον ὅτι περὶ τῶν αὐτῶν πραγμάτων ῥᾷον ἄν τις παρὼν πρὸς παρόντα φράσειν ἢ δι’ ἐπιστολῆς δηλώσειεν, οὐδ’ ὅτι πάντες τοῖς λεγομένοις μᾶλλον ἢ τοῖς γεγραμμένοις πιστεύουσι, καὶ τῶν μὲν ὡς εἰσηγημάτων, τῶν δ’ ὡς ποιημάτων ποιοῦνται τὴν ἀκρόασιν·", "st": "ep1.2"}, {"sp": "N", "t": "ἔτι δὲ πρὸς τούτοις ἐν μὲν ταῖς συνουσίαις ἢν ἀγνοηθῇ τι τῶν λεγομένων ἢ μὴ πιστευθῇ, παρὼν ὁ τὸν λόγον διεξιὼν ἀμφοτέροις τούτοις ἐπήμυνεν, ἐν δὲ τοῖς ἐπιστελλομένοις καὶ γεγραμμένοις ἤν τι συμβῇ τοιοῦτον, οὐκ ἔστιν ὁ διορθώσων· ἀπόντος γὰρ τοῦ γράψαντος ἔρημα τοῦ βοηθήσοντός ἐστιν. οὐ μὴν ἀλλ’ ἐπειδὴ σὺ μέλλεις αὐτῶν ἔσεσθαι κριτής, πολλὰς ἐλπίδας ἔχω φανήσεσθαι λέγοντας ἡμᾶς τι τῶν δεόντων· ἡγοῦμαι γὰρ ἁπάσας ἀφέντα σε τὰς δυσχερείας τὰς προειρημένας αὐταῖς ταῖς πράξεσι προσέξειν τὸν νοῦν.", "st": "ep1.3"}, {"sp": "N", "t": "καίτοι τινὲς ἤδη με τῶν σοὶ πλησιασάντων ἐκφοβεῖν ἐπεχείρησαν, λέγοντες ὡς σὺ τοὺς μὲν κολακεύοντας τιμᾶς, τῶν δὲ συμβουλευόντων καταφρονεῖς. ἐγὼ δ’ εἰ μὲν ἀπεδεχόμην τοὺς λόγους τούτους ἐκείνων, πολλὴν ἂν ἡσυχίαν εἶχον· νῦν δ’ οὐδεὶς ἄν με πείσειεν, ὡς οἷόν τ’ ἐστὶ τοσοῦτον καὶ τῇ γνώμῃ καὶ ταῖς πράξεσι διενεγκεῖν, ἂν μή τις τῶν μὲν μαθητής, τῶν δ’ ἀκροατής, τῶν δ’ εὑρετὴς γένηται, καὶ πανταχόθεν προσαγάγηται καὶ συλλέξηται, δι’ ὧν οἷόν τ’ ἐστὶν ἀσκῆσαι τὴν αὑτοῦ διάνοιαν.", "st": "ep1.4"}, {"sp": "N", "t": "ἐπήρθην μὲν οὖν ἐπιστέλλειν σοι διὰ ταῦτα. λέγειν δὲ μέλλω περὶ μεγάλων πραγμάτων καὶ περὶ ὧν οὐδενὶ τῶν ζώντων ἀκοῦσαι μᾶλλον ἢ σοὶ προσήκει. καὶ μὴ νόμιζέ με προθύμως οὕτω σε παρακαλεῖν, ἵνα γένῃ συγγράμματος ἀκροατής· οὐ γὰρ οὔτ’ ἐγὼ τυγχάνω φιλοτίμως διακείμενος πρὸς τὰς ἐπιδείξεις οὔτε σὺ λανθάνεις ἡμᾶς ἤδη πλήρης ὢν τῶν τοιούτων.", "st": "ep1.5"}, {"sp": "N", "t": "πρὸς δὲ τούτοις κἀκεῖνο πᾶσι φανερόν, ὅτι τοῖς μὲν ἐπιδείξεως δεομένοις αἱ πανηγύρεις ἁρμόττουσιν, ἐκεῖ γὰρ ἄν τις ἐν πλείστοις τὴν αὑτοῦ δύναμιν διασπείρειεν, τοῖς δὲ διαπράξασθαί τι βουλομένοις πρὸς τοῦτον διαλεκτέον, ὅστις τάχιστα μέλλει τὰς πράξεις ἐπιτελεῖν τὰς ὑπὸ τοῦ λόγου δηλωθείσας.", "st": "ep1.6"}, {"sp": "N", "t": "εἰ μὲν οὖν μιᾷ τινι τῶν πόλεων εἰσηγούμην, πρὸς τοὺς ἐκείνης προεστῶτας τοὺς λόγους ἂν ἐποιούμην· ἐπειδὴ δ’ ὑπὲρ τῆς τῶν Ἑλλήνων σωτηρίας παρεσκεύασμαι συμβουλεύειν, πρὸς τίν’ ἂν δικαιότερον διαλεχθείην ἢ πρὸς τὸν πρωτεύοντα τοῦ γένους καὶ μεγίστην ἔχοντα δύναμιν;", "st": "ep1.7"}, {"sp": "N", "t": "καὶ μὴν οὐδ’ ἀκαίρως φανησόμεθα μεμνημένοι περὶ τούτων. ὅτε μὲν γὰρ Λακεδαιμόνιοι τὴν ἀρχὴν εἶχον, οὐ ῥᾴδιον ἦν ἐπιμεληθῆναί σοι τῶν περὶ τὸν τόπον τὸν ἡμέτερον, οὐδὲ τούτοις ἐναντία πράττειν ἄμα καὶ Καρχηδονίοις πολεμεῖν· ἐπειδὴ δὲ Λακεδαιμόνιοι μὲν οὕτω πράττουσιν ὥστ’ ἀγαπᾶν, ἢν τὴν χώραν τὴν αὑτῶν ἔχωσιν, ἡ δ’ ἡμετέρα πόλις ἡδέως ἂν αὑτήν σοι παράσχοι συναγωνιζομένην, εἴ τι πράττοις ὑπὲρ τῆς Ἑλλάδος ἀγαθόν, πῶς ἂν παραπέσοι καλλίων καιρὸς τοῦ νῦν σοι παρόντος;", "st": "ep1.8"}, {"sp": "N", "t": "καὶ μὴ θαυμάσῃς, εἰ μήτε δημηγορῶν μήτε στρατηγῶν μήτ’ ἄλλως δυνάσης ὢν οὕτως ἐμβριθὲς αἴρομαι πρᾶγμα καὶ δυοῖν ἐπιχειρῶ τοῖν μεγίστοιν, ὑπέρ τε τῆς Ἑλλάδος λέγειν καὶ σοὶ συμβουλεύειν. ἐγὼ γὰρ τοῦ μὲν πράττειν τι τῶν κοινῶν εὐθὺς ἐξέστην, δι’ ἃς δὲ προφάσεις πολὺ ἂν ἔργον εἴη μοι λέγειν, τῆς δὲ παιδεύσεως τῆς τῶν μὲν μικρῶν καταφρονούσης, τῶν δὲ μεγάλωι ἐφικνεῖσθαι πειρωμένης οὐκ ἂν φανείην ἄμοιρος γεγενημένος.", "st": "ep1.9"}, {"sp": "N", "t": "ὥστ’ οὐδὲν ἄτοπον, εἴ τι τῶν συμφερόντων ἰδεῖν ἂν μᾶλλον δυνηθείην τῶν εἰκῇ μὲν πολιτευομένων, μεγάλην δὲ δόξαν εἰληφότων δηλώσομεν δ’ οὐκ εἰς ἀναβολάς, εἴ τινος ἄξιοι τυγχάνομεν ὄντες, ἀλλ’ ἐκ τῶν ῥηθήσεσθαι μελλόντων …", "st": "ep1.10"}, {"sp": "HDR", "t": "Ἐπιστολὴ Βʹ: Φιλίππῳ Αʹ", "st": "ep2"}, {"sp": "N", "t": "οἶδα μὲν ὅτι πάντες εἰώθασι πλείω χάριν ἔχειν τοῖς ἐπαινοῦσιν ἢ τοῖς συμβουλεύουσιν, ἄλλως τε κἂν μὴ κελευσθεὶς ἐπιχειρῇ τις τοῦτο ποιεῖν. ἐγὼ δ’ εἰ μὲν μὴ καὶ πρότερον ἐτύγχανόν σοι παρῃνεκὼς μετὰ πολλῆς εὐνοίας, ἐξ ὧν ἐδόκεις μοι τὰ πρέποντα μάλιστ’ ἂν σαυτῷ πράττειν, ἴσως οὐδ’ ἂν νῦν ἐπεχείρουν ἀποφαίνεσθαι περὶ τῶν σοὶ συμβεβηκότων·", "st": "ep2.1"}, {"sp": "N", "t": "ἐπειδὴ δὲ προειλόμην φροντίζειν τῶν σῶν πραγμάτων καὶ τῆς πόλεως ἕνεκα τῆς ἐμαυτοῦ καὶ τῶν ἄλλων Ἑλλήνων, αἰσχυνθείην ἄν, εἰ περὶ μὲν τῶν ἧττον ἀναγκαίων φαινοίμην σοι συμβεβουλευκώς, ὑπὲρ δὲ τῶν μᾶλλον κατεπειγόντων μηδένα λόγον ποιόμην, καὶ ταῦτ’ εἰδὼς ἐκεῖνα μὲν ὑπὲρ δόξης ὄντα, ταῦτα δ’ ὑπὲρ τῆς σῆς σωτηρίας, ἧς ὀλιγωρεῖν ἅπασιν ἔδοξας τοῖς ἀκούσασι τὰς περὶ σοῦ ῥηθείσας βλασφημίας.", "st": "ep2.2"}, {"sp": "N", "t": "οὐδεὶς γὰρ ἔστιν, ὅστις οὐ κατέγνω προπετέστερόν σε κινδυνεύειν ἢ βασιλικώτερον, καὶ μᾶλλόν σοι μέλειν τῶν περὶ τὴν ἀνδρίαν ἐπαίνων ἢ τῶν ὅλων πραγμάτων. ἔστι δ’ ὁμοίως αἰσχρὸν περιστάντων τε τῶν πολεμίων μὴ διαφέροντα γενέσθαι τῶν ἄλλων, μηδεμιᾶς τε συμπεσούσης ἀνάγκης αὑτὸν ἐμβαλεῖν εἰς τοιούτους ἀγῶνας, ἐν οἷς κατορθώσας μὲν οὐδὲν ἂν ἦσθα μέγα διαπεπραγμένος, τελευτήσας δὲ τὸν βίον ἅπασαν ἂν τὴν ὑπάρχουσαν εὐδαιμονίαν συνανεῖλες.", "st": "ep2.3"}, {"sp": "N", "t": "χρὴ δὲ μὴ καλὰς ἁπάσας ὑπολαμβάνειν τὰς ἐν τοῖς πολέμοις τελευτάς, ἀλλὰ τὰς μὲν ὑπὲρ τῆς πατρίδος καὶ τῶν γονέων καὶ τῶν παίδων ἐπαίνων ἀξίας, τὰς δὲ ταῦτα τε πάντα βλαπτούσας καὶ τὰς πράξεις τὰς πρότερον κατωρθωμένας καταρρυπαινούσας αἰσχρὰς νομίζειν καὶ φεύγειν ὡς αἰτίας πολλῆς ἀδοξίας γιγνομένας.", "st": "ep2.4"}, {"sp": "N", "t": "ἡγοῦμαι δέ σοι συμφέρειν μιμεῖσθαι τὰς πόλεις, ὃν τρόπον διοικοῦσι τὰ περὶ τοὺς πολέμους. ἅπασαι γάρ, ὅταν στρατόπεδον ἐκπέμπωσιν, εἰώθασι τὸ κοινὸν καὶ τὸ βουλευσόμενον ὑπὲρ τῶν ἐνεστώτων εἰς ἀσφάλειαν καθιστάναι· διὸ δὴ συμβαίνει μὴ μιᾶς ἀτυχίας συμπεσούσης ἀνῃρῆσθαι καὶ τὴν δύναμιν αὐτῶν, ἀλλὰ πολλὰς ὑποφέρειν δύνασθαι συμφορὰς καὶ πάλιν αὑτὰς ἐκ τούτων ἀναλαμβάνειν. ὃ καὶ σὲ δεῖ σκοπεῖν,", "st": "ep2.5"}, {"sp": "N", "t": "καὶ μηδὲν μεῖζον ἀγαθὸν τῆς σωτηρίας ὑπολαμβάνειν, ἵνα καὶ τὰς νίκας τὰς συμβαινούσας κατὰ τρόπον διοικῇς καὶ τὰς ἀτυχίας τὰς συμπιπτούσας ἐπανορθοῦν δύνῃ. ἴδοις δ’ ἂν καὶ Λακεδαιμονίους περὶ τῆς τῶν βασιλέων σωτηρίας πολλὴν ἐπιμέλειαν ποιουμένους καὶ τοὺς ἐνδοξοτάτους τῶν πολιτῶν φύλακας αὐτῶν καθιστάντας, οἷς αἴσχιόν ἐστιν ἐκείνους τελευτήσαντας περιιδεῖν ἢ τὰς ἀσπίδας ἀποβαλεῖν.", "st": "ep2.6"}, {"sp": "N", "t": "ἀλλὰ μὴν οὐδ’ ἐκεῖνά σε λέληθεν ἃ Θέρξῃ τε τῷ καταδουλώσασθαι τοὺς Ἕλληνας βουληθέντι καὶ Κύρῳ τῷ τῆς βασιλείας ἀμφισβητήσαντι συνέπεσεν. ὁ μὲν γὰρ τηλικαύταις ἥτταις καὶ συμφοραῖς περιπεσών, ἡλίκας οὐδεὶς οἶδεν ἄλλοις γενομένας, διὰ τὸ περιποιῆσαι τὴν αὑτοῦ ψυχὴν τήν τε βασιλείαν κατέσχε καὶ τοῖς παισὶ τοῖς αὑτοῦ παρέδωκε καὶ τὴν Ἀσίαν οὕτω διῴκησεν ὥστε μηδὲν ἧττον αὐτὴν εἶναι φοβερὰν τοῖς Ἕλλησιν ἢ πρότερον·", "st": "ep2.7"}, {"sp": "N", "t": "Κῦρος δὲ νικήσας ἅπασαν τὴν βασιλέως δύναμιν καὶ κρατήσας ἂν τῶν πραγμάτων, εἰ μὴ διὰ τὴν αὑτοῦ προπέτειαν, οὐ μόνον αὑτὸν ἀπεστέρησε τηλικαύτης δυναστείας, ἀλλὰ καὶ τοὺς συνακολουθήσαντας εἰς τὰς ἐσχάτας συμφορὰς κατέστησεν. ἔχοιμι δ’ ἂν παμπληθεῖς εἰπεῖν οἳ μεγάλων στρατοπέδων ἡγεμόνες γενόμενοι διὰ τὸ προδιαφθαρῆναι πολλὰς μυριάδας αὑτοῖς συναπώλεσαν.", "st": "ep2.8"}, {"sp": "N", "t": "ὧν ἐνθυμούμενον χρὴ μὴ τιμᾶν τὴν ἀνδρίαν τὴν μετ’ ἀνοίας ἀλογίστου καὶ φιλοτιμίας ἀκαίρου γιγνομένην, μηδὲ πολλῶν κινδύνων ἰδίων ὑπαρχόντων ταῖς μοναρχίαις ἑτέρους ἀδόξους καὶ στρατιωτικοὺς αὑτῷ προσεξευρίσκειν, μηδ’ ἁμιλλᾶσθαι τοῖς ἢ βίου δυστυχοῦς ἀπαλλαγῆναι βουλομένοις ἢ μισθοφορᾶς ἕνεκα μείζονος εἰκῇ τοὺς κινδύνους προαιρουμένοις,", "st": "ep2.9"}, {"sp": "N", "t": "μηδ’ ἐπιθυμεῖν τοιαύτης δόξης, ἧς πολλοὶ καὶ τῶν Ἑλλήνων καὶ τῶν βαρβάρων τυγχάνουσιν, ἀλλὰ τῆς τηλικαύτης τὸ μέγεθος, ἣν μόνος ἂν τῶν νῦν ὄντων κτήσασθαι δυνηθείης· μηδ’ ἀγαπᾶν λίαν τὰς τοιαύτας ἀρετὰς ὧν καὶ τοῖς φαύλοις μέτεστιν, ἀλλ’ ἐκείνας ὧν οὐδεὶς ἂν πονηρὸς κοινωνήσειεν·", "st": "ep2.10"}, {"sp": "N", "t": "μηδὲ ποιεῖσθαι πολέμους ἀδόξους καὶ χαλεπούς, ἐξὸν ἐντίμους καὶ ῥᾳδίους, μηδ’ ἐξ ὧν τοὺς μὲν οἰκειοτάτους εἰς λύπας καὶ φροντίδας καταστήσεις, τοὺς δ’ ἐχθροὺς ἐν ἐλπίσι μεγάλαις ποιήσεις, οἵας καὶ νῦν αὐτοῖς παρέσχες· ἀλλὰ τῶν μὲν βαρβάρων, πρὸς οὓς νῦν πολεμεῖς, ἐπὶ τοσοῦτον ἐξαρκέσει σοι κρατεῖν, ὅσον ἐν ἀσφαλείᾳ καταστῆσαι τὴν σαυτοῦ χώραν, τὸν δὲ βασιλέα τὸν νῦν μέγαν προσαγορευόμενον καταλύειν ἐπιχειρήσεις, ἵνα τήν τε σαυτοῦ δόξαν μείζω ποιήσῃς καὶ τοῖς Ἕλλησιν ὑποδείξῃς πρὸς ὃν χρὴ πολεμεῖν.", "st": "ep2.11"}, {"sp": "N", "t": "πρὸ πολλοῦ δ’ ἂν ἐποιησάμην ἐπιστεῖλαί σοι ταῦτα πρὸ τῆς στρατείας, ἵν’ εἰ μὲν ἐπείσθης, μὴ τηλικούτῳ κινδύνῳ περιέπεσες, εἰ δ’ ἠπίστησας, μὴ συμβουλεύειν ἐδόκουν ταὐτὰ τοῖς ἤδη διὰ τὸ πάθος ὑπὸ πάντων ἐγνωσμένοις, ἀλλὰ τὸ συμβεβηκὸς ἐμαρτύρει τοὺς λόγους ὀρθῶς ἔχειν τοὺς ὑπ’ ἐμοῦ περὶ αὐτῶν εἰρημένους.", "st": "ep2.12"}, {"sp": "N", "t": "πολλὰ δ’ ἔχων εἰπεῖν διὰ τὴν τοῦ πράγματος φύσιν παύσομαι λέγων· οἶμαι γὰρ καὶ σὲ καὶ τῶν ἑταίρων τοὺς σπουδαιοτάτους ῥᾳδίως ὁπόσ’ ἂν βούλησθε προσθήσειν τοῖς εἰρημένοις. πρὸς δὲ τούτοις φοβοῦμαι τὴν ἀκαιρίαν· καὶ γὰρ νῦν κατὰ μικρὸν προϊὼν ἔλαθον ἐμαυτὸν οὐκ εἰς ἐπιστολῆς συμμετρίαν ἀλλ’ εἰς λόγου μῆκος ἐξοκείλας.", "st": "ep2.13"}, {"sp": "N", "t": "οὐ μὴν ἀλλὰ καίπερ τούτων οὕτως ἐχόντων οὐ παραλειπτέον ἐστὶ τὰ περὶ τῆς πόλεως, ἀλλὰ πειρατέον παρακαλέσαι σε πρὸς τὴν οἰκειότητα καὶ τὴν χρῆσιν αὐτῆς. οἶμαι γὰρ πολλοὺς εἶναι τοὺς ἀπαγγέλλοντας καὶ λέγοντας οὐ μόνον τὰ δυσχερέστατα τῶν περὶ σοῦ παρ’ ἡμῖν εἰρημένων, ἀλλὰ καὶ παρ’ αὑτῶν προστιθέντας· οἷς οὐκ εἰκὸς προσέχειν τὸν νοῦν.", "st": "ep2.14"}, {"sp": "N", "t": "καὶ γὰρ ἂν ἄτοπον ποιοίης, εἰ τὸν μὲν δῆμον τὸν ἡμέτερον ψέγοις ὅτι ῥᾳδίως πείθεται τοῖς διαβάλλουσιν, αὐτὸς δὲ φαίνοιο πιστεύων τοῖς τὴν τέχνην ταύτην ἔχουσι, καὶ μὴ γιγνώσκοις ὡς ὅσῳπερ ἂν τὴν πόλιν εὐαγωγοτέραν ὑπὸ τῶν τυχόντων οὖσαν ἀποφαίνωσι, τοσούτῳ μᾶλλόν σοι συμφερόντως ἔχουσαν αὐτὴν ἐπιδεικνύουσιν. εἰ γὰρ οἱ μηδὲν ἀγαθὸν οἷοί τ’ ὄντες ποιῆσαι διαπράττονται τοῖς λόγοις ὅ τι ἂν βουληθῶσιν, ἦ που σέ γε προσήκει τὸν πλεῖστ’ ἂν ἔργῳ δυνάμενον εὐεργετῆσαι μηδενὸς ἀποτυχεῖν παρ’ ἡμῶν.", "st": "ep2.15"}, {"sp": "N", "t": "ἡγοῦμαι δὲ δεῖν πρὸς μὲν τοὺς πικρῶς τῆς πόλεως ἡμῶν κατηγοροῦντας ἐκείνους ἀντιτάττεσθαι τοὺς πάντα τἀναντί’ εἶναι λέγοντας καὶ τοὺς μήτε μεῖζον μήτ’ ἔλαττον αὐτὴν ἠδικηκέναι φάσκοντας· ἐγὼ δ’ οὐδὲν ἂν εἴποιμι τοιοῦτον· αἰσχυνθείην γὰρ ἄν, εἰ τῶν ἄλλων μηδὲ τοὺς θεοὺς ἀναμαρτήτους εἶναι νομιζόντων αὐτὸς τολμῴην λέγειν, ὡς οὐδὲν πώποθ’ ἡ πόλις ἡμῶν πεπλημμέληκεν.", "st": "ep2.16"}, {"sp": "N", "t": "οὐ μὴν ἀλλ’ ἐκεῖν’ ἔχω περὶ αὐτῆς εἰπεῖν, ὅτι χρησιμωτέραν οὐκ ἂν εὕροις ταύτης οὔτε τοῖς Ἕλλησιν οὔτε τοῖς σοῖς πράγμασιν· ᾧ μάλιστα προσεκτέον τὸν νοῦν ἐστίν. οὐ γὰρ μόνον συναγωνιζομένη γίγνοιτ’ ἂν αἰτία σοι πολλῶν ἀγαθῶν,", "st": "ep2.17"}, {"sp": "N", "t": "ἀλλὰ καὶ φιλικῶς ἔχειν δοκοῦσα μόνον· τούς τε γὰρ ὑπὸ σοὶ νῦν ὄντας ῥᾷον ἂν κατέχοις, εἰ μηδεμίαν ἔχοιεν ἀποστροφήν, τῶν τε βαρβάρων οὓς βουληθείης θᾶττον ἂν καταστρέψαιο. καίτοι πῶς οὐ χρὴ προθύμως ὀρέγεσθαι τῆς τοιαύτης εὐνοίας, δι’ ἣν οὐ μόνον τὴν ὑπάρχουσαν ἀρχὴν ἀσφαλῶς καθέξεις, ἀλλὰ καὶ πολλὴν ἑτέραν ἀκινδύνως προσκτήσει;", "st": "ep2.18"}, {"sp": "N", "t": "θαυμάζω δ’ ὅσοι τῶν τὰς δυνάμεις ἐχόντων τὰ μὲν τῶν ξενιτευομένων στρατόπεδα μισθοῦνται καὶ χρήματα πολλὰ δαπανῶσι, συνειδότες ὅτι πλείους ἠδίκηκε τῶν πιστευσάντων αὐτοῖς ἢ σέσωκε, τὴν δὲ πόλιν τὴν τηλικαύτην δύναμιν κεκτημένην μὴ πειρῶνται θεραπεύειν, ἣ καὶ μίαν ἑκάστην τῶν πόλεων καὶ σύμπασαν τὴν Ἑλλάδα πολλάκις ἤδη σέσωκεν.", "st": "ep2.19"}, {"sp": "N", "t": "ἐνθυμοῦ δ’ ὅτι πολλοῖς καλῶς βεβουλεῦσθαι δοκεῖς ὅτι δικαίως κέχρησαι Θετταλοῖς καὶ συμφερόντως ἐκείνοις, ἀνδράσιν οὐκ εὐμεταχειρίστοις, ἀλλὰ μεγαλοψύχοις καὶ στάσεως μεστοῖς. χρὴ τοίνυν καὶ περὶ ἡμᾶς πειρᾶσθαι γίγνεσθαί σε τοιοῦτον, ἐπιστάμενον ὅτι τὴν μὲν χώραν Θετταλοί, τὴν δὲ δύναμιν ἡμεῖς ὅμορόν σοι τυγχάνομεν ἔχοντες, ἣν ἐκ παντὸς τρόπου ζήτει προσαγαγέσθαι.", "st": "ep2.20"}, {"sp": "N", "t": "πολὺ γὰρ κάλλιόν ἐστι τὰς εὐνοίας τὰς τῶν πόλεων αἱρεῖν ἢ τὰ τείχη. τὰ μὲν γὰρ τοιαῦτα τῶν ἔργων οὐ μόνον ἔχει φθόνον, ἀλλὰ καὶ τῶν τοιούτων τὴν αἰτίαν τοῖς στρατοπέδοις ἀνατιθέασιν· ἢν δὲ τὰς οἰκειότητας καὶ τὰς εὐνοίας κτήσασθαι δυνηθῇς, ἅπαντες τὴν σὴν διάνοιαν ἐπαινέσονται.", "st": "ep2.21"}, {"sp": "N", "t": "δικαίως δ’ ἄν μοι πιστεύοις οἷς εἴρηκα περὶ τῆς πόλεως· φανήσομαι γὰρ οὔτε κολακεύειν αὐτὴν ἐν τοῖς λόγοις εἰθισμένος, ἀλλὰ πλεῖστα πάντων ἐπιτετιμηκώς, οὔτ’ εὖ παρὰ τοῖς πολλοῖς καὶ τοῖς εἰκῇ δοκιμάζουσι φερόμενος, ἀλλ’ ἀγνοούμενος ὑπ’ αὐτῶν καὶ φθονούμενος ὥσπερ σύ. πλὴν τοσοῦτον διαφέρομεν, ὅτι πρὸς σὲ μὲν διὰ τὴν δύναμιν καὶ τὴν εὐδαιμονίαν οὕτως ἔχουσι, πρὸς δ’ ἐμέ, διότι προσποιοῦμαι τὸ βέλτιον αὐτῶν φρονεῖν καὶ πλείους ὁρῶσιν ἐμοὶ διαλέγεσθαι βουλομένους ἢ σφίσιν αὐτοῖς.", "st": "ep2.22"}, {"sp": "N", "t": "ἠβουλόμην δ’ ἂν ἡμῖν ὁμοίως ῥᾴδιον εἶναι τὴν δόξαν ἣν ἔχομεν παρ’ αὐτοῖς διαφεύγειν. νῦν δὲ σὺ μὲν οὐ χαλεπῶς, ἢν βουληθῇς, αὐτὴν διαλύσεις, ἐμοὶ δ’ ἀνάγκη καὶ διὰ τὸ γῆρας καὶ δι’ ἄλλα πολλὰ στέργειν τοῖς παροῦσιν.", "st": "ep2.23"}, {"sp": "N", "t": "οὐκ οἶδ’ ὅ τι δεῖ πλείω λέγειν πλὴν τοσοῦτον, ὅτι καλόν ἐστι τὴν βασιλείαν καὶ τὴν εὐδαιμονίαν τὴν ὑπάρχουσαν ὑμῖν παρακαταθέσθαι τῇ τῶν Ἑλλήνων εὐνοίᾳ.", "st": "ep2.24"}, {"sp": "HDR", "t": "Ἐπιστολὴ Γʹ: Φιλίππῳ Βʹ", "st": "ep3"}, {"sp": "N", "t": "ἐγὼ διελέχθην μὲν καὶ πρὸς Ἀντίπατρον περί τε τῶν τῇ πόλει καὶ τῶν σοὶ συμφερόντων ἐξαρκούντως, ὡς ἐμαυτὸν ἔπειθον, ἠβουλήθην δὲ καὶ πρὸς σὲ γράψαι περὶ ὧν μοι δοκεῖ πρακτέον εἶναι μετὰ τὴν εἰρήνην, παραπλήσια μὲν τοῖς ἐν τῷ λόγῳ γεγραμμένοις, πολὺ δ’ ἐκείνων συντομώτερα.", "st": "ep3.1"}, {"sp": "N", "t": "κατ’ ἐκεῖνον μὲν γὰρ τὸν χρόνον συνεβούλευον ὡς χρὴ διαλλάξαντά σε τὴν πόλιν τὴν ἡμετέραν καὶ τὴν Λακεδαιμονίων καὶ τὴν Θηβαίων καὶ τὴν Ἀργείων εἰς ὁμόνοιαν καταστῆσαι τοὺς Ἕλληνας, ἡγούμενος, ἂν τὰς προεστώσας πόλεις πείσῃς οὕτω φρονεῖν, ταχέως καὶ τὰς ἄλλας ἐπακολουθήσειν. τότε μὲν οὖν ἄλλος ἦν καιρός, νῦν δὲ συμβέβηκε μηκέτι δεῖν πείθειν· διὰ γὰρ τὸν ἀγῶνα τὸν γεγενημένον ἠναγκασμένοι πάντες εἰσὶν εὖ φρονεῖν καὶ τούτων ἐπιθυμεῖν ὧν ὑπονοοῦσί σε βούλεσθαι πράττειν καὶ λέγειν, ὡς δεῖ παυσαμένους τῆς μανίας καὶ τῆς πλεονεξίας, ἣν ἐποιοῦντο πρὸς ἀλλήλους, εἰς τὴν Ἀσίαν τὸν πόλεμον ἐξενεγκεῖν.", "st": "ep3.2"}, {"sp": "N", "t": "καὶ πολλοὶ πυνθάνονται παρ’ ἐμοῦ πότερον ἐγώ σοι παρῄνεσα ποιεῖσθαι τὴν στρατείαν τὴν ἐπὶ τοὺς βαρβάρους ἢ σοῦ διανοηθέντος συνεῖπον· ἐγὼ δ’ οὐκ εἰδέναι μέν φημι τὸ σαφές, οὐ γὰρ συγγεγενῆσθαί σοι πρότερον, οὐ μὴν ἀλλ’ οἴεσθαι σὲ μὲν ἐγνωκέναι περὶ τούτων, ἐμὲ δὲ συνειρηκέναι ταῖς σαῖς ἐπιθυμίαις. ταῦτα δ’ ἀκούοντες ἐδέοντό μου πάντες παρακελεύεσθαί σοι καὶ προτρέπειν ἐπὶ τῶν αὐτῶν τούτων μένειν, ὡς οὐδέποτ’ ἂν γενομένων οὔτε καλλιόνων ἔργων οὔτ’ ὠφελιμωτέρων τοῖς Ἕλλησιν οὔτ’ ἐν καιρῷ μᾶλλον πραχθησομένων.", "st": "ep3.3"}, {"sp": "N", "t": "εἰ μὲν οὖν εἶχον τὴν αὐτὴν δύναμιν ἥνπερ πρότερον, καὶ μὴ παντάπασιν ἦν ἀπειρηκώς, οὐκ ἂν δι’ ἐπιστολῆς διελεγόμην, ἀλλὰ παρὼν αὐτὸς παρώξυνον ἄν σε καὶ παρεκάλουν ἐπὶ τὰς πράξεις ταύτας. νῦν δ’ ὡς δύναμαι παρακελεύομαί σοι μὴ καταμελῆσαι τούτων, πρὶν ἂν τέλος ἐπιθῇς αὐτοῖς. ἔστι δὲ πρὸς μὲν ἄλλο τι τῶν ὄντων ἀπλήστως ἔχειν οὐ καλόν, αἱ γὰρ μετριότητες παρὰ τοῖς πολλοῖς εὐδοκιμοῦσι, δόξης δὲ μεγάλης καὶ καλῆς ἐπιθυμεῖν καὶ μηδέποτ’ ἐμπίπλασθαι προσήκει τοῖς πολὺ τῶν ἄλλων διενεγκοῦσιν· ὅπερ σοὶ συμβέβηκεν.", "st": "ep3.4"}, {"sp": "N", "t": "ἡγοῦ δὲ τόθ’ ἕξειν ἀνυπέρβλητον αὐτὴν καὶ τῶν σοὶ πεπραγμένων ἀξίαν, ὅταν τοὺς μὲν βαρβάρους ἀναγκάσῃς εἱλωτεύειν τοῖς Ἕλλησι πλὴν τῶν σοὶ συναγωνισαμένων, τὸν δὲ βασιλέα τὸν νῦν μέγαν προσαγορευόμενον ποιήσῃς τοῦτο πράττειν ὅ τι ἂν σὺ προστάττῃς. οὐδὲν γὰρ ἔσται λοιπὸν ἔτι πλὴν θεὸν γενέσθαι. ταῦτα δὲ κατεργάσασθαι πολὺ ῥᾷόν ἐστιν ἐκ τῶν παρόντων ἢ προελθεῖν ἐπὶ τὴν δύναμιν καὶ τὴν δόξαν ἣν νῦν ἔχεις, ἐκ τῆς βασιλείας τῆς ἐξ ἀρχῆς ὑμῖν ὑπαρξάσης.", "st": "ep3.5"}, {"sp": "N", "t": "χάριν δ’ ἔχω τῷ γήρᾳ ταύτην μόνην, ὅτι προήγαγεν εἰς τοῦτό μου τὸν βίον, ὥσθ’ ἃ νέος ὢν διενοούμην καὶ γράφειν ἐπεχείρουν ἔν τε τῷ πανηγυρικῷ λόγῳ καὶ τῷ πρὸς σὲ πεμφθέντι, ταῦτα νῦν τὰ μὲν ἤδη γιγνόμενα διὰ τῶν σῶν ἐφορῶ πράξεων, τὰ δ’ ἐλπίζω γενήσεσθαι.", "st": "ep3.6"}, {"sp": "HDR", "t": "Ἐπιστολὴ Δʹ: Ἀντιπάτρῳ", "st": "ep4"}, {"sp": "N", "t": "ἐγώ, καίπερ ἐπικινδύνου παρ’ ἡμῖν ὄντος εἰς Μακεδονίαν πέμπειν ἐπιστολήν, οὐ μόνον νῦν ὅτε πολεμοῦμεν πρὸς ὑμᾶς, ἀλλὰ καὶ τῆς εἰρήνης οὔσης, ὅμως γράψαι πρὸς σὲ προειλόμην περὶ Διοδότου, δίκαιον εἶναι νομίζων ἅπαντας μὲν περὶ πολλοῦ ποιεῖσθαι τοὺς ἐμαυτῷ πεπλησιακότας καὶ γεγενημένους ἀξίους ἡμῶν, οὐχ ἥκιστα δὲ τοῦτον καὶ διὰ τὴν εὔνοιαν τὴν εἰς ἡμᾶς καὶ διὰ τὴν ἄλλην ἐπιείκειαν.", "st": "ep4.1"}, {"sp": "N", "t": "μάλιστα μὲν οὖν ἠβουλόμην ἂν αὐτὸν συσταθῆναί σοι δι’ ἡμῶν· ἐπειδὴ δὲ δι’ ἑτέρων ἐντετύχηκέ σοι, λοιπόν ἐστί μοι μαρτυρῆσαι περὶ αὐτοῦ καὶ βεβαιῶσαι τὴν γεγενημένην αὐτῷ πρὸς σὲ γνῶσιν. ἐμοὶ γὰρ πολλῶν καὶ παντοδαπῶν συγγεγενημένων ἀνδρῶν καὶ δόξας ἐνίων μεγάλας ἐχόντων, τῶν μὲν ἄλλων ἁπάντων οἱ μέν τινες περὶ αὐτὸν τὸν λόγον, οἱ δὲ περὶ τὸ διανοηθῆναι καὶ πρᾶξαι δεινοὶ γεγόνασιν, οἱ ἐπὶ μὲν τοῦ βίου σώφρονες καὶ χαρίεντες, πρὸς δὲ τὰς ἄλλας χρήσεις καὶ διαγωγὰς ἀφυεῖς παντάπασιν·", "st": "ep4.2"}, {"sp": "N", "t": "οὗτος δ’ οὕτως εὐάρμοστον τὴν φύσιν ἔσχηκεν ὥστ’ ἐν ἅπασι τοῖς εἰρημένοις τελειότατος εἶναι. καὶ ταῦτ’ οὐκ ἂν ἐτόλμων λέγειν, εἰ μὴ τὴν ἀκριβεστάτην πεῖραν αὐτός τ’ εἶχον αὐτοῦ καὶ σὲ λήψεσθαι προσεδόκων, τὰ μὲν αὐτὸν χρώμενον αὐτῷ,", "st": "ep4.3"}, {"sp": "N", "t": "τὰ δὲ καὶ παρὰ τῶν ἄλλων τῶν ἐμπείρων αὐτοῦ πυνθανόμενον, ὧν οὐδεὶς ὅστις οὐκ ἂν ὁμολογήσειεν, εἰ μὴ λίαν εἴη φθονερός, καὶ εἰπεῖν καὶ βουλεύσασθαι μηδενὸς ἧττον αὐτὸν δύνασθαι καὶ δικαιότατον καὶ σωφρονέστατον εἶναι καὶ χρημάτων ἐγκρατέστατον, ἔτι δὲ συνημερεῦσαι καὶ συμβιῶναι πάντων ἥδιστον καὶ λιγυρώτατον, πρὸς δὲ τούτοις πλείστην ἔχειν παρρησίαν, οὐχ ἣν οὐ προσῆκεν, ἀλλὰ τὴν εἰκότως ἂν μέγιστον γιγνομένην σημεῖον τῆς εὐνοίας τῆς πρὸς τοὺς φίλους·", "st": "ep4.4"}, {"sp": "N", "t": "ἣν τῶν δυναστῶν οἱ μὲν ἀξιόχρεων τὸν ὄγκον τὸν τῆς ψυχῆς ἔχοντες τιμῶσιν ὡς χρησίμην οὖσαν, οἱ δ’ ἀσθενέστεροι τὰς φύσεις ὄντες ἢ κατὰ τὰς ὑπαρχούσας ἐξουσίας δυσχεραίνουσιν, ὡς ὧν οὐ προαιροῦνταί τι ποιεῖν βιαζομένην αὑτούς, οὐκ εἰδότες ὡς οἱ μάλιστα περὶ τοῦ συμφέροντος ἀντιλέγειν τολμῶντες, οὗτοι πλείστην ἐξουσίαν αὐτοῖς τοῦ πράττειν ἃ βούλονται παρασκευάζουσιν.", "st": "ep4.5"}, {"sp": "N", "t": "εἰκὸς γὰρ διὰ μὲν τοὺς ἀεὶ πρὸς ἡδονὴν λέγειν προαιρουμένους οὐχ ὅπως τὰς μοναρχίας δύνασθαι διαμένειν, αἳ πολλοὺς τοὺς ἀναγκαίους ἐφέλκονται κινδύνους, ἀλλ’ οὐδὲ τὰς πολιτείας, αἳ μετὰ πλείονος ἀσφαλείας εἰσί, διὰ δὲ τοὺς ἐπὶ τῷ βελτίστῳ παρρησιαζομένους πολλὰ σῴζεσθαι καὶ τῶν ἐπιδόξων διαφθαρήσεσθαι πραγμάτων. ὧν ἕνεκα προσῆκε μὲν παρὰ πᾶσι τοῖς μονάρχοις πλέον φέρεσθαι τοὺς τὴν ἀλήθειαν ἀποφαινομένους τῶν ἅπαντα μὲν πρὸς χάριν, μηδὲν δὲ χάριτος ἄξιον λεγόντων· συμβαίνει δ’ ἔλαττον ἔχειν αὐτοὺς παρ’ ἐνίοις αὐτῶν.", "st": "ep4.6"}, {"sp": "N", "t": "ὃ καὶ Διοδότῳ παθεῖν συνέπεσε παρά τισι τῶν περὶ τὴν Ἀσίαν δυναστῶν, οἷς περὶ πολλὰ χρήσιμος γενόμενος οὐ μόνον τῷ συμβουλεύειν ἀλλὰ καὶ τῷ πράττειν καὶ κινδυνεύειν, διὰ τὸ παρρησιάζεσθαι πρὸς αὐτοὺς περὶ ὧν ἐκείνοις συνέφερε, καὶ τῶν οἴκοι τιμῶν ἀπεστέρηται καὶ πολλῶν ἄλλων ἐλπίδων, καὶ μεῖζον ἴσχυσαν αἱ τῶν τυχόντων ἀνθρώπων κολακεῖαι τῶν εὐεργεσιῶν τῶν τούτου.", "st": "ep4.7"}, {"sp": "N", "t": "διὸ δὴ καὶ πρὸς ὑμᾶς ἀεὶ προσιέναι διανοούμενος ὀκνηρῶς εἶχεν, οὐχ ὡς ἅπαντας ὁμοίους εἶναι νομίζων τοὺς ὑπὲρ αὑτὸν ὄντας, ἀλλὰ διὰ τὰς πρὸς ἐκείνους γεγενημένας δυσχερείας καὶ πρὸς τὰς παρ’ ὑμῶν ἐλπίδας ἀθυμότερος ἦν, παραπλήσιον, ὡς ἐμοὶ δοκεῖ, πεπονθὼς τῶν πεπλευκότων τισίν, οἳ τὸ πρῶτον, ὅταν χρήσωνται χειμῶσιν, οὐκέτι θαρροῦντες εἰσβαίνουσιν εἰς θάλατταν, καίπερ εἰδότες ὅτι καὶ καλοῦ πλοῦ πολλάκις ἐπιτυχεῖν ἔστιν. οὐ μὴν ἀλλ’ ἐπειδὴ συνέστηκέ σοι, καλῶς ποιεῖ. λογίζομαι γὰρ αὐτῷ συνοίσειν,", "st": "ep4.8"}, {"sp": "N", "t": "μάλιστα μὲν τῇ φιλανθρωπίᾳ τῇ σῇ στοχαζόμενος, ἣν ἔχειν ὑπείληψαι παρὰ τοῖς ἔξωθεν ἀνθρώποις, ἔπειτα νομίζων οὐκ ἀγνοεῖν ὑμᾶς ὅτι πάντων ἥδιστόν ἐστι καὶ λυσιτελέστατον πιστοὺς ἅμα καὶ χρησίμους φίλους κτᾶσθαι ταῖς εὐεργεσίαις καὶ τοὺς τοιούτους εὖ ποιεῖν, ὑπὲρ ὧν πολλοὶ καὶ τῶν ἄλλων ὑμῖν χάριν ἕξουσιν. ἅπαντες γὰρ οἱ χαρίεντες τοὺς τοῖς σπουδαίοις τῶν ἀνδρῶν καλῶς ὁμιλοῦντας ὁμοίως ἐπαινοῦσι καὶ τιμῶσιν ὥσπερ αὐτοὶ τῶν ὠφελειῶν ἀπολαύοντες.", "st": "ep4.9"}, {"sp": "N", "t": "ἀλλὰ γὰρ Διόδοτον αὐτὸν οἶμαι μάλιστά σε προτρέψεσθαι πρὸς τὸ φροντίζειν αὑτοῦ. συνέπειθον δὲ καὶ τὸν υἱὸν αὐτοῦ τῶν ὑμετέρων ἀντέχεσθαι πραγμάτων καὶ παραδόνθ’ ὑμῖν αὑτὸν ὥσπερ μαθητὴν εἰς τοὔμπροσθε πειραθῆναι προελθεῖν. ὁ δὲ ταῦτά μου λέγοντος ἐπιθυμεῖν μὲν ἔφασκε τῆς ὑμετέρας φιλίας, οὐ μὴν ἀλλὰ παραπλήσιόν τι πεπονθέναι πρὸς αὐτὴν καὶ πρὸς τοὺς στεφανίτας ἀγῶνας.", "st": "ep4.10"}, {"sp": "N", "t": "ἐκείνους τε γὰρ νικᾶν μὲν ἂν βούλεσθαι, καταβῆναι δ’ εἰς αὐτοὺς οὐκ ἂν τολμῆσαι διὰ τὸ μὴ μετεσχηκέναι ῥώμης ἀξίας τῶν στεφάνων, τῶν τε παρ’ ὑμῶν τιμῶν εὔξασθαι μὲν ἂν τυχεῖν, ἐφίξεσθαι δ’ αὐτῶν οὐ προσδοκᾶν· τήν τε γὰρ ἀπειρίαν τὴν αὑτοῦ καταπεπλῆχθαι καὶ τὴν λαμπρότητα τὴν ὑμετέραν, ἔτι δὲ καὶ τὸ σωμάτιον οὐκ εὐκρινὲς ὂν ἀλλ’ ἔχον ἄττα σίνη νομίζειν ἐμποδιεῖν αὑτὸν πρὸς πολλὰ τῶν πραγμάτων.", "st": "ep4.11"}, {"sp": "N", "t": "οὗτος μὲν οὖν, ὅ τι ἂν αὐτῷ δοκῇ συμφέρειν, τοῦτο πράξει· σὺ δ’ ἄν τε περὶ ὑμᾶς ἄν θ’ ἡσυχίαν ἔχων διατρίβῃ περὶ τούτους τοὺς τόπους, ἐπιμελοῦ καὶ τῶν ἄλλων μὲν ἁπάντων ὧν ἂν τυγχάνῃ δεόμενος, μάλιστα δὲ τῆς ἀσφαλείας καὶ τῆς τούτου καὶ τῆς τοῦ πατρὸς αὐτοῦ, νομίσας ὥσπερ παρακαταθήκην ἔχειν τούτους παρά τε τοῦ γήρως ἡμῶν, ὃ προσηκόντως ἂν πολλῆς τυγχάνοι προνοίας, καὶ τῆς δόξης τῆς ὑπαρχούσης, εἴ τινος ἄρα σπουδῆς ἐστὶν ἀξία, καὶ τῆς εὐνοίας τῆς πρὸς ὑμᾶς ἣν ἔχων ἅπαντα τὸν χρόνον διατετέλεκα.", "st": "ep4.12"}, {"sp": "N", "t": "καὶ μὴ θαυμάσῃς, μήτ’ εἰ μακροτέραν γέγραφα τὴν ἐπιστολὴν μήτ’ εἴ τι περιεργότερον καὶ πρεσβυτικώτερον εἰρήκαμεν ἐν αὐτῇ· πάντων γὰρ τῶν ἄλλων ἀμελήσας ἑνὸς μόνον ἐφρόντισα, τοῦ φανῆναι σπουδάζων ὑπὲρ ἀνδρῶν φίλων καὶ προσφιλεστάτων μοι γεγενημένων.", "st": "ep4.13"}, {"sp": "HDR", "t": "Ἐπιστολὴ Εʹ: Ἀλεξάνδρῳ", "st": "ep5"}, {"sp": "N", "t": "πρὸς τὸν πατέρα σου γράφων ἐπιστολὴν ἄτοπον ᾤμην ποιήσειν, εἰ περὶ τὸν αὐτὸν ὄντα σὲ τόπον ἐκείνῳ μήτε προσερῶ μήτ’ ἀσπάσομαι μήτε γράψω τι τοιοῦτον, ὃ ποιήσει τοὺς ἀναγνόντας μὴ νομίζειν ἤδη με παραφρονεῖν διὰ τὸ γῆρας μηδὲ παντάπασι ληρεῖν, ἀλλ’ ἔτι τὸ καταλελειμμένον μου μέρος καὶ λοιπὸν ὂν οὐκ ἀνάξιον εἶναι τῆς δυνάμεως ἣν ἔσχον νεώτερος ὤν.", "st": "ep5.1"}, {"sp": "N", "t": "ἀκούω δέ σε πάντων λεγόντων ὡς φιλάνθρωπος εἶ καὶ φιλαθήναιος καὶ φιλόσοφος, οὐκ ἀφρόνως ἀλλὰ νοῦν ἐχόντως. τῶν τε γὰρ πολιτῶν ἀποδέχεσθαί σε τῶν ἡμετέρων οὐ τοὺς ἠμεληκότας αὑτῶν καὶ πονηρῶν πραγμάτων ἐπιθυμοῦντας, ἀλλ’ οἷς συνδιατρίβων τ’ οὐκ ἂν λυπηθείης, συμβάλλων τε καὶ κοινωνῶν πραγμάτων οὐδὲν ἂν βλαβείης οὐδ’ ἀδικηθείης, οἵοις περ χρὴ πλησιάζειν τοὺς εὖ φρονοῦντας·", "st": "ep5.2"}, {"sp": "N", "t": "τῶν τε φιλοσοφιῶν οὐκ ἀποδοκιμάζειν μὲν οὐδὲ τὴν περὶ τὰς ἔριδας, ἀλλὰ νομίζειν εἶναι πλεονεκτικὴν ἐν ταῖς ἰδίαις διατριβαῖς, οὐ μὴν ἁρμόττειν οὔτε τοῖς τοῦ πλήθους προεστῶσιν οὔτε τοῖς τὰς μοναρχίας ἔχουσιν· οὐδὲ γὰρ συμφέρον οὐδὲ πρέπον ἐστὶ τοῖς μεῖζον τῶν ἄλλων φρονοῦσιν οὔτ’ αὐτοῖς ἐρίζειν πρὸς τοὺς συμπολιτευομένους οὔτε τοῖς ἄλλοις ἐπιτρέπειν πρὸς αὑτοὺς ἀντιλέγειν.", "st": "ep5.3"}, {"sp": "N", "t": "ταύτην μὲν οὖν οὐκ ἀγαπᾶν σε τὴν διατριβήν, προαιρεῖσθαι δὲ τὴν παιδείαν τὴν περὶ τοὺς λόγους, οἷς χρώμεθα περὶ τὰς πράξεις τὰς προσπιπτούσας καθ’ ἑκάστην τὴν ἡμέραν καὶ μεθ’ ὧν βουλευόμεθα περὶ τῶν κοινῶν· δι’ ἣν νῦν τε δοξάζειν περὶ τῶν μελλόντων ἐπιεικῶς, τοῖς τ’ ἀρχομένοις προστάττειν οὐκ ἀνοήτως ἃ δεῖ πράττειν ἑκάστους, ἐπιστήσει, περὶ δὲ τῶν καλῶν καὶ δικαίων καὶ τῶν τούτοις ἐναντίων ὀρθῶς κρίνειν, πρὸς δὲ τούτοις τιμᾶν τε καὶ κολάζειν ὡς προσῆκόν ἐστιν ἑκατέρους.", "st": "ep5.4"}, {"sp": "N", "t": "σωφρονεῖς οὖν νῦν ταῦτα μελετῶν· ἐλπίδας γὰρ τῷ τε πατρὶ καὶ τοῖς ἄλλοις παρέχεις, ὡς, ἂν πρεσβύτερος γενόμενος ἐμμείνῃς τούτοις, τοσοῦτον προέξεις τῇ φρονήσει τῶν ἄλλων, ὅσον περ ὁ πατήρ σου διενήνοχεν ἁπάντων.", "st": "ep5.5"}, {"sp": "HDR", "t": "Ἐπιστολὴ Ϛʹ: Τοῖς Ἰάσονος παισίν", "st": "ep6"}, {"sp": "N", "t": "ἀπήγγειλέ τίς μοι τῶν πρεσβευσάντων ὡς ὑμᾶς ὅτι καλέσαντες αὐτὸν ἄνευ τῶν ἄλλων ἐρωτήσαιτ’ εἰ πεισθείην ἂν ἀποδημῆσαι καὶ διατρῖψαι παρ’ ὑμῖν. ἐγὼ δ’ ἕνεκα μὲν τῆς Ἰάσονος καὶ Πολυαλκοῦς ξενίας ἡδέως ἂν ἀφικοίμην ὡς ὑμᾶς· οἶμαι γὰρ ἂν τὴν ὁμιλίαν τὴν γενομένην ἅπασιν ἡμῖν συνενεγκεῖν· ἀλλὰ γὰρ ἐμποδίζει με πολλά,", "st": "ep6.1"}, {"sp": "N", "t": "μάλιστα μὲν τὸ μὴ δύνασθαι πλανᾶσθαι καὶ τὸ μὴ πρέπειν ἐπιξενοῦσθαι τοῖς τηλικούτοις, ἔπειθ’ ὅτι πάντες οἱ πυθόμενοι τὴν ἀποδημίαν δικαίως ἄν μου καταφρονήσειαν, εἰ προῃρημένος τὸν ἄλλον χρόνον ἡσυχίαν ἄγειν ἐπὶ γήρως ἀποδημεῖν ἐπιχειροίην, ὅτ’ εἰκὸς ἦν, εἰ καὶ πρότερον ἄλλοθί που διέτριβον, νῦν οἴκαδε σπεύδειν, οὕτως ὑπογυίου μοι τῆς τελευτῆς οὔσης.", "st": "ep6.2"}, {"sp": "N", "t": "πρὸς δὲ τούτοις φοβοῦμαι καὶ τὴν πόλιν· χρὴ γὰρ τἀληθῆ λέγειν. ὁρῶ γὰρ τὰς συμμαχίας τὰς πρὸς αὐτὴν γιγνομένας ταχέως διαλυομένας. εἰ δή τι συμβαίη καὶ πρὸς ὑμᾶς τοιοῦτον, εἰ καὶ τὰς αἰτίας καὶ τοὺς κινδύνους διαφυγεῖν δυνηθείην, ὃ χαλεπόν ἐστιν, ἀλλ’ οὖν αἰσχυνθείην ἄν, εἴτε διὰ τὴν πόλιν δόξαιμί τισιν ὑμῶν ἀμελεῖν, εἴτε δι’ ὑμᾶς τῆς πόλεως ὀλιγωρεῖν. μὴ κοινοῦ δὲ τοῦ συμφέροντος ὄντος οὐκ οἶδ’ ὅπως ἂν ἀμφοτέροις ἀρέσκειν δυνηθείην. αἱ μὲν οὖν αἰτίαι, δι’ ἃς οὐκ ἔξεστί μοι ποιεῖν ἃ βούλομαι, τοιαῦται συμβεβήκασιν.", "st": "ep6.3"}, {"sp": "N", "t": "οὐ μὴν περὶ τῶν ἐμαυτοῦ μόνον ἐπιστείλας οἶμαι δεῖν ἀμελῆσαι τῶν ὑμετέρων, ἀλλ’ ἅπερ ἂν παραγενόμενος πρὸς ὑμᾶς διελέχθην, πειράσομαι καὶ νῦν περὶ τῶν αὐτῶν τούτων ὅπως ἂν δύνωμαι διεξελθεῖν. μηδὲν δ’ ὑπολάβητε τοιοῦτον, ὡς ἄρ’ ἐγὼ ταύτην ἔγραψα τὴν ἐπιστολὴν οὐχ ἕνεκα τῆς ὑμετέρας ξενίας, ἀλλ’ ἐπίδειξιν ποιήσασθαι βουλόμενος. οὐ γὰρ εἰς τοῦθ’ ἥκω μανίας ὥστ’ ἀγνοεῖν ὅτι κρείττω μὲν γράψαι τῶν πρότερον διαδεδομένων οὐκ ἂν δυναίμην, τοσοῦτον τῆς ἀκμῆς ὑστερῶν, χείρω δ’ ἐξενεγκὼν πολὺ φαυλοτέραν ἂν λάβοιμι δόξαν τῆς νῦν ἡμῖν ὑπαρχούσης.", "st": "ep6.4"}, {"sp": "N", "t": "ἔπειτ’ εἴπερ ἐπιδείξει προσεῖχον τὸν νοῦν ἀλλὰ μὴ πρὸς ὑμᾶς ἐσπούδαζον, οὐκ ἂν ταύτην ἐξ ἁπασῶν προειλόμην τὴν ὑπόθεσιν, περὶ ἧς χαλεπόν ἐστιν ἐπιεικῶς εἰπεῖν, ἀλλὰ πολὺ καλλίους ἑτέρας ἂν εὗρον καὶ μᾶλλον λόγον ἐχούσας. ἀλλὰ γὰρ οὔτε πρότερον οὐδὲ πώποτ’ ἐφιλοτιμήθην ἐπὶ τούτοις, ἀλλ’ ἐφ’ ἑτέροις μᾶλλον, ἃ τοὺς πολλοὺς διαλέληθεν, οὔτε νῦν ἔχων ταύτην τὴν διάνοιαν ἐπραγματευσάμην,", "st": "ep6.5"}, {"sp": "N", "t": "ἀλλ’ ὑμᾶς μὲν ὁρῶν ἐν πολλοῖς καὶ μεγάλοις πράγμασιν ὄντας, αὐτὸς δ’ ἀποφήνασθαι βουλόμενος ἣν ἔχω γνώμην περὶ αὐτῶν. ἡγοῦμαι δὲ συμβουλεύειν μὲν ἀκμὴν ἔχειν, αἱ γὰρ ἐμπειρίαι παιδεύουσι τοὺς τηλικούτους καὶ ποιοῦσι μᾶλλον τῶν ἄλλων δύνασθαι καθορᾶν τὸ βέλτιστον, εἰπεῖν δὲ περὶ τῶν προτεθέντων ἐπιχαρίτως καὶ μουσικῶς καὶ διαπεπονημένως οὐκέτι τῆς ἡμετέρας ἡλικίας ἐστίν, ἀλλ’ ἀγαπῴην ἄν, εἰ μὴ παντάπασιν ἐκλελυμένως διαλεχθείην περὶ αὐτῶν.", "st": "ep6.6"}, {"sp": "N", "t": "μὴ θαυμάζετε δ’ ἄν τι φαίνωμαι λέγων ὧν πρότερον ἀκηκόατε· τῷ μὲν γὰρ ἴσως ἄκων ἂν ἐντύχοιμι, τὸ δὲ καὶ προειδώς, εἰ πρέπον εἰς τὸν λόγον εἴη, προσλάβοιμι· καὶ γὰρ ἂν ἄτοπος εἴην, εἰ τοὺς ἄλλους ὁρῶν τοῖς ἐμοῖς χρωμένους αὐτὸς μόνος ἀπεχοίμην τῶν ὑπ’ ἐμοῦ πρότερον εἰρημένων. τούτου δ’ ἕνεκα ταῦτα προεῖπον, ὅτι τὸ πρῶτον ἐπιφερόμενον ἓν τῶν τεθρυλημένων ἐστίν.", "st": "ep6.7"}, {"sp": "N", "t": "εἴθισμαι γὰρ λέγειν πρὸς τοὺς περὶ τὴν φιλοσοφίαν τὴν ἡμετέραν διατρίβοντας ὅτι τοῦτο πρῶτον δεῖ σκέψασθαι, τί τῷ λόγῳ καὶ τοῖς τοῦ λόγου μέρεσι διαπρακτέον ἐστίν· ἐπειδὰν δὲ τοῦθ’ εὕρωμεν καὶ διακριβωσώμεθα, ζητητέον εἶναί φημι τὰς ἰδέας δι’ ὧν ταῦτ’ ἐξεργασθήσεται καὶ λήψεται τέλος ὅπερ ὑπεθέμεθα. καὶ ταῦτα φράζω μὲν ἐπὶ τῶν λόγων, ἔστι δὲ τοῦτο στοιχεῖον καὶ κατὰ τῶν ἄλλων ἁπάντων καὶ κατὰ τῶν ὑμετέρων πραγμάτων. οὐδὲν γὰρ οἷόν τ’ ἐστὶ πραχθῆναι νοῦν ἐχόντως,", "st": "ep6.8"}, {"sp": "N", "t": "ἂν μὴ τοῦτο πρῶτον μετὰ πολλῆς προνοίας λογίσησθε καὶ βουλεύσησθε, πῶς χρὴ τὸν ἐπίλοιπον χρόνον ὑμῶν αὐτῶν προστῆναι καὶ τίνα βίον προελέσθαι καὶ ποίας δόξης ὀριγνηθῆναι καὶ ποτέρας τῶν τιμῶν ἀγαπῆσαι, τὰς παρ’ ἑκόντων γιγνομένας ἢ τὰς παρ’ ἀκόντων τῶν πολιτῶν· ταῦτα δὲ διορισαμένους τότ’ ἤδη τὰς πράξεις τὰς καθ’ ἑκάστην τὴν ἡμέραν σκεπτέον, ὅπως συντενοῦσι πρὸς τὰς ὑποθέσεις τὰς ἐξ ἀρχῆς γενομένας.", "st": "ep6.9"}, {"sp": "N", "t": "καὶ τοῦτον μὲν τὸν τρόπον ζητοῦντες καὶ φιλοσοφοῦντες ὥσπερ σκοποῦ κειμένου στοχάσεσθε τῇ ψυχῇ καὶ μᾶλλον ἐπιτεύξεσθε τοῦ συμφέροντος· ἂν δὲ μηδεμίαν ποιήσησθε τοιαύτην ὑπόθεσιν, ἀλλὰ τὸ προσπῖπτον ἐπιχειρῆτε πράττειν, ἀναγκαῖόν ἐστιν ὑμᾶς ταῖς διανοίαις πλανᾶσθαι καὶ πολλῶν διαμαρτάνειν πραγμάτων.", "st": "ep6.10"}, {"sp": "N", "t": "ἴσως ἂν οὖν τις τῶν εἰκῇ ζῆν προῃρημένων τοὺς μὲν τοιούτους λογισμοὺς διασύρειν ἐπιχειρήσειεν, ἀξιώσειε δ’ ἂν ἤδη με συμβουλεύειν περὶ τῶν προειρημένων. ἔστιν οὖν οὐκ ὀκνητέον ἀποφήνασθαι περὶ αὐτῶν ἃ τυγχάνω γιγνώσκων. ἐμοὶ γὰρ αἱρετώτερος ὁ βίος εἶναι δοκεῖ καὶ βελτίων ὁ τῶν ἰδιωτευόντων ἢ τῶν τυραννούντων, καὶ τὰς τιμὰς ἡδίους ἡγοῦμαι τὰς ἐν ταῖς πολιτείαις ἢ τὰς ἐν ταῖς μοναρχίαις· καὶ περὶ τούτων λέγειν ἐπιχειρήσω.", "st": "ep6.11"}, {"sp": "N", "t": "καίτοι μ’ οὐ λέληθεν ὅτι πολλοὺς ἕξω τοὺς ἐναντιουμένους, καὶ μάλιστα τοὺς περὶ ὑμᾶς ὄντας. οἶμαι γὰρ οὐχ ἥκιστα τούτους ἐπὶ τὴν τυραννίδα παροξύνειν ὑμᾶς· σκοποῦσι γὰρ οὐ πανταχῇ τὴν φύσιν τοῦ πράγματος, ἀλλὰ πολλὰ παραλογίζονται σφᾶς αὐτούς. τὰς μὲν γὰρ ἐξουσίας καὶ τὰ κέρδη καὶ τὰς ἡδονὰς ὁρῶσι καὶ τούτων ἀπολαύσεσθαι προσδοκῶσι, τὰς δὲ ταραχὰς καὶ τοὺς φόβους καὶ τὰς συμφορὰς τὰς τοῖς ἄρχουσι συμπιπτούσας καὶ τοῖς φίλοις αὐτῶν οὐ θεωροῦσιν, ἀλλὰ πεπόνθασιν ὅπερ οἱ τοῖς αἰσχίστοις καὶ παρανομωτάτοις τῶν ἔργων ἐπιχειροῦντες.", "st": "ep6.12"}, {"sp": "N", "t": "καὶ γὰρ ἐκεῖνοι τὰς μὲν πονηρίας τὰς τῶν πραγμάτων οὐκ ἀγνοοῦσιν, ἐλπίζουσι δ’ ὅσον μὲν ἀγαθόν ἐστιν ἐν αὐτοῖς, τοῦτο μὲν ἐκλήψεσθαι, τὰ δὲ δεινὰ πάντα τὰ προσόντα τῷ πράγματι καὶ τὰ κακὰ διαφεύξεσθαι, καὶ διοικήσειν τὰ περὶ σφᾶς αὐτοὺς οὕτως, ὥστε τῶν μὲν κινδύνων εἶναι πόρρω, τῶν δ’ ὠφελειῶν ἐγγύς.", "st": "ep6.13"}, {"sp": "N", "t": "τοὺς μὲν οὖν ταύτην ἔχοντας τὴν διάνοιαν ζηλῶ τῆς ῥᾳθυμίας, αὐτὸς δ’ αἰσχυνθείην ἄν, εἰ συμβουλεύων ἑτέροις ἐκείνων ἀμελήσας τὸ ἐμαυτῷ συμφέρον ποιοίην καὶ μὴ παντάπασιν ἔξω θεὶς ἐμαυτὸν καὶ τῶν ὠφελειῶν καὶ τῶν ἄλλων ἁπάντων τὰ βέλτιστα παραινοίην. ὡς οὖν ἐμοῦ ταύτην ἔχοντος τὴν γνώμην, οὕτω μοι προσέχετε τὸν νοῦν. …", "st": "ep6.14"}, {"sp": "HDR", "t": "Ἐπιστολὴ Ζʹ: Τιμοθέῳ", "st": "ep7"}, {"sp": "N", "t": "περὶ μὲν τῆς οἰκειότητος τῆς ὑπαρχούσης ἡμῖν πρὸς ἀλλήλους οἶμαί σε πολλῶν ἀκηκοέναι, συγχαίρω δέ σοι πυνθανόμενος, πρῶτον μὲν ὅτι τῇ δυναστείᾳ τῇ παρούσῃ κάλλιον χρῇ τοῦ πατρὸς καὶ φρονιμώτερον, ἔπειθ’ ὅτι προαιρεῖ δόξαν καλὴν κτήσασθαι μᾶλλον ἢ πλοῦτον μέγαν συναγαγεῖν. σημεῖον γὰρ οὐ μικρὸν ἐκφέρεις ἀρετῆς, ἀλλ’ ὡς δυνατὸν μέγιστον, ταύτην ἔχων τὴν γνώμην· ὥστ’ ἢν ἐμμείνῃς τοῖς περὶ σοῦ νῦν λεγομένοις, οὐκ ἀπορήσεις τῶν ἐγκωμιασομένων τήν τε φρόνησιν τὴν σὴν καὶ τὴν προαίρεσιν ταύτην.", "st": "ep7.1"}, {"sp": "N", "t": "ἡγοῦμαι δὲ καὶ τὰ διηγγελμένα περὶ τοῦ πατρός σου συμβαλεῖσθαι μεγάλην πίστιν πρὸς τὸ δοκεῖν εὖ φρονεῖν σε καὶ διαφέρειν τῶν ἄλλων· εἰώθασι γὰρ οἱ πλεῖστοι τῶν ἀνθρώπων οὐχ οὕτως ἐπαινεῖν καὶ τιμᾶν τοὺς ἐκ τῶν πατέρων τῶν εὐδοκιμούντων γεγονότας, ὡς τοὺς ἐκ τῶν δυσκόλων καὶ χαλεπῶν, ἤν περ φαίνωνται μηδὲν ὅμοιοι τοῖς γονεῦσιν ὄντες. μᾶλλον γὰρ ἐπὶ πάντων κεχαρισμένον αὐτοῖς ἐστὶ τὸ παρὰ λόγον συμβαῖνον ἀγαθὸν τῶν εἰκότως καὶ προσηκόντως γιγνομένων.", "st": "ep7.2"}, {"sp": "N", "t": "ὧν ἐνθυμούμενον χρὴ ζητεῖν καὶ φιλοσοφεῖν ἐξ ὅτου τρόπου καὶ μετὰ τίνων καὶ τίσι συμβούλοις χρώμενος τάς τε τῆς πόλεως ἀτυχίας ἐπανορθώσεις καὶ τοὺς πολίτας ἐπί τε τὰς ἐργασίας καὶ τὴν σωφροσύνην προτρέψεις καὶ ποιήσεις αὐτοὺς ἥδιον ζῆν καὶ θαρραλεώτερον ἢ τὸν παρελθόντα χρόνον· ταῦτα γάρ ἐστιν ἔργα τῶν ὀρθῶς καὶ φρονίμως τυραννευόντων.", "st": "ep7.3"}, {"sp": "N", "t": "ὧν ἔνιοι καταφρονήσαντες οὐδὲν ἄλλο σκοποῦσι, πλὴν ὅπως αὐτοί θ’ ὡς μετὰ πλείστης ἀσελγείας τὸν βίον διάξουσι, τῶν τε πολιτῶν τοὺς βελτίστους καὶ πλουσιωτάτους καὶ φρονιμωτάτους λυμανοῦνται καὶ δασμολογήσουσι, κακῶς εἰδότες ὅτι προσήκει τοὺς εὖ φρονοῦντας καὶ τὴν τιμὴν ταύτην ἔχοντας μὴ τοῖς τῶν ἄλλων κακοῖς αὑτοῖς ἡδονὰς παρασκευάζειν, ἀλλὰ ταῖς αὑτῶν ἐπιμελείαις τοὺς πολίτας εὐδαιμονεστέρους ποιεῖν,", "st": "ep7.4"}, {"sp": "N", "t": "μηδὲ πικρῶς μὲν καὶ χαλεπῶς διακεῖσθαι πρὸς ἅπαντας, ἀμελεῖν δὲ τῆς αὑτῶν σωτηρίας, ἀλλ’ οὕτω μὲν πράως καὶ νομίμως ἐπιστατεῖν τῶν πραγμάτων ὥστε μηδένα τολμᾶν αὐτοῖς ἐπιβουλεύειν, μετὰ τοσαύτης δ’ ἀκριβείας τὴν τοῦ σώματος ποιεῖσθαι φυλακὴν ὡς ἁπάντων αὐτοὺς ἀνελεῖν βουλομένων. ταύτην γὰρ τὴν διάνοιαν ἔχοντες αὐτοί τ’ ἂν ἔξω τῶν κινδύνων εἶεν καὶ παρὰ τοῖς ἄλλοις εὐδοκιμοῖεν· ὧν ἀγαθὰ μείζω χαλεπὸν εὑρεῖν ἐστίν.", "st": "ep7.5"}, {"sp": "N", "t": "ἐνεθυμήθην δὲ μεταξὺ γράφων, ὡς εὐτυχῶς ἅπαντά σοι συμβέβηκεν. τὴν μὲν γὰρ εὐπορίαν ἣν ἀναγκαῖον ἦν κτήσασθαι μετὰ βίας καὶ τυραννικῶς καὶ μετὰ πολλῆς ἀπεχθείας ὁ πατήρ σοι καταλέλοιπε, τὸ δὲ χρῆσθαι τούτοις καλῶς καὶ φιλανθρώπως ἐπὶ σοὶ γέγονεν· ὧν χρή σε πολλὴν ποιεῖσθαι τὴν ἐπιμέλειαν.", "st": "ep7.6"}, {"sp": "N", "t": "ἃ μὲν οὖν ἐγὼ γιγνώσκω, ταῦτ’ ἐστίν· ἔχει δ’ οὕτως. εἰ μὲν ἐρᾷς χρημάτων καὶ μείζονος δυναστείας καὶ κινδύνων δι’ ὧν αἱ κτήσεις τούτων εἰσίν, ἑτέρους σοι συμβούλους παρακλητέον· εἰ δὲ ταῦτα μὲν ἱκανῶς ἔχεις, ἀρετῆς δὲ καὶ δόξης καλῆς καὶ τῆς παρὰ τῶν πολλῶν εὐνοίας ἐπιθυμεῖς, τοῖς τε λόγοις τοῖς ἐμοῖς προσεκτέον τὸν νοῦν ἐστὶ καὶ τοῖς καλῶς τὰς πόλεις τὰς αὑτῶν διοικοῦσιν ἁμιλλητέον καὶ πειρατέον αὐτῶν διενεγκεῖν.", "st": "ep7.7"}, {"sp": "N", "t": "ἀκούω δὲ Κλέομμιν τὸν ἐν Μηθύμνῃ ταύτην ἔχοντα τὴν δυναστείαν περί τε τὰς ἄλλας πράξεις καλὸν κἀγαθὸν εἶναι καὶ φρόνιμον, καὶ τοσοῦτον ἀπέχειν τοῦ τῶν πολιτῶν τινας ἀποκτείνειν ἢ φυγαδεύειν ἢ δημεύειν τὰς οὐσίας ἢ ποιεῖν ἄλλο τι κακόν, ὥστε πολλὴν μὲν ἀσφάλειαν παρέχειν τοῖς συμπολιτευομένοις, κατάγειν δὲ τοὺς φεύγοντας, ἀποδιδόναι δὲ τοῖς μὲν κατιοῦσι τὰς κτήσεις ἐξ ὧν ἐξέπεσον,", "st": "ep7.8"}, {"sp": "N", "t": "τοῖς δὲ πριαμένοις τὰς τιμὰς τὰς ἑκάστοις γιγνομένας, πρὸς δὲ τούτοις καθοπλίζειν ἅπαντας τοὺς πολίτας, ὡς οὐδενὸς μὲν ἐπιχειρήσοντος περὶ αὐτὸν νεωτερίζειν, ἢν δ’ ἄρα τινὲς τολμήσωσιν, ἡγούμενον λυσιτελεῖν αὑτῷ τεθνάναι τοιαύτην ἀρετὴν ἐνδειξαμένῳ τοῖς πολίταις μᾶλλον ἢ ζῆν πλείω χρόνον τῇ πόλει τῶν μεγίστων κακῶν αἴτιον γενόμενον.", "st": "ep7.9"}, {"sp": "N", "t": "ἔτι δ’ ἂν πλείω σοι περὶ τούτων διελέχθην, ἴσως δ’ ἂν καὶ χαριέστερον, εἰ μὴ παντάπασιν ἔδει με διὰ ταχέων γράψαι τὴν ἐπιστολήν. νῦν δὲ σοὶ μὲν αὖθις συμβουλεύσομεν, ἂν μὴ κωλύσῃ με τὸ γῆρας, ἐν δὲ τῷ παρόντι περὶ τῶν ἰδίων δηλώσομεν. αὐτοκράτωρ γὰρ ὁ τὰ γράμματα φέρων οἰκείως ἡμῖν ἔχει·", "st": "ep7.10"}, {"sp": "N", "t": "περί τε γὰρ τὰς διατριβὰς τὰς αὐτὰς γεγόναμεν καὶ τῇ τέχνῃ πολλάκις αὐτοῦ κέχρημαι καὶ τὸ τελευταῖον περὶ τῆς ἀποδημίας τῆς ὡς σὲ σύμβουλος ἐγενόμην αὐτῷ. διὰ δὴ ταῦτα πάντα βουλοίμην ἄν σε καλῶς αὐτῷ χρήσασθαι καὶ συμφερόντως ἀμφοτέροις ἡμῖν, καὶ γενέσθαι φανερόν, ὅτι μέρος τι καὶ δι’ ἐμὲ γίγνεταί τι τῶν δεόντων αὐτῷ.", "st": "ep7.11"}, {"sp": "N", "t": "καὶ μὴ θαυμάσῃς, εἰ σοὶ μὲν οὕτως ἐπιστέλλω προθύμως, Κλεάρχου δὲ μηδὲν πώποτ’ ἐδεήθην. σχεδὸν γὰρ ἅπαντες οἱ παρ’ ὑμῶν καταπλέοντες σὲ μὲν ὅμοιόν φασιν εἶναι τοῖς βελτίστοις τῶν ἐμοὶ πεπλησιακότων, Κλέαρχον δὲ κατὰ μὲν ἐκεῖνον τὸν χρόνον, ὅτ’ ἦν παρ’ ἡμῖν, ὡμολόγουν, ὅσοι περ ἐνέτυχον, ἐλευθεριώτατον εἶναι καὶ πραότατον καὶ φιλανθρωπότατον τῶν μετεχόντων τῆς διατριβῆς· ἐπειδὴ δὲ τὴν δύναμιν ἔλαβε, τοσοῦτον ἔδοξε μεταπεσεῖν ὥστε πάντας θαυμάζειν τοὺς πρότερον αὐτὸν γιγνώσκοντας.", "st": "ep7.12"}, {"sp": "N", "t": "πρὸς μὲν οὖν ἐκεῖνον διὰ ταύτας τὰς αἰτίας ἀπηλλοτριώθην· σὲ δ’ ἀποδέχομαι καὶ πρὸ πολλοῦ ποιησαίμην ἂν οἰκείως διατεθῆναι πρὸς ἡμᾶς. δηλώσεις δὲ καὶ σὺ διὰ ταχέων, εἰ τὴν αὐτὴν γνώμην ἔχεις ἡμῖν· αὐτοκράτορός τε γὰρ ἐπιμελήσει καὶ πέμψεις ἐπιστολὴν ὡς ἡμᾶς, ἀνανεούμενος τὴν φιλίαν καὶ ξενίαν τὴν πρότερον ὑπάρχουσαν. ἔρρωσο, κἄν του δέῃ τῶν παρ’ ἡμῖν, ἐπίστελλε.", "st": "ep7.13"}, {"sp": "HDR", "t": "Ἐπιστολὴ Ηʹ: Τοῖς Μυτιληναίων ἄρχουσιν", "st": "ep8"}, {"sp": "N", "t": "οἱ παῖδες οἱ Ἀφαρέως, ὑιδεῖς δ’ ἐμοί, παιδευθέντες ὑπ’ Ἀγήνορος τὰ περὶ τὴν μουσικήν, ἐδεήθησάν μου γράμματα πέμψαι πρὸς ὑμᾶς, ὅπως ἄν, ἐπειδὴ καὶ τῶν ἄλλων τινὰς κατηγάγετε φυγάδων, καὶ τοῦτον καταδέξησθε καὶ τὸν πατέρα καὶ τοὺς ἀδελφούς. λέγοντος δέ μου πρὸς αὐτοὺς ὅτι δέδοικα μὴ λίαν ἄτοπος εἶναι δόξω καὶ περίεργος, ζητῶν εὑρίσκεσθαι τηλικαῦτα τὸ μέγεθος παρ’ ἀνδρῶν οἷς οὐδὲ πώποτε πρότερον οὔτε διελέχθην οὔτε συνήθης ἐγενόμην, ἀκούσαντες ταῦτα πολὺ μᾶλλον ἐλιπάρουν.", "st": "ep8.1"}, {"sp": "N", "t": "ὡς δ’ οὐδὲν αὐτοῖς ἀπέβαινεν ὧν ἤλπιζον, ἅπασιν ἦσαν καταφανεῖς ἀηδῶς διακείμενοι καὶ χαλεπῶς φέροντες. ὁρῶν δ’ αὐτοὺς λυπουμένους μᾶλλον τοῦ προσήκοντος, τελευτῶν ὑπεσχόμην γράψειν τὴν ἐπιστολὴν καὶ πέμψειν ὑμῖν. ὑπὲρ μὲν οὖν τοῦ μὴ δικαίως ἂν δοκεῖν μωρὸς εἶναι μηδ’ ὀχληρὸς ταῦτ’ ἔχω λέγειν.", "st": "ep8.2"}, {"sp": "N", "t": "ἡγοῦμαι δὲ καλῶς ὑμᾶς βεβουλεῦσθαι καὶ διαλλαττομένους τοῖς πολίταις τοῖς ὑμετέροις, καὶ πειρωμένους τοὺς μὲν φεύγοντας ὀλίγους ποιεῖν, τοὺς δὲ συμπολιτευομένους πολλούς, καὶ μιμουμένους τὰ περὶ τὴν στάσιν τὴν πόλιν τὴν ἡμετέραν. μάλιστα δ’ ἄν τις ὑμᾶς ἐπαινέσειεν ὅτι τοῖς κατιοῦσιν ἀποδίδοτε τὴν οὐσίαν· ἐπιδείκνυσθε γὰρ καὶ ποιεῖτε πᾶσι φανερὸν ὡς οὐ τῶν κτημάτων ἐπιθυμήσαντες τῶν ἀλλοτρίων, ἀλλ’ ὑπὲρ τῆς πόλεως δείσαντες ἐποιήσασθε τὴν ἐκβολὴν αὐτῶν.", "st": "ep8.3"}, {"sp": "N", "t": "οὐ μὴν ἀλλ’ εἰ καὶ μηδὲν ὑμῖν ἔδοξε τούτων μηδὲ προσεδέχεσθε μηδένα τῶν φυγάδων, τούτους γε νομίζω συμφέρειν ὑμῖν κατάγειν. αἰσχρὸν γὰρ τὴν μὲν πόλιν ὑμῶν ὑπὸ πάντων ὁμολογεῖσθαι μουσικωτάτην εἶναι καὶ τοὺς ὀνομαστοτάτους ἐν αὐτῇ παρ’ ὑμῖν τυγχάνειν γεγονότας, τὸν δὲ προέχοντα τῶν νῦν ὄντων περὶ τὴν ἱστορίαν τῆς παιδείας ταύτης φεύγειν ἐκ τῆς τοιαύτης πόλεως, καὶ τοὺς μὲν ἄλλους Ἕλληνας τοὺς διαφέροντας περί τι τῶν καλῶν ἐπιτηδευμάτων, κἂν μηδὲν προσήκωσι, ποιεῖσθαι πολίτας, ὑμᾶς δὲ τοὺς εὐδοκιμοῦντάς τε παρὰ τοῖς ἄλλοις καὶ μετασχόντας τῆς αὐτῆς φύσεως περιορᾶν παρ’ ἑτέροις μετοικοῦντας.", "st": "ep8.4"}, {"sp": "N", "t": "θαυμάζω δ’ ὅσαι τῶν πόλεων μειζόνων δωρεῶν ἀξιοῦσι τοὺς ἐν τοῖς γυμνικοῖς ἀγῶσι κατορθοῦντας μᾶλλον ἢ τοὺς τῇ φρονήσει καὶ τῇ φιλοπονίᾳ τι τῶν χρησίμων εὑρίσκοντας, καὶ μὴ συνορῶσιν ὅτι πεφύκασιν αἱ μὲν περὶ τὴν ῥώμην καὶ τὸ τάχος δυνάμεις συναποθνῄσκειν τοῖς σώμασιν, αἱ δ’ ἐπιστῆμαι παραμένειν ἅπαντα τὸν χρόνον ὠφελοῦσαι τοὺς χρωμένους αὐταῖς.", "st": "ep8.5"}, {"sp": "N", "t": "ὧν ἐνθυμουμένους χρὴ τοὺς νοῦν ἔχοντας περὶ πλείστου μὲν ποιεῖσθαι τοὺς καλῶς καὶ δικαίως τῆς αὑτῶν πόλεως ἐπιστατοῦντας, δευτέρους δὲ τοὺς τιμὴν καὶ δόξαν αὐτῇ καλὴν συμβαλέσθαι δυναμένους· ἅπαντες γὰρ ὥσπερ δείγματι τοῖς τοιούτοις χρώμενοι καὶ τοὺς ἄλλους τοὺς συμπολιτευομένους ὁμοίους εἶναι τούτοις νομίζουσιν.", "st": "ep8.6"}, {"sp": "N", "t": "ἴσως οὖν εἴποι τις ἂν ὅτι προσήκει τοὺς εὑρέσθαι τι βουλομένους μὴ τὸ πρᾶγμα μόνον ἐπαινεῖν ἀλλὰ καὶ σφᾶς αὐτοὺς ἐπιδεικνύναι δικαίως ἂν τυγχάνοντας, περὶ ὧν ποιοῦνται τοὺς λόγους. ἔχει δ’ οὕτως. ἐγὼ τοῦ μὲν πολιτεύεσθαι καὶ ῥητορεύειν ἀπέστην· οὔτε γὰρ φωνὴν ἔσχον ἱκανὴν οὔτε τόλμαν· οὐ μὴν παντάπασιν ἄχρηστος ἔφυν οὐδ’ ἀδόκιμος, ἀλλὰ τοῖς τε λέγειν προῃρημένοις ἀγαθόν τι περὶ ὑμῶν καὶ τῶν ἄλλων συμμάχων φανείην ἂν καὶ σύμβουλος καὶ συναγωνιστὴς γεγενημένος, αὐτός τε πλείους λόγους πεποιημένος ὑπὲρ τῆς ἐλευθερίας καὶ τῆς αὐτονομίας τῆς τῶν Ἑλλήνων ἢ σύμπαντες οἱ τὰ βήματα κατατετριφότες.", "st": "ep8.7"}, {"sp": "N", "t": "ὑπὲρ ὧν ὑμεῖς ἄν μοι δικαίως πλείστην ἔχοιτε χάριν· μάλιστα γὰρ ἐπιθυμοῦντες διατελεῖτε τῆς τοιαύτης καταστάσεως. οἶμαι δ’ ἄν, εἰ Κόνων μὲν καὶ Τιμόθεος ἐτύγχανον ζῶντες, Διόφαντος δ’ ἧκεν ἐκ τῆς Ἀσίας, πολλὴν ἂν αὐτοὺς ποιήσασθαι σπουδήν, εὑρέσθαι με βουλομένους ὧν τυγχάνω δεόμενος. περὶ ὧν οὐκ οἶδ’ ὅ τι δεῖ πλείω λέγειν· οὐδεὶς γὰρ ὑμῶν οὕτως ἐστὶ νέος οὐδ’ ἐπιλήσμων, ὅστις οὐκ οἶδε τὰς ἐκείνων εὐεργεσίας.", "st": "ep8.8"}, {"sp": "N", "t": "οὕτω δ’ ἄν μοι δοκεῖτε κάλλιστα βουλεύσασθαι περὶ τούτων, εἰ σκέψαισθε, τίς ἐστιν ὁ δεόμενος καὶ ὑπὲρ ποίων τινῶν ἀνθρώπων. εὑρήσετε γὰρ ἐμὲ μὲν οἰκειότατα κεχρημένον τοῖς μεγίστων ἀγαθῶν αἰτίοις γεγενημένοις ὑμῖν τε καὶ τοῖς ἄλλοις, ὑπὲρ ὧν δὲ δέομαι τοιούτους ὄντας, οἵους τοὺς μὲν πρεσβυτέρους καὶ τοὺς περὶ τὴν πολιτείαν ὄντας μὴ λυπεῖν, τοῖς δὲ νεωτέροις διατριβὴν παρέχειν ἡδεῖαν καὶ χρησίμην καὶ πρέπουσαν τοῖς τηλικούτοις.", "st": "ep8.9"}, {"sp": "N", "t": "μὴ θαυμάζετε δ’ εἰ προθυμότερον καὶ διὰ μακροτέρων γέγραφα τὴν ἐπιστολήν· βούλομαι γὰρ ἀμφότερα, τοῖς τε παισὶν ἡμῶν χαρίσασθαι καὶ ποιῆσαι φανερὸν αὐτοῖς ὅτι, κἂν μὴ δημηγορῶσι μηδὲ στρατηγῶσιν ἀλλὰ μόνον μιμῶνται τὸν τρόπον τὸν ἐμόν, οὐκ ἠμελημένως διάξουσιν ἐν τοῖς Ἕλλησιν. ἓν ἔτι λοιπόν· ἂν ἄρα δόξῃ τι τούτων ὑμῖν πράττειν, Ἀγήνορί τε δηλώσατε καὶ τοῖς ἀδελφοῖς ὅτι μέρος τι καὶ δι’ ἐμὲ τυγχάνουσιν ὧν ἐπεθύμουν.", "st": "ep8.10"}, {"sp": "HDR", "t": "Ἐπιστολὴ Θʹ: Ἀρχιδάμῳ", "st": "ep9"}, {"sp": "N", "t": "εἰδώς, ὦ Ἀρχίδαμε, πολλοὺς ὡρμημένους ἐγκωμιάζειν σὲ καὶ τὸν πατέρα καὶ τὸ γένος ὑμῶν, εἱλόμην τοῦτον μὲν τὸν λόγον, ἐπειδὴ λίαν ῥᾴδιος ἦν, ἐκείνοις παραλιπεῖν, αὐτὸς δέ σε διανοοῦμαι παρακαλεῖν ἐπὶ στρατηγίας καὶ στρατείας οὐδὲν ὁμοίας ταῖς νῦν ἐνεστηκυίαις, ἀλλ’ ἐξ ὧν μεγάλων ἀγαθῶν αἴτιος γενήσει καὶ τῇ πόλει τῇ σαυτοῦ καὶ τοῖς Ἕλλησιν ἅπασιν.", "st": "ep9.1"}, {"sp": "N", "t": "ταύτην δ’ ἐποιησάμην τὴν αἵρεσιν, οὐκ ἀγνοῶν τῶν λόγων τὸν εὐμεταχειριστότερον, ἀλλ’ ἀκριβῶς εἰδὼς ὅτι πράξεις μὲν εὑρεῖν καλὰς καὶ μεγάλας καὶ συμφερούσας χαλεπὸν καὶ σπάνιόν ἐστιν, ἐπαινέσαι δὲ τὰς ἀρετὰς τὰς ὑμετέρας ῥᾳδίως οἷός τ’ ἂν ἐγενόμην. οὐ γὰρ ἔδει με παρ’ ἐμαυτοῦ πορίζεσθαι τὰ λεχθησόμενα περὶ αὐτῶν, ἀλλ’ ἐκ τῶν ὑμῖν πεπραγμένων τοσαύτας ἂν καὶ τοιαύτας ἀφορμὰς ἔλαβον ὥστε τὰς περὶ τῶν ἄλλων εὐλογίας μηδὲ κατὰ μικρὸν ἐναμίλλους γενέσθαι τῇ περὶ ὑμᾶς ῥηθείσῃ.", "st": "ep9.2"}, {"sp": "N", "t": "πῶς γὰρ ἄν τις ἢ τὴν εὐγένειαν ὑπερεβάλετο τῶν γεγονότων ἀφ’ Ἡρακλέους καὶ Διὸς ἣν πάντες ἴσασι μόνοις ὑμῖν ὁμολογουμένως ὑπάρχουσαν, ἢ τὴν ἀρετὴν τῶν ἐν Πελοποννήσῳ τὰς Δωρικὰς πόλεις κτισάντων καὶ τὴν χώραν ταύτην κατασχόντων, ἢ τὸ πλῆθος τῶν κινδύνων καὶ τῶν τροπαίων τῶν διὰ τὴν ὑμετέραν ἡγεμονίαν καὶ βασιλείαν σταθέντων;", "st": "ep9.3"}, {"sp": "N", "t": "τίς δ’ ἂν ἠπόρησε, διεξιέναι βουληθεὶς τὴν ἀνδρίαν ὅλης τῆς πόλεως καὶ σωφροσύνην καὶ πολιτείαν τὴν ὑπὸ τῶν προγόνων τῶν ὑμετέρων συνταχθεῖσαν; πόσοις δ’ ἂν λόγοις ἐξεγένετο χρήσασθαι περὶ τὴν φρόνησιν τοῦ σοῦ πατρὸς καὶ τὴν ἐν ταῖς συμφοραῖς διοίκησιν καὶ τὴν μάχην τὴν ἐν τῇ πόλει γενομένην ἧς ἡγεμὼν σὺ καταστὰς καὶ μετ’ ὀλίγων πρὸς πολλοὺς κινδυνεύσας καὶ πάντων διενεγκὼν αἴτιος ἐγένου τῇ πόλει τῆς σωτηρίας, οὗ κάλλιον ἔργον οὐδεὶς ἂν ἐπιδείξειεν;", "st": "ep9.4"}, {"sp": "N", "t": "οὔτε γὰρ πόλεις ἑλεῖν οὔτε πολλοὺς ἀποκτεῖναι τῶν πολεμίων οὕτω μέγα καὶ σεμνόν ἐστιν ὡς ἐκ τῶν τοιούτων κινδύνων σῶσαι τὴν πατρίδα, μὴ τὴν τυχοῦσαν ἀλλὰ τὴν τοσοῦτον ἐπ’ ἀρετῇ διενεγκοῦσαν. περὶ ὧν μὴ κομψῶς, ἀλλ’ ἁπλῶς διελθών, μηδὲ τῇ λέξει κοσμήσας, ἀλλ’ ἐξαριθμήσας μόνον καὶ χύδην εἰπὼν οὐδεὶς ὅστις οὐκ ἂν εὐδοκιμήσειεν.", "st": "ep9.5"}, {"sp": "N", "t": "ἐγὼ τοίνυν δυνηθεὶς ἂν καὶ περὶ τούτων ἐξαρκούντως διαλεχθῆναι, κἀκεῖνο γιγνώσκων, πρῶτον μὲν ὅτι ῥᾷόν ἐστι περὶ τῶν γεγενημένων εὐπόρως ἐπιδραμεῖν ἢ περὶ τῶν μελλόντων νουνεχόντως εἰπεῖν, ἔπειθ’ ὅτι πάντες ἄνθρωποι πλείω χάριν ἔχουσι τοῖς ἐπαινοῦσιν ἢ τοῖς συμβουλεύουσι, τοὺς μὲν γὰρ ὡς εὔνους ὄντας ἀποδέχονται, τοὺς δ’ ἂν μὴ κελευσθέντες παραινῶσιν,", "st": "ep9.6"}, {"sp": "N", "t": "ἐνοχλεῖν νομίζουσιν, ἀλλ’ ὅμως ἅπαντα ταῦτα προειδὼς τῶν μὲν πρὸς χάριν ἂν ῥηθέντων ἀπεσχόμην, περὶ δὲ τοιούτων μέλλω λέγειν, περὶ ὧν οὐδεὶς ἂν ἄλλος τολμήσειεν, ἡγούμενος δεῖν τοὺς ἐπιεικείας καὶ φρονήσεως ἀμφισβητοῦντας μὴ τοὺς ῥᾴστους προαιρεῖσθαι τῶν λόγων, ἀλλὰ τοὺς ἐργωδεστάτους, μηδὲ τοὺς ἡδίστους τοῖς ἀκούουσιν, ἀλλ’ ἐξ ὧν ὠφελήσουσι καὶ τὰς πόλεις τὰς αὑτῶν τοὺς ἄλλους Ἕλληνας· ἐφ’ οἷσπερ ἐγὼ τυγχάνω νῦν ἐφεστηκώς.", "st": "ep9.7"}, {"sp": "N", "t": "θαυμάζω δὲ καὶ τῶν ἄλλων τῶν πράττειν ἢ λέγειν δυναμένων, εἰ μηδὲ πώποτ’ αὐτοῖς ἐπῆλθεν ἐνθυμηθῆναι περὶ τῶν κοινῶν πραγμάτων, μηδ’ ἐλεῆσαι τὰς τῆς Ἑλλάδος δυσπραξίας οὕτως αἰσχρῶς καὶ δεινῶς διατιθεμένης, ἧς οὐδεὶς παραλέλειπται τόπος, ὃς οὐ γέμει καὶ μεστός ἐστι πολέμου καὶ στάσεων καὶ σφαγῶν καὶ κακῶν ἀναριθμήτων· ὧν πλεῖστον μέρος μετειλήφασιν οἱ τῆς Ἀσίας τὴν παραλίαν οἰκοῦντες, οὓς ἐν τοῖς συνθήκαις ἅπαντας ἐκδεδώκαμεν οὐ μόνον τοῖς βαρβάροις ἀλλὰ καὶ τῶν Ἑλλήνων τοῖς τῆς μὲν φωνῆς τῆς ἡμετέρας κοινωνοῦσι, τῷ δὲ τρόπῳ τῷ τῶν βαρβάρων χρωμένοις· οὕς,", "st": "ep9.8"}, {"sp": "N", "t": "εἰ νοῦν εἴχομεν, οὐκ ἂν περιεωρῶμεν ἀθροιζομένους οὐδ’ ὑπὸ τῶν τυχόντων στρατηγουμένους, οὐδὲ μείζους καὶ κρείττους συντάξεις στρατοπέδων γιγνομένας ἐκ τῶν πλανωμένων ἢ τῶν πολιτευομένων· οἳ τῆς μὲν βασιλέως χώρας μικρὸν μέρος λυμαίνονται, τὰς δὲ πόλεις τὰς Ἑλληνίδας, εἰς ἣν ἂν εἰσέλθωσιν, ἀναστάτους ποιοῦσι, τοὺς μὲν ἀποκτείνοντες, τοὺς δὲ φυγαδεύοντες,", "st": "ep9.9"}, {"sp": "N", "t": "τῶν δὲ τὰς οὐσίας διαρπάζοντες, ἔτι δὲ παῖδας καὶ γυναῖκας ὑβρίζοντες, καὶ τὰς μὲν εὐπρεπεστάτας καταισχύνοντες, τῶν δ’ ἄλλων ἃ περὶ τοῖς σώμασιν ἔχουσι περισπῶντες, ὥσθ’ ἃς πρότερον οὐδὲ κεκοσμημένας ἦν ἰδεῖν τοῖς ἀλλοτρίοις, ταύτας ὑπὸ πολλῶν ὁρᾶσθαι γυμνάς, ἐνίας δ’ αὐτῶν ἐν ῥάκεσι περιφθειρομένας δι’ ἔνδειαν τῶν ἀναγκαίων.", "st": "ep9.10"}, {"sp": "N", "t": "ὑπὲρ ὧν πολὺν ἤδη χρόνον γιγνομένων οὔτε πόλις οὐδεμία τῶν προεστάναι τῶν Ἐλλήνων ἀξιουσῶν ἠγανάκτησεν, οὔτ’ ἀνὴρ τῶν πρωτευόντων οὐδεὶς βαρέως ἤνεγκε, πλὴν ὁ σὸς πατήρ· μόνος γὰρ Ἀγησίλαος ὧν ἡμεῖς ἴσμεν ἐπιθυμῶν ἅπαντα τὸν χρόνον διετέλεσε τοὺς μὲν Ἕλληνας ἐλευθερῶσαι, πρὸς δὲ τοὺς βαρβάρους πόλεμον ἐξενεγκεῖν. οὐ μὴν ἀλλὰ κἀκεῖνος ἑνὸς πράγματος διήμαρτεν. καὶ μὴ θαυμάσῃς,", "st": "ep9.11"}, {"sp": "N", "t": "εἰ πρὸς σὲ διαλεγόμενος μνησθήσομαι τῶν οὐκ ὀρθῶς ὑπ’ αὐτοῦ γνωσθέντων· εἴθισμαί τε γὰρ μετὰ παρρησίας ἀεὶ ποιεῖσθαι τοὺς λόγους, καὶ δεξαίμην ἂν δικαίως ἐπιτιμήσας ἀπεχθέσθαι μᾶλλον ἢ παρὰ τὸ προσῆκον ἐπαινέσας χαρίσασθαι.", "st": "ep9.12"}, {"sp": "N", "t": "τὸ μὲν οὖν ἐμὸν οὕτως ἔχον ἐστίν, ἐκεῖνος δ’ ἐν ἅπασι τοῖς ἄλλοις διενεγκὼν καὶ γενόμενος ἐγκρατέστατος καὶ δικαιότατος καὶ πολιτικώτατος διττὰς ἔσχεν ἐπιθυμίας, χωρὶς μὲν ἑκατέραν καλὴν εἶναι δοκοῦσαν, οὐ συμφωνούσας δ’ ἀλλήλαις οὐδ’ ἅμα πράττεσθαι δυναμένας· ἠβούλετο γὰρ βασιλεῖ τε πολεμεῖν καὶ τῶν φίλων τοὺς φεύγοντας εἰς τὰς πόλεις καταγαγεῖν καὶ κυρίους καταστῆσαι τῶν πραγμάτων.", "st": "ep9.13"}, {"sp": "N", "t": "συνέβαινεν οὖν ἐκ μὲν τῆς πραγματείας τῆς ὑπὲρ τῶν ἑταίρων ἐν κακοῖς καὶ κινδύνοις εἶναι τοὺς Ἕλληνας, διὰ δὲ τὴν ταραχὴν τὴν ἐνθάδε γιγνομένην μὴ σχολὴν ἄγειν μηδὲ δύνασθαι πολεμεῖν τοῖς βαρβάροις. ὥστ’ ἐκ τῶν ἀγνοηθέντων κατ’ ἐκεῖνον τὸν χρόνον ῥᾴδιον καταμαθεῖν ὅτι δεῖ τοὺς ὀρθῶς βουλευομένους μὴ πρότερον ἐκφέρειν πρὸς βασιλέα πόλεμον, πρὶν ἂν διαλλάξῃ τις τοὺς Ἕλληνας καὶ παύσῃ τῆς μανίας καὶ τῆς φιλονικίας ἡμᾶς. περὶ ὧν ἐγὼ καὶ πρότερον εἴρηκα καὶ νῦν ποιήσομαι τοὺς λόγους.", "st": "ep9.14"}, {"sp": "N", "t": "καίτοι τινὲς τῶν οὐδεμιᾶς μὲν παιδείας μετεσχηκότων, δύνασθαι δὲ παιδεύειν τοὺς ἄλλους ὑπισχνουμένων, καὶ ψέγειν μὲν τἀμὰ τολμώντων, μιμεῖσθαι δὲ γλιχομένων, τάχ’ ἂν μανίαν εἶναι φήσειαν τὸ μέλειν ἐμοὶ τῶν τῆς Ἑλλάδος συμφορῶν, ὥσπερ παρὰ τοὺς ἐμοὺς λόγους ἢ βέλτιον ἢ χεῖρον αὐτὴν πράξουσαν. ὧν δικαίως ἂν ἅπαντες πολλὴν ἀνανδρίαν καὶ μικροψυχίαν καταγνοῖεν, ὅτι προσποιούμενοι φιλοσοφεῖν αὐτοὶ μὲν ἐπὶ μικροῖς φιλοτιμοῦνται, τοῖς δὲ δυναμένοις περὶ τῶν μεγίστων συμβουλεύειν φθονοῦντες διατελοῦσιν.", "st": "ep9.15"}, {"sp": "N", "t": "οὗτοι μὲν οὖν βοηθοῦντες ταῖς αὑτῶν ἀσθενείαις καὶ ῥᾳθυμίαις ἴσως τοιαῦτ’ ἐροῦσιν· ἐγὼ δ’ οὕτως ἐπ’ ἐμαυτῷ μέγα φρονῶ, καίπερ ἔτη γεγονὼς ὀγδοήκοντα καὶ παντάπασιν ἀπειρηκώς, ὥστ’ οἶμαι καὶ λέγειν ἐμοὶ προσήκειν μάλιστα περὶ τούτων καὶ καλῶς βεβουλεῦσθαι πρὸς σὲ ποιούμενον τοὺς λόγους, καὶ τυχὸν ἀπ’ αὐτῶν γενήσεσθαί τι τῶν δεόντων.", "st": "ep9.16"}, {"sp": "N", "t": "ἡγοῦμαι δὲ καὶ τοὺς ἄλλους Ἕλληνας, εἰ δεήσειεν αὐτοὺς ἐξ ἁπάντων ἐκλέξασθαι τόν τε τῷ λόγῳ κάλλιστ’ ἂν δυνηθέντα παρακαλέσαι τοὺς Ἕλληνας ἐπὶ τὴν τῶν βαρβάρων στρατείαν καὶ τὸν τάχιστα μέλλοντα τὰς πράξεις ἐπιτελεῖν τὰς συμφέρειν δοξάσας, οὐκ ἂν ἄλλους ἀνθ’ ἡμῶν προκριθῆναι. καίτοι πῶς οὐκ ἂν αἰσχρὸν ποιήσαιμεν, εἰ τούτων ἀμελήσαιμεν οὕτως ἐντίμων ὄντων ὧν ἅπαντες ἂν ἡμᾶς ἀξιώσαιεν;", "st": "ep9.17"}, {"sp": "N", "t": "τὸ μὲν οὖν ἐμὸν ἔλαττόν ἐστιν· ἀποφήνασθαι γὰρ ἃ γιγνώσκει τις οὐ πάνυ τῶν χαλεπῶν πέφυκεν· σοὶ δὲ προσήκει προσέχοντι τὸν νοῦν τοῖς ὑπ’ ἐμοῦ λεγομένοις βουλεύσασθαι, πότερον ὀλιγωρητέον ἐστὶ τῶν Ἑλληνικῶν πραγμάτων γεγονότι μέν, ὥσπερ ὀλίγῳ πρότερον ἐγὼ διῆλθον, ἡγεμόνι δὲ Λακεδαιμονίων ὄντι, βασιλεῖ δὲ προσαγορευομένῳ, μεγίστην δὲ τῶν Ἑλλήνων ἔχοντι δόξαν, ἢ τῶν μὲν ἐνεστώτων πραγμάτων ὑπεροπτέον, μείζοσι δ’ ἐπιχειρητέον.", "st": "ep9.18"}, {"sp": "N", "t": "ἐγὼ μὲν γάρ φημι χρῆναί σε πάντων ἀφέμενον τῶν ἄλλων δυοῖν τούτοιν προσέχειν τὸν νοῦν, ὅπως τοὺς μὲν Ἕλληνας ἀπαλλάξεις τῶν πολέμων καὶ τῶν ἄλλων κακῶν τῶν νῦν αὐτοῖς παρόντων, τοὺς δὲ βαρβάρους παύσεις ὑβρίζοντας καὶ πλείω κεκτημένους ἀγαθὰ τοῦ προσήκοντος. ὡς δ’ ἐστὶ ταῦτα δυνατὰ καὶ συμφέροντα καὶ σοὶ καὶ τῇ πόλει καὶ τοῖς ἄλλοις ἅπασιν, ἐμὸν ἔργον ἤδη διδάξαι περὶ αὐτῶν ἐστιν …", "st": "ep9.19"}], []);})();
